import time
import threading
from collections import OrderedDict
from typing import Any, Optional, Dict

class LRUCache:
    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("Capacity must be a positive integer.")

        self.capacity = capacity
        self.cache: OrderedDict[Any, Dict[str, Any]] = OrderedDict()
        self.lock = threading.RLock()

    def _is_expired(self, entry: Dict[str, Any]) -> bool:
        return time.monotonic() > entry['expiry']

    def get(self, key: Any) -> Optional[Any]:
        with self.lock:
            if key not in self.cache:
                return None

            entry = self.cache[key]
            if self._is_expired(entry):
                del self.cache[key]
                return None

            # Refresh LRU position
            self.cache.move_to_end(key)
            return entry['value']

    def put(self, key: Any, value: Any, ttl_seconds: float) -> None:
        if ttl_seconds <= 0:
            raise ValueError("TTL must be positive.")

        with self.lock:
            if key in self.cache:
                self.cache.move_to_end(key)

            self.cache[key] = {
                'value': value,
                'expiry': time.monotonic() + ttl_seconds
            }

            # Evict expired entries first to free space
            self._reap_expired()

            # If still over capacity, evict the LRU entry
            if len(self.cache) > self.capacity:
                self.cache.popitem(last=False)

    def _reap_expired(self) -> None:
        """Removes expired entries from the front of the OrderedDict."""
        while self.cache:
            key, entry = next(iter(self.cache.items()))
            if self._is_expired(entry):
                self.cache.popitem(last=False)
            else:
                break

    def size(self) -> int:
        with self.lock:
            self._reap_expired()
            return len(self.cache)

# --- Usage Example ---
if __name__ == "__main__":
    # Initialize cache with capacity 2
    lru = LRUCache(capacity=2)

    # Add items
    lru.put("a", 1, ttl_seconds=0.1)
    lru.put("b", 2, ttl_seconds=10.0)

    print(f"Get 'a': {lru.get('a')}")  # 1

    time.sleep(0.2)
    print(f"Get 'a' after expiry: {lru.get('a')}")  # None

    lru.put("c", 3, ttl_seconds=10.0)
    lru.put("d", 4, ttl_seconds=10.0)

    # 'b' should have been evicted due to capacity limit
    print(f"Size after capacity overflow: {lru.size()}") # 2 (contains c and d)

