import re
from typing import List, Union

class ParseError(Exception):
    pass

class Parser:
    def __init__(self, expression: str):
        self.tokens = self._tokenize(expression)
        self.pos = 0

    def _tokenize(self, expr: str) -> List[str]:
        # Tokenize numbers (int/float), operators, and parens
        token_pattern = r'\d*\.\d+|\d+|[\+\-\*\/\(\)\^]'
        tokens = re.findall(token_pattern, expr.replace('**', '^'))
        # Validate for unexpected characters
        clean = re.sub(r'\s+', '', expr).replace('**', '^')
        if len("".join(tokens)) != len(clean):
            raise ParseError("Input contains invalid characters")
        return tokens

    def _peek(self) -> Union[str, None]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _consume(self) -> str:
        token = self._peek()
        self.pos += 1
        return token

    def parse_expression(self) -> float:
        """Handles + and -"""
        node = self._parse_term()
        while self._peek() in ('+', '-'):
            op = self._consume()
            right = self._parse_term()
            node = (node + right) if op == '+' else (node - right)
        return node

    def _parse_term(self) -> float:
        """Handles * and /"""
        node = self._parse_unary()
        while self._peek() in ('*', '/'):
            op = self._consume()
            right = self._parse_unary()
            if op == '*': node *= right
            else:
                if right == 0: raise ParseError("Division by zero")
                node /= right
        return node

    def _parse_unary(self) -> float:
        """Handles unary -"""
        if self._peek() == '-':
            self._consume()
            return -self._parse_unary()
        return self._parse_power()

    def _parse_power(self) -> float:
        """Handles ** (right-associative)"""
        node = self._parse_factor()
        if self._peek() == '^':
            self._consume()
            node = node ** self._parse_power()
        return node

    def _parse_factor(self) -> float:
        """Handles numbers and parentheses"""
        token = self._consume()
        if token == '(':
            result = self.parse_expression()
            if self._consume() != ')':
                raise ParseError("Unbalanced parentheses")
            return result
        try:
            return float(token)
        except (ValueError, TypeError):
            raise ParseError(f"Unexpected token: {token}")

def evaluate(expression: str) -> float:
    parser = Parser(expression)
    result = parser.parse_expression()
    if parser.pos < len(parser.tokens):
        raise ParseError("Trailing data after expression")
    return float(result)

# --- Usage Examples ---
if __name__ == "__main__":
    # 1. Precedence: * before +
    print(f"1 + 2 * 3 = {evaluate('1 + 2 * 3')}")  # 7.0

    # 2. Parentheses and Unary Minus
    print(f"-(2 + 3) * 4 = {evaluate('-(2 + 3) * 4')}")  # -20.0

