from typing import Union, List, Tuple
import re

class ParseError(Exception):
    """Base class for parsing errors"""
    pass

class TokenizerError(ParseError):
    """Error during tokenization"""
    pass

class ParserError(ParseError):
    """Error during parsing"""
    pass

class EvaluationError(ParseError):
    """Error during evaluation"""
    pass

class Token:
    """Represents a token in the input string"""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Parser:
    """Recursive-descent parser for arithmetic expressions"""

    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.current_token = None
        self.position = -1
        self.advance()

    def advance(self) -> None:
        """Move to the next token"""
        self.position += 1
        if self.position < len(self.tokens):
            self.current_token = self.tokens[self.position]
        else:
            self.current_token = None

    def consume(self, expected_type: str) -> Token:
        """Consume the current token if it matches expected type, else raise error"""
        if self.current_token and self.current_token.type == expected_type:
            token = self.current_token
            self.advance()
            return token
        raise ParserError(f"Expected {expected_type}, got {self.current_token.type if self.current_token else 'EOF'}")

    def parse(self) -> float:
        """Parse the expression and return the result"""
        result = self.expression()
        if self.current_token is not None:
            raise ParserError(f"Unexpected token at end of input: {self.current_token}")
        return result

    def expression(self) -> float:
        """Parse an expression (handles + and -)"""
        result = self.term()

        while self.current_token and self.current_token.type in ('PLUS', 'MINUS'):
            token = self.current_token
            if token.type == 'PLUS':
                self.advance()
                result += self.term()
            elif token.type == 'MINUS':
                self.advance()
                result -= self.term()

        return result

    def term(self) -> float:
        """Parse a term (handles * and /)"""
        result = self.factor()

        while self.current_token and self.current_token.type in ('MULTIPLY', 'DIVIDE'):
            token = self.current_token
            if token.type == 'MULTIPLY':
                self.advance()
                result *= self.factor()
            elif token.type == 'DIVIDE':
                self.advance()
                divisor = self.factor()
                if divisor == 0:
                    raise EvaluationError("Division by zero")
                result /= divisor

        return result

    def factor(self) -> float:
        """Parse a factor (handles ** and unary minus)"""
        if self.current_token and self.current_token.type == 'MINUS':
            self.advance()
            return -self.exponent()
        return self.exponent()

    def exponent(self) -> float:
        """Parse an exponentiation (right-associative)"""
        result = self.primary()

        if self.current_token and self.current_token.type == 'POWER':
            self.advance()
            exponent = self.exponent()  # Right-associative
            result **= exponent

        return result

    def primary(self) -> float:
        """Parse a primary (numbers and parentheses)"""
        token = self.current_token

        if token.type == 'NUMBER':
            self.advance()
            return token.value
        elif token.type == 'LPAREN':
            self.advance()
            result = self.expression()
            self.consume('RPAREN')
            return result
        else:
            raise ParserError(f"Unexpected token: {token}")

def tokenize(expression: str) -> List[Token]:
    """Convert input string into a list of tokens"""
    token_specification = [
        ('NUMBER',    r'\d+\.?\d*|\.\d+'),  # Integer or decimal number
        ('PLUS',      r'\+'),               # Addition operator
        ('MINUS',     r'-'),                # Subtraction operator
        ('MULTIPLY',  r'\*'),               # Multiplication operator
        ('DIVIDE',    r'/'),                # Division operator
        ('POWER',     r'\*\*'),             # Exponentiation operator
        ('LPAREN',    r'\('),               # Left parenthesis
        ('RPAREN',    r'\)'),               # Right parenthesis
        ('SKIP',      r'[ \t]+'),           # Skip over whitespace
        ('MISMATCH',  r'.'),                # Any other character
    ]
    tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)
    tokens = []

    for mo in re.finditer(tok_regex, expression):
        kind = mo.lastgroup
        value = mo.group()

        if kind == 'NUMBER':
            try:
                # Try to parse as int first, then float if that fails
                num = int(value)
            except ValueError:
                num = float(value)
            tokens.append(Token(kind, num))
        elif kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise TokenizerError(f"Unexpected character: {value}")
        else:
            tokens.append(Token(kind, value))

    return tokens

def evaluate(expression: str) -> float:
    """Evaluate an arithmetic expression and return the result as a float"""
    try:
        tokens = tokenize(expression)
        parser = Parser(tokens)
        return parser.parse()
    except ParseError as e:
        raise ParseError(f"Error evaluating expression '{expression}': {str(e)}")

# --- file boundary ---

# Example 1: Operator precedence (** > unary minus > * / > + -)
print(evaluate("2 + 3 * 4"))        # 14 (3*4=12, then 2+12=14)
print(evaluate("2 * 3 + 4"))        # 10 (2*3=6, then 6+4=10)
print(evaluate("2 ** 3 + 4"))       # 12 (2**3=8, then 8+4=12)
print(evaluate("2 + 3 ** 4"))       # 83 (3**4=81, then 2+81=83)
print(evaluate("-2 ** 2"))          # -4 (2**2=4, then unary minus applies)
print(evaluate("(-2) ** 2"))        # 4 (parentheses change precedence)

# Example 2: Parentheses for grouping
print(evaluate("(2 + 3) * 4"))      # 20 (5*4=20)
print(evaluate("2 * (3 + 4)"))      # 14 (2*7=14)
print(evaluate("2 * (3 + 4 * 5)"))  # 46 (4*5=20, 3+20=23, 2*23=46)
print(evaluate("((2 + 3) * 4) + 1")) # 21

# Example 3: Unary minus and division
print(evaluate("-5 + 3"))           # -2
print(evaluate("5 + -3"))           # 2
print(evaluate("10 / -2"))          # -5.0
print(evaluate("-10 / 2"))          # -5.0
print(evaluate("3 + 4 * 2 / (1 - 5) ** 2"))  # 3.5

# --- file boundary ---

try:
    print(evaluate("2 + * 3"))       # Syntax error
except ParseError as e:
    print(f"Error: {e}")

try:
    print(evaluate("2 / 0"))         # Division by zero
except EvaluationError as e:
    print(f"Error: {e}")

try:
    print(evaluate("2 + (3 * 4"))    # Unbalanced parentheses
except ParseError as e:
    print(f"Error: {e}")

try:
    print(evaluate("2 + $ 3"))       # Unexpected character
except TokenizerError as e:
    print(f"Error: {e}")

