import re
from dataclasses import dataclass
from enum import Enum, auto
from typing import List, Union


# ==========================================
# 1. Tokenizer (Lexer)
# ==========================================

class TokenType(Enum):
    INTEGER = auto()
    FLOAT = auto()
    PLUS = auto()
    MINUS = auto()
    MUL = auto()
    DIV = auto()
    POW = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()


@dataclass
class Token:
    type: TokenType
    value: any


class Lexer:
    """Converts a string of characters into a stream of Tokens."""

    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos] if self.text else None

    def advance(self):
        self.pos += 1
        self.current_char = self.text[self.pos] if self.pos < len(self.text) else None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def _id_float(self) -> Token:
        """Read a float number (e.g., 1.2, .5, 10.0)"""
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return Token(TokenType.FLOAT, float(result))

    def get_next_token(self) -> Token:
        while self.current_char is not None:
            # Skip whitespace
            if self.current_char.isspace():
                self.skip_whitespace()
                continue

            # Integer or Float
            if self.current_char.isdigit() or self.current_char == '.':
                return self._id_float()

            # Operators and Parens
            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS, '+')
            if self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS, '-')
            if self.current_char == '*':
                self.advance()
                # Check for **
                if self.current_char == '*':
                    self.advance()
                    return Token(TokenType.POW, '**')
                return Token(TokenType.MUL, '*')
            if self.current_char == '/':
                self.advance()
                return Token(TokenType.DIV, '/')
            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN, '(')
            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN, ')')

            # Unknown character
            raise SyntaxError(f"Illegal character '{self.current_char}'")

        return Token(TokenType.EOF, None)


# ==========================================
# 2. Abstract Syntax Tree (AST) Nodes
# ==========================================

@dataclass
class AST:
    pass

@dataclass
class Num(AST):
    value: float

@dataclass
class BinOp(AST):
    left: AST
    op: str  # '+', '-', '*', '/', '**'
    right: AST

@dataclass
class UnaryOp(AST):
    op: str  # '-'
    operand: AST


# ==========================================
# 3. Recursive Descent Parser
# ==========================================

class Parser:
    """
    Parses tokens into an AST.
    Grammar:
        expression  -> term ((PLUS | MINUS) term)*
        term        -> factor ((MUL | DIV) factor)*
        factor      -> power (POW factor)?     // Right associative
        power       -> (MINUS power) | primary // Unary minus
        primary     -> NUMBER | (LPAREN expression RPAREN)
    """

    def __init__(self, lexer: Lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self, expected: str):
        raise SyntaxError(f"Expected {expected}, but got {self.current_token.type.name} (value: {self.current_token.value})")

    def eat(self, token_type: TokenType):
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error(token_type.name)

    def parse(self) -> AST:
        ast = self.expression()
        if self.current_token.type != TokenType.EOF:
            self.error("EOF")
        return ast

    # 1. Expression: + and -
    def expression(self) -> AST:
        node = self.term()

        while self.current_token.type in (TokenType.PLUS, TokenType.MINUS):
            token = self.current_token
            if token.type == TokenType.PLUS:
                self.eat(TokenType.PLUS)
            elif token.type == TokenType.MINUS:
                self.eat(TokenType.MINUS)

            right = self.term()
            node = BinOp(left=node, op=token.value, right=right)

        return node

    # 2. Term: * and /
    def term(self) -> AST:
        node = self.factor()

        while self.current_token.type in (TokenType.MUL, TokenType.DIV):
            token = self.current_token
            if token.type == TokenType.MUL:
                self.eat(TokenType.MUL)
            elif token.type == TokenType.DIV:
                self.eat(TokenType.DIV)

            right = self.factor()
            node = BinOp(left=node, op=token.value, right=right)

        return node

    # 3. Factor: ** (Right Associative)
    def factor(self) -> AST:
        node = self.power()

        if self.current_token.type == TokenType.POW:
            token = self.current_token
            self.eat(TokenType.POW)
            # Recursively call factor to make it right-associative
            right = self.factor() 
            node = BinOp(left=node, op=token.value, right=right)

        return node

    # 4. Power: Unary Minus
    def power(self) -> AST:
        if self.current_token.type == TokenType.MINUS:
            self.eat(TokenType.MINUS)
            operand = self.power() # Recursive to handle --2
            return UnaryOp(op='-', operand=operand)

        return self.primary()

    # 5. Primary: Numbers and Parentheses
    def primary(self) -> AST:
        token = self.current_token

        if token.type in (TokenType.INTEGER, TokenType.FLOAT):
            self.eat(token.type)
            return Num(value=token.value)

        elif token.type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            node = self.expression()
            if self.current_token.type != TokenType.RPAREN:
                self.error("RPAREN")
            self.eat(TokenType.RPAREN)
            return node

        else:
            self.error("Number or LPAREN")


# ==========================================
# 4. Evaluator
# ==========================================

class Evaluator:
    @staticmethod
    def visit(node: AST) -> float:
        if isinstance(node, Num):
            return node.value

        elif isinstance(node, BinOp):
            left = Evaluator.visit(node.left)
            right = Evaluator.visit(node.right)

            if node.op == '+':
                return left + right
            elif node.op == '-':
                return left - right
            elif node.op == '*':
                return left * right
            elif node.op == '/':
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                return left / right
            elif node.op == '**':
                return left ** right

        elif isinstance(node, UnaryOp):
            operand = Evaluator.visit(node.operand)
            if node.op == '-':
                return -operand

        raise ValueError(f"Unknown node type: {type(node)}")


# ==========================================
# 5. Public API
# ==========================================

def evaluate(expression: str) -> float:
    """
    Parses and evaluates an arithmetic expression.

    Supported operators: +, -, *, /, ** (exponent), unary -
    Supported grouping: parentheses
    Supported numbers: integers and floats

    Args:
        expression: A string containing the math expression.

    Returns:
        The result as a float.

    Raises:
        SyntaxError: If the expression is malformed.
        ZeroDivisionError: If division by zero occurs.
    """
    try:
        lexer = Lexer(expression)
        parser = Parser(lexer)
        tree = parser.parse()
        result = Evaluator.visit(tree)
        return result
    except ZeroDivisionError:
        raise
    except SyntaxError as e:
        # Wrap generic syntax errors for cleaner API
        raise SyntaxError(f"Invalid syntax in expression: '{expression}'. Details: {e}") from e


# ==========================================
