import re
from typing import Union, List

class ParseError(Exception):
    """Custom exception for parsing errors."""
    pass

class Token:
    """Class to represent a token."""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Tokenizer:
    """Tokenizer for arithmetic expressions."""
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.current_char = self.expression[self.position] if self.expression else None

    def advance(self):
        """Advance the position and update the current character."""
        self.position += 1
        if self.position < len(self.expression):
            self.current_char = self.expression[self.position]
        else:
            self.current_char = None

    def skip_whitespace(self):
        """Skip whitespace characters."""
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self) -> Token:
        """Return a number token (integer or float)."""
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return Token('NUMBER', float(num_str))

    def get_next_token(self) -> Token:
        """Return the next token from the input string."""
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()
            if self.current_char == '+':
                self.advance()
                return Token('PLUS', '+')
            if self.current_char == '-':
                self.advance()
                return Token('MINUS', '-')
            if self.current_char == '*':
                self.advance()
                return Token('MUL', '*')
            if self.current_char == '/':
                self.advance()
                return Token('DIV', '/')
            if self.current_char == '(':
                self.advance()
                return Token('LPAREN', '(')
            if self.current_char == ')':
                self.advance()
                return Token('RPAREN', ')')
            if self.current_char == '**':
                self.advance()
                return Token('POW', '**')
            raise ParseError(f"Unexpected character: {self.current_char}")
        return Token('EOF', None)

class Parser:
    """Parser for arithmetic expressions."""
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer
        self.current_token = self.tokenizer.get_next_token()

    def error(self):
        """Raise a parsing error."""
        raise ParseError(f"Invalid syntax at token: {self.current_token}")

    def eat(self, token_type: str):
        """Consume the current token if it matches the expected type."""
        if self.current_token.type == token_type:
            self.current_token = self.tokenizer.get_next_token()
        else:
            self.error()

    def factor(self) -> float:
        """Parse a factor (number or unary minus)."""
        if self.current_token.type == 'MINUS':
            self.eat('MINUS')
            return -self.factor()
        elif self.current_token.type == 'NUMBER':
            value = self.current_token.value
            self.eat('NUMBER')
            return value
        elif self.current_token.type == 'LPAREN':
            self.eat('LPAREN')
            result = self.expr()
            self.eat('RPAREN')
            return result
        self.error()

    def power(self) -> float:
        """Parse exponentiation (right associative)."""
        result = self.factor()
        while self.current_token.type == 'POW':
            self.eat('POW')
            result **= self.factor()
        return result

    def term(self) -> float:
        """Parse multiplication and division."""
        result = self.power()
        while self.current_token.type in ('MUL', 'DIV'):
            if self.current_token.type == 'MUL':
                self.eat('MUL')
                result *= self.power()
            elif self.current_token.type == 'DIV':
                self.eat('DIV')
                divisor = self.power()
                if divisor == 0:
                    raise ParseError("Division by zero")
                result /= divisor
        return result

    def expr(self) -> float:
        """Parse addition and subtraction."""
        result = self.term()
        while self.current_token.type in ('PLUS', 'MINUS'):
            if self.current_token.type == 'PLUS':
                self.eat('PLUS')
                result += self.term()
            elif self.current_token.type == 'MINUS':
                self.eat('MINUS')
                result -= self.term()
        return result

    def parse(self) -> float:
        """Parse the entire expression and return the result."""
        return self.expr()

def evaluate(expression: str) -> float:
    """Public API to evaluate an arithmetic expression."""
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    return parser.parse()

