import math

class ParseError(Exception):
    pass

class EvalError(Exception):
    pass

Token = Union[str, float]

def tokenize(expression: str) -> List[Token]:
    """Convert input string into a list of tokens."""
    tokens = []
    i = 0
    n = len(expression)

    while i < n:
        c = expression[i]

        # Skip whitespace
        if c.isspace():
            i += 1
            continue

        # Handle numbers (integers and floats)
        if c.isdigit() or c == '.':
            start = i
            has_decimal = False

            while i < n and (expression[i].isdigit() or expression[i] == '.'):
                if expression[i] == '.':
                    if has_decimal:
                        raise ParseError(f"Invalid number format at position {i}")
                    has_decimal = True
                i += 1

            num_str = expression[start:i]
            try:
                # Try to convert to int first if no decimal point
                if not has_decimal:
                    tokens.append(int(num_str))
                else:
                    tokens.append(float(num_str))
            except ValueError:
                raise ParseError(f"Invalid number format at position {start}")
            continue

        # Handle operators and parentheses
        if c in '+-*/()**':
            # Handle ** operator
            if c == '*' and i + 1 < n and expression[i+1] == '*':
                tokens.append('**')
                i += 2
            # Handle unary minus (we'll handle this in parsing)
            elif c == '-' and (i == 0 or expression[i-1] in '+-*/(**'):
                tokens.append('u-')
                i += 1
            else:
                tokens.append(c)
                i += 1
            continue

        # Handle unexpected characters
        raise ParseError(f"Unexpected character '{c}' at position {i}")

    return tokens

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        """Peek at the current token without consuming it."""
        if self.pos >= len(self.tokens):
            return None
        return self.tokens[self.pos]

    def consume(self) -> Token:
        """Consume and return the current token."""
        token = self.peek()
        if token is None:
            raise ParseError("Unexpected end of input")
        self.pos += 1
        return token

    def expect(self, expected: Token) -> None:
        """Consume the current token if it matches expected, otherwise raise error."""
        token = self.peek()
        if token != expected:
            raise ParseError(f"Expected '{expected}', got '{token}'")
        self.consume()

    def parse_expression(self) -> float:
        """Parse an expression (lowest precedence)."""
        left = self.parse_term()

        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self.parse_term()
            if op == '+':
                left += right
            else:
                left -= right

        return left

    def parse_term(self) -> float:
        """Parse a term (medium precedence)."""
        left = self.parse_factor()

        while self.peek() in ('*', '/'):
            op = self.consume()
            right = self.parse_factor()
            if op == '*':
                left *= right
            else:
                if right == 0:
                    raise EvalError("Division by zero")
                left /= right

        return left

    def parse_factor(self) -> float:
        """Parse a factor (high precedence)."""
        token = self.peek()

        if token == 'u-':
            self.consume()
            value = self.parse_factor()
            return -value
        elif token == '(':
            self.consume()
            value = self.parse_expression()
            self.expect(')')
            return value
        else:
            return self.parse_power()

    def parse_power(self) -> float:
        """Parse power operations (highest precedence, right-associative)."""
        left = self.parse_primary()

        if self.peek() == '**':
            self.consume()
            right = self.parse_power()  # Right-associative: parse_power instead of parse_primary
            return left ** right

        return left

    def parse_primary(self) -> float:
        """Parse primary expressions (numbers)."""
        token = self.consume()

        if isinstance(token, (int, float)):
            return float(token)
        else:
            raise ParseError(f"Expected number, got '{token}'")

def evaluate(expression: str) -> float:
    """Evaluate an arithmetic expression string and return the result as a float."""
    if not expression.strip():
        raise ParseError("Empty expression")

    try:
        tokens = tokenize(expression)
        parser = Parser(tokens)
        result = parser.parse_expression()

        # Check if we consumed all tokens
        if parser.pos != len(tokens):
            raise ParseError(f"Unexpected token '{parser.peek()}' at position {parser.pos}")

        return result
    except (ParseError, EvalError) as e:
        raise e
    except Exception as e:
        raise ParseError(f"Error evaluating expression: {str(e)}")

