    def factor(self) -> float:
        """Parse a factor (number or parenthesized expression)."""
        if self.current_token.type == 'NUMBER':
            value = self.current_token.value
            self.eat('NUMBER')
            return value
        elif self.current_token.type == 'MINUS':
            self.eat('MINUS')
            return -self.factor()
        elif self.current_token.type == 'LPAREN':
            self.eat('LPAREN')
            value = self.expr()
            self.eat('RPAREN')
            return value
        self.error()

    def term(self) -> float:
        """Parse a term (factor followed by * or /)."""
        result = self.factor()
        while self.current_token.type in ('MUL', 'DIV'):
            token = self.current_token
            if token.type == 'MUL':
                self.eat('MUL')
                result *= self.factor()
            elif token.type == 'DIV':
                self.eat('DIV')
                divisor = self.factor()
                if divisor == 0:
                    raise ZeroDivisionError("Division by zero")
                result /= divisor
        return result

    def power(self) -> float:
        """Parse a power expression (factor followed by **)."""
        result = self.term()
        while self.current_token.type == 'POW':
            self.eat('POW')
            result **= self.term()
        return result

    def expr(self) -> float:
        """Parse an expression (term followed by + or -)."""
        result = self.power()
        while self.current_token.type in ('PLUS', 'MINUS'):
            token = self.current_token
            if token.type == 'PLUS':
                self.eat('PLUS')
                result += self.power()
            elif token.type == 'MINUS':
                self.eat('MINUS')
                result -= self.power()
        return result

