import re
from typing import List, Tuple

class ExpressionError(Exception):
    """Custom exception for parsing and evaluation errors."""
    pass

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Evaluator:
    """
    Recursive Descent Parser and Evaluator for arithmetic expressions.
    Precedence: ** (Right) > Unary - > * / > + -
    """

    # Token definitions
    TOKEN_SPEC = [
        ('NUMBER',   r'\d+(\.\d*)?'),  # Integer or decimal
        ('POW',      r'\*\*'),         # Exponentiation
        ('PLUS',     r'\+'),           # Addition
        ('MINUS',    r'-'),            # Subtraction
        ('MUL',      r'\*'),           # Multiplication
        ('DIV',      r'/'),            # Division
        ('LPAREN',   r'\('),           # Left Parenthesis
        ('RPAREN',   r'\)'),           # Right Parenthesis
        ('SKIP',     r'[ \t]+'),       # Whitespace
        ('MISMATCH', r'.'),            # Any other character
    ]

    def __init__(self, expression: str):
        self.tokens = self._tokenize(expression)
        self.pos = 0

    def _tokenize(self, expression: str) -> List[Token]:
        regex = '|'.join('(?P<%s>%s)' % pair for pair in self.TOKEN_SPEC)
        tokens = []
        for mo in re.finditer(regex, expression):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                tokens.append(Token('NUMBER', value))
            elif kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise ExpressionError(f"Unexpected character: {value!r}")
            else:
                tokens.append(Token(kind, value))
        return tokens

    def _peek(self) -> Token:
        """Look at the current token without consuming it."""
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return Token('EOF', '')

    def _consume(self, expected_type: str = None) -> Token:
        """Consume the current token and move the pointer."""
        token = self._peek()
        if expected_type and token.type != expected_type:
            raise ExpressionError(f"Expected {expected_type}, found {token.type}")
        self.pos += 1
        return token

    def parse_expression(self) -> float:
        """Handle Addition and Subtraction (Lowest Precedence)"""
        result = self.parse_term()
        while self._peek().type in ('PLUS', 'MINUS'):
            token = self._consume()
            if token.type == 'PLUS':
                result += self.parse_term()
            else:
                result -= self.parse_term()
        return result

    def parse_term(self) -> float:
        """Handle Multiplication and Division"""
        result = self.parse_unary()
        while self._peek().type in ('MUL', 'DIV'):
            token = self._consume()
            right = self.parse_unary()
            if token.type == 'MUL':
                result *= right
            else:
                if right == 0:
                    raise ExpressionError("Division by zero")
                result /= right
        return result

    def parse_unary(self) -> float:
        """Handle Unary Minus"""
        if self._peek().type == 'MINUS':
            self._consume('MINUS')
            return -self.parse_unary() # Recursive to handle --5
        return self.parse_power()

    def parse_power(self) -> float:
        """Handle Exponentiation (Right-Associative)"""
        result = self.parse_atom()
        if self._peek().type == 'POW':
            self._consume('POW')
            # Right associativity: call parse_power recursively
            result = result ** self.parse_power()
        return result

    def parse_atom(self) -> float:
        """Handle Numbers and Parentheses (Highest Precedence)"""
        token = self._peek()

        if token.type == 'NUMBER':
            self._consume('NUMBER')
            return float(token.value)

        elif token.type == 'LPAREN':
            self._consume('LPAREN')
            result = self.parse_expression()
            if self._peek().type != 'RPAREN':
                raise ExpressionError("Unbalanced parentheses: Missing ')'")
            self._consume('RPAREN')
            return result

        else:
            raise ExpressionError(f"Unexpected token: {token.value if token.value else 'EOF'}")

def evaluate(expression: str) -> float:
    """
    Public API to evaluate an arithmetic expression string.
    """
    evaluator = Evaluator(expression)
    result = evaluator.parse_expression()
    if evaluator.pos < len(evaluator.tokens):
        raise ExpressionError(f"Unexpected trailing tokens starting at {evaluator.tokens[evaluator.pos]}")
    return result

