from typing import Generator, Union

# --- Token types ---
NUMBER = "NUMBER"
PLUS = "PLUS"
MINUS = "MINUS"
STAR = "STAR"
SLASH = "SLASH"
POW = "POW"
LPAREN = "LPAREN"
RPAREN = "RPAREN"
END = "END"

# --- Token class ---
class Token:
    def __init__(self, typ: str, value: Union[str, float, None] = None):
        self.type = typ
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value!r})"


# --- Tokenizer ---
class Tokenizer:
    """Splits an expression string into a stream of tokens."""

    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self._tokens: list[Token] = []
        self._tokenize()

    def _tokenize(self) -> None:
        while self.pos < len(self.text):
            ch = self.text[self.pos]
            # skip whitespace
            if ch.isspace():
                self.pos += 1
                continue

            # number (int or float)
            if ch.isdigit() or (ch == '.' and self.pos + 1 < len(self.text) and self.text[self.pos + 1].isdigit()):
                start = self.pos
                while self.pos < len(self.text) and (self.text[self.pos].isdigit() or self.text[self.pos] == '.'):
                    self.pos += 1
                num_str = self.text[start:self.pos]
                # ensure it's a valid number (at most one dot)
                if num_str.count('.') > 1:
                    raise ValueError(f"Invalid number literal: {num_str}")
                value = float(num_str) if '.' in num_str else int(num_str)
                self._tokens.append(Token(NUMBER, value))
                continue

            # operators and parentheses
            if ch == '+':
                self._tokens.append(Token(PLUS))
            elif ch == '-':
                self._tokens.append(Token(MINUS))
            elif ch == '*':
                # check for **
                if self.pos + 1 < len(self.text) and self.text[self.pos + 1] == '*':
                    self.pos += 2
                    self._tokens.append(Token(POW))
                    continue
                else:
                    self._tokens.append(Token(STAR))
            elif ch == '/':
                self._tokens.append(Token(SLASH))
            elif ch == '(':
                self._tokens.append(Token(LPAREN))
            elif ch == ')':
                self._tokens.append(Token(RPAREN))
            else:
                raise ValueError(f"Unexpected character: {ch!r} at position {self.pos}")
            self.pos += 1

        self._tokens.append(Token(END))

    def get_tokens(self) -> list[Token]:
        return self._tokens


# --- Parser / Evaluator ---
class Parser:
    """Recursive-descent parser that evaluates arithmetic expressions on the fly."""

    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def _current(self) -> Token:
        return self.tokens[self.pos]

    def _expect(self, typ: str) -> None:
        """Consume a token of given type, or raise error."""
        if self._current().type == typ:
            self.pos += 1
        else:
            expected = f"expected {typ}, got {self._current().type}"
            if self._current().value is not None:
                expected += f" ({self._current().value!r})"
            raise ValueError(expected)

    def parse(self) -> float:
        """Start parsing from the expression rule."""
        result = self._expr()
        if self._current().type != END:
            raise ValueError(f"Unexpected token: {self._current()}")
        return result

    # Grammar:
    # expr     -> term (('+' | '-') term)*
    # term     -> factor (('*' | '/') factor)*
    # factor   -> primary ('**' factor)?
    # primary  -> NUMBER | '(' expr ')' | '-' primary

    def _expr(self) -> float:
        result = self._term()
        while self._current().type in (PLUS, MINUS):
            op = self._current().type
            self.pos += 1
            right = self._term()
            if op == PLUS:
                result += right
            else:
                result -= right
        return result

    def _term(self) -> float:
        result = self._factor()
        while self._current().type in (STAR, SLASH):
            op = self._current().type
            self.pos += 1
            right = self._factor()
            if op == STAR:
                result *= right
            else:
                if right == 0:
                    raise ValueError("Division by zero")
                result /= right
        return result

    def _factor(self) -> float:
        # Parse primary first, then handle exponent (right-associative)
        left = self._primary()
        if self._current().type == POW:
            self.pos += 1
            right = self._factor()  # right-associative: parse right-side exponent fully
            left = left ** right
        return left

    def _primary(self) -> float:
        token = self._current()
        if token.type == NUMBER:
            self.pos += 1
            return float(token.value)  # ensure float result
        elif token.type == LPAREN:
            self.pos += 1
            result = self._expr()
            if self._current().type != RPAREN:
                raise ValueError("Expected closing parenthesis")
            self.pos += 1
            return result
        elif token.type == MINUS:
            self.pos += 1
            # unary minus: parse the following primary
            return -self._primary()
        else:
            raise ValueError(f"Unexpected token: {token}")


# --- Public API ---
def evaluate(expression: str) -> float:
    """Evaluate an arithmetic expression and return the result as a float.

    Args:
        expression: A string containing an arithmetic expression.

    Returns:
        The computed floating-point result.

    Raises:
        ValueError: If the expression is syntactically incorrect, contains
            unbalanced parentheses, or attempts division by zero.
    """
    tokenizer = Tokenizer(expression)
    tokens = tokenizer.get_tokens()
    parser = Parser(tokens)
    return parser.parse()


# --- Usage Examples ---
if __name__ == "__main__":
    # Example 1: precedence (multiplication before addition)
    print(evaluate("3 + 5 * 2"))        # 3 + 10 = 13.0

    # Example 2: parentheses override precedence
    print(evaluate("(3 + 5) * 2"))      # 8 * 2 = 16.0

    # Example 3: unary minus vs exponent (exponent first)
    print(evaluate("-3 ** 2"))          # -(3^2) = -9.0

    # Example 4: exponent and unary minus combination
    print(evaluate("2 ** -3"))          # 2^(-3) = 0.125

    # Example 5: chained exponent (right-associative)
    print(evaluate("2 ** 3 ** 2"))      # 2^(3^2) = 2^9 = 512.0

    # Example 6: nested parentheses
    print(evaluate("((5 - 3) * (4 + 2)) / 2"))  # (2*6)/2 = 6.0

    # Error examples:
    try:
        print(evaluate("3 +"))
    except ValueError as e:
        print("Error caught:", e)

    try:
        print(evaluate("(3 + 5"))
    except ValueError as e:
