                    tokens.append(Token('OPERATOR', '**'))
                    i += 2
                    continue
                tokens.append(Token('OPERATOR', '*'))
                i += 1
                continue

            # Invalid character
            raise ParseError(f"Unexpected character '{char}' at position {i}")

        return tokens

    def current_token(self) -> Optional[Token]:
        """Get current token or None if at end"""
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def eat(self, token_type: str, value: Optional[str] = None) -> Token:
        """Consume current token if it matches expected type/value"""
        token = self.current_token()
        if not token:
            raise ParseError(f"Unexpected end of expression, expected {token_type}")
        if token.type != token_type:
            raise ParseError(f"Expected {token_type}, got {token.type}")
        if value is not None and token.value != value:
