# Token type: (type_name, value)
Token = Tuple[str, Union[str, float]]

def tokenize(expression: str) -> List[Token]:
    """Splits an arithmetic expression string into a list of tokens."""
    tokens: List[Token] = []
    i, n = 0, len(expression)

    while i < n:
        if expression[i].isspace():
            i += 1
        elif expression[i:i+2] == '**':
            tokens.append(('POW', '**'))
            i += 2
        elif expression[i] == '*':
            tokens.append(('MULT', '*'))
            i += 1
        elif expression[i] == '/':
            tokens.append(('DIV', '/'))
            i += 1
        elif expression[i] == '+':
            tokens.append(('PLUS', '+'))
            i += 1
        elif expression[i] == '-':
            tokens.append(('MINUS', '-'))
            i += 1
        elif expression[i] == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif expression[i] == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        elif expression[i].isdigit() or expression[i] == '.':
            j = i
            while j < n and (expression[j].isdigit() or expression[j] == '.'):
                j += 1
            num_str = expression[i:j]
            # Validate number format
            if num_str.count('.') > 1 or not any(c.isdigit() for c in num_str):
                raise ValueError(f"Invalid number format: '{num_str}'")
            tokens.append(('NUMBER', float(num_str)))
            i = j
        else:
            raise ValueError(f"Unexpected character '{expression[i]}' at index {i}")

    tokens.append(('EOF', None))
    return tokens


class Parser:
    """Recursive-descent parser that evaluates arithmetic expressions directly."""

    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current(self) -> Token:
        return self.tokens[self.pos]

    def consume(self, expected_type: str = None) -> Token:
        tok = self.current()
        if expected_type and tok[0] != expected_type:
            raise ValueError(f"Expected '{expected_type}', got '{tok[0]}'")
        self.pos += 1
        return tok

    def parse(self) -> float:
        result = self.expr()
        if self.current()[0] != 'EOF':
            raise ValueError(f"Unexpected token: {self.current()}")
        return result

    # expr     -> term (('+' | '-') term)*
    def expr(self) -> float:
        result = self.term()
        while self.current()[0] in ('PLUS', 'MINUS'):
            op = self.consume()[0]
            right = self.term()
            result = result + right if op == 'PLUS' else result - right
        return result

    # term     -> unary (('*' | '/') unary)*
    def term(self) -> float:
        result = self.unary()
        while self.current()[0] in ('MULT', 'DIV'):
            op = self.consume()[0]
            right = self.unary()
            if op == 'MULT':
                result *= right
            else:
                if right == 0.0:
                    raise ZeroDivisionError("Division by zero")
                result /= right
        return result

    # unary    -> ('-') unary | power
    def unary(self) -> float:
        if self.current()[0] == 'EOF':
            raise ValueError("Unexpected end of expression")
        if self.current()[0] == 'MINUS':
            self.consume()
            return -self.unary()
        return self.power()

    # power    -> atom ('**' power)?  (right-associative)
    def power(self) -> float:
        base = self.atom()
        if self.current()[0] == 'POW':
            self.consume()
            exp = self.power()  # Right-associative: exponent is also a power expression
            return base ** exp
        return base

    # atom     -> NUMBER | '(' expr ')'
    def atom(self) -> float:
        tok = self.current()
        if tok[0] == 'NUMBER':
            self.consume()
            return tok[1]
        elif tok[0] == 'LPAREN':
            self.consume()
            result = self.expr()
            if self.current()[0] != 'RPAREN':
                raise ValueError("Unbalanced parentheses: missing ')'")
            self.consume()
            return result
        else:
            raise ValueError(f"Unexpected token in expression: {tok}")


def evaluate(expression: str) -> float:
    """
    Public API: Parses and evaluates an arithmetic expression string.

    Supports: integers, floats, +, -, *, /, ** (right-associative), unary minus, parentheses.
    Precedence: ** > unary minus > * / > + -
    """
    tokens = tokenize(expression)
    parser = Parser(tokens)
    return parser.parse()

