import re
from typing import List, Union, Iterator

class ExpressionError(Exception):
    """Custom exception for parsing and evaluation errors."""
    pass

class Tokenizer:
    TOKEN_SPEC = [
        ('NUMBER',   r'\d+(\.\d*)?'),
        ('OP',       r'[+\-*/()]|\*\*'),
        ('SKIP',     r'\s+'),
        ('MISMATCH', r'.'),
    ]

    def __init__(self, expression: str):
        regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in self.TOKEN_SPEC)
        self.tokens: List[str] = []
        for mo in re.finditer(regex, expression):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                self.tokens.append(value)
            elif kind == 'OP':
                self.tokens.append(value)
            elif kind == 'SKIP':
                continue
            else:
                raise ExpressionError(f"Unexpected character: {value}")

class Parser:
    """
    Grammar:
    expr   -> term (('+' | '-') term)*
    term   -> unary (('*' | '/') unary)*
    unary  -> '-' unary | power
    power  -> factor ('**' power)?  (Right-associative)
    factor -> NUMBER | '(' expr ')'
    """
    def __init__(self, tokens: List[str]):
        self.tokens = tokens
        self.pos = 0

    def _peek(self) -> str:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _consume(self) -> str:
        token = self._peek()
        self.pos += 1
        return token

    def parse(self) -> float:
        result = self._expr()
        if self.pos < len(self.tokens):
            raise ExpressionError(f"Unexpected token at end: {self._peek()}")
        return result

    def _expr(self) -> float:
        node = self._term()
        while self._peek() in ('+', '-'):
            op = self._consume()
            right = self._term()
            node = node + right if op == '+' else node - right
        return node

    def _term(self) -> float:
        node = self._unary()
        while self._peek() in ('*', '/'):
            op = self._consume()
            right = self._unary()
            if op == '*': node *= right
            else:
                if right == 0: raise ExpressionError("Division by zero")
                node /= right
        return node

    def _unary(self) -> float:
        if self._peek() == '-':
            self._consume()
            return -self._unary()
        return self._power()

    def _power(self) -> float:
        node = self._factor()
        if self._peek() == '**':
            self._consume()
            node = node ** self._power() # Recursive call for right-associativity
        return node

    def _factor(self) -> float:
        token = self._consume()
        if token == '(':
            result = self._expr()
            if self._consume() != ')':
                raise ExpressionError("Unbalanced parentheses")
            return result
        try:
            return float(token)
        except (TypeError, ValueError):
            raise ExpressionError(f"Expected number or '(', got: {token}")

def evaluate(expression: str) -> float:
    tokens = Tokenizer(expression).tokens
    return Parser(tokens).parse()

# --- Usage Examples ---
if __name__ == "__main__":
