    print(f"1 + 2 * 3 = {evaluate('1 + 2 * 3')}")  # 7.0

    # 2. Parentheses and Unary Minus
    print(f"-(2 + 3) * 4 = {evaluate('-(2 + 3) * 4')}")  # -20.0

    # 3. Right-associativity of **
    # 2 ** 3 ** 2 is 2 ** 9 = 512
    print(f"2 ** 3 ** 2 = {evaluate('2 ** 3 ** 2')}")  # 512.0

from __future__ import annotations
import re
from typing import Union, List, Tuple, Optional

Number = Union[int, float]

class ParseError(Exception):
    """Raised when the input cannot be parsed."""
    pass

class EvaluationError(Exception):
    """Raised when evaluation fails (e.g., division by zero)."""
    pass

class Token:
    """Represents a token in the input stream."""
    def __init__(self, type: str, value: Optional[Union[str, Number]] = None):
        self.type = type
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.type}, {self.value})" if self.value is not None else f"Token({self.type})"

class Tokenizer:
    """Converts input string into a stream of tokens."""
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.length = len(text)

    def peek(self) -> Optional[str]:
        """Return the current character without consuming it."""
        if self.pos >= self.length:
            return None
        return self.text[self.pos]

    def consume(self) -> str:
        """Consume and return the current character."""
        char = self.peek()
        if char is None:
            raise ParseError("Unexpected end of input")
        self.pos += 1
        return char

    def skip_whitespace(self) -> None:
        """Skip any whitespace characters."""
        while self.peek() is not None and self.peek().isspace():
            self.pos += 1

    def read_number(self) -> Number:
        """Read a number (integer or float) from the input."""
        start = self.pos
        has_decimal = False

        # Read integer part
        while self.peek() is not None and self.peek().isdigit():
            self.pos += 1

        # Read decimal part if present
        if self.peek() == '.':
            has_decimal = True
            self.pos += 1
            while self.peek() is not None and self.peek().isdigit():
                self.pos += 1

        # Read exponent if present
        if self.peek() in ('e', 'E'):
            self.pos += 1
            if self.peek() in ('+', '-'):
                self.pos += 1
            while self.peek() is not None and self.peek().isdigit():
                self.pos += 1

        num_str = self.text[start:self.pos]
        try:
            if has_decimal:
                return float(num_str)
            return int(num_str)
        except ValueError:
            raise ParseError(f"Invalid number: {num_str}")

    def read_identifier(self) -> str:
        """Read an identifier (not used in this grammar but included for completeness)."""
        start = self.pos
        while self.peek() is not None and (self.peek().isalnum() or self.peek() == '_'):
            self.pos += 1
        return self.text[start:self.pos]

    def next_token(self) -> Token:
        """Return the next token from the input."""
        self.skip_whitespace()

        if self.pos >= self.length:
            return Token('EOF')

        char = self.peek()

        # Handle multi-character operators first
        if char == '**':
            self.pos += 2
            return Token('**')
        if char in ('+', '-', '*', '/', '(', ')', ','):
            self.pos += 1
            return Token(char)

        # Handle numbers
        if char.isdigit() or char == '.':
            return Token('NUMBER', self.read_number())

        # Handle identifiers (not used in this grammar)
        if char.isalpha() or char == '_':
            return Token('IDENTIFIER', self.read_identifier())

        raise ParseError(f"Unexpected character: {char}")

    def tokenize(self) -> List[Token]:
        """Convert the entire input into a list of tokens."""
        tokens = []
        while True:
            token = self.next_token()
            tokens.append(token)
            if token.type == 'EOF':
                break
        return tokens

class Parser:
    """Recursive-descent parser for arithmetic expressions."""
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Optional[Token]:
        """Return the current token without consuming it."""
        if self.pos >= len(self.tokens):
            return None
        return self.tokens[self.pos]

    def consume(self) -> Token:
        """Consume and return the current token."""
        token = self.peek()
        if token is None:
            raise ParseError("Unexpected end of input")
        self.pos += 1
        return token

    def expect(self, type: str) -> Token:
        """Consume and return the current token if it matches the expected type."""
        token = self.peek()
        if token is None or token.type != type:
            raise ParseError(f"Expected {type}, got {token.type if token else 'EOF'}")
        return self.consume()

    def parse_expression(self) -> Number:
        """Parse an expression (lowest precedence)."""
        left = self.parse_term()
        while True:
            token = self.peek()
            if token and token.type in ('+', '-'):
                op = self.consume().type
                right = self.parse_term()
                if op == '+':
                    left += right
                else:
                    left -= right
            else:
                break
        return left

    def parse_term(self) -> Number:
        """Parse a term (medium precedence)."""
        left = self.parse_factor()
        while True:
            token = self.peek()
            if token and token.type in ('*', '/'):
                op = self.consume().type
                right = self.parse_factor()
                if op == '*':
                    left *= right
                else:
                    if right == 0:
                        raise EvaluationError("Division by zero")
                    left /= right
            else:
                break
        return left

    def parse_factor(self) -> Number:
        """Parse a factor (high precedence)."""
        token = self.peek()
        if token and token.type == '-':
            # Handle unary minus
            self.consume()
            value = self.parse_factor()
            return -value
        return self.parse_power()

    def parse_power(self) -> Number:
        """Parse a power expression (highest precedence, right-associative)."""
        left = self.parse_primary()
        token = self.peek()
        if token and token.type == '**':
            self.consume()
            right = self.parse_power()  # Right-associative: parse_power() not parse_primary()
            return left ** right
        return left

    def parse_primary(self) -> Number:
        """Parse a primary expression (numbers or parenthesized expressions)."""
        token = self.peek()
        if token is None:
            raise ParseError("Unexpected end of input")

        if token.type == 'NUMBER':
            return self.consume().value  # type: ignore
        elif token.type == '(':
            self.consume()  # Consume '('
            value = self.parse_expression()
            self.expect(')')  # Consume ')'
            return value
        else:
            raise ParseError(f"Unexpected token: {token.type}")

    def parse(self) -> Number:
        """Parse the entire token stream and return the result."""
        result = self.parse_expression()
        if self.peek() and self.peek().type != 'EOF':
            raise ParseError(f"Unexpected token at end of input: {self.peek().type}")
        return result

def evaluate(expression: str) -> float:
    """
    Evaluate an arithmetic expression.

    Args:
        expression: A string containing the arithmetic expression to evaluate.

    Returns:
        The result of the evaluation as a float.

    Raises:
        ParseError: If the input cannot be parsed.
        EvaluationError: If evaluation fails (e.g., division by zero).
    """
    tokenizer = Tokenizer(expression)
    tokens = tokenizer.tokenize()
    parser = Parser(tokens)
    return float(parser.parse())

