from typing import Union, List, Tuple
import re

class ParseError(Exception):
    """Raised when the input expression is malformed."""
    pass

class EvalError(Exception):
    """Raised when evaluation fails (e.g., division by zero)."""
    pass

Token = Union[float, str]

class Tokenizer:
    """Converts an input string into a stream of tokens."""

    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.length = len(text)

    def skip_whitespace(self) -> None:
        while self.pos < self.length and self.text[self.pos].isspace():
            self.pos += 1

    def get_next_token(self) -> Token:
        self.skip_whitespace()
        if self.pos >= self.length:
            return None

        char = self.text[self.pos]

        # Handle numbers (integers and floats)
        if char.isdigit() or char == '.':
            start = self.pos
            if char == '.':
                self.pos += 1
                if self.pos >= self.length or not self.text[self.pos].isdigit():
                    raise ParseError(f"Invalid number at position {start}")
                while self.pos < self.length and self.text[self.pos].isdigit():
                    self.pos += 1
            else:
                while self.pos < self.length and self.text[self.pos].isdigit():
                    self.pos += 1
                if self.pos < self.length and self.text[self.pos] == '.':
                    self.pos += 1
                    while self.pos < self.length and self.text[self.pos].isdigit():
                        self.pos += 1
            try:
                return float(self.text[start:self.pos])
            except ValueError:
                raise ParseError(f"Invalid number at position {start}")

        # Handle operators and parentheses
        if char in '+-*/()**':
            if char == '*' and self.pos + 1 < self.length and self.text[self.pos + 1] == '*':
                self.pos += 2
                return '**'
            self.pos += 1
            return char

        raise ParseError(f"Unexpected character '{char}' at position {self.pos}")

    def tokenize(self) -> List[Token]:
        """Convert the entire input into a list of tokens."""
        tokens = []
        while True:
            token = self.get_next_token()
            if token is None:
                break
            tokens.append(token)
        return tokens

class Parser:
    """Recursive-descent parser for arithmetic expressions."""

    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0
        self.length = len(tokens)

    def peek(self) -> Token:
        """Return the current token without consuming it."""
        if self.pos >= self.length:
            return None
        return self.tokens[self.pos]

    def consume(self) -> Token:
        """Return the current token and advance the position."""
        token = self.peek()
        if token is not None:
            self.pos += 1
        return token

    def expect(self, expected: str) -> Token:
        """Consume the current token if it matches expected, else raise error."""
        token = self.consume()
        if token != expected:
            raise ParseError(f"Expected '{expected}', got '{token}'")
        return token

    def parse_expression(self) -> float:
        """Parse an expression (lowest precedence)."""
        left = self.parse_term()
        while True:
            op = self.peek()
            if op in ('+', '-'):
                self.consume()
                right = self.parse_term()
                left = left + right if op == '+' else left - right
            else:
                break
        return left

    def parse_term(self) -> float:
        """Parse a term (medium precedence)."""
        left = self.parse_factor()
        while True:
            op = self.peek()
            if op in ('*', '/'):
                self.consume()
                right = self.parse_factor()
                if op == '*':
                    left *= right
                else:
                    if right == 0:
                        raise EvalError("Division by zero")
                    left /= right
            else:
                break
        return left

    def parse_factor(self) -> float:
        """Parse a factor (high precedence)."""
        token = self.peek()
        if token == '(':
            self.consume()
            expr = self.parse_expression()
            self.expect(')')
            return expr
        elif token == '-':
            self.consume()
            return -self.parse_factor()
        elif token == '+':
            self.consume()
            return +self.parse_factor()
        else:
            return self.parse_exponent()

    def parse_exponent(self) -> float:
        """Parse an exponentiation (highest precedence, right-associative)."""
        left = self.parse_primary()
        if self.peek() == '**':
            self.consume()
            right = self.parse_exponent()  # Right-associative
            return left ** right
        return left

    def parse_primary(self) -> float:
        """Parse a primary (number)."""
        token = self.consume()
        if isinstance(token, (int, float)):
            return float(token)
        raise ParseError(f"Expected a number, got '{token}'")

def evaluate(expression: str) -> float:
    """
    Evaluate an arithmetic expression string and return the result as a float.

    Supports: integers and floats, +, -, *, /, ** (right-associative), unary minus,
    parentheses for grouping, and correct operator precedence.

    Args:
        expression: A string containing the arithmetic expression to evaluate.

    Returns:
        The result of the evaluated expression as a float.

    Raises:
        ParseError: If the input expression is malformed.
        EvalError: If evaluation fails (e.g., division by zero).
    """
    tokenizer = Tokenizer(expression)
    tokens = tokenizer.tokenize()
    if not tokens:
        raise ParseError("Empty expression")

    parser = Parser(tokens)
    try:
        result = parser.parse_expression()
    except IndexError:
        raise ParseError("Unexpected end of expression")

    # Check if there are any remaining tokens
    if parser.pos < len(tokens):
        raise ParseError(f"Unexpected token '{tokens[parser.pos]}' at position {parser.pos}")

    return result

