from typing import List, Tuple, Union

Token = Tuple[str, Union[str, float, None]]

class Tokenizer:
    """Splits an arithmetic expression string into a stream of tokens."""

    def __init__(self, text: str) -> None:
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos] if self.pos < len(self.text) else None

    def advance(self) -> None:
        self.pos += 1
        self.current_char = self.text[self.pos] if self.pos < len(self.text) else None

    def skip_whitespace(self) -> None:
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def read_number(self) -> Token:
        start = self.pos
        has_dot = False
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            if self.current_char == '.':
                if has_dot:
                    raise ValueError(f"Invalid number format at position {self.pos}")
                has_dot = True
            self.advance()

        num_str = self.text[start:self.pos]
        try:
            return ('NUMBER', float(num_str))
        except ValueError:
            raise ValueError(f"Invalid number format: '{num_str}'")

    def tokenize(self) -> List[Token]:
        tokens: List[Token] = []
        while self.current_char is not None:
            self.skip_whitespace()
            if self.current_char is None:
                break

            if self.current_char.isdigit() or self.current_char == '.':
                tokens.append(self.read_number())
            elif self.current_char == '+':
                tokens.append(('PLUS', '+'))
                self.advance()
            elif self.current_char == '-':
                tokens.append(('MINUS', '-'))
                self.advance()
            elif self.current_char == '*':
                self.advance()
                if self.current_char == '*':
                    tokens.append(('POW', '**'))
                    self.advance()
                else:
                    tokens.append(('STAR', '*'))
            elif self.current_char == '/':
                tokens.append(('SLASH', '/'))
                self.advance()
            elif self.current_char == '(':
                tokens.append(('LPAREN', '('))
                self.advance()
            elif self.current_char == ')':
                tokens.append(('RPAREN', ')'))
                self.advance()
            else:
                raise ValueError(f"Unexpected character '{self.current_char}' at position {self.pos}")

        tokens.append(('EOF', None))
        return tokens


class Parser:
    """Recursive-descent parser that evaluates arithmetic expressions directly."""

    def __init__(self, tokens: List[Token]) -> None:
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token:
        return self.tokens[self.pos]

    def eat(self, token_type: str) -> Token:
        token = self.current_token()
        if token[0] == token_type:
            self.pos += 1
            return token
        raise ValueError(f"Expected '{token_type}', got '{token[1]}' at position {self.pos}")

    def parse(self) -> float:
        result = self.expr()
        if self.current_token()[0] != 'EOF':
            raise ValueError(f"Unexpected token '{self.current_token()[1]}' at position {self.pos}")
        return result

    # expr       -> term (('+' | '-') term)*
    def expr(self) -> float:
        result = self.term()
        while self.current_token()[0] in ('PLUS', 'MINUS'):
            op = self.current_token()[0]
            self.eat(op)
            right = self.term()
            if op == 'PLUS':
                result += right
            else:
                result -= right
        return result

    # term       -> unary (('*' | '/') unary)*
    def term(self) -> float:
        result = self.unary()
        while self.current_token()[0] in ('STAR', 'SLASH'):
            op = self.current_token()[0]
            self.eat(op)
            right = self.unary()
            if op == 'STAR':
                result *= right
            else:
                if right == 0.0:
                    raise ZeroDivisionError("Division by zero")
                result /= right
        return result

    # unary      -> ('-' unary) | ('+' unary) | power
    def unary(self) -> float:
        if self.current_token()[0] == 'MINUS':
            self.eat('MINUS')
            return -self.unary()
        if self.current_token()[0] == 'PLUS':
            self.eat('PLUS')
            return self.unary()
        return self.power()

    # power      -> atom ('**' power)?  # Right-associative
    def power(self) -> float:
        base = self.atom()
        if self.current_token()[0] == 'POW':
            self.eat('POW')
            exponent = self.power()  # Recursive call ensures right-associativity
            return base ** exponent
        return base

    # atom       -> NUMBER | '(' expr ')'
    def atom(self) -> float:
        token = self.current_token()
        if token[0] == 'NUMBER':
            self.eat('NUMBER')
            return token[1]
        if token[0] == 'LPAREN':
            self.eat('LPAREN')
            result = self.expr()
            if self.current_token()[0] != 'RPAREN':
                raise ValueError("Unbalanced parentheses: missing closing ')'")
            self.eat('RPAREN')
            return result
        raise ValueError(f"Unexpected token '{token[1]}' at position {self.pos}")


def evaluate(expression: str) -> float:
    """
    Public API: Parses and evaluates an arithmetic expression string.

    Supports: integers, floats, +, -, *, /, ** (right-associative), unary minus.
    Precedence: ** > unary minus > * / > + -
    """
    if not expression.strip():
        raise ValueError("Empty expression")

    tokenizer = Tokenizer(expression)
    tokens = tokenizer.tokenize()
    parser = Parser(tokens)
    return parser.parse()


