import re
from typing import List, Tuple, Union

class ParseError(Exception):
    """Custom exception for parsing and evaluation errors."""
    pass

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Evaluator:
    """
    Recursive Descent Parser and Evaluator for arithmetic expressions.
    Grammar:
    expression : term ((PLUS | MINUS) term)*
    term       : factor ((MUL | DIV) factor)*
    factor     : power (POWER power)*  <-- Right associative
    power      : (MINUS) power | atom
    atom       : NUMBER | LPAREN expression RPAREN
    """

    def __init__(self, text: str):
        self.tokens = self._tokenize(text)
        self.pos = 0

    def _tokenize(self, text: str) -> List[Token]:
        # Regex for tokens: floats/ints, operators, and parentheses
        token_specification = [
            ('NUMBER',   r'\d+(\.\d*)?'), 
            ('POWER',    r'\*\*'),       
            ('OP',       r'[+\-*/]'),    
            ('LPAREN',   r'\('),         
            ('RPAREN',   r'\)'),         
            ('SKIP',     r'\s+'),       
            ('MISMATCH', r'.'),          
        ]
        tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)
        tokens = []
        for mo in re.finditer(tok_regex, text):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                tokens.append(Token('NUMBER', value))
            elif kind == 'POWER':
                tokens.append(Token('POWER', value))
            elif kind == 'OP':
                tokens.append(Token('OP', value))
            elif kind == 'LPAREN':
                tokens.append(Token('LPAREN', value))
            elif kind == 'RPAREN':
                tokens.append(Token('RPAREN', value))
            elif kind == 'SKIP':
                continue
            else:
                raise ParseError(f"Unexpected character: {value}")
        return tokens

    def _peek(self) -> Union[Token, None]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _consume(self, expected_type: str = None) -> Token:
        token = self._peek()
        if not token:
            raise ParseError("Unexpected end of input")
        if expected_type and token.type != expected_type:
            raise ParseError(f"Expected {expected_type}, got {token.type}")
        self.pos += 1
        return token

    def parse_expression(self) -> float:
        # Handle + and -
        node = self.parse_term()
        while (token := self._peek()) and token.type == 'OP' and token.value in ('+', '-'):
            op = self._consume().value
            right = self.parse_term()
            node = node + right if op == '+' else node - right
        return node

    def parse_term(self) -> float:
        # Handle * and /
        node = self.parse_factor()
        while (token := self._peek()) and token.type == 'OP' and token.value in ('*', '/'):
            op = self._consume().value
            right = self.parse_factor()
            if op == '/':
                if right == 0:
                    raise ParseError("Division by zero")
                node /= right
            else:
                node *= right
        return node

    def parse_factor(self) -> float:
        # Handle ** (Right Associative)
        node = self.parse_power()
        if (token := self._peek()) and token.type == 'POWER':
            self._consume() # consume **
            # Recursive call to parse_factor instead of a loop ensures right-associativity
            node = node ** self.parse_factor()
        return node

    def parse_power(self) -> float:
        # Handle Unary Minus
        if (token := self._peek()) and token.type == 'OP' and token.value == '-':
            self._consume()
            return -self.parse_power()
        return self.parse_atom()

    def parse_atom(self) -> float:
        token = self._peek()
        if not token:
            raise ParseError("Unexpected end of expression")

        if token.type == 'NUMBER':
            self._consume()
            return float(token.value)
        elif token.type == 'LPAREN':
            self._consume() # consume (
            result = self.parse_expression()
            self._consume('RPAREN') # consume )
            return result
        else:
            raise ParseError(f"Unexpected token: {token.value}")

def evaluate(expression: str) -> float:
    """
    Public API to evaluate an arithmetic expression.
    """
    evaluator = Evaluator(expression)
    result = evaluator.parse_expression()
    if evaluator.pos < len(evaluator.tokens):
        raise ParseError(f"Unexpected token at end: {evaluator.tokens[evaluator.pos].value}")
    return result

