import re
from typing import Union

class ParseError(Exception):
    """Custom exception for parsing errors."""
    pass

class Token:
    """Class representing a token."""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Tokenizer:
    """Tokenizer for splitting input string into tokens."""
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.current_char = self.expression[self.position] if self.expression else None

    def advance(self):
        """Advance the position and update the current character."""
        self.position += 1
        if self.position < len(self.expression):
            self.current_char = self.expression[self.position]
        else:
            self.current_char = None

    def skip_whitespace(self):
        """Skip whitespace characters."""
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self) -> Token:
        """Parse a number (integer or float)."""
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return Token('NUMBER', float(num_str))

    def get_next_token(self) -> Token:
        """Get the next token from the input."""
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()
            if self.current_char == '+':
                self.advance()
                return Token('PLUS', '+')
            if self.current_char == '-':
                self.advance()
                return Token('MINUS', '-')
            if self.current_char == '*':
                self.advance()
                return Token('MUL', '*')
            if self.current_char == '/':
                self.advance()
                return Token('DIV', '/')
            if self.current_char == '(':
                self.advance()
                return Token('LPAREN', '(')
            if self.current_char == ')':
                self.advance()
                return Token('RPAREN', ')')
            if self.current_char == '^':
                self.advance()
                return Token('POW', '^')
            raise ParseError(f"Unexpected character: {self.current_char}")
        return Token('EOF', None)

class Parser:
    """Parser for evaluating arithmetic expressions."""
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer
        self.current_token = self.tokenizer.get_next_token()

    def error(self):
        """Raise a parsing error."""
        raise ParseError(f"Invalid syntax at token: {self.current_token}")

    def eat(self, token_type: str):
        """Consume the current token if it matches the expected type."""
        if self.current_token.type == token_type:
            self.current_token = self.tokenizer.get_next_token()
        else:
            self.error()

    def factor(self) -> float:
        """Parse a factor (number or parenthesized expression)."""
        if self.current_token.type == 'NUMBER':
            value = self.current_token.value
            self.eat('NUMBER')
            return value
        elif self.current_token.type == 'LPAREN':
            self.eat('LPAREN')
            value = self.expr()
            self.eat('RPAREN')
            return value
        elif self.current_token.type == 'MINUS':
            self.eat('MINUS')
            return -self.factor()
        self.error()

    def power(self) -> float:
        """Parse exponentiation."""
        result = self.factor()
        while self.current_token.type == 'POW':
            self.eat('POW')
            result **= self.factor()
        return result

    def term(self) -> float:
        """Parse multiplication and division."""
        result = self.power()
        while self.current_token.type in ('MUL', 'DIV'):
            if self.current_token.type == 'MUL':
                self.eat('MUL')
                result *= self.power()
            elif self.current_token.type == 'DIV':
                self.eat('DIV')
                divisor = self.power()
                if divisor == 0:
                    raise ParseError("Division by zero")
                result /= divisor
        return result

    def expr(self) -> float:
        """Parse addition and subtraction."""
        result = self.term()
        while self.current_token.type in ('PLUS', 'MINUS'):
            if self.current_token.type == 'PLUS':
                self.eat('PLUS')
                result += self.term()
            elif self.current_token.type == 'MINUS':
                self.eat('MINUS')
                result -= self.term()
        return result

def evaluate(expression: str) -> float:
    """Public API to evaluate an arithmetic expression."""
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    result = parser.expr()
    if parser.current_token.type != 'EOF':
        raise ParseError("Unexpected input after expression")
    return result

# Usage examples
if __name__ == "__main__":
    print(evaluate("3 + 5"))                 # 8.0
    print(evaluate("(2 + 3) * (5 - 2)"))     # 15.0
    print(evaluate("-2 ** 3"))                # -8.0

import re
from typing import Union, List

class ParseError(Exception):
    """Custom exception for parsing errors."""
    pass

class Token:
    """Represents a single token in the token stream."""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Tokenizer:
    """Tokenizes the input string into a stream of tokens."""
    def __init__(self, expression: str):
        self.tokens: List[Token] = []
        self.current_token_index: int = 0
        self.tokenize(expression)

    def tokenize(self, expression: str):
        # Regular expression for tokenizing
        token_specification = [
            ('NUMBER', r'\d+(\.\d*)?'),  # Integer or decimal number
            ('PLUS', r'\+'),              # Addition
            ('MINUS', r'-'),             # Subtraction
            ('TIMES', r'\*'),             # Multiplication
            ('DIVIDE', r'/'),             # Division
            ('POWER', r'\*\*'),           # Exponentiation
            ('LPAREN', r'\('),            # Left Parenthesis
            ('RPAREN', r'\)'),            # Right Parenthesis
            ('SKIP', r'[ \t]+'),          # Skip over spaces and tabs
            ('MISMATCH', r'.'),           # Any other character
        ]
        tok_regex = '|'.join(f'(?P<{pair[0]}>{pair[1]})' for pair in token_specification)
        for mo in re.finditer(tok_regex, expression):
            kind = mo.lastgroup
            value = mo.group(kind)
            if kind == 'NUMBER':
                value = float(value) if '.' in value else int(value)
                self.tokens.append(Token('NUMBER', value))
            elif kind in {'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'POWER', 'LPAREN', 'RPAREN'}:
                self.tokens.append(Token(kind, value))
            elif kind == 'MISMATCH':
                raise ParseError(f"Unexpected character: {value}")

    def next_token(self) -> Token:
        if self.current_token_index < len(self.tokens):
            token = self.tokens[self.current_token_index]
            self.current_token_index += 1
            return token
        return Token('EOF', None)

class Parser:
    """Parses the token stream and evaluates the expression."""
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer
        self.current_token = self.tokenizer.next_token()

    def error(self, message: str):
        raise ParseError(message)

    def eat(self, token_type: str):
        if self.current_token.type == token_type:
            self.current_token = self.tokenizer.next_token()
        else:
            self.error(f"Expected token {token_type}, got {self.current_token.type}")

    def parse(self) -> float:
        return self.expr()

    def expr(self) -> float:
        """expr : term ((PLUS | MINUS) term)*"""
        result = self.term()
        while self.current_token.type in {'PLUS', 'MINUS'}:
            if self.current_token.type == 'PLUS':
                self.eat('PLUS')
                result += self.term()
            elif self.current_token.type == 'MINUS':
                self.eat('MINUS')
                result -= self.term()
        return result

    def term(self) -> float:
        """term : factor ((TIMES | DIVIDE) factor)*"""
        result = self.factor()
        while self.current_token.type in {'TIMES', 'DIVIDE'}:
            if self.current_token.type == 'TIMES':
                self.eat('TIMES')
                result *= self.factor()
            elif self.current_token.type == 'DIVIDE':
                self.eat('DIVIDE')
                divisor = self.factor()
                if divisor == 0:
                    self.error("Division by zero")
                result /= divisor
        return result

    def factor(self) -> float:
        """factor : (PLUS | MINUS) factor | power | LPAREN expr RPAREN"""
        if self.current_token.type == 'PLUS':
            self.eat('PLUS')
            return self.factor()
        elif self.current_token.type == 'MINUS':
            self.eat('MINUS')
            return -self.factor()
        elif self.current_token.type == 'LPAREN':
            self.eat('LPAREN')
            result = self.expr()
            self.eat('RPAREN')
            return result
        else:
            return self.power()

    def power(self) -> float:
        """power : atom (POWER atom)*"""
        result = self.atom()
        while self.current_token.type == 'POWER':
            self.eat('POWER')
            result **= self.atom()
        return result

    def atom(self) -> float:
        """atom : NUMBER"""
        if self.current_token.type == 'NUMBER':
            value = self.current_token.value
            self.eat('NUMBER')
            return value
        self.error("Expected a number")

def evaluate(expression: str) -> float:
    """Evaluates an arithmetic expression and returns the result."""
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    return parser.parse()

# Usage examples
if __name__ == "__main__":
    print(evaluate("3 + 5"))                # Output: 8.0
    print(evaluate("10 + 2 * 6"))           # Output: 22.0
    print(evaluate("100 * 2 + 12"))         # Output: 212.0
    print(evaluate("100 * (2 + 12)"))       # Output: 1400.0
    print(evaluate("100 * (2 + 12) / 14"))  # Output: 100.0
    print(evaluate("-3 + 5"))               # Output: 2.0
    print(evaluate("2 ** 3 ** 2"))          # Output: 512.0

import re
from typing import Iterator, NamedTuple, Union

class Token(NamedTuple):
    type: str
    value: Union[str, float]

class ParseError(Exception):
    """Raised when the expression is syntactically invalid."""
    pass

class Evaluator:
    """
    Grammar:
    expression   ::= term (('+' | '-') term)*
    term         ::= factor (('*' | '/') factor)*
    factor       ::= unary ('**' factor)?
    unary        ::= '-' unary | primary
    primary      ::= NUMBER | '(' expression ')'
    """

    def __init__(self, expression: str):
        self.tokens = self._tokenize(expression)
        self.current_token = next(self.tokens, None)

    def _tokenize(self, expr: str) -> Iterator[Token]:
        token_specification = [
            ('NUMBER',   r'\d+(\.\d*)?'),
            ('OP',       r'\*\*|[\+\-\*\/\(\)]'),
            ('SKIP',     r'\s+'),
            ('MISMATCH', r'.'),
        ]
        regex = re.compile('|'.join(f'(?P<{name}>{pattern})' for name, pattern in token_specification))
        for match in regex.finditer(expr):
            kind = match.lastgroup
            value = match.group()
            if kind == 'NUMBER':
                yield Token(kind, float(value))
            elif kind == 'OP':
                yield Token(kind, value)
            elif kind == 'MISMATCH':
                raise ParseError(f"Unexpected character: {value}")

    def _consume(self, expected_value: str = None):
        if expected_value and (not self.current_token or self.current_token.value != expected_value):
            raise ParseError(f"Expected '{expected_value}', got {self.current_token}")
        self.current_token = next(self.tokens, None)

    def evaluate(self) -> float:
        result = self._expression()
        if self.current_token is not None:
            raise ParseError(f"Unexpected token: {self.current_token.value}")
        return result

    def _expression(self) -> float:
        node = self._term()
        while self.current_token and self.current_token.value in ('+', '-'):
            op = self.current_token.value
            self._consume()
            right = self._term()
            node = node + right if op == '+' else node - right
        return node

    def _term(self) -> float:
        node = self._factor()
        while self.current_token and self.current_token.value in ('*', '/'):
            op = self.current_token.value
            self._consume()
            right = self._factor()
            if op == '*':
                node *= right
            else:
                if right == 0: raise ZeroDivisionError("Division by zero")
                node /= right
        return node

    def _factor(self) -> float:
        node = self._unary()
        if self.current_token and self.current_token.value == '**':
            self._consume()
            node = node ** self._factor()
        return node

    def _unary(self) -> float:
        if self.current_token and self.current_token.value == '-':
            self._consume()
            return -self._unary()
        return self._primary()

    def _primary(self) -> float:
        token = self.current_token
        if not token:
            raise ParseError("Unexpected end of expression")
        if token.type == 'NUMBER':
            self._consume()
            return token.value
        if token.value == '(':
            self._consume()
            result = self._expression()
            self._consume(')')
            return result
        raise ParseError(f"Unexpected token: {token.value}")

def evaluate(expression: str) -> float:
    """Public API to evaluate arithmetic expressions."""
    return Evaluator(expression).evaluate()

# Usage Examples
if __name__ == "__main__":
    # 1. Precedence: * before +
    print(f"1 + 2 * 3 = {evaluate('1 + 2 * 3')}")  # 7.0

    # 2. Parentheses: overrides precedence
    print(f"(1 + 2) * 3 = {evaluate('(1 + 2) * 3')}")  # 9.0

    # 3. Unary minus and Exponentiation (right-associative)
    # -3**2 is -(3**2) = -9.0
    print(f"-3**2 = {evaluate('-3**2')}")  # -9.0

    # 4. Complex nested
    print(f"2**3**2 = {evaluate('2**3**2')}")  # 512.0 (2**(3**2))

import re
from typing import Union, List, Tuple
from enum import Enum, auto

class TokenType(Enum):
    INTEGER = auto()
    FLOAT = auto()
    PLUS = auto()
    MINUS = auto()
    STAR = auto()
    SLASH = auto()
    STARSTAR = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()

class Token:
    def __init__(self, type_: TokenType, value: Union[int, float, str] = None):
        self.type = type_
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})" if self.value is not None else f"Token({self.type})"

class ParseError(Exception):
    """Raised when the input expression is malformed."""
    pass

class EvaluationError(Exception):
    """Raised when evaluation fails (e.g., division by zero)."""
    pass

class Lexer:
    """Tokenizes arithmetic expressions into a stream of tokens."""

    def __init__(self, text: str):
        self.text = text
        self.position = 0
        self.current_char = self.text[self.position] if self.text else None

    def advance(self) -> None:
        """Move to the next character in the input."""
        self.position += 1
        if self.position < len(self.text):
            self.current_char = self.text[self.position]
        else:
            self.current_char = None

    def skip_whitespace(self) -> None:
        """Skip any whitespace characters."""
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def integer(self) -> int:
        """Consume and return an integer token."""
        result = []
        while self.current_char is not None and self.current_char.isdigit():
            result.append(self.current_char)
            self.advance()
        return int("".join(result))

    def float_(self) -> float:
        """Consume and return a float token."""
        result = []
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result.append(self.current_char)
            self.advance()
        return float("".join(result))

    def get_next_token(self) -> Token:
        """Lexical analyzer (also known as scanner or tokenizer)."""
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue

            if self.current_char.isdigit():
                # Check if it's a float by looking ahead for a decimal point
                peek_pos = self.position
                while peek_pos < len(self.text) and (self.text[peek_pos].isdigit() or self.text[peek_pos] == '.'):
                    peek_pos += 1
                if peek_pos < len(self.text) and self.text[peek_pos] == '.':
                    return Token(TokenType.FLOAT, self.float_())
                return Token(TokenType.INTEGER, self.integer())

            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS)

            if self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS)

            if self.current_char == '*':
                self.advance()
                if self.current_char == '*':
                    self.advance()
                    return Token(TokenType.STARSTAR)
                return Token(TokenType.STAR)

            if self.current_char == '/':
                self.advance()
                return Token(TokenType.SLASH)

            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN)

            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN)

            raise ParseError(f"Unexpected character: '{self.current_char}' at position {self.position}")

        return Token(TokenType.EOF)

class Parser:
    """Recursive-descent parser for arithmetic expressions."""

    def __init__(self, lexer: Lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def eat(self, token_type: TokenType) -> None:
        """Consume the current token if it matches the expected type."""
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            raise ParseError(f"Expected {token_type}, got {self.current_token.type} at position {self.lexer.position}")

    def factor(self) -> float:
        """factor : (PLUS | MINUS) factor | INTEGER | FLOAT | LPAREN expr RPAREN"""
        token = self.current_token
        if token.type == TokenType.PLUS:
            self.eat(TokenType.PLUS)
            return self.factor()
        elif token.type == TokenType.MINUS:
            self.eat(TokenType.MINUS)
            return -self.factor()
        elif token.type == TokenType.INTEGER:
            self.eat(TokenType.INTEGER)
            return float(token.value)
        elif token.type == TokenType.FLOAT:
            self.eat(TokenType.FLOAT)
            return token.value
        elif token.type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            result = self.expr()
            self.eat(TokenType.RPAREN)
            return result
        else:
            raise ParseError(f"Unexpected token {token} in factor")

    def term(self) -> float:
        """term : factor ((STAR | SLASH) factor)*"""
        result = self.factor()

        while self.current_token.type in (TokenType.STAR, TokenType.SLASH):
            token = self.current_token
            if token.type == TokenType.STAR:
                self.eat(TokenType.STAR)
                result *= self.factor()
            elif token.type == TokenType.SLASH:
                self.eat(TokenType.SLASH)
                divisor = self.factor()
                if divisor == 0:
                    raise EvaluationError("Division by zero")
                result /= divisor

        return result

    def expr(self) -> float:
        """expr   : term ((PLUS | MINUS) term)*"""
        result = self.term()

        while self.current_token.type in (TokenType.PLUS, TokenType.MINUS):
            token = self.current_token
            if token.type == TokenType.PLUS:
                self.eat(TokenType.PLUS)
                result += self.term()
            elif token.type == TokenType.MINUS:
                self.eat(TokenType.MINUS)
                result -= self.term()

        return result

    def parse(self) -> float:
        """Parse the entire expression and return the result."""
        return self.expr()

def evaluate(expression: str) -> float:
    """
    Evaluate an arithmetic expression string and return the result as a float.

    Args:
        expression: A string containing a valid arithmetic expression

    Returns:
        The result of evaluating the expression

    Raises:
        ParseError: If the expression is malformed
        EvaluationError: If evaluation fails (e.g., division by zero)
    """
    if not expression or not expression.strip():
        raise ParseError("Empty expression")

    try:
        lexer = Lexer(expression)
        parser = Parser(lexer)
        return parser.parse()
    except IndexError as e:
        raise ParseError(f"Unexpected end of input: {e}")
    except ParseError:
        raise
    except EvaluationError:
        raise
    except Exception as e:
        raise ParseError(f"Error evaluating expression: {e}")

