from typing import List, Tuple, Union

Token = Tuple[str, Union[str, float]]

def tokenize(expression: str) -> List[Token]:
    """Splits an arithmetic expression string into a stream of tokens."""
    tokens: List[Token] = []
    i = 0
    n = len(expression)

    while i < n:
        c = expression[i]

        if c.isspace():
            i += 1
        elif c.isdigit() or c == '.':
            j = i
            while j < n and (expression[j].isdigit() or expression[j] == '.'):
                j += 1
            num_str = expression[i:j]
            try:
                tokens.append(('NUMBER', float(num_str)))
            except ValueError:
                raise ValueError(f"Invalid number format: '{num_str}'")
            i = j
        elif c == '*':
            if i + 1 < n and expression[i+1] == '*':
                tokens.append(('POW', '**'))
                i += 2
            else:
                tokens.append(('MUL', '*'))
                i += 1
        elif c == '+':
            tokens.append(('PLUS', '+'))
            i += 1
        elif c == '-':
            tokens.append(('MINUS', '-'))
            i += 1
        elif c == '/':
            tokens.append(('DIV', '/'))
            i += 1
        elif c == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif c == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        else:
            raise ValueError(f"Unexpected character: '{c}'")

    tokens.append(('EOF', None))
    return tokens


class ArithmeticParser:
    """Recursive-descent parser that evaluates arithmetic expressions directly."""

    def __init__(self, tokens: List[Token]) -> None:
        self.tokens = tokens
        self.pos = 0

    def current(self) -> Token:
        return self.tokens[self.pos]

    def consume(self, expected_type: str = None) -> Token:
        tok = self.current()
        if expected_type and tok[0] != expected_type:
            raise ValueError(f"Expected {expected_type}, got {tok[0]}")
        self.pos += 1
        return tok

    def parse(self) -> float:
        result = self.expr()
        if self.current()[0] != 'EOF':
            raise ValueError(f"Unexpected token after expression: {self.current()}")
        return result

    # Grammar (lowest to highest precedence):
    # expr     -> term (('+' | '-') term)*
    # term     -> power (('*' | '/') power)*
    # power    -> unary ('**' power)?          # Right-associative
    # unary    -> ('-' | '+') power | primary
    # primary  -> NUMBER | '(' expr ')'

    def expr(self) -> float:
        left = self.term()
        while self.current()[0] in ('PLUS', 'MINUS'):
            op = self.consume()[0]
            right = self.term()
            if op == 'PLUS':
                left += right
            else:
                left -= right
        return left

    def term(self) -> float:
        left = self.power()
        while self.current()[0] in ('MUL', 'DIV'):
            op = self.consume()[0]
            right = self.power()
            if op == 'MUL':
                left *= right
            else:
                if right == 0.0:
                    raise ZeroDivisionError("Division by zero")
                left /= right
        return left

    def power(self) -> float:
        base = self.unary()
        if self.current()[0] == 'POW':
            self.consume()
            # Right-associative: recursively call power() for the exponent
            exponent = self.power()
            return base ** exponent
        return base

    def unary(self) -> float:
        if self.current()[0] in ('PLUS', 'MINUS'):
            op = self.consume()[0]
            val = self.power()
            return -val if op == 'MINUS' else val
        return self.primary()

    def primary(self) -> float:
        tok = self.current()
        if tok[0] == 'NUMBER':
            self.consume()
            return tok[1]
        elif tok[0] == 'LPAREN':
            self.consume()
            val = self.expr()
            if self.current()[0] != 'RPAREN':
                raise ValueError("Unbalanced parentheses: missing closing ')'")
            self.consume()
            return val
        else:
            raise ValueError(f"Unexpected token in primary expression: {tok}")


def evaluate(expression: str) -> float:
    """
    Public API: Parses and evaluates an arithmetic expression string.

    Supports: integers, floats, +, -, *, /, ** (right-associative), unary minus.
    Precedence: ** > unary minus > * / > + -
    """
    tokens = tokenize(expression)
    parser = ArithmeticParser(tokens)
    return parser.parse()


