import re
from typing import Iterator, NamedTuple, Optional

class Token(NamedTuple):
    type: str
    value: str

class ParseError(Exception):
    """Raised when the input expression is malformed."""
    pass

class Evaluator:
    """
    Grammar:
    expression   ::= term {('+' | '-') term}
    term         ::= factor {('*' | '/') factor}
    factor       ::= unary ['**' factor]
    unary        ::= '-' unary | primary
    primary      ::= NUMBER | '(' expression ')'
    """

    def __init__(self, expression: str):
        self.tokens = self._tokenize(expression)
        self.current_token: Optional[Token] = None
        self._advance()

    def _tokenize(self, expression: str) -> Iterator[Token]:
        token_specification = [
            ('NUMBER',   r'\d+(\.\d*)?'),
            ('OP',       r'\*\*|[+\-*/()]'),
            ('SKIP',     r'\s+'),
            ('MISMATCH', r'.'),
        ]
        tok_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in token_specification)
        for mo in re.finditer(tok_regex, expression):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                yield Token(kind, value)
            elif kind == 'OP':
                yield Token(kind, value)
            elif kind == 'SKIP':
                continue
            else:
                raise ParseError(f"Unexpected character: {value}")
        yield Token('EOF', '')

    def _advance(self) -> None:
        self.current_token = next(self.tokens)

    def _consume(self, value: str) -> None:
        if self.current_token and self.current_token.value == value:
            self._advance()
        else:
            raise ParseError(f"Expected '{value}', got '{self.current_token.value}'")

    def _parse_primary(self) -> float:
        token = self.current_token
        if token.type == 'NUMBER':
            self._advance()
            return float(token.value)
        if token.value == '(':
            self._advance()
            result = self._parse_expression()
            self._consume(')')
            return result
        raise ParseError(f"Unexpected token: {token.value}")

    def _parse_unary(self) -> float:
        if self.current_token.value == '-':
            self._advance()
            return -self._parse_unary()
        return self._parse_primary()

    def _parse_factor(self) -> float:
        left = self._parse_unary()
        if self.current_token.value == '**':
            self._advance()
            return left ** self._parse_factor()
        return left

    def _parse_term(self) -> float:
        left = self._parse_factor()
        while self.current_token.value in ('*', '/'):
            op = self.current_token.value
            self._advance()
            right = self._parse_factor()
            if op == '*':
                left *= right
            else:
                if right == 0:
                    raise ParseError("Division by zero")
                left /= right
        return left

    def _parse_expression(self) -> float:
        left = self._parse_term()
        while self.current_token.value in ('+', '-'):
            op = self.current_token.value
            self._advance()
            right = self._parse_term()
            if op == '+':
                left += right
            else:
                left -= right
        return left

def evaluate(expression: str) -> float:
    """Public API to evaluate an arithmetic expression string."""
    parser = Evaluator(expression)
    result = parser._parse_expression()
    if parser.current_token.type != 'EOF':
        raise ParseError(f"Unexpected token at end: {parser.current_token.value}")
    return result

# Usage Examples
if __name__ == "__main__":
    # Precedence: * before +
    print(f"1 + 2 * 3 = {evaluate('1 + 2 * 3')}")  # 7.0

    # Parentheses and Unary Minus
    print(f"-(2 + 3) * 4 = {evaluate('-(2 + 3) * 4')}")  # -20.0

    # Right-associativity of exponentiation: 2**3**2 = 2**(3**2) = 512
    print(f"2**3**2 = {evaluate('2**3**2')}")  # 512.0

import re
from typing import Union, List

class ParseError(Exception):
    """Custom exception for parsing errors."""
    pass

class Token:
    """Represents a token in the input expression."""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.type}, {self.value})"

class Tokenizer:
    """Tokenizes the input string into a stream of tokens."""
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.tokens: List[Token] = []
        self.tokenize()

    def tokenize(self) -> None:
        """Tokenizes the input expression."""
        token_specification = [
            ('NUMBER', r'\d+(\.\d*)?'),  # Integer or decimal number
            ('PLUS', r'\+'),              # Addition operator
            ('MINUS', r'-'),              # Subtraction operator
            ('TIMES', r'\*'),             # Multiplication operator
            ('DIVIDE', r'/'),             # Division operator
            ('POWER', r'\*\*'),           # Exponentiation operator
            ('LPAREN', r'\('),            # Left parenthesis
            ('RPAREN', r'\)'),            # Right parenthesis
            ('SKIP', r'[ \t]+'),          # Skip over spaces and tabs
            ('MISMATCH', r'.'),           # Any other character
        ]
        tok_regex = '|'.join(f'(?P<{pair[0]}>{pair[1]})' for pair in token_specification)
        for mo in re.finditer(tok_regex, self.expression):
            kind = mo.lastgroup
            value = mo.group(kind)
            if kind == 'NUMBER':
                value = float(value) if '.' in value else int(value)
                self.tokens.append(Token('NUMBER', value))
            elif kind in {'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'POWER', 'LPAREN', 'RPAREN'}:
                self.tokens.append(Token(kind, value))
            elif kind == 'MISMATCH':
                raise ParseError(f"Unexpected character: {value}")
        self.tokens.append(Token('EOF', None))  # End of file token

    def next_token(self) -> Token:
        """Returns the next token in the stream."""
        if self.tokens:
            return self.tokens.pop(0)
        return Token('EOF', None)

class Parser:
    """Parses tokens and evaluates arithmetic expressions."""
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer
        self.current_token = self.tokenizer.next_token()

    def error(self, message: str) -> None:
        """Raises a parsing error with a descriptive message."""
        raise ParseError(message)

    def eat(self, token_type: str) -> None:
        """Consumes the current token if it matches the expected type."""
        if self.current_token.type == token_type:
            self.current_token = self.tokenizer.next_token()
        else:
            self.error(f"Expected token {token_type}, got {self.current_token.type}")

    def factor(self) -> float:
        """Parses a factor: NUMBER | LPAREN expression RPAREN | unary minus factor."""
        if self.current_token.type == 'NUMBER':
            value = self.current_token.value
            self.eat('NUMBER')
            return value
        elif self.current_token.type == 'LPAREN':
            self.eat('LPAREN')
            value = self.expression()
            self.eat('RPAREN')
            return value
        elif self.current_token.type == 'MINUS':
            self.eat('MINUS')
            return -self.factor()
        self.error("Invalid factor")

    def term(self) -> float:
        """Parses a term: factor ( (TIMES | DIVIDE) factor )*."""
        result = self.factor()
        while self.current_token.type in {'TIMES', 'DIVIDE'}:
            if self.current_token.type == 'TIMES':
                self.eat('TIMES')
                result *= self.factor()
            elif self.current_token.type == 'DIVIDE':
                self.eat('DIVIDE')
                divisor = self.factor()
                if divisor == 0:
                    self.error("Division by zero")
                result /= divisor
        return result

    def power(self) -> float:
        """Parses a power: term (POWER term)*."""
        result = self.term()
        while self.current_token.type == 'POWER':
            self.eat('POWER')
            result **= self.term()
        return result

    def expression(self) -> float:
        """Parses an expression: power ( (PLUS | MINUS) power )*."""
        result = self.power()
        while self.current_token.type in {'PLUS', 'MINUS'}:
            if self.current_token.type == 'PLUS':
                self.eat('PLUS')
                result += self.power()
            elif self.current_token.type == 'MINUS':
                self.eat('MINUS')
                result -= self.power()
        return result

def evaluate(expression: str) -> float:
    """Evaluates an arithmetic expression and returns the result."""
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    result = parser.expression()
    if parser.current_token.type != 'EOF':
        raise ParseError("Unexpected tokens at the end of the expression")
    return result

# Usage examples
if __name__ == "__main__":
    print(evaluate("3 + 5 * 2"))             # 13.0
    print(evaluate("(2 + 3) ** 2"))          # 25.0
    print(evaluate("-4 + 2 * (3 - 1)"))      # 0.0

