import math

class Token:
    def __init__(self, type: str, value: Union[int, float, str]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class ParserError(Exception):
    pass

class EvaluatorError(Exception):
    pass

def tokenize(expression: str) -> List[Token]:
    tokens = []
    i = 0
    n = len(expression)

    while i < n:
        c = expression[i]

        if c.isspace():
            i += 1
            continue

        if c.isdigit() or c == '.':
            # Parse number (int or float)
            j = i
            while j < n and (expression[j].isdigit() or expression[j] == '.'):
                j += 1
            num_str = expression[i:j]
            if '.' in num_str:
                tokens.append(Token('FLOAT', float(num_str)))
            else:
                tokens.append(Token('INT', int(num_str)))
            i = j
        elif c in '+-*/()**':
            if c == '*' and i + 1 < n and expression[i+1] == '*':
                tokens.append(Token('POW', '**'))
                i += 2
            else:
                tokens.append(Token('OP', c))
                i += 1
        else:
            raise ParserError(f"Unexpected character: '{c}' at position {i}")

    return tokens

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Optional[Token]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self) -> Token:
        token = self.peek()
        if token is None:
            raise ParserError("Unexpected end of input")
        self.pos += 1
        return token

    def parse_expression(self) -> float:
        return self.parse_add_sub()

    def parse_add_sub(self) -> float:
        left = self.parse_mul_div()
        while True:
            token = self.peek()
            if token and token.type == 'OP' and token.value in '+-':
                op = self.consume().value
                right = self.parse_mul_div()
                if op == '+':
                    left += right
                else:
                    left -= right
            else:
                break
        return left

    def parse_mul_div(self) -> float:
        left = self.parse_pow()
        while True:
            token = self.peek()
            if token and token.type == 'OP' and token.value in '*/':
                op = self.consume().value
                right = self.parse_pow()
                if op == '*':
                    left *= right
                else:
                    if right == 0:
                        raise EvaluatorError("Division by zero")
                    left /= right
            else:
                break
        return left

    def parse_pow(self) -> float:
        left = self.parse_unary_minus()
        token = self.peek()
        if token and token.type == 'POW':
            self.consume()
            right = self.parse_pow()  # Right-associative
            return left ** right
        return left

    def parse_unary_minus(self) -> float:
        token = self.peek()
        if token and token.type == 'OP' and token.value == '-':
            self.consume()
            return -self.parse_unary_minus()
        return self.parse_primary()

    def parse_primary(self) -> float:
        token = self.consume()

        if token.type == 'INT' or token.type == 'FLOAT':
            return float(token.value)
        elif token.type == 'OP' and token.value == '(':
            expr = self.parse_expression()
            if self.consume().type != 'OP' or self.consume().value != ')':
                raise ParserError("Expected closing parenthesis")
            return expr
        else:
            raise ParserError(f"Unexpected token: {token}")

def evaluate(expression: str) -> float:
    tokens = tokenize(expression)
    parser = Parser(tokens)
    return parser.parse_expression()

