        return f"Token({self.type}, {self.value})"

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.tokens = []
        self._tokenize()

    def _tokenize(self):
        token_specs = [
            ('NUMBER', r'\d+(\.\d*)?|\.\d+'),
            ('PLUS', r'\+'),
            ('MINUS', r'-'),
            ('MULTIPLY', r'\*'),
            ('DIVIDE', r'/'),
            ('POWER', r'\*\*'),
            ('LPAREN', r'\('),
            ('RPAREN', r'\)'),
            ('SKIP', r'\s+'), # Skip whitespace
        ]

        token_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in token_specs)

        for match in re.finditer(token_regex, self.text):
            token_type = match.lastgroup
            token_value = match.group(token_type)

            if token_type == 'SKIP':
                continue
            elif token_type == 'NUMBER':
                self.tokens.append(Token(token_type, token_value))
            elif token_type in ['PLUS', 'MINUS', 'MULTIPLY', 'DIVIDE', 'POWER', 'LPAREN', 'RPAREN']:
                self.tokens.append(Token(token_type, token_value))
            else:
                raise Exception(f"Unexpected character: {token_value}")

        self.tokens.append(Token('EOF', '')) # End of file token

    def get_next_token(self) -> Token:
        if self.pos >= len(self.tokens):
            return Token('EOF', '')
        token = self.tokens[self.pos]
        self.pos += 1
        return token

    def peek(self) -> Token:
        if self.pos >= len(self.tokens):
            return Token('EOF', '')
        return self.tokens[self.pos]

