            if current_char == '^': # Using ^ for **
                self.pos += 1
                return Token("POWER", '^')
            if current_char == '(':
                self.pos += 1
                return Token("LPAREN", '(')
            if current_char == ')':
                self.pos += 1
                return Token("RPAREN", ')')

            self.error(f"Unexpected character '{current_char}'")

        return Token("EOF", "")

class Parser:
    def __init__(self, lexer: Lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self, message: str = "Invalid syntax"):
        raise Exception(f"Parser Error: {message} at token {self.current_token}")

    def eat(self, token_type: str):
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error(f"Expected {token_type}, got {self.current_token.type}")

    def factor(self) -> float:
        token = self.current_token
        if token.type == "PLUS":
            self.eat("PLUS")
            return +self.factor()
        elif token.type == "MINUS":
            self.eat("MINUS")
            return -self.factor()
        elif token.type == "INTEGER":
            self.eat("INTEGER")
            return float(token.value)
        elif token.type == "FLOAT":
            self.eat("FLOAT")
            return float(token.value)
        elif token.type == "LPAREN":
            self.eat("LPAREN")
            result = self.expr()
            self.eat("RPAREN")
            return result
        else:
            self.error("Expected number or unary operator or LPAREN")

    def power(self) -> float:
        result = self.factor()
        while self.current_token.type == "POWER":
            op_token = self.current_token
            self.eat("POWER")
            # Power is right-associative, so we parse the right side as a full power expression
            right_operand = self.power()
            result **= right_operand
        return result

    def term(self) -> float:
        result = self.power()
        while self.current_token.type in ("MULTIPLY", "DIVIDE"):
            op_token = self.current_token
            if op_token.type == "MULTIPLY":
                self.eat("MULTIPLY")
                result *= self.power()
            elif op_token.type == "DIVIDE":
                self.eat("DIVIDE")
                divisor = self.power()
                if divisor == 0:
                    raise ZeroDivisionError("Division by zero")
                result /= divisor
        return result

    def expr(self) -> float:
        result = self.term()
        while self.current_token.type in ("PLUS", "MINUS"):
            op_token = self.current_token
            if op_token.type == "PLUS":
                self.eat("PLUS")
                result += self.term()
            elif op_token.type == "MINUS":
                self.eat("MINUS")
                result -= self.term()
        return result

    def parse(self) -> float:
        result = self.expr()
        if self.current_token.type != "EOF":
            self.error("Unexpected token at end of expression")
        return result

def evaluate(expression: str) -> float:
    lexer = Lexer(expression)
    parser = Parser(lexer)
    return parser.parse()

