from typing import List, Tuple, Union

class Tokenizer:
    """Splits an expression string into a list of (type, value) tokens."""
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.tokens: List[Tuple[str, Union[str, float]]] = []
        self._tokenize()

    def _tokenize(self):
        while self.pos < len(self.text):
            char = self.text[self.pos]

            if char.isspace():
                self.pos += 1
                continue

            # Numbers (int or float)
            if char.isdigit() or char == '.':
                self._read_number()
            # Operators
            elif char == '*':
                self.pos += 1
                if self.pos < len(self.text) and self.text[self.pos] == '*':
                    self.pos += 1
                    self.tokens.append(('POW', '**'))
                else:
                    self.tokens.append(('STAR', '*'))
            elif char == '+':
                self.tokens.append(('PLUS', '+'))
                self.pos += 1
            elif char == '-':
                self.tokens.append(('MINUS', '-'))
                self.pos += 1
            elif char == '/':
                self.tokens.append(('SLASH', '/'))
                self.pos += 1
            # Parentheses
            elif char == '(':
                self.tokens.append(('LPAREN', '('))
                self.pos += 1
            elif char == ')':
                self.tokens.append(('RPAREN', ')'))
                self.pos += 1
            else:
                raise ValueError(f"Unexpected character '{char}' at index {self.pos}")

        self.tokens.append(('EOF', None))

    def _read_number(self):
        start = self.pos
        while self.pos < len(self.text) and (self.text[self.pos].isdigit() or self.text[self.pos] == '.'):
            self.pos += 1
        num_str = self.text[start:self.pos]
        try:
            val = float(num_str) if '.' in num_str else int(num_str)
            self.tokens.append(('NUMBER', val))
        except ValueError:
            raise ValueError(f"Invalid number format: '{num_str}'")


class Parser:
    """Recursive descent parser that evaluates directly.
    Precedence (lowest to highest): + - > * / > unary - > **
    """
    def __init__(self, tokens: List[Tuple[str, Union[str, float]]]):
        self.tokens = tokens
        self.pos = 0

    def parse(self) -> float:
        result = self.expr()
        if self._current()[0] != 'EOF':
            raise ValueError(f"Unexpected token '{self._current()}' after expression")
        return result

    def _current(self) -> Tuple[str, Union[str, float]]:
        return self.tokens[self.pos]

    def _advance(self) -> Tuple[str, Union[str, float]]:
        token = self._current()
        self.pos += 1
        return token

    # expr: handles + and - (left-associative)
    def expr(self) -> float:
        result = self.term()
        while self._current()[0] in ('PLUS', 'MINUS'):
            op = self._advance()[0]
            right = self.term()
            result = result + right if op == 'PLUS' else result - right
        return result

    # term: handles * and / (left-associative)
    def term(self) -> float:
        result = self.power()
        while self._current()[0] in ('STAR', 'SLASH'):
            op = self._advance()[0]
            right = self.power()
            if op == 'STAR':
                result *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                result /= right
        return result

    # power: handles ** (right-associative)
    def power(self) -> float:
        base = self.atom()
        if self._current()[0] == 'POW':
            self._advance()
            # Right-associative: evaluate the right side recursively
            exponent = self.power()
            return base ** exponent
        return base

    # unary: handles unary minus
    def unary(self) -> float:
        if self._current()[0] == 'MINUS':
            self._advance()
            return -self.unary()
        return self.power()

    # atom: handles numbers and parenthesized expressions
    def atom(self) -> float:
        token = self._current()
        if token[0] == 'NUMBER':
            self._advance()
            return float(token[1])
        elif token[0] == 'LPAREN':
            self._advance()
            result = self.expr()
