import math
from typing import Union, List, Iterator
from enum import Enum, auto


class TokenType(Enum):
    """Types of tokens in arithmetic expressions."""
    INTEGER = auto()
    FLOAT = auto()
    PLUS = auto()
    MINUS = auto()
    MULTIPLY = auto()
    DIVIDE = auto()
    POWER = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()


class Token:
    """Represents a single token with type and value."""

    __slots__ = ('type', 'value')

    def __init__(self, token_type: TokenType, value: Union[int, float, str, None] = None):
        self.type = token_type
        self.value = value

    def __repr__(self) -> str:
        return f'Token({self.type.name}, {repr(self.value)})'


class Lexer:
    """Converts input string into a stream of tokens."""

    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos] if self.text else None

    def error(self, message: str) -> SyntaxError:
        """Raise a syntax error with position context."""
        return SyntaxError(f'{message} at position {self.pos}: {repr(self.text[max(0, self.pos-10):self.pos+10])}')

    def advance(self) -> None:
        """Move to the next character in the input."""
        self.pos += 1
        if self.pos < len(self.text):
            self.current_char = self.text[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self) -> None:
        """Skip all whitespace characters."""
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self) -> Token:
        """Parse a number (integer or float) from the input."""
        result = ''
        decimal_seen = False

        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            if self.current_char == '.':
                if decimal_seen:
                    raise self.error('Multiple decimal points in number')
                decimal_seen = True
            result += self.current_char
            self.advance()

        # Handle case where number ends with a decimal point
        if result.endswith('.'):
            raise self.error('Number cannot end with decimal point')

        if decimal_seen:
            return Token(TokenType.FLOAT, float(result))
        else:
            return Token(TokenType.INTEGER, int(result))

    def get_next_token(self) -> Token:
        """Return the next token from the input."""
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue

            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()

            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS, '+')

            if self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS, '-')

            if self.current_char == '*':
                self.advance()
                if self.current_char == '*':
                    self.advance()
                    return Token(TokenType.POWER, '**')
                return Token(TokenType.MULTIPLY, '*')

            if self.current_char == '/':
                self.advance()
                return Token(TokenType.DIVIDE, '/')

            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN, '(')

            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN, ')')

            raise self.error(f'Unexpected character: {repr(self.current_char)}')

        return Token(TokenType.EOF)


class Parser:
    """Recursive descent parser for arithmetic expressions."""

    def __init__(self, lexer: Lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self, message: str, token: Token) -> SyntaxError:
        """Raise a syntax error with token context."""
        return SyntaxError(f'{message}. Got {token.type.name} with value {repr(token.value)}')

    def eat(self, token_type: TokenType) -> None:
        """Consume the current token if it matches expected type."""
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            raise self.error(f'Expected {token_type.name}', self.current_token)

    def factor(self) -> float:
        """Parse a factor: number or parenthesized expression or unary minus."""
        token = self.current_token

        if token.type == TokenType.INTEGER:
            self.eat(TokenType.INTEGER)
            return float(token.value)

        if token.type == TokenType.FLOAT:
            self.eat(TokenType.FLOAT)
            return token.value

        if token.type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            result = self.expr()
            self.eat(TokenType.RPAREN)
            return result

        if token.type == TokenType.MINUS:
            self.eat(TokenType.MINUS)
            # Unary minus has higher precedence than power
            return -self.factor()

        if token.type == TokenType.PLUS:
            self.eat(TokenType.PLUS)
            # Unary plus
            return self.factor()

        raise self.error('Expected number, parentheses, or unary operator', token)

    def power(self) -> float:
        """Parse power operator (right-associative)."""
        result = self.factor()

        while self.current_token.type == TokenType.POWER:
            self.eat(TokenType.POWER)
            # Right-associative: a**b**c = a**(b**c)
            right = self.power()
            result = result ** right

        return result

    def term(self) -> float:
        """Parse multiplication and division operators."""
        result = self.power()

        while self.current_token.type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            token = self.current_token

            if token.type == TokenType.MULTIPLY:
                self.eat(TokenType.MULTIPLY)
                result *= self.power()
            elif token.type == TokenType.DIVIDE:
                self.eat(TokenType.DIVIDE)
                divisor = self.power()
                if divisor == 0:
                    raise ZeroDivisionError('Division by zero')
                result /= divisor

        return result

    def expr(self) -> float:
        """Parse addition and subtraction operators."""
        result = self.term()

        while self.current_token.type in (TokenType.PLUS, TokenType.MINUS):
            token = self.current_token

            if token.type == TokenType.PLUS:
                self.eat(TokenType.PLUS)
                result += self.term()
            elif token.type == TokenType.MINUS:
                self.eat(TokenType.MINUS)
                result -= self.term()

        return result

    def parse(self) -> float:
        """Parse the entire expression and return the result."""
        result = self.expr()

        if self.current_token.type != TokenType.EOF:
            raise self.error('Unexpected tokens at end of expression', self.current_token)

        return result


def evaluate(expression: str) -> float:
    """
    Evaluate an arithmetic expression.

    Args:
        expression: String containing arithmetic expression

    Returns:
        float: Result of the evaluation

    Raises:
        SyntaxError: For malformed expressions
        ZeroDivisionError: For division by zero
        ValueError: For invalid operations

    Examples:
        >>> evaluate("2 + 3 * 4")
        14.0
        >>> evaluate("(2 + 3) * 4")
        20.0
        >>> evaluate("-3 ** 2")
        -9.0
    """
    if not expression or expression.isspace():
        raise ValueError('Empty expression')

    lexer = Lexer(expression)
    parser = Parser(lexer)
    return parser.parse()


