import re
from typing import List, Union

# I'm not sure if I should use a class or just functions, 
# but I'll use a class to keep track of the current token index.

class Parser:
    def __init__(self, tokens: List[str]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Union[str, None]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self) -> str:
        token = self.peek()
        if token is None:
            raise Exception("Unexpected end of input")
        self.pos += 1
        return token

    # Precedence: + - (lowest)
    def parse_expression(self) -> float:
        result = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self.parse_term()
            if op == '+':
                result = result + right
            else:
                result = result - right
        return result

    # Precedence: * /
    def parse_term(self) -> float:
        result = self.parse_unary()
        while self.peek() in ('*', '/'):
            op = self.consume()
            right = self.parse_unary()
            if op == '*':
                result = result * right
            else:
                if right == 0:
                    raise ZeroDivisionError("Cannot divide by zero!")
                result = result / right
        return result

