import re
from typing import Union, List

class ParseError(Exception):
    """Custom exception for parsing errors."""
    pass

class Token:
    """Represents a token in the token stream."""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Tokenizer:
    """Converts an input string into a stream of tokens."""
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.tokens: List[Token] = []
        self._tokenize()

    def _tokenize(self):
        token_specification = [
            ('NUMBER', r'\d+(\.\d*)?'),  # Integer or decimal number
            ('PLUS', r'\+'),              # Addition
            ('MINUS', r'-'),             # Subtraction
            ('TIMES', r'\*'),             # Multiplication
            ('DIVIDE', r'/'),             # Division
            ('POWER', r'\*\*'),           # Exponentiation
            ('LPAREN', r'\('),            # Left Parenthesis
            ('RPAREN', r'\)'),            # Right Parenthesis
            ('SKIP', r'[ \t]+'),          # Skip over spaces and tabs
            ('MISMATCH', r'.'),           # Any other character
        ]
        tok_regex = '|'.join(f'(?P<{pair[0]}>{pair[1]})' for pair in token_specification)
        for mo in re.finditer(tok_regex, self.expression):
            kind = mo.lastgroup
            value = mo.group(kind)
            if kind == 'NUMBER':
                value = float(value) if '.' in value else int(value)
                self.tokens.append(Token('NUMBER', value))
            elif kind in {'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'POWER', 'LPAREN', 'RPAREN'}:
                self.tokens.append(Token(kind, value))
            elif kind == 'MISMATCH':
                raise ParseError(f"Unexpected character: {value}")

    def next_token(self) -> Token:
        if self.position < len(self.tokens):
            token = self.tokens[self.position]
            self.position += 1
            return token
        return Token('EOF', None)

class Parser:
    """Parses tokens into an Abstract Syntax Tree (AST) and evaluates it."""
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer
        self.current_token = self.tokenizer.next_token()

    def parse(self) -> float:
        result = self.expression()
        if self.current_token.type != 'EOF':
            raise ParseError("Unexpected input after expression")
        return result

    def expression(self) -> float:
        result = self.term()
        while self.current_token.type in {'PLUS', 'MINUS'}:
            op = self.current_token
            self.current_token = self.tokenizer.next_token()
            if op.type == 'PLUS':
                result += self.term()
            elif op.type == 'MINUS':
                result -= self.term()
        return result

    def term(self) -> float:
        result = self.factor()
        while self.current_token.type in {'TIMES', 'DIVIDE'}:
            op = self.current_token
            self.current_token = self.tokenizer.next_token()
            if op.type == 'TIMES':
                result *= self.factor()
            elif op.type == 'DIVIDE':
                divisor = self.factor()
                if divisor == 0:
                    raise ParseError("Division by zero")
                result /= divisor
        return result

    def factor(self) -> float:
        if self.current_token.type == 'MINUS':
            self.current_token = self.tokenizer.next_token()
            return -self.unary()
        return self.unary()

    def unary(self) -> float:
        if self.current_token.type == 'NUMBER':
            value = self.current_token.value
            self.current_token = self.tokenizer.next_token()
            return value
        elif self.current_token.type == 'LPAREN':
            self.current_token = self.tokenizer.next_token()
            result = self.expression()
            if self.current_token.type != 'RPAREN':
                raise ParseError("Unbalanced parentheses")
            self.current_token = self.tokenizer.next_token()
            return result
        raise ParseError("Unexpected token")

def evaluate(expression: str) -> float:
    """Evaluates a given arithmetic expression and returns the result."""
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    return parser.parse()

# Usage examples
if __name__ == "__main__":
    print(evaluate("3 + 5"))                # 8
    print(evaluate("10 + 2 * 6"))           # 22
    print(evaluate("(2 + 3) * (5 - 1)"))    # 20
    print(evaluate("-3 + 4 ** 2"))          # 13

import re
from typing import List, Tuple, Union

class ExpressionError(Exception):
    """Custom exception for parsing and evaluation errors."""
    pass

class Tokenizer:
    """
    Converts an input string into a stream of tokens.
    Uses regular expressions to identify numbers and operators.
    """
    TOKEN_SPEC = [
        ('NUMBER', r'\d+(\.\d*)?'),  # Integer or decimal
        ('POW',    r'\*\*'),        # Exponentiation
        ('PLUS',   r'\+'),          # Addition
        ('MINUS',  r'-'),           # Subtraction / Unary minus
        ('MUL',    # Multiplication
         r'\*'),
        ('DIV',    # Division
         r'/'),
        ('LPAREN', r'\('),          # Left parenthesis
        ('RPAREN', r'\)'),          # Right parenthesis
        ('SKIP',   r'\s+'),         # Whitespace
        ('MISMATCH', r'.'),         # Any other character
    ]

    def __init__(self, text: str):
        self.text = text
        self.tokens: List[Tuple[str, str]] = self._tokenize()
        self.pos = 0

    def _tokenize(self) -> List[Tuple[str, str]]:
        regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in self.TOKEN_SPEC)
        tokens = []
        for mo in re.finditer(regex, self.text):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                tokens.append((kind, value))
            elif kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise ExpressionError(f"Unexpected character: {value!r}")
            else:
                tokens.append((kind, value))
        return tokens

    def peek(self) -> Union[Tuple[str, str], None]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self) -> Union[Tuple[str, str], None]:
        token = self.peek()
        self.pos += 1
        return token

class Parser:
    """
    Recursive descent parser that evaluates the expression on the fly.
    Precedence (lowest to highest):
    1. Addition/Subtraction
    2. Multiplication/Division
    3. Unary Minus
    4. Exponentiation (Right-associative)
    5. Parentheses/Numbers
    """
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer

    def parse(self) -> float:
        result = self._expression()
        if self.tokenizer.peek() is not None:
            raise ExpressionError(f"Unexpected token at end: {self.tokenizer.peek()[1]}")
        return float(result)

    def _expression(self) -> float:
        # Handle + and -
        node = self._term()
        while (token := self.tokenizer.peek()) and token[0] in ('PLUS', 'MINUS'):
            op = self.tokenizer.consume()[0]
            right = self._term()
            node = node + right if op == 'PLUS' else node - right
        return node

    def _term(self) -> float:
        # Handle * and /
        node = self._unary()
        while (token := self.tokenizer.peek()) and token[0] in ('MUL', 'DIV'):
            op = self.tokenizer.consume()[0]
            right = self._unary()
            if op == 'DIV':
                if right == 0:
                    raise ExpressionError("Division by zero")
                node /= right
            else:
                node *= right
        return node

    def _unary(self) -> float:
        # Handle unary minus
        if (token := self.tokenizer.peek()) and token[0] == 'MINUS':
            self.tokenizer.consume()
            # Unary minus has lower precedence than exponentiation in some languages,
            # but the requirement specifies: ** > unary minus > * /
            return -self._unary()
        return self._exponent()

    def _exponent(self) -> float:
        # Handle ** (Right-associative)
        node = self._factor()
        if (token := self.tokenizer.peek()) and token[0] == 'POW':
            self.tokenizer.consume()
            # Recursive call to handle right-associativity (e.g., 2**3**2 is 2**(3**2))
            right = self._exponent()
            node = node ** right
        return node

    def _factor(self) -> float:
        # Handle parentheses and numbers
        token = self.tokenizer.consume()
        if token is None:
            raise ExpressionError("Unexpected end of expression")

        kind, value = token
        if kind == 'NUMBER':
            return float(value)
        elif kind == 'LPAREN':
            result = self._expression()
            if (next_token := self.tokenizer.consume()) is None or next_token[0] != 'RPAREN':
                raise ExpressionError("Unbalanced parentheses: missing ')'")
            return result
        else:
            raise ExpressionError(f"Unexpected token: {value}")

def evaluate(expression: str) -> float:
    """
    Public API to evaluate an arithmetic expression.
    """
    if not expression.strip():
        raise ExpressionError("Empty expression")

    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    return parser.parse()

