from typing import Union, List, Tuple
import math

class ParseError(Exception):
    """Raised when the input cannot be parsed."""
    pass

class EvalError(Exception):
    """Raised when evaluation fails (e.g., division by zero)."""
    pass

Token = Union[float, str]  # Tokens are either numbers or operators/parens

def tokenize(expression: str) -> List[Token]:
    """Convert a string into a list of tokens."""
    tokens = []
    i = 0
    n = len(expression)

    while i < n:
        c = expression[i]

        if c.isspace():
            i += 1
            continue

        if c in '()+-*/':
            # Handle ** operator
            if c == '*' and i + 1 < n and expression[i+1] == '*':
                tokens.append('**')
                i += 2
            else:
                tokens.append(c)
                i += 1
        elif c.isdigit() or c == '.':
            # Parse numbers (integers or floats)
            j = i
            if c == '.':
                j += 1
                while j < n and expression[j].isdigit():
                    j += 1
            else:
                while j < n and expression[j].isdigit():
                    j += 1
                if j < n and expression[j] == '.':
                    j += 1
                    while j < n and expression[j].isdigit():
                        j += 1

            num_str = expression[i:j]
            try:
                if '.' in num_str:
                    tokens.append(float(num_str))
                else:
                    tokens.append(int(num_str))
            except ValueError:
                raise ParseError(f"Invalid number: {num_str}")

            i = j
        else:
            raise ParseError(f"Unexpected character: {c}")

    return tokens

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        """Return the current token without consuming it."""
        if self.pos >= len(self.tokens):
            return None
        return self.tokens[self.pos]

    def consume(self) -> Token:
        """Consume and return the current token."""
        token = self.peek()
        if token is None:
            raise ParseError("Unexpected end of input")
        self.pos += 1
        return token

    def expect(self, expected: Token) -> None:
        """Consume the current token if it matches expected, else raise error."""
        token = self.peek()
        if token != expected:
            raise ParseError(f"Expected {expected}, got {token}")
        self.pos += 1

    def parse_expression(self) -> float:
        """Parse an expression (lowest precedence)."""
        left = self.parse_term()

        while True:
            op = self.peek()
            if op in ('+', '-'):
                self.consume()
                right = self.parse_term()
                left = left + right if op == '+' else left - right
            else:
                break

        return left

    def parse_term(self) -> float:
        """Parse a term (medium precedence)."""
        left = self.parse_factor()

        while True:
            op = self.peek()
            if op in ('*', '/'):
                self.consume()
                right = self.parse_factor()
                if op == '*' and isinstance(left, (int, float)) and isinstance(right, (int, float)):
                    left = left * right
                elif op == '/' and isinstance(left, (int, float)) and isinstance(right, (int, float)):
                    if right == 0:
                        raise EvalError("Division by zero")
                    left = left / right
            else:
                break

        return left

    def parse_factor(self) -> float:
        """Parse a factor (high precedence)."""
        token = self.peek()

        if token == '+':
            self.consume()
            return self.parse_factor()
        elif token == '-':
            self.consume()
            return -self.parse_factor()
        elif token == '(':
            self.consume()
            expr = self.parse_expression()
            self.expect(')')
            return expr
        else:
            return self.parse_power()

    def parse_power(self) -> float:
        """Parse a power expression (highest precedence, right-associative)."""
        left = self.parse_atom()

        while True:
            op = self.peek()
            if op == '**':
                self.consume()
                right = self.parse_power()  # Right-associative
                left = left ** right
            else:
                break

        return left

    def parse_atom(self) -> float:
        """Parse a number or parenthesized expression."""
        token = self.consume()

        if isinstance(token, (int, float)):
            return float(token)
        elif token == '(':
            expr = self.parse_expression()
            self.expect(')')
            return expr
        else:
            raise ParseError(f"Unexpected token: {token}")

def evaluate(expression: str) -> float:
    """Evaluate an arithmetic expression and return the result as a float."""
    tokens = tokenize(expression)
    if not tokens:
        raise ParseError("Empty expression")

    parser = Parser(tokens)
    try:
        result = parser.parse_expression()
    except IndexError:
        raise ParseError("Unexpected end of input")

    # Check for remaining tokens
    if parser.pos < len(tokens):
        raise ParseError(f"Unexpected token at end: {tokens[parser.pos]}")

    return result

# Usage examples
if __name__ == "__main__":
    # Example 1: Operator precedence
    print(evaluate("2 + 3 * 4"))  # 2 + (3 * 4) = 14
    print(evaluate("2 * 3 + 4"))  # (2 * 3) + 4 = 10
    print(evaluate("2 ** 3 ** 2"))  # 2 ** (3 ** 2) = 512 (right-associative)

    # Example 2: Parentheses for grouping
    print(evaluate("(2 + 3) * 4"))  # (2 + 3) * 4 = 20
    print(evaluate("2 * (3 + 4)"))  # 2 * (3 + 4) = 14
    print(evaluate("((2 + 3) * 4) + 1"))  # (((2 + 3) * 4) + 1) = 21

    # Example 3: Unary minus
    print(evaluate("-2 + 3"))  # (-2) + 3 = 1
    print(evaluate("2 * -3"))  # 2 * (-3) = -6
    print(evaluate("-2 ** 2"))  # -(2 ** 2) = -4 (unary minus has higher precedence than **)
    print(evaluate("(-2) ** 2"))  # (-2) ** 2 = 4

    # Error cases
    try:
        print(evaluate("2 + * 3"))
    except ParseError as e:
        print(f"Error: {e}")  # Error: Unexpected token: *

    try:
        print(evaluate("2 + 3 / 0"))
    except EvalError as e:
        print(f"Error: {e}")  # Error: Division by zero

    try:
        print(evaluate("(2 + 3"))
    except ParseError as e:
        print(f"Error: {e}")  # Error: Unexpected end of input

