class Parser:
    def __init__(self, expression: str):
        self.tokens = self._tokenize(expression)
        self.pos = 0

    def _tokenize(self, expr: str) -> List[str]:
        # Regex for numbers (int/float) and operators
        token_pattern = re.compile(r'\d*\.\d+|\d+|[+\-*/()^]')
        tokens = token_pattern.findall(expr.replace('**', '^'))
        # Validate for unexpected characters
        if len("".join(tokens)) != len(expr.replace(" ", "")):
            raise ParseError("Input contains invalid characters.")
        return tokens

    def _peek(self) -> Union[str, None]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _consume(self) -> str:
        token = self._peek()
        self.pos += 1
        return token

    def evaluate(self) -> float:
        result = self._expression()
        if self.pos < len(self.tokens):
            raise ParseError(f"Unexpected token at end: {self.tokens[self.pos]}")
        return result

    def _expression(self) -> float:
        node = self._term()
        while self._peek() in ('+', '-'):
            op = self._consume()
            right = self._term()
            node = node + right if op == '+' else node - right
        return node

    def _term(self) -> float:
        node = self._unary()
        while self._peek() in ('*', '/'):
            op = self._consume()
            right = self._unary()
            if op == '*': node *= right
            else:
                if right == 0: raise ParseError("Division by zero.")
                node /= right
        return node

    def _unary(self) -> float:
        if self._peek() == '-':
            self._consume()
            return -self._unary()
        return self._power()

    def _power(self) -> float:
        node = self._primary()
        if self._peek() == '^':
            self._consume()
            # Right-associativity: recurse on the right side
            node = node ** self._power()
        return node

    def _primary(self) -> float:
        token = self._consume()
        if token == '(':
            result = self._expression()
            if self._consume() != ')':
                raise ParseError("Unbalanced parentheses: missing closing bracket.")
            return result
        try:
            return float(token)
        except (ValueError, TypeError):
            raise ParseError(f"Unexpected token: {token}")

def evaluate(expression: str) -> float:
