import re

# I'm still learning, so I'm just using a list for tokens 
# and a global index to keep track of where I am.
tokens = []
pos = 0

def tokenize(text: str):
    # I found this regex online to split numbers and symbols
    # It keeps the delimiters as separate items in the list
    pattern = r'(\d*\.\d+|\d+|[\+\-\*/\(\)\^])'
    # I'm replacing ** with ^ because it's easier to handle as one character
    text = text.replace('**', '^')
    return re.findall(pattern, text)

def peek() -> str:
    global pos
    if pos < len(tokens):
        return tokens[pos]
    return None

def consume() -> str:
    global pos
    token = peek()
    pos += 1
    return token

# Precedence: 
# expression (lowest) -> term -> factor -> power -> unary -> primary (highest)

def parse_expression() -> float:
    # Handles + and -
    node = parse_term()
    while peek() == '+' or peek() == '-':
        op = consume()
        right = parse_term()
        if op == '+':
            node = node + right
        else:
            node = node - right
    return node

def parse_term() -> float:
    # Handles * and /
    node = parse_factor()
    while peek() == '*' or peek() == '/':
        op = consume()
        right = parse_factor()
        if op == '*':
            node = node * right
        else:
            if right == 0:
                raise ZeroDivisionError("Cannot divide by zero!")
            node = node / right
    return node

def parse_factor() -> float:
    # Handles unary minus
    if peek() == '-':
        consume() # eat the minus
        return -parse_factor()
    return parse_power()

def parse_power() -> float:
    # Handles ** (which I turned into ^)
    # This one is right-associative, so it calls itself recursively
    node = parse_primary()
    if peek() == '^':
        consume() # eat the ^
        right = parse_power() # recursive call for right-associativity
        return node ** right
    return node

def parse_primary() -> float:
    token = consume()
    if token == None:
        raise Exception("Unexpected end of input")

    if token == '(':
        result = parse_expression()
        if consume() != ')':
            raise Exception("Missing closing parenthesis!")
        return result

    try:
        # Try to turn it into a float
        return float(token)
    except:
        raise Exception(f"Unexpected character: {token}")

def evaluate(expression: str) -> float:
