from typing import Union, List

class ParseError(Exception):
    """Custom exception for parsing errors."""
    pass

class Token:
    """Represents a token in the input expression."""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Tokenizer:
    """Tokenizes the input string into a stream of tokens."""
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.tokens: List[Token] = []
        self.tokenize()

    def tokenize(self):
        """Tokenizes the input expression."""
        token_specification = [
            ('NUMBER', r'\d+(\.\d*)?'),  # Integer or decimal number
            ('PLUS', r'\+'),              # Addition
            ('MINUS', r'-'),             # Subtraction
            ('TIMES', r'\*'),             # Multiplication
            ('DIVIDE', r'/'),            # Division
            ('POWER', r'\*\*'),          # Exponentiation
            ('LPAREN', r'\('),           # Left Parenthesis
            ('RPAREN', r'\)'),           # Right Parenthesis
            ('SKIP', r'[ \t]+'),         # Skip over spaces and tabs
            ('MISMATCH', r'.'),          # Any other character
        ]
        tok_regex = '|'.join(f'(?P<{pair[0]}>{pair[1]})' for pair in token_specification)
        for mo in re.finditer(tok_regex, self.expression):
            kind = mo.lastgroup
            value = mo.group(kind)
            if kind == 'NUMBER':
                value = float(value) if '.' in value else int(value)
                self.tokens.append(Token('NUMBER', value))
            elif kind in {'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'POWER', 'LPAREN', 'RPAREN'}:
                self.tokens.append(Token(kind, value))
            elif kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise ParseError(f"Unexpected character: {value}")
        self.tokens.append(Token('EOF', None))  # End of file token

    def next_token(self) -> Token:
        """Returns the next token from the token stream."""
        if self.position < len(self.tokens):
            token = self.tokens[self.position]
            self.position += 1
            return token
        return Token('EOF', None)

class Parser:
    """Parses tokens and evaluates arithmetic expressions."""
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer
        self.current_token = self.tokenizer.next_token()

    def error(self, message: str):
        """Raises a ParseError with a descriptive message."""
        raise ParseError(message)

    def eat(self, token_type: str):
        """Consumes a token of the specified type."""
        if self.current_token.type == token_type:
            self.current_token = self.tokenizer.next_token()
        else:
            self.error(f"Expected token {token_type}, got {self.current_token.type}")

    def factor(self) -> float:
        """Parses a factor (number or parenthesis)."""
        if self.current_token.type == 'NUMBER':
            value = self.current_token.value
            self.eat('NUMBER')
            return value
        elif self.current_token.type == 'LPAREN':
            self.eat('LPAREN')
            result = self.expr()
            self.eat('RPAREN')
            return result
        elif self.current_token.type == 'MINUS':
            self.eat('MINUS')
            return -self.factor()
        self.error("Invalid factor")

    def power(self) -> float:
        """Parses exponentiation."""
        result = self.factor()
        while self.current_token.type == 'POWER':
            self.eat('POWER')
            result **= self.factor()
        return result

    def term(self) -> float:
        """Parses multiplication and division."""
        result = self.power()
        while self.current_token.type in {'TIMES', 'DIVIDE'}:
            if self.current_token.type == 'TIMES':
                self.eat('TIMES')
                result *= self.power()
            elif self.current_token.type == 'DIVIDE':
                self.eat('DIVIDE')
                divisor = self.power()
                if divisor == 0:
                    self.error("Division by zero")
                result /= divisor
        return result

    def expr(self) -> float:
        """Parses addition and subtraction."""
        result = self.term()
        while self.current_token.type in {'PLUS', 'MINUS'}:
            if self.current_token.type == 'PLUS':
                self.eat('PLUS')
                result += self.term()
            elif self.current_token.type == 'MINUS':
                self.eat('MINUS')
                result -= self.term()
        return result

    def parse(self) -> float:
        """Parses the entire expression and returns the result."""
        result = self.expr()
        if self.current_token.type != 'EOF':
            self.error("Unexpected token after expression")
        return result

def evaluate(expression: str) -> float:
    """Evaluates an arithmetic expression and returns the result."""
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    return parser.parse()

# Usage examples:
if __name__ == "__main__":
    print(evaluate("3 + 5 * 2"))          # 13
    print(evaluate("(3 + 5) * 2"))        # 16
    print(evaluate("-3 + 5 ** 2"))        # 22
    print(evaluate("-(3 + 5) * 2"))       # -16
    print(evaluate("2 ** 3 ** 2"))        # 256

from typing import List, Union, Optional

class Token:
    def __init__(self, type: str, value: Union[str, float, int, None] = None):
        self.type = type
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.type}, {self.value})"

class ParserError(Exception):
    pass

class Evaluator:
    def __init__(self):
        self.tokens: List[Token] = []
        self.pos = 0

    def tokenize(self, expression: str) -> List[Token]:
        """Convert input string into tokens"""
        tokens = []
        i = 0
        n = len(expression)

        while i < n:
            ch = expression[i]

            # Skip whitespace
            if ch.isspace():
                i += 1
                continue

            # Numbers (integers and floats)
            if ch.isdigit() or ch == '.':
                num_str = ""
                has_decimal = False

                while i < n and (expression[i].isdigit() or expression[i] == '.'):
                    if expression[i] == '.':
                        if has_decimal:
                            raise ParserError("Invalid number with multiple decimal points")
                        has_decimal = True
                    num_str += expression[i]
                    i += 1

                # Check if it's a valid number
                if num_str == '.':
                    raise ParserError("Invalid number")

                if has_decimal:
                    tokens.append(Token('NUMBER', float(num_str)))
                else:
                    tokens.append(Token('NUMBER', int(num_str)))
                continue

            # Operators and parentheses
            if ch in '+-*/()':
                if ch == '-':
                    # Check if it's a unary minus
                    if not tokens or tokens[-1].type in ['OP', 'LPAREN']:
                        tokens.append(Token('UNARY_MINUS'))
                    else:
                        tokens.append(Token('OP', ch))
                elif ch == '+':
                    # Check if it's a unary plus (just ignore it)
                    if not tokens or tokens[-1].type in ['OP', 'LPAREN']:
                        i += 1
                        continue
                    else:
                        tokens.append(Token('OP', ch))
                else:
                    if ch in '()':
                        tokens.append(Token('LPAREN' if ch == '(' else 'RPAREN'))
                    else:
                        tokens.append(Token('OP', ch))
                i += 1
                continue

            # Exponentiation operator
            if ch == '*':
                if i + 1 < n and expression[i + 1] == '*':
                    tokens.append(Token('OP', '**'))
                    i += 2
                    continue
                else:
                    tokens.append(Token('OP', '*'))
                    i += 1
                continue

            # Invalid character
            raise ParserError(f"Unexpected character: '{ch}'")

        return tokens

    def current_token(self) -> Optional[Token]:
        """Get current token or None if at end"""
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def eat(self, token_type: str, value: Optional[str] = None) -> Token:
        """Consume current token if it matches expected type"""
        token = self.current_token()
        if not token:
            raise ParserError(f"Expected {token_type}, got end of input")
        if token.type != token_type:
            raise ParserError(f"Expected {token_type}, got {token.type}")
        if value is not None and token.value != value:
            raise ParserError(f"Expected {value}, got {token.value}")

        self.pos += 1
        return token

    def parse_expression(self) -> float:
        """Parse addition and subtraction"""
        result = self.parse_term()

        while self.current_token() and self.current_token().type == 'OP' and self.current_token().value in '+-':
            op = self.eat('OP').value
            right = self.parse_term()

            if op == '+':
                result += right
            else:  # op == '-'
                result -= right

        return result

    def parse_term(self) -> float:
        """Parse multiplication and division"""
        result = self.parse_factor()

        while self.current_token() and self.current_token().type == 'OP' and self.current_token().value in '*/':
            op = self.eat('OP').value
            right = self.parse_factor()

            if op == '*':
                result *= right
            else:  # op == '/'
                if right == 0:
                    raise ParserError("Division by zero")
                result /= right

        return result

    def parse_factor(self) -> float:
        """Parse exponentiation"""
        result = self.parse_unary()

        while self.current_token() and self.current_token().type == 'OP' and self.current_token().value == '**':
            self.eat('OP', '**')
            right = self.parse_unary()  # Right-associative: parse another unary
            result = result ** right

        return result

    def parse_unary(self) -> float:
        """Parse unary minus"""
        if self.current_token() and self.current_token().type == 'UNARY_MINUS':
            self.eat('UNARY_MINUS')
            return -self.parse_atom()

        return self.parse_atom()

    def parse_atom(self) -> float:
        """Parse numbers and parentheses"""
        token = self.current_token()

        if not token:
            raise ParserError("Unexpected end of input")

        if token.type == 'NUMBER':
            num = self.eat('NUMBER').value
            return float(num)

        if token.type == 'LPAREN':
            self.eat('LPAREN')
            result = self.parse_expression()
            self.eat('RPAREN')
            return result

        raise ParserError(f"Unexpected token: {token}")

    def evaluate(self, expression: str) -> float:
        """Public API: Evaluate an arithmetic expression"""
        # Reset parser state
        self.tokens = self.tokenize(expression)
        self.pos = 0

        if not self.tokens:
            raise ParserError("Empty expression")

        result = self.parse_expression()

        # Check if we parsed everything
        if self.current_token():
            raise ParserError(f"Unexpected token at end: {self.current_token()}")

        return result


def evaluate(expression: str) -> float:
    """Public API function for evaluating expressions"""
    evaluator = Evaluator()
    return evaluator.evaluate(expression)


