import re
from typing import Union, List, Tuple
import math

class ParseError(Exception):
    """Raised when the input expression cannot be parsed."""
    pass

class EvaluationError(Exception):
    """Raised when evaluation fails (e.g., division by zero)."""
    pass

Token = Union[float, str]

class ArithmeticParser:
    """
    Recursive-descent parser and evaluator for arithmetic expressions.

    Grammar:
        expr   : term (('+' | '-') term)*
        term   : factor (('*' | '/') factor)*
        factor : power (('**') power)*
        power  : unary ('**' unary)*
        unary  : ('-')* primary
        primary: NUMBER | '(' expr ')'
    """

    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.current = 0

    def evaluate(self) -> float:
        """Evaluate the expression and return the result as a float."""
        try:
            result = self._expr()
            if self.current < len(self.tokens):
                raise ParseError(f"Unexpected token at position {self.current}: {self.tokens[self.current]}")
            return result
        except (ParseError, EvaluationError) as e:
            raise e
        except Exception as e:
            raise ParseError(f"Unexpected error during evaluation: {e}")

    def _expr(self) -> float:
        """Parse and evaluate an expression (handles + and -)."""
        result = self._term()
        while self._match('+', '-'):
            op = self._previous()
            right = self._term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def _term(self) -> float:
        """Parse and evaluate a term (handles * and /)."""
        result = self._factor()
        while self._match('*', '/'):
            op = self._previous()
            right = self._factor()
            if op == '*':
                result *= right
            else:
                if right == 0:
                    raise EvaluationError("Division by zero")
                result /= right
        return result

    def _factor(self) -> float:
        """Parse and evaluate a factor (handles **)."""
        result = self._power()
        while self._match('**'):
            op = self._previous()
            right = self._power()
            result **= right
        return result

    def _power(self) -> float:
        """Parse and evaluate power expressions (right-associative **)."""
        result = self._unary()
        while self._match('**'):
            op = self._previous()
            right = self._unary()
            result **= right
        return result

    def _unary(self) -> float:
        """Parse and evaluate unary minus operations."""
        if self._match('-'):
            return -self._unary()
        return self._primary()

    def _primary(self) -> float:
        """Parse and evaluate primary expressions (numbers and parentheses)."""
        if self._match('('):
            expr = self._expr()
            if not self._match(')'):
                raise ParseError("Unbalanced parentheses: missing closing ')'")
            return expr

        token = self._advance()
        if isinstance(token, (int, float)):
            return float(token)
        raise ParseError(f"Expected number or '(', got: {token}")

    def _match(self, *types: str) -> bool:
        """Check if current token matches any of the given types and consume it."""
        if self._is_at_end():
            return False
        for token_type in types:
            if self._peek() == token_type:
                self._advance()
                return True
        return False

    def _advance(self) -> Token:
        """Consume and return the current token."""
        if not self._is_at_end():
            self.current += 1
        return self._previous()

    def _peek(self) -> Token:
        """Return the current token without consuming it."""
        if self._is_at_end():
            return ''
        return self.tokens[self.current]

    def _previous(self) -> Token:
        """Return the previous token."""
        return self.tokens[self.current - 1]

    def _is_at_end(self) -> bool:
        """Check if we've reached the end of the token stream."""
        return self.current >= len(self.tokens)

def tokenize(expression: str) -> List[Token]:
    """
    Tokenize the input string into a list of tokens.

    Tokens can be:
    - Numbers (integers or floats)
    - Operators (+, -, *, /, **)
    - Parentheses ((), )
    """
    token_specification = [
        ('NUMBER', r'\d+\.?\d*|\.\d+'),  # Integer or decimal number
        ('PLUS', r'\+'),
        ('MINUS', r'-'),
        ('TIMES', r'\*'),
        ('DIVIDE', r'/'),
        ('POWER', r'\*\*'),
        ('LPAREN', r'\('),
        ('RPAREN', r'\)'),
        ('SKIP', r'\s+'),  # Skip whitespace
        ('MISMATCH', r'.'),  # Any other character
    ]
    tok_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in token_specification)
    tokens = []

    for mo in re.finditer(tok_regex, expression):
        kind = mo.lastgroup
        value = mo.group()

        if kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise ParseError(f"Unexpected character: '{value}'")
        elif kind == 'NUMBER':
            try:
                # Try to parse as int first, then float if that fails
                if '.' in value or 'e' in value.lower():
                    tokens.append(float(value))
                else:
                    tokens.append(int(value))
            except ValueError:
                raise ParseError(f"Invalid number: '{value}'")
        else:
            tokens.append(value)

    return tokens

