from enum import Enum, auto
from typing import List

class TokenType(Enum):
    NUMBER = auto()
    PLUS = auto()
    MINUS = auto()
    MULTIPLY = auto()
    DIVIDE = auto()
    POWER = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()

class Token:
    def __init__(self, type: TokenType, value: float = None):
        self.type = type
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.type.name}, {self.value})"

def tokenize(expr: str) -> List[Token]:
    """Splits an expression string into a stream of typed tokens."""
    tokens: List[Token] = []
    i = 0
    n = len(expr)

    while i < n:
        if expr[i].isspace():
            i += 1
            continue

        if expr[i] == '*':
            if i + 1 < n and expr[i+1] == '*':
                tokens.append(Token(TokenType.POWER))
                i += 2
            else:
                tokens.append(Token(TokenType.MULTIPLY))
                i += 1
        elif expr[i] == '+':
            tokens.append(Token(TokenType.PLUS))
            i += 1
        elif expr[i] == '-':
            tokens.append(Token(TokenType.MINUS))
            i += 1
        elif expr[i] == '/':
            tokens.append(Token(TokenType.DIVIDE))
            i += 1
        elif expr[i] == '(':
            tokens.append(Token(TokenType.LPAREN))
            i += 1
        elif expr[i] == ')':
            tokens.append(Token(TokenType.RPAREN))
            i += 1
        elif expr[i].isdigit() or expr[i] == '.':
            j = i
            has_dot = False
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                if expr[j] == '.':
                    if has_dot:
                        raise ValueError(f"Invalid number format at position {i}")
                    has_dot = True
                j += 1
            if j == i or (j == i + 1 and expr[i] == '.'):
                raise ValueError(f"Invalid number format at position {i}")
            num_str = expr[i:j]
            tokens.append(Token(TokenType.NUMBER, float(num_str)))
            i = j
        else:
            raise ValueError(f"Unexpected character '{expr[i]}' at position {i}")

    tokens.append(Token(TokenType.EOF))
    return tokens

class Parser:
    """Recursive-descent parser that evaluates arithmetic expressions directly."""

    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current(self) -> Token:
        return self.tokens[self.pos]

    def consume(self, expected_type: TokenType) -> Token:
        token = self.current()
        if token.type != expected_type:
            raise ValueError(f"Expected {expected_type.name} but got {token.type.name} at position {self.pos}")
        self.pos += 1
        return token

    def parse(self) -> float:
        result = self.expr()
        if self.current().type != TokenType.EOF:
            raise ValueError(f"Unexpected token '{self.current().type.name}' at position {self.pos}")
        return result

    # expr     -> term (('+' | '-') term)*
    def expr(self) -> float:
        left = self.term()
        while self.current().type in (TokenType.PLUS, TokenType.MINUS):
            op = self.consume(self.current().type)
            right = self.term()
            left = left + right if op.type == TokenType.PLUS else left - right
        return left

    # term     -> power (('*' | '/') power)*
    def term(self) -> float:
        left = self.power()
        while self.current().type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            op = self.consume(self.current().type)
            right = self.power()
            if op.type == TokenType.MULTIPLY:
                left = left * right
            else:
                if right == 0.0:
                    raise ZeroDivisionError("Division by zero")
                left = left / right
        return left

    # power    -> primary ('**' power)?  # Right-associative
    def power(self) -> float:
        base = self.primary()
        if self.current().type == TokenType.POWER:
            self.consume(TokenType.POWER)
            exponent = self.power()  # Recursive call ensures right-associativity
            return base ** exponent
        return base

    # unary    -> ('-' unary) | power
    def unary(self) -> float:
        if self.current().type == TokenType.MINUS:
            self.consume(TokenType.MINUS)
            return -self.unary()
        return self.power()

    # primary  -> NUMBER | '(' expr ')'
    def primary(self) -> float:
        token = self.current()
        if token.type == TokenType.NUMBER:
            self.consume(TokenType.NUMBER)
            return token.value
        elif token.type == TokenType.LPAREN:
            self.consume(TokenType.LPAREN)
            result = self.expr()
            self.consume(TokenType.RPAREN)
            return result
        else:
            raise ValueError(f"Unexpected token '{token.type.name}' at position {self.pos}")

def evaluate(expression: str) -> float:
    """Public API: Parses and evaluates an arithmetic expression string."""
    tokens = tokenize(expression)
    parser = Parser(tokens)
    return parser.parse()

