    print(f"  10 / (2 - 7)   = {evaluate('10 / (2 - 7)')}")   # 10 / -5 = -2.0

    # 3. Unary minus & Right-associative **
    print("\nUnary & Associativity Test:")
    print(f"  -2 * 3         = {evaluate('-2 * 3')}")         # (-2) * 3 = -6.0
    print(f"  2 ** 3 ** 2    = {evaluate('2 ** 3 ** 2')}")    # 2 ** (3 ** 2) = 512.0
    print(f"  -(-5)          = {evaluate('-(-5)')}")          # 5.0

import re
from typing import Union, List

class ParseError(Exception):
    pass

class Token:
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f'Token({self.type}, {self.value})'

class Tokenizer:
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.current_char = self.expression[self.position] if self.expression else None

    def advance(self):
        self.position += 1
        if self.position < len(self.expression):
            self.current_char = self.expression[self.position]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self) -> Token:
        num_str = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            num_str += self.current_char
            self.advance()
        return Token('NUMBER', float(num_str))

    def get_next_token(self) -> Token:
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()
            if self.current_char == '+':
                self.advance()
                return Token('PLUS', '+')
            if self.current_char == '-':
                self.advance()
                return Token('MINUS', '-')
            if self.current_char == '*':
                self.advance()
                return Token('MUL', '*')
            if self.current_char == '/':
                self.advance()
                return Token('DIV', '/')
            if self.current_char == '(':
                self.advance()
                return Token('LPAREN', '(')
            if self.current_char == ')':
                self.advance()
                return Token('RPAREN', ')')
            if self.current_char == '**':
                self.advance()
                return Token('POW', '**')
            raise ParseError(f'Unexpected character: {self.current_char}')
        return Token('EOF', None)

class ASTNode:
    pass

class BinOp(ASTNode):
    def __init__(self, left: ASTNode, op: Token, right: ASTNode):
        self.left = left
        self.op = op
        self.right = right

class UnaryOp(ASTNode):
    def __init__(self, op: Token, expr: ASTNode):
        self.op = op
        self.expr = expr

class Num(ASTNode):
    def __init__(self, token: Token):
        self.token = token

class Parser:
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer
        self.current_token = self.tokenizer.get_next_token()

    def error(self):
        raise ParseError('Invalid syntax')

    def eat(self, token_type: str):
        if self.current_token.type == token_type:
            self.current_token = self.tokenizer.get_next_token()
        else:
            self.error()

    def factor(self) -> ASTNode:
        token = self.current_token
        if token.type == 'PLUS':
            self.eat('PLUS')
            return self.factor()
        elif token.type == 'MINUS':
            self.eat('MINUS')
            return UnaryOp(token, self.factor())
        elif token.type == 'NUMBER':
            self.eat('NUMBER')
            return Num(token)
        elif token.type == 'LPAREN':
            self.eat('LPAREN')
            node = self.expr()
            self.eat('RPAREN')
            return node
        self.error()

    def term(self) -> ASTNode:
        node = self.factor()
        while self.current_token.type in ('MUL', 'DIV'):
            token = self.current_token
            if token.type == 'MUL':
                self.eat('MUL')
            elif token.type == 'DIV':
                self.eat('DIV')
            node = BinOp(node, token, self.factor())
        return node

    def power(self) -> ASTNode:
        node = self.term()
        while self.current_token.type == 'POW':
            token = self.current_token
            self.eat('POW')
            node = BinOp(node, token, self.term())
        return node

    def expr(self) -> ASTNode:
        node = self.power()
        while self.current_token.type in ('PLUS', 'MINUS'):
            token = self.current_token
            if token.type == 'PLUS':
                self.eat('PLUS')
            elif token.type == 'MINUS':
                self.eat('MINUS')
            node = BinOp(node, token, self.power())
        return node

class Evaluator:
    def visit(self, node: ASTNode) -> float:
        if isinstance(node, Num):
            return node.token.value
        elif isinstance(node, UnaryOp):
            return -self.visit(node.expr)
        elif isinstance(node, BinOp):
            if node.op.type == 'PLUS':
                return self.visit(node.left) + self.visit(node.right)
            elif node.op.type == 'MINUS':
                return self.visit(node.left) - self.visit(node.right)
            elif node.op.type == 'MUL':
                return self.visit(node.left) * self.visit(node.right)
            elif node.op.type == 'DIV':
                right = self.visit(node.right)
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                return self.visit(node.left) / right
            elif node.op.type == 'POW':
                return self.visit(node.left) ** self.visit(node.right)
        raise ParseError('Invalid AST node')

def evaluate(expression: str) -> float:
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    ast = parser.expr()
    evaluator = Evaluator()
    return evaluator.visit(ast)

# Usage examples
if __name__ == "__main__":
    print(evaluate("3 + 5"))               # 8.0
    print(evaluate("10 + 2 * 6"))          # 22.0
    print(evaluate("(10 + 2) * 6"))        # 72.0
    print(evaluate("-3 + 5"))              # 2.0
    print(evaluate("2 ** 3 ** 2"))         # 512.0
    print(evaluate("2 * (3 + 5)"))         # 16.0
    print(evaluate("-(3 + 5)"))            # -8.0

import re
import math
from typing import Iterator, NamedTuple, Optional

class Token(NamedTuple):
    type: str
    value: str

class ParseError(Exception):
    """Raised when the expression is syntactically invalid."""
    pass

class Evaluator:
    """
    Grammar:
    expression   ::= term {('+' | '-') term}
    term         ::= factor {('*' | '/') factor}
    factor       ::= unary ['**' factor]
    unary        ::= '-' unary | primary
    primary      ::= NUMBER | '(' expression ')'
    """

    TOKEN_SPEC = [
        ('NUMBER',   r'\d+(\.\d*)?'),
        ('PLUS',     r'\+'),
        ('MINUS',    r'-'),
        ('MUL',      r'\*'),
        ('DIV',      r'/'),
        ('POW',      r'\*\*'),
        ('LPAREN',   r'\('),
        ('RPAREN',   r'\)'),
        ('SKIP',     r'\s+'),
        ('MISMATCH', r'.'),
    ]

    def __init__(self):
        self.regex = re.compile('|'.join(f'(?P<{name}>{pattern})' for name, pattern in self.TOKEN_SPEC))
        self.tokens: Iterator[Token] = iter([])
        self.current_token: Optional[Token] = None

    def _tokenize(self, expression: str) -> Iterator[Token]:
        for mo in self.regex.finditer(expression):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise ParseError(f"Unexpected character: {value}")
            yield Token(kind, value)

    def _advance(self) -> None:
        self.current_token = next(self.tokens, None)

    def _consume(self, token_type: str) -> str:
        if self.current_token and self.current_token.type == token_type:
            val = self.current_token.value
            self._advance()
            return val
        raise ParseError(f"Expected {token_type}, got {self.current_token}")

    def _primary(self) -> float:
        token = self.current_token
        if token and token.type == 'NUMBER':
            self._advance()
            return float(token.value)
        if token and token.type == 'LPAREN':
            self._advance()
            result = self._expression()
            self._consume('RPAREN')
            return result
        raise ParseError(f"Unexpected token in primary: {token}")

    def _unary(self) -> float:
        if self.current_token and self.current_token.type == 'MINUS':
            self._advance()
            return -self._unary()
        return self._primary()

    def _factor(self) -> float:
        node = self._unary()
        if self.current_token and self.current_token.type == 'POW':
            self._advance()
            return math.pow(node, self._factor())
        return node

    def _term(self) -> float:
        node = self._factor()
        while self.current_token and self.current_token.type in ('MUL', 'DIV'):
            op = self.current_token.type
            self._advance()
            right = self._factor()
            if op == 'MUL':
                node *= right
            else:
                if right == 0: raise ZeroDivisionError("Division by zero")
                node /= right
        return node

    def _expression(self) -> float:
        node = self._term()
        while self.current_token and self.current_token.type in ('PLUS', 'MINUS'):
            op = self.current_token.type
            self._advance()
            right = self._term()
            node = (node + right) if op == 'PLUS' else (node - right)
        return node

    def evaluate(self, expression: str) -> float:
        self.tokens = self._tokenize(expression)
        self._advance()
        result = self._expression()
        if self.current_token is not None:
            raise ParseError(f"Unexpected trailing tokens: {self.current_token.value}")
        return result

def evaluate(expression: str) -> float:
    """Public API to evaluate arithmetic expressions."""
    return Evaluator().evaluate(expression)

# Usage Examples
if __name__ == "__main__":
    # 1. Precedence: 2 + 3 * 4 = 14
    print(f"Precedence: {evaluate('2 + 3 * 4')}") 

    # 2. Parentheses: (2 + 3) * 4 = 20
    print(f"Parentheses: {evaluate('(2 + 3) * 4')}")

    # 3. Unary minus and Power: -2 ** 2 = -4 (unary minus is lower than power)
    # Note: In standard math, -2**2 is -(2**2) = -4. 
    # If you wanted (-2)**2 = 4, parentheses are required.
    print(f"Unary/Power: {evaluate('-2 ** 2')}")

import re
import math
from typing import Iterator, NamedTuple, Union

class Token(NamedTuple):
    type: str
    value: Union[str, float]

class ParseError(Exception):
    """Raised when the expression is syntactically invalid."""
    pass

class Tokenizer:
    TOKEN_SPEC = [
        ('NUMBER',   r'\d+(\.\d*)?'),
        ('PLUS',     r'\+'),
        ('MINUS',    r'-'),
        ('MUL',      r'\*'),
        ('DIV',      r'/'),
        ('POW',      r'\*\*'),
        ('LPAREN',   r'\('),
        ('RPAREN',   r'\)'),
        ('SKIP',     r'\s+'),
        ('MISMATCH', r'.'),
    ]

    def __init__(self, expression: str):
        self.tokens = self._tokenize(expression)
        self.pos = 0

    def _tokenize(self, expression: str) -> list[Token]:
        regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in self.TOKEN_SPEC)
        tokens = []
        for mo in re.finditer(regex, expression):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                tokens.append(Token(kind, float(value)))
            elif kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise ParseError(f"Unexpected character: {value}")
            else:
                tokens.append(Token(kind, value))
        return tokens

    def peek(self) -> Union[Token, None]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected_type: str = None) -> Token:
        token = self.peek()
        if not token:
            raise ParseError("Unexpected end of expression")
        if expected_type and token.type != expected_type:
            raise ParseError(f"Expected {expected_type}, got {token.type}")
        self.pos += 1
        return token

class Evaluator:
    """Recursive descent parser and evaluator."""
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer

    def evaluate(self) -> float:
        result = self._expression()
        if self.tokenizer.peek() is not None:
            raise ParseError("Trailing data in expression")
        return result

    def _expression(self) -> float:
        node = self._term()
        while self.tokenizer.peek() and self.tokenizer.peek().type in ('PLUS', 'MINUS'):
            op = self.tokenizer.consume().type
            right = self._term()
            node = node + right if op == 'PLUS' else node - right
        return node

    def _term(self) -> float:
        node = self._unary()
        while self.tokenizer.peek() and self.tokenizer.peek().type in ('MUL', 'DIV'):
            op = self.tokenizer.consume().type
            right = self._unary()
            if op == 'MUL':
                node *= right
            else:
                if right == 0: raise ZeroDivisionError("Division by zero")
                node /= right
        return node

    def _unary(self) -> float:
        if self.tokenizer.peek() and self.tokenizer.peek().type == 'MINUS':
            self.tokenizer.consume()
            return -self._unary()
        return self._power()

    def _power(self) -> float:
        node = self._factor()
        if self.tokenizer.peek() and self.tokenizer.peek().type == 'POW':
            self.tokenizer.consume()
            node = math.pow(node, self._power()) # Right-associative
        return node

    def _factor(self) -> float:
        token = self.tokenizer.consume()
        if token.type == 'NUMBER':
            return token.value
        if token.type == 'LPAREN':
            result = self._expression()
            self.tokenizer.consume('RPAREN')
            return result
        raise ParseError(f"Unexpected token: {token.type}")

def evaluate(expression: str) -> float:
    """Public API to evaluate arithmetic expressions."""
    tokenizer = Tokenizer(expression)
    return Evaluator(tokenizer).evaluate()

