    print(f"Precedence: {evaluate('2 + 3 * 4')}") 

    # 2. Parentheses: (2 + 3) * 4 = 20
    print(f"Parentheses: {evaluate('(2 + 3) * 4')}")

    # 3. Unary minus and exponentiation: -2 ** 2 = -4 (Note: -2**2 is -(2**2))
    print(f"Unary/Power: {evaluate('-2 ** 2')}")

import enum
from abc import ABC, abstractmethod
from typing import Union

# -----------------------------------------------------------------------------
# 1. Exceptions
# -----------------------------------------------------------------------------

class EvaluationError(Exception):
    """Base exception for parsing and evaluation errors."""
    pass

# -----------------------------------------------------------------------------
# 2. Tokenizer (Lexer)
# -----------------------------------------------------------------------------

class TokenType(enum.Enum):
    INTEGER = "INTEGER"
    FLOAT = "FLOAT"
    PLUS = "PLUS"
    MINUS = "MINUS"
    MUL = "MUL"
    DIV = "DIV"
    POW = "POW"
    LPAREN = "LPAREN"
    RPAREN = "RPAREN"
    EOF = "EOF"

class Token:
    def __init__(self, type: TokenType, value: Union[int, float, str], pos: int):
        self.type = type
        self.value = value
        self.pos = pos

    def __repr__(self):
        return f"Token({self.type.name}, {self.value})"

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.current_char = self.text[0] if self.text else None

    def error(self, message: str):
        raise EvaluationError(f"Lexer error at position {self.pos}: {message}")

    def advance(self):
        self.pos += 1
        self.current_char = self.text[self.pos] if self.pos < len(self.text) else None

    def peek(self, offset=1):
        peek_pos = self.pos + offset
        return self.text[peek_pos] if peek_pos < len(self.text) else None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def read_number(self):
        """Reads an integer or float."""
        start_pos = self.pos
        has_dot = False
        value_str = ""

        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            if self.current_char == '.':
                if has_dot:
                    self.error("Multiple dots in number")
                has_dot = True
            value_str += self.current_char
            self.advance()

        token_type = TokenType.FLOAT if has_dot else TokenType.INTEGER
        value = float(value_str) if has_dot else int(value_str)
        return Token(token_type, value, start_pos)

    def get_next_token(self):
        """Main tokenizer logic."""
        while self.current_char is not None:
            # Skip whitespace
            if self.current_char.isspace():
                self.skip_whitespace()
                continue

            # Numbers
            if self.current_char.isdigit():
                return self.read_number()

            # Multi-character operators
            if self.current_char == '*':
                if self.peek() == '*':
                    pos = self.pos
                    self.advance()
                    self.advance()
                    return Token(TokenType.POW, '**', pos)
                else:
                    pos = self.pos
                    self.advance()
                    return Token(TokenType.MUL, '*', pos)

            # Single character operators
            if self.current_char == '+':
                pos = self.pos
                self.advance()
                return Token(TokenType.PLUS, '+', pos)

            if self.current_char == '-':
                pos = self.pos
                self.advance()
                return Token(TokenType.MINUS, '-', pos)

            if self.current_char == '/':
                pos = self.pos
                self.advance()
                return Token(TokenType.DIV, '/', pos)

            # Parentheses
            if self.current_char == '(':
                pos = self.pos
                self.advance()
                return Token(TokenType.LPAREN, '(', pos)

            if self.current_char == ')':
                pos = self.pos
                self.advance()
                return Token(TokenType.RPAREN, ')', pos)

            self.error(f"Unexpected character '{self.current_char}'")

        return Token(TokenType.EOF, None, self.pos)

    def tokenize(self):
        tokens = []
        while self.current_char is not None:
            tokens.append(self.get_next_token())
        tokens.append(Token(TokenType.EOF, None, self.pos))
        return tokens

# -----------------------------------------------------------------------------
# 3. Abstract Syntax Tree (AST)
# -----------------------------------------------------------------------------

class AST(ABC):
    @abstractmethod
    def accept(self, visitor):
        pass

class Number(AST):
    def __init__(self, value: Union[int, float]):
        self.value = value

    def accept(self, visitor):
        return visitor.visit_number(self)

class BinOp(AST):
    def __init__(self, left: AST, op: Token, right: AST):
        self.left = left
        self.op = op
        self.right = right

    def accept(self, visitor):
        return visitor.visit_binop(self)

class UnaryOp(AST):
    def __init__(self, op: Token, operand: AST):
        self.op = op
        self.operand = operand

    def accept(self, visitor):
        return visitor.visit_unaryop(self)

# -----------------------------------------------------------------------------
# 4. Parser (Recursive Descent)
# -----------------------------------------------------------------------------

class Parser:
    """
    Grammar:
    expression  -> term ((PLUS | MINUS) term)*
    term        -> factor ((MUL | DIV) factor)*
    factor      -> unary (POW factor)?     # Right associative
    unary       -> (MINUS) unary | power
    power       -> base                    # Alias to handle precedence cleanly if needed, 
                                           # but here merged with unary for simplicity or 
                                           # we can define base -> primary
    base        -> primary | unary         # Actually, let's stick to standard precedence:
                                           # ** > unary > * / > + -

    Refined Grammar:
    expression = term ((+|-) term)*
    term       = factor ((*|/) factor)*
    factor     = base (** factor)?
    base       = (- base) | primary
    primary    = NUMBER | ( expression )
    """

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0
        self.current_token = self.tokens[0]

    def error(self, message: str):
        raise EvaluationError(f"Parser error: {message}")

    def advance(self):
        self.pos += 1
        self.current_token = self.tokens[self.pos]

    def eat(self, token_type: TokenType):
        if self.current_token.type == token_type:
            self.advance()
        else:
            self.error(f"Expected {token_type}, got {self.current_token.type}")

    # --- Grammar Rules ---

    def expression(self):
        """expression -> term ((PLUS | MINUS) term)*"""
        result = self.term()

        while self.current_token.type in (TokenType.PLUS, TokenType.MINUS):
            op = self.current_token
            if op.type == TokenType.PLUS:
                self.eat(TokenType.PLUS)
            else:
                self.eat(TokenType.MINUS)

            right = self.term()
            result = BinOp(result, op, right)

        return result

    def term(self):
        """term -> factor ((MUL | DIV) factor)*"""
        result = self.factor()

        while self.current_token.type in (TokenType.MUL, TokenType.DIV):
            op = self.current_token
            if op.type == TokenType.MUL:
                self.eat(TokenType.MUL)
            else:
                self.eat(TokenType.DIV)

            right = self.factor()
            result = BinOp(result, op, right)

        return result

    def factor(self):
        """factor -> base (POW factor)? 
           Handles Right Associativity: 2 ** 3 ** 2 becomes 2 ** (3 ** 2)
        """
        node = self.base()

        if self.current_token.type == TokenType.POW:
            op = self.current_token
            self.eat(TokenType.POW)
            # Recursive call is on the right side to ensure right-associativity
            right = self.factor() 
            node = BinOp(node, op, right)

        return node

    def base(self):
        """base -> MINUS base | primary
           Handles Unary Minus precedence (higher than *, lower than **)
        """
        if self.current_token.type == TokenType.MINUS:
            op = self.current_token
            self.eat(TokenType.MINUS)
            operand = self.base() # Recurse to handle --2
            return UnaryOp(op, operand)

        return self.primary()

    def primary(self):
        """primary -> NUMBER | LPAREN expression RPAREN"""
        token = self.current_token

        if token.type in (TokenType.INTEGER, TokenType.FLOAT):
            self.eat(token.type)
            return Number(token.value)

        if token.type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            node = self.expression()
            if self.current_token.type != TokenType.RPAREN:
                self.error("Expected ')'")
            self.eat(TokenType.RPAREN)
            return node

        self.error(f"Unexpected token in primary: {token}")

    def parse(self):
        if self.current_token.type == TokenType.EOF and self.current_token.value is None:
            return None # Empty expression

        node = self.expression()

        if self.current_token.type != TokenType.EOF:
            self.error(f"Unexpected token after expression: {self.current_token}")

        return node

# -----------------------------------------------------------------------------
# 5. Evaluator
# -----------------------------------------------------------------------------

class Evaluator:
    def visit_number(self, node: Number):
        return float(node.value)

    def visit_binop(self, node: BinOp):
        left = node.left.accept(self)
        right = node.right.accept(self)

        if node.op.type == TokenType.PLUS:
            return left + right
        elif node.op.type == TokenType.MINUS:
            return left - right
        elif node.op.type == TokenType.MUL:
            return left * right
        elif node.op.type == TokenType.DIV:
            if right == 0:
                raise EvaluationError("Division by zero")
            return left / right
        elif node.op.type == TokenType.POW:
            return left ** right

        return 0.0

    def visit_unaryop(self, node: UnaryOp):
        operand = node.operand.accept(self)
        if node.op.type == TokenType.MINUS:
            return -operand
        return operand

# -----------------------------------------------------------------------------
# 6. Public API
# -----------------------------------------------------------------------------

def evaluate(expression: str) -> float:
    """
    Parses and evaluates an arithmetic expression.

    Supported operators: +, -, *, /, ** (exponentiation), unary -
    Precedence: ** > unary - > * / > + -

    Args:
        expression: A string containing the arithmetic expression.

    Returns:
        The result as a float.

    Raises:
        EvaluationError: If the expression is malformed or contains division by zero.
    """
    try:
        # 1. Tokenize
        lexer = Lexer(expression)
        tokens = lexer.tokenize()

        # 2. Parse into AST
        parser = Parser(tokens)
        ast = parser.parse()

        if ast is None:
            return 0.0

        # 3. Evaluate
        evaluator = Evaluator()
        return ast.accept(evaluator)

    except EvaluationError:
        raise
    except ZeroDivisionError:
        raise EvaluationError("Division by zero")
    except Exception as e:
        # Catch unexpected internal errors and wrap them
        raise EvaluationError(f"Internal error: {str(e)}")

