    # Example 1: Precedence and Right-Associativity
    # ** is higher than *, and ** is right-associative.
    # 2 * 3 ** 2 = 2 * 9 = 18
    # 2 ** 3 ** 2 = 2 ** 9 = 512
    expr1 = "2 * 3 ** 2"
