import re
from typing import Union, List, Optional

class ParseError(Exception):
    """Exception raised for errors in the parsing process."""
    pass

class Token:
    """Represents a token in the token stream."""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f'Token({self.type}, {self.value})'

class Tokenizer:
    """Converts a string expression into a stream of tokens."""
    def __init__(self, expression: str):
        self.tokens: List[Token] = []
        self.current_token_index: int = 0
        self.tokenize(expression)

    def tokenize(self, expression: str) -> None:
        """Tokenizes the input expression into a list of tokens."""
        token_specification = [
            ('NUMBER', r'\d+(\.\d*)?'),  # Integer or decimal number
            ('PLUS', r'\+'),              # Addition operator
            ('MINUS', r'-'),             # Subtraction operator
            ('TIMES', r'\*'),             # Multiplication operator
            ('DIVIDE', r'/'),            # Division operator
            ('POWER', r'\*\*'),          # Exponentiation operator
            ('LPAREN', r'\('),           # Left parenthesis
            ('RPAREN', r'\)'),           # Right parenthesis
            ('SKIP', r'[ \t]+'),         # Skip over spaces and tabs
            ('MISMATCH', r'.'),          # Any other character
        ]
        tok_regex = '|'.join(f'(?P<{pair[0]}>{pair[1]})' for pair in token_specification)
        for match in re.finditer(tok_regex, expression):
            kind = match.lastgroup
            value = match.group(kind)
            if kind == 'NUMBER':
                self.tokens.append(Token('NUMBER', float(value)))
            elif kind in {'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'POWER', 'LPAREN', 'RPAREN'}:
                self.tokens.append(Token(kind, value))
            elif kind == 'MISMATCH':
                raise ParseError(f"Unexpected character: {value}")

    def next_token(self) -> Optional[Token]:
        """Returns the next token in the stream."""
        if self.current_token_index < len(self.tokens):
            token = self.tokens[self.current_token_index]
            self.current_token_index += 1
            return token
        return None

    def peek_token(self) -> Optional[Token]:
        """Returns the next token without consuming it."""
        if self.current_token_index < len(self.tokens):
            return self.tokens[self.current_token_index]
        return None

class Parser:
    """Parses a stream of tokens and evaluates the expression."""
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer
        self.current_token: Optional[Token] = self.tokenizer.next_token()

    def parse(self) -> float:
        """Parses the expression and returns the evaluated result."""
        result = self.parse_expression()
        if self.current_token is not None:
            raise ParseError("Unexpected token after expression.")
        return result

    def parse_expression(self) -> float:
        """Parses an expression (handles + and -)."""
        result = self.parse_term()
        while self.current_token is not None and self.current_token.type in {'PLUS', 'MINUS'}:
            token = self.current_token
            self.current_token = self.tokenizer.next_token()
            if token.type == 'PLUS':
                result += self.parse_term()
            elif token.type == 'MINUS':
                result -= self.parse_term()
        return result

    def parse_term(self) -> float:
        """Parses a term (handles *, /)."""
        result = self.parse_factor()
        while self.current_token is not None and self.current_token.type in {'TIMES', 'DIVIDE'}:
            token = self.current_token
            self.current_token = self.tokenizer.next_token()
            if token.type == 'TIMES':
                result *= self.parse_factor()
            elif token.type == 'DIVIDE':
                divisor = self.parse_factor()
                if divisor == 0:
                    raise ZeroDivisionError("Division by zero.")
                result /= divisor
        return result

    def parse_factor(self) -> float:
        """Parses a factor (handles ** and parentheses)."""
        if self.current_token is None:
            raise ParseError("Unexpected end of expression.")

        if self.current_token.type == 'MINUS':
            self.current_token = self.tokenizer.next_token()
            return -self.parse_factor()  # Unary minus

        if self.current_token.type == 'LPAREN':
            self.current_token = self.tokenizer.next_token()
            result = self.parse_expression()
            if self.current_token is None or self.current_token.type != 'RPAREN':
                raise ParseError("Unbalanced parentheses.")
            self.current_token = self.tokenizer.next_token()
            return result

        if self.current_token.type == 'NUMBER':
            result = self.current_token.value
            self.current_token = self.tokenizer.next_token()
            return result

        raise ParseError(f"Unexpected token: {self.current_token}")

def evaluate(expression: str) -> float:
    """Evaluates an arithmetic expression and returns the result."""
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    return parser.parse()

# Usage examples
if __name__ == "__main__":
    print(evaluate("3 + 5"))               # 8.0
    print(evaluate("10 + 2 * 6"))          # 22.0
    print(evaluate("(2 + 3) * (5 - 1)"))   # 20.0
    print(evaluate("5 ** 2"))               # 25.0
    print(evaluate("-3 + 4.5"))             # 1.5
    print(evaluate("2 ** 3 ** 2"))          # 512.0

import re
from typing import Union, List, Tuple

class ParseError(Exception):
    """Custom exception for parsing errors."""
    pass

class Token:
    """Represents a token in the token stream."""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Tokenizer:
    """Converts a string expression into a stream of tokens."""
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.tokens: List[Token] = []
        self.tokenize()

    def tokenize(self):
        """Tokenizes the input expression."""
        token_specification = [
            ('NUMBER', r'\d+(\.\d*)?'),  # Integer or decimal number
            ('PLUS', r'\+'),              # Addition operator
            ('MINUS', r'-'),              # Subtraction operator
            ('TIMES', r'\*'),             # Multiplication operator
            ('DIVIDE', r'/'),             # Division operator
            ('POWER', r'\*\*'),           # Exponentiation operator
            ('LPAREN', r'\('),            # Left Parenthesis
            ('RPAREN', r'\)'),            # Right Parenthesis
            ('SKIP', r'[ \t]+'),          # Skip over spaces and tabs
            ('MISMATCH', r'.'),           # Any other character
        ]
        tok_regex = '|'.join(f'(?P<{pair[0]}>{pair[1]})' for pair in token_specification)
        for mo in re.finditer(tok_regex, self.expression):
            kind = mo.lastgroup
            value = mo.group(kind)
            if kind == 'NUMBER':
                value = float(value) if '.' in value else int(value)
                self.tokens.append(Token('NUMBER', value))
            elif kind in {'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'POWER', 'LPAREN', 'RPAREN'}:
                self.tokens.append(Token(kind, value))
            elif kind == 'MISMATCH':
                raise ParseError(f"Unexpected character: {value}")
        self.tokens.append(Token('EOF', None))  # End of file token

    def next_token(self) -> Token:
        """Returns the next token in the stream."""
        if self.tokens:
            return self.tokens.pop(0)
        return Token('EOF', None)

class Parser:
    """Parses tokens and evaluates arithmetic expressions."""
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer
        self.current_token = self.tokenizer.next_token()

    def error(self, message: str):
        """Raises a parsing error with a message."""
        raise ParseError(message)

    def eat(self, token_type: str):
        """Consumes a token of the given type."""
        if self.current_token.type == token_type:
            self.current_token = self.tokenizer.next_token()
        else:
            self.error(f"Expected token {token_type}, got {self.current_token.type}")

    def factor(self) -> float:
        """Parses a factor: NUMBER | LPAREN expression RPAREN | unary minus factor."""
        if self.current_token.type == 'NUMBER':
            value = self.current_token.value
            self.eat('NUMBER')
            return value
        elif self.current_token.type == 'LPAREN':
            self.eat('LPAREN')
            value = self.expr()
            self.eat('RPAREN')
            return value
        elif self.current_token.type == 'MINUS':
            self.eat('MINUS')
            return -self.factor()
        self.error("Invalid factor")

    def term(self) -> float:
        """Parses a term: factor ((TIMES | DIVIDE) factor)*."""
        value = self.factor()
        while self.current_token.type in ('TIMES', 'DIVIDE'):
            if self.current_token.type == 'TIMES':
                self.eat('TIMES')
                value *= self.factor()
            elif self.current_token.type == 'DIVIDE':
                self.eat('DIVIDE')
                divisor = self.factor()
                if divisor == 0:
                    self.error("Division by zero")
                value /= divisor
        return value

    def power(self) -> float:
        """Parses an exponentiation: term (POWER term)*."""
        value = self.term()
        while self.current_token.type == 'POWER':
            self.eat('POWER')
            value **= self.term()
        return value

    def expr(self) -> float:
        """Parses an expression: power ((PLUS | MINUS) power)*."""
        value = self.power()
        while self.current_token.type in ('PLUS', 'MINUS'):
            if self.current_token.type == 'PLUS':
                self.eat('PLUS')
                value += self.power()
            elif self.current_token.type == 'MINUS':
                self.eat('MINUS')
                value -= self.power()
        return value

def evaluate(expression: str) -> float:
    """Evaluates an arithmetic expression and returns the result."""
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    result = parser.expr()
    if parser.current_token.type != 'EOF':
        raise ParseError("Unexpected tokens at the end of the expression")
    return result

