"""Recursive-descent parser and evaluator for arithmetic expressions.

Supports: integers, floats, +, -, *, /, ** (right-associative), unary minus.
Operator precedence: ** > unary minus > * / > + -
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum, auto
from typing import Union


# =============================================================================
# Token Definitions
# =============================================================================


class TokenType(Enum):
    NUMBER = auto()
    PLUS = auto()
    MINUS = auto()
    STAR = auto()
    SLASH = auto()
    POWER = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()


@dataclass(frozen=True)
class Token:
    type: TokenType
    value: Union[str, float, None]
    position: int


# =============================================================================
# AST Node Definitions
# =============================================================================


@dataclass
class NumberNode:
    value: float


@dataclass
class UnaryOpNode:
    operator: TokenType
    operand: ASTNode


@dataclass
class BinaryOpNode:
    operator: TokenType
    left: ASTNode
    right: ASTNode


ASTNode = Union[NumberNode, UnaryOpNode, BinaryOpNode]


# =============================================================================
# Custom Exceptions
# =============================================================================


class ParseError(Exception):
    """Raised when tokenization or parsing fails."""

    def __init__(self, message: str, position: int | None = None):
        if position is not None:
            super().__init__(f"Position {position}: {message}")
        else:
            super().__init__(message)


class EvaluationError(Exception):
    """Raised during expression evaluation (e.g., division by zero)."""

    pass


# =============================================================================
# Tokenizer
# =============================================================================


class Tokenizer:
    """Converts an input string into a stream of tokens."""

    def __init__(self, text: str):
        self.text = text
        self.pos = 0

    def current_char(self) -> str | None:
        if self.pos >= len(self.text):
            return None
        return self.text[self.pos]

    def advance(self) -> None:
        self.pos += 1

    def skip_whitespace(self) -> None:
        while self.current_char() and self.current_char().isspace():
            self.advance()

    def read_number(self) -> float:
        """Read a number (integer or float) from the input."""
        start = self.pos
        has_dot = False

        while self.current_char() and (
            self.current_char().isdigit()
            or (self.current_char() == "." and not has_dot)
        ):
            if self.current_char() == ".":
                has_dot = True
            self.advance()

        num_str = self.text[start : self.pos]
        try:
            return float(num_str)
        except ValueError:
            raise ParseError(f"Invalid number: {num_str}", start)

    def read_operator(self) -> TokenType:
        """Read an operator token, checking for **."""
        char = self.text[self.pos]
        self.advance()

        if char == "*" and self.current_char() == "*":
            self.advance()
            return TokenType.POWER

        if char == "/":
            return TokenType.SLASH
        if char == "+":
            return TokenType.PLUS
        if char == "-":
            return TokenType.MINUS
        if char == "*":
            return TokenType.STAR

        raise ParseError(f"Unexpected operator: {char}", self.pos - 1)

    def next_token(self) -> Token:
        """Return the next token in the stream."""
        while self.current_char():
            if self.current_char().isspace():
                self.skip_whitespace()
                continue

            pos = self.pos

            if self.current_char().isdigit() or self.current_char() == ".":
                return Token(TokenType.NUMBER, self.read_number(), pos)

            if self.current_char() in "+-*/()":
                op_type = self.read_operator()
                if op_type == TokenType.POWER:
                    return Token(TokenType.POWER, "**", pos)
                if op_type == TokenType.PLUS:
                    return Token(TokenType.PLUS, "+", pos)
                if op_type == TokenType.MINUS:
                    return Token(TokenType.MINUS, "-", pos)
                if op_type == TokenType.STAR:
                    return Token(TokenType.STAR, "*", pos)
                if op_type == TokenType.SLASH:
                    return Token(TokenType.SLASH, "/", pos)

            if self.current_char() == "(":
                self.advance()
                return Token(TokenType.LPAREN, "(", pos)

            if self.current_char() == ")":
                self.advance()
                return Token(TokenType.RPAREN, ")", pos)

            raise ParseError(
                f"Unexpected character: {self.current_char()!r}", self.pos
            )

        return Token(TokenType.EOF, None, self.pos)

    def tokenize(self) -> list[Token]:
        """Tokenize the entire input and return a list of tokens."""
        tokens = []
        while True:
            token = self.next_token()
            tokens.append(token)
            if token.type == TokenType.EOF:
                break
        return tokens


# =============================================================================
# Parser (Recursive Descent)
# =============================================================================


class Parser:
    """Recursive-descent parser building an AST from tokens.

    Grammar (precedence from lowest to highest):
        expression = term (('+' | '-') term)*
        term       = factor (('*' | '/') factor)*
        factor     = power
        power      = unary ('**' power)?      // right-associative
        unary      = ('+' | '-') unary | primary
        primary    = NUMBER | '(' expression ')'
    """

    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def current(self) -> Token:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return Token(TokenType.EOF, None, -1)

    def eat(self, expected: TokenType) -> Token:
        """Consume the current token if it matches expected type."""
        token = self.current()
        if token.type != expected:
            raise ParseError(
                f"Expected {expected.name}, got {token.type.name}", token.position
            )
        self.pos += 1
        return token

    def parse(self) -> ASTNode:
        """Parse the token stream and return the root AST node."""
        result = self.expression()
        if self.current().type != TokenType.EOF:
            raise ParseError(
                f"Unexpected token after expression: {self.current().type.name}",
                self.current().position,
            )
        return result

    def expression(self) -> ASTNode:
        """Parse addition and subtraction (lowest precedence)."""
        node = self.term()

        while self.current().type in (TokenType.PLUS, TokenType.MINUS):
            op = self.current().type
            self.eat(op)
            node = BinaryOpNode(operator=op, left=node, right=self.term())

        return node

    def term(self) -> ASTNode:
        """Parse multiplication and division."""
        node = self.factor()

        while self.current().type in (TokenType.STAR, TokenType.SLASH):
            op = self.current().type
            self.eat(op)
            node = BinaryOpNode(operator=op, left=node, right=self.factor())

        return node

    def factor(self) -> ASTNode:
        """Parse exponentiation (right-associative)."""
        node = self.unary()

        if self.current().type == TokenType.POWER:
            self.eat(TokenType.POWER)
            # Right-associative: parse the right side as factor again
            right = self.factor()
            node = BinaryOpNode(operator=TokenType.POWER, left=node, right=right)

        return node

    def unary(self) -> ASTNode:
        """Parse unary plus and minus."""
        if self.current().type in (TokenType.PLUS, TokenType.MINUS):
            op = self.current().type
            self.eat(op)
            operand = self.unary()
            return UnaryOpNode(operator=op, operand=operand)

        return self.primary()

    def primary(self) -> ASTNode:
        """Parse numbers and parenthesized expressions."""
        token = self.current()

        if token.type == TokenType.NUMBER:
            self.eat(TokenType.NUMBER)
            return NumberNode(value=token.value)

        if token.type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            node = self.expression()
            self.eat(TokenType.RPAREN)
            return node

        raise ParseError(
            f"Unexpected token in primary: {token.type.name}", token.position
        )


# =============================================================================
# Evaluator
# =============================================================================


class Evaluator:
    """Evaluates an AST to produce a float result."""

    @staticmethod
    def evaluate(node: ASTNode) -> float:
        """Recursively evaluate the AST node."""
        match node:
            case NumberNode(value=value):
                return value

            case UnaryOpNode(operator=op, operand=operand):
                value = Evaluator.evaluate(operand)
                if op == TokenType.PLUS:
                    return value
                if op == TokenType.MINUS:
                    return -value
                raise EvaluationError(f"Unknown unary operator: {op}")

            case BinaryOpNode(operator=op, left=left, right=right):
                left_val = Evaluator.evaluate(left)
                right_val = Evaluator.evaluate(right)

                if op == TokenType.PLUS:
                    return left_val + right_val
                if op == TokenType.MINUS:
                    return left_val - right_val
                if op == TokenType.STAR:
                    return left_val * right_val
                if op == TokenType.SLASH:
                    if right_val == 0:
                        raise EvaluationError("Division by zero")
                    return left_val / right_val
                if op == TokenType.POWER:
                    return left_val ** right_val

                raise EvaluationError(f"Unknown binary operator: {op}")

            case _:
                raise EvaluationError(f"Unknown node type: {type(node)}")


# =============================================================================
# Public API
# =============================================================================


def evaluate(expression: str) -> float:
    """Evaluate an arithmetic expression and return the result as a float.

    Args:
        expression: A string containing an arithmetic expression.

    Returns:
        The result of the expression as a float.

    Raises:
        ParseError: If the expression is malformed (unbalanced parentheses,
            unexpected characters, etc.).
        EvaluationError: If evaluation fails (e.g., division by zero).

    Examples:
        >>> evaluate("2 + 3 * 4")
        14.0
        >>> evaluate("(2 + 3) * 4")
        20.0
        >>> evaluate("-3 + 5")
        2.0
    """
    tokenizer = Tokenizer(expression)
    tokens = tokenizer.tokenize()

    parser = Parser(tokens)
    ast = parser.parse()

    return Evaluator.evaluate(ast)


