import re

class Parser:
    def __init__(self, expression):
        # Tokenize: match numbers, operators, or parentheses
        self.tokens = re.findall(r'\d+\.?\d*|\+|\-|\*|\/|\(|\)', expression)
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self):
        token = self.peek()
        self.pos += 1
        return token

    # Expression -> Term { ('+'|'-') Term }
    def parse_expression(self):
        node = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self.parse_term()
            node = (node + right) if op == '+' else (node - right)
        return node

    # Term -> Factor { ('*'|'/') Factor }
    def parse_term(self):
        node = self.parse_factor()
        while self.peek() in ('*', '/'):
            op = self.consume()
            right = self.parse_factor()
            node = (node * right) if op == '*' else (node / right)
        return node

    # Factor -> Number | '(' Expression ')'
    def parse_factor(self):
        token = self.consume()
        if token == '(':
            result = self.parse_expression()
            self.consume()  # Consume ')'
            return result
        return float(token)

