class Parser:
    def __init__(self, text):
        self.text = text.replace(' ', '')  # Remove all whitespace
        self.pos = 0
        self.current_char = self.text[self.pos] if self.text else None

    def advance(self):
        """Advance to the next character"""
        self.pos += 1
        if self.pos > len(self.text) - 1:
            self.current_char = None
        else:
            self.current_char = self.text[self.pos]

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def integer(self):
        """Return a (multidigit) integer consumed from the input"""
        result = ''
        while (self.current_char is not None and
               self.current_char.isdigit()):
            result += self.current_char
            self.advance()
        return int(result) if result else None

    def get_next_token(self):
        """Lexical analyzer (also known as scanner or tokenizer)"""
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue

            if self.current_char.isdigit():
                token = self.integer()
                return ('INTEGER', token)

            if self.current_char == '+':
                self.advance()
                return ('PLUS', '+')

            if self.current_char == '-':
                self.advance()
                return ('MINUS', '-')

            if self.current_char == '*':
                self.advance()
                return ('MULTIPLY', '*')

            if self.current_char == '/':
                self.advance()
                return ('DIVIDE', '/')

            if self.current_char == '(':
                self.advance()
                return ('LPAREN', '(')

            if self.current_char == ')':
                self.advance()
                return ('RPAREN', ')')

            if self.current_char == '\n':
                self.advance()
                continue

            raise Exception(f"Invalid character: {self.current_char}")

        return ('EOF', None)

    def eat(self, token_type):
        """Consume the current token if it matches the expected type"""
        token = self.get_next_token()
        if token[0] != token_type:
            raise Exception(f"Expected {token_type}, got {token[0]}")
        return token

    def factor(self):
        """factor : INTEGER | LPAREN expr RPAREN"""
        token = self.get_next_token()
        if token[0] == 'INTEGER':
            return token[1]
        elif token[0] == 'LPAREN':
            result = self.expr()
            self.eat('RPAREN')
            return result
        else:
            raise Exception(f"Unexpected token: {token}")

    def term(self):
        """term : factor ((MULTIPLY|DIVIDE) factor)*"""
        result = self.factor()

        while True:
            token = self.get_next_token()
            if token[0] == 'MULTIPLY':
                result *= self.factor()
            elif token[0] == 'DIVIDE':
                result /= self.factor()
            else:
                # Put the token back if it's not part of this production
                self.pos -= len(token[1]) if isinstance(token[1], str) else 1
                self.current_char = self.text[self.pos] if self.pos >= 0 else None
                break

        return result

    def expr(self):
        """expr   : term ((PLUS | MINUS) term)*
           term   : factor ((MULTIPLY|DIVIDE) factor)*
           factor : INTEGER | LPAREN expr RPAREN"""
        result = self.term()

        while True:
            token = self.get_next_token()
            if token[0] == 'PLUS':
                result += self.term()
            elif token[0] == 'MINUS':
                result -= self.term()
            else:
                # Put the token back if it's not part of this production
                self.pos -= len(token[1]) if isinstance(token[1], str) else 1
                self.current_char = self.text[self.pos] if self.pos >= 0 else None
                break

        return result

    def parse(self):
        """Parse the expression and return the result"""
        return self.expr()

def evaluate_expression(expression):
    """Evaluate a mathematical expression string"""
    parser = Parser(expression)
    return parser.parse()

