class Parser:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.current_token = None
        self.advance()

    def advance(self):
        """Advance to the next token and update current_token"""
        while self.pos < len(self.text) and self.text[self.pos].isspace():
            self.pos += 1

        if self.pos >= len(self.text):
            self.current_token = None
            return

        char = self.text[self.pos]

        if char.isdigit():
            # Handle numbers
            num = 0
            while self.pos < len(self.text) and self.text[self.pos].isdigit():
                num = num * 10 + int(self.text[self.pos])
                self.pos += 1
            self.current_token = ('INTEGER', num)
        elif char in '+-*/()':
            # Handle operators and parentheses
            self.current_token = (char, char)
            self.pos += 1
        else:
            raise Exception(f"Invalid character: {char}")

    def eat(self, token_type):
        """Consume the current token if it matches the expected type"""
        if self.current_token is None:
            raise Exception("Unexpected end of input")
        if token_type != self.current_token[0]:
            raise Exception(f"Expected {token_type}, got {self.current_token[0]}")
        self.advance()

    def parse(self):
        """Parse and evaluate the expression"""
        return self.expr()

    def expr(self):
        """Parse an expression (handles + and -)"""
        node = self.term()

        while self.current_token is not None and self.current_token[0] in ('+', '-'):
            token_type = self.current_token[0]
            self.eat(token_type)
            right = self.term()
            node = (token_type, node, right)

        return node

    def term(self):
        """Parse a term (handles * and /)"""
        node = self.factor()

        while self.current_token is not None and self.current_token[0] in ('*', '/'):
            token_type = self.current_token[0]
            self.eat(token_type)
            right = self.factor()
            node = (token_type, node, right)

        return node

    def factor(self):
        """Parse a factor (handles numbers and parenthesized expressions)"""
        token = self.current_token

        if token[0] == '(':
            self.eat('(')
            node = self.expr()
            self.eat(')')
            return node
        elif token[0] == 'INTEGER':
            self.eat('INTEGER')
            return ('INTEGER', token[1])
        else:
            raise Exception(f"Unexpected token: {token[0]}")

def evaluate(node):
    """Evaluate the parsed expression tree"""
    if node[0] == 'INTEGER':
        return node[1]
    elif node[0] in ('+', '-', '*', '/'):
        left_val = evaluate(node[1])
        right_val = evaluate(node[2])

        if node[0] == '+':
            return left_val + right_val
        elif node[0] == '-':
            return left_val - right_val
        elif node[0] == '*':
            return left_val * right_val
        elif node[0] == '/':
            return left_val / right_val
    else:
        raise Exception(f"Unknown node type: {node[0]}")

def parse_and_evaluate(expr):
    """Parse and evaluate an arithmetic expression"""
    parser = Parser(expr)
    parsed = parser.parse()
    return evaluate(parsed)

