import re
from typing import List, Tuple, Optional
from dataclasses import dataclass

# --- Domain Exceptions ---

class ExpressionError(Exception):
    """Base class for all expression parsing and evaluation errors."""
    pass

class TokenError(ExpressionError):
    """Raised when the tokenizer encounters an invalid character."""
    pass

class ParseError(ExpressionError):
    """Raised when the parser encounters a syntax error."""
    pass

# --- Tokenizer ---

@dataclass
class Token:
    type: str
    value: any

class Tokenizer:
    # Token definitions: (Type, Regex)
    # Order matters: multi-char operators must come before single-char operators
    TOKEN_SPEC = [
        ('NUMBER', r'\d+(\.\d*)?'), 
        ('POWER',  r'\*\*'),
        ('PLUS',   r'\+'),
        ('MINUS',  r'-'),
        ('MUL',    r'\*'),
        ('DIV',    r'/'),
        ('LPAREN', r'\('),
        ('RPAREN', r'\)'),
        ('SKIP',   r'\s+'),
        ('MISMATCH', r'.'),
    ]

    def __init__(self, text: str):
        self.text = text
        self.tokens: List[Token] = []
        self._tokenize()

    def _tokenize(self) -> None:
        regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in self.TOKEN_SPEC)
        for mo in re.finditer(regex, self.text):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                self.tokens.append(Token(kind, float(value)))
            elif kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise TokenError(f"Unexpected character: {value!r}")
            else:
                self.tokens.append(Token(kind, value))
        self.tokens.append(Token('EOF', None))

# --- Parser & Evaluator ---

class Parser:
    """
    Grammar:
    expression -> term { ('+' | '-') term }
    term       -> factor { ('*' | '/') factor }
    factor     -> unary { '**' factor }  (Right associative)
    unary      -> '-' unary | primary
    primary    -> NUMBER | '(' expression ')'
    """

    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def _current(self) -> Token:
        return self.tokens[self.pos]

    def _eat(self, expected_type: str) -> Token:
        token = self._current()
        if token.type == expected_type:
            self.pos += 1
            return token
        raise ParseError(f"Expected {expected_type}, found {token.type} at position {self.pos}")

    def parse(self) -> float:
        result = self._expression()
        if self._current().type != 'EOF':
            raise ParseError(f"Unexpected token {self._current().type} at end of expression")
        return result

    def _expression(self) -> float:
        # Handle + and - (Lowest precedence)
        node = self._term()
        while self._current().type in ('PLUS', 'MINUS'):
            token = self._current()
            self._eat(token.type)
            if token.type == 'PLUS':
                node += self._term()
            else:
                node -= self._term()
        return node

    def _term(self) -> float:
        # Handle * and /
        node = self._factor()
        while self._current().type in ('MUL', 'DIV'):
            token = self._current()
            self._eat(token.type)
            if token.type == 'MUL':
                node *= self._factor()
            else:
                divisor = self._factor()
                if divisor == 0:
                    raise ExpressionError("Division by zero")
                node /= divisor
        return node

    def _factor(self) -> float:
        # Handle ** (Right associative)
        node = self._unary()
        if self._current().type == 'POWER':
            self._eat('POWER')
            # Recursive call to _factor instead of while loop ensures right-associativity
            node = node ** self._factor()
        return node

    def _unary(self) -> float:
        # Handle unary minus
        if self._current().type == 'MINUS':
            self._eat('MINUS')
            return -self._unary()
        return self._primary()

    def _primary(self) -> float:
        # Handle numbers and parentheses
        token = self._current()
        if token.type == 'NUMBER':
            self._eat('NUMBER')
            return token.value
        elif token.type == 'LPAREN':
            self._eat('LPAREN')
            result = self._expression()
            if self._current().type != 'RPAREN':
                raise ParseError("Unbalanced parentheses: Missing ')'")
            self._eat('RPAREN')
            return result
        else:
            raise ParseError(f"Unexpected token {token.type} in primary expression")

def evaluate(expression: str) -> float:
    """
    Public API to evaluate an arithmetic expression.
    """
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer.tokens)
    return parser.parse()

