from __future__ import annotations
from dataclasses import dataclass
from typing import List, Tuple, Union


# ----------------------------------------------------------------------
# Token definitions
# ----------------------------------------------------------------------
@dataclass(frozen=True)
class Token:
    """Simple token used by the lexer."""
    type: str
    value: Union[float, None] = None   # only NUMERIC tokens carry a value


TOKEN_TYPES = {
    "NUMBER": "NUMBER",
    "PLUS": "+",
    "MINUS": "-",
    "STAR": "*",
    "SLASH": "/",
    "POW": "**",
    "LPAREN": "(",
    "RPAREN": ")",
    "EOF": "\0",
}


# ----------------------------------------------------------------------
# Lexer (tokenizer)
# ----------------------------------------------------------------------
class Lexer:
    """Turns a string into a stream of Token objects."""

    def __init__(self, text: str) -> None:
        self.text = text
        self.pos = 0
        self.current_char: Union[str, None] = self.text[0] if self.text else None

    # ------------------------------------------------------------------
    # Helper methods
    # ------------------------------------------------------------------
    def advance(self) -> None:
        """Move to the next character."""
        self.pos += 1
        if self.pos >= len(self.text):
            self.current_char = None
        else:
            self.current_char = self.text[self.pos]

    def skip_whitespace(self) -> None:
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self) -> float:
        """Consume a sequence of digits with an optional decimal point."""
        start = self.pos
        dot_seen = False
        while self.current_char is not None and (
            self.current_char.isdigit() or self.current_char == "."
        ):
            if self.current_char == ".":
                if dot_seen:                     # second dot → malformed number
                    raise ValueError(f"Invalid number format at position {self.pos}")
                dot_seen = True
            self.advance()
        num_str = self.text[start:self.pos]
        try:
            return float(num_str)
        except ValueError as exc:
            raise ValueError(f"Invalid number '{num_str}'") from exc

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def get_next_token(self) -> Token:
        """Return the next token from the input."""
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue

            if self.current_char.isdigit() or self.current_char == ".":
                return Token(TOKEN_TYPES["NUMBER"], self.number())

            # two‑character operator **
            if self.current_char == "*":
                if self.peek() == "*":
                    self.advance()  # consume first *
                    self.advance()  # consume second *
                    return Token(TOKEN_TYPES["POW"])
                return Token(TOKEN_TYPES["STAR"])

            if self.current_char == "+":
                self.advance()
                return Token(TOKEN_TYPES["PLUS"])
            if self.current_char == "-":
                self.advance()
                return Token(TOKEN_TYPES["MINUS"])
            if self.current_char == "/":
                self.advance()
                return Token(TOKEN_TYPES["SLASH"])
            if self.current_char == "(":
                self.advance()
                return Token(TOKEN_TYPES["LPAREN"])
            if self.current_char == ")":
                self.advance()
                return Token(TOKEN_TYPES["RPAREN"])

            # Anything else is illegal
            raise ValueError(f"Unexpected character '{self.current_char}' at position {self.pos}")

        return Token(TOKEN_TYPES["EOF"])

    def peek(self) -> Union[str, None]:
        """Look ahead one character without consuming it."""
        if self.pos + 1 >= len(self.text):
            return None
        return self.text[self.pos + 1]


# ----------------------------------------------------------------------
# Parser / Evaluator (recursive‑descent)
# ----------------------------------------------------------------------
class Parser:
    """Recursive‑descent parser that evaluates the expression while parsing."""

    def __init__(self, lexer: Lexer) -> None:
        self.lexer = lexer
        self.current_token: Token = self.lexer.get_next_token()

    # ------------------------------------------------------------------
    # Token management
    # ------------------------------------------------------------------
    def eat(self, token_type: str) -> None:
        """Consume the current token if it matches *token_type*; otherwise error."""
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            expected = token_type
            got = self.current_token.type
            raise SyntaxError(
                f"Expected token {expected!r} but got {got!r} "
                f"(value={self.current_token.value!r})"
            )

    # ------------------------------------------------------------------
    # Grammar methods (each returns a float)
    # ------------------------------------------------------------------
    def parse(self) -> float:
        """Entry point – parses an expression and ensures EOF follows."""
        result = self.expr()
        if self.current_token.type != TOKEN_TYPES["EOF"]:
            raise SyntaxError(
                f"Unexpected trailing tokens after position {self.lexer.pos}"
            )
        return result

    # expression → term ((+|-) term)*
    def expr(self) -> float:
        left = self.term()
        while self.current_token.type in (TOKEN_TYPES["PLUS"], TOKEN_TYPES["MINUS"]):
            op = self.current_token.type
            self.eat(op)
            right = self.term()
            if op == TOKEN_TYPES["PLUS"]:
                left += right
            else:  # MINUS
                left -= right
        return left

    # term → power ((*|/) power)*
    def term(self) -> float:
        left = self.power()
        while self.current_token.type in (TOKEN_TYPES["STAR"], TOKEN_TYPES["SLASH"]):
            op = self.current_token.type
            self.eat(op)
            right = self.power()
            if op == TOKEN_TYPES["STAR"]:
                left *= right
            else:  # SLASH
                if right == 0.0:
                    raise ZeroDivisionError("division by zero")
                left /= right
        return left

    # power → unary ( ** power )?   # right‑associative
    def power(self) -> float:
        left = self.unary()
        if self.current_token.type == TOKEN_TYPES["POW"]:
            self.eat(TOKEN_TYPES["POW"])
            right = self.power()          # note: recursive call for right‑associativity
            return left ** right
        return left

    # unary → ('-') unary | primary
    def unary(self) -> float:
        if self.current_token.type == TOKEN_TYPES["MINUS"]:
            self.eat(TOKEN_TYPES["MINUS"])
            return -self.unary()
        return self.primary()

    # primary → NUMBER | '(' expression ')'
    def primary(self) -> float:
        tok = self.current_token
        if tok.type == TOKEN_TYPES["NUMBER"]:
            self.eat(TOKEN_TYPES["NUMBER"])
            return tok.value  # type: ignore[return-value]
        if tok.type == TOKEN_TYPES["LPAREN"]:
            self.eat(TOKEN_TYPES["LPAREN"])
            val = self.expr()
            self.eat(TOKEN_TYPES["RPAREN"])
            return val
        raise SyntaxError(
            f"Unexpected token {tok.type!r} (value={tok.value!r}) while expecting a number or '('"
