        if self.current_char == '(':
            self.advance()  # skip '('
            result = self.expr()
            self.advance()  # skip ')'
            return result
        else:
            return self.parse_number()

    def term(self):
        """Handles the term grammar rule."""
        result = self.factor()

        while self.current_char is not None and self.current_char in ('*', '/'):
            if self.current_char == '*':
                self.advance()
                result *= self.factor()
            elif self.current_char == '/':
                self.advance()
                result /= self.factor()

        return result

    def expr(self):
        """Handles the expression grammar rule."""
        result = self.term()

        while self.current_char is not None and self.current_char in ('+', '-'):
            if self.current_char == '+':
                self.advance()
                result += self.term()
            elif self.current_char == '-':
                self.advance()
                result -= self.term()

        return result

    def parse(self):
        """Wrapper function to initiate parsing."""
        self.skip_whitespace()
        return self.expr()

