import re
import math
from typing import Union, List

class Token:
    def __init__(self, type: str, value: Union[int, float, str]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Lexer:
    """Tokenizes the input string."""

    TOKEN_TYPES = [
        ('NUMBER', r'\d+\.?\d*'),  # Integer or float
        ('PLUS', r'\+'),
        ('MINUS', r'-'),
        ('MULTIPLY', r'\*'),
        ('DIVIDE', r'/'),
        ('LPAREN', r'\('),
        ('RPAREN', r'\)'),
        ('WHITESPACE', r'\s+'),
    ]

    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.current_char = self.text[0] if self.text else None

    def error(self):
        raise Exception("Invalid character")

    def advance(self):
        """Move the pos pointer and update current_char."""
        self.pos += 1
        self.current_char = self.text[self.pos] if self.pos < len(self.text) else None

    def skip_whitespace(self):
        """Skip whitespace characters."""
        while self.current_char and self.current_char.isspace():
            self.advance()

    def get_next_token(self):
        """Lexical analyzer that returns the next token."""
        while self.current_char is not None:
            # Skip whitespace
            if self.current_char.isspace():
                self.skip_whitespace()
                continue

            # Match numbers (integer or float)
            if self.current_char.isdigit():
                return self._get_number()

            # Match operators and parentheses
            for token_type, pattern in self.TOKEN_TYPES:
                if token_type == 'WHITESPACE':
                    continue
                if re.match(pattern, self.text[self.pos:]):
                    token = Token(token_type, self.text[self.pos])
                    self.advance()
                    return token

            self.error()

        return Token('EOF', None)

    def _get_number(self):
        """Extract a number token."""
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()

        # Return as float if there's a decimal point, otherwise int
        if '.' in result:
            return Token('NUMBER', float(result))
        return Token('NUMBER', int(result))

class Parser:
    """Recursive descent parser for arithmetic expressions."""

    # Grammar:
    # expression     → term ( (PLUS | MINUS) term )*
    # term            → unary ( (MULTIPLY | DIVIDE) unary )*
    # unary           → (MINUS) unary | factor
    # factor          → NUMBER | LPAREN expression RPAREN

    def __init__(self, lexer: Lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self):
        raise Exception("Invalid syntax")

    def eat(self, token_type: str):
        """Consume the current token and advance to the next."""
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error()

    def parse(self):
        """Parse and evaluate the expression."""
        result = self.expression()
        if self.current_token.type != 'EOF':
            self.error()
        return result

    def expression(self):
        """expression → term ( (PLUS | MINUS) term )*"""
        result = self.term()

        while self.current_token.type in ('PLUS', 'MINUS'):
            token = self.current_token
            if token.type == 'PLUS':
                self.eat('PLUS')
                result = result + self.term()
            elif token.type == 'MINUS':
                self.eat('MINUS')
                result = result - self.term()

        return result

    def term(self):
        """term → unary ( (MULTIPLY | DIVIDE) unary )*"""
        result = self.unary()

        while self.current_token.type in ('MULTIPLY', 'DIVIDE'):
            token = self.current_token
            if token.type == 'MULTIPLY':
                self.eat('MULTIPLY')
                result = result * self.unary()
            elif token.type == 'DIVIDE':
                self.eat('DIVIDE')
                divisor = self.unary()
                if divisor == 0:
                    raise ZeroDivisionError("Division by zero")
                result = result / divisor

        return result

    def unary(self):
        """unary → (MINUS) unary | factor"""
        if self.current_token.type == 'MINUS':
            self.eat('MINUS')
            return -self.unary()
        return self.factor()

    def factor(self):
        """factor → NUMBER | LPAREN expression RPAREN"""
        token = self.current_token

        if token.type == 'NUMBER':
            self.eat('NUMBER')
            return token.value
        elif token.type == 'LPAREN':
            self.eat('LPAREN')
            result = self.expression()
            self.eat('RPAREN')
            return result
        else:
            self.error()

class Evaluator:
    """Combined lexer, parser, and evaluator."""

    def __init__(self, text: str):
        self.lexer = Lexer(text)
        self.parser = Parser(self.lexer)

    def evaluate(self):
        """Evaluate the expression and return the result."""
        return self.parser.parse()

def evaluate_expression(expression: str) -> Union[int, float]:
    """
    Evaluate an arithmetic expression.

    Args:
        expression: A string containing the arithmetic expression

    Returns:
        The result of the evaluation

    Examples:
        >>> evaluate_expression("2 + 3")
        5
        >>> evaluate_expression("2 + 3 * 4")
        14
        >>> evaluate_expression("(2 + 3) * 4")
        20
    """
    evaluator = Evaluator(expression)
    return evaluator.evaluate()

