import re
from typing import Union

class Tokenizer:
    """Splits input string into tokens: numbers, operators, parentheses."""
    def __init__(self, text: str):
        # Match numbers (int/float), operators, parentheses. Skip whitespace.
        raw_tokens = re.findall(r'\d+(?:\.\d+)?|\.\d+|[+\-*/()]|\s+', text)
        self.tokens = [t for t in raw_tokens if not t.isspace()]
        self.idx = 0

    def peek(self) -> str:
        return self.tokens[self.idx] if self.idx < len(self.tokens) else 'EOF'

    def consume(self) -> str:
        tok = self.peek()
        self.idx += 1
        return tok

    def expect(self, val: str) -> str:
        tok = self.peek()
        if tok != val:
            raise SyntaxError(f"Expected '{val}', got '{tok}'")
        return self.consume()


class ArithmeticParser:
    """Recursive-descent parser that directly evaluates expressions."""
    def __init__(self, text: str):
        self.tok = Tokenizer(text)

    def parse(self) -> Union[int, float]:
        """Entry point: parse expression and ensure full consumption."""
        try:
            result = self.expr()
            if self.tok.peek() != 'EOF':
                raise SyntaxError(f"Unexpected trailing token: {self.tok.peek()}")
            return result
        except Exception as e:
            raise RuntimeError(f"Parse/Evaluation Error: {e}")

    # Grammar rule: expr -> term { ('+' | '-') term }
    def expr(self) -> Union[int, float]:
        val = self.term()
        while self.tok.peek() in ('+', '-'):
            op = self.tok.consume()
            right = self.term()
            val = val + right if op == '+' else val - right
        return val

    # Grammar rule: term -> factor { ('*' | '/') factor }
    def term(self) -> Union[int, float]:
        val = self.factor()
        while self.tok.peek() in ('*', '/'):
            op = self.tok.consume()
            right = self.factor()
            if op == '/', right == 0:
                raise ZeroDivisionError("Division by zero")
            val = val * right if op == '*' else val / right
        return val

    # Grammar rule: factor -> NUMBER | '(' expr ')' | operator factor
    def factor(self) -> Union[int, float]:
        tok = self.tok.peek()

        if tok == 'EOF':
            raise SyntaxError("Unexpected end of input")

        if tok == '(':
            self.tok.consume()
            val = self.expr()
            self.tok.expect(')')
            return val

        if tok in ('+', '-'):
            op = self.tok.consume()
            val = self.factor()
            return -val if op == '-' else val

        if all(c.isdigit() or c == '.' for c in tok):
            self.tok.consume()
            return float(tok) if '.' in tok else int(tok)

        raise SyntaxError(f"Unexpected token: {tok}")


