import re

# --- Tokenizer (Lexer) ---

class Token:
    def __init__(self, type, value=None):
        self.type = type
        self.value = value

    def __repr__(self):
        if self.value is not None:
            return f"Token({self.type}, {self.value})"
        return f"Token({self.type})"

TOKEN_TYPES = {
    'NUMBER': r'\d+(\.\d*)?',
    'PLUS': r'\+',
    'MINUS': r'-',
    'MULTIPLY': r'\*',
    'DIVIDE': r'/',
    'LPAREN': r'\(',
    'RPAREN': r'\)',
    'WHITESPACE': r'\s+',  # To ignore whitespace
}

class Lexer:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.tokens = self._tokenize()

    def _tokenize(self):
        tokens = []
        token_specs = [
            ('NUMBER', r'\d+(\.\d*)?'),
            ('PLUS', r'\+'),
            ('MINUS', r'-'),
            ('MULTIPLY', r'\*'),
            ('DIVIDE', r'\/'),
            ('LPAREN', r'\('),
            ('RPAREN', r'\)'),
            ('WHITESPACE', r'\s+'),
        ]

        while self.pos < len(self.text):
            match = None
            for token_type, pattern in token_specs:
                regex = re.compile(pattern)
                m = regex.match(self.text, self.pos)
                if m:
                    if token_type != 'WHITESPACE':
                        value = m.group(0)
                        if token_type == 'NUMBER':
                            tokens.append(Token('NUMBER', float(value)))
                        else:
                            tokens.append(Token(token_type))
                    self.pos = m.end()
                    match = True
                    break
            if not match:
                raise Exception(f"Lexer error: Invalid character at position {self.pos}")

        tokens.append(Token('EOF')) # Mark the end of input
        return tokens

    def get_tokens(self):
        return self.tokens

# --- Parser and Evaluator ---

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.current_token_index = 0
        self.current_token = self.tokens[self.current_token_index]

    def advance(self):
        self.current_token_index += 1
        if self.current_token_index < len(self.tokens):
            self.current_token = self.tokens[self.current_token_index]
        else:
            self.current_token = Token('EOF') # Ensure current_token reflects EOF

    def eat(self, token_type):
        if self.current_token.type == token_type:
            self.advance()
        else:
            raise Exception(f"Parser error: Expected {token_type}, got {self.current_token.type}")

