from typing import List, Tuple, Union, Optional
from enum import Enum

class TokenType(Enum):
    """Types of tokens in the arithmetic expression language."""
    INTEGER = "INTEGER"
    FLOAT = "FLOAT"
    PLUS = "PLUS"
    MINUS = "MINUS"
    MULTIPLY = "MULTIPLY"
    DIVIDE = "DIVIDE"
    POWER = "POWER"
    LPAREN = "LPAREN"
    RPAREN = "RPAREN"
    EOF = "EOF"

class Token:
    """Represents a token with type and value."""
    def __init__(self, type_: TokenType, value: Union[str, int, float, None] = None):
        self.type = type_
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.type}, {repr(self.value)})"

class ParseError(Exception):
    """Custom exception for parsing errors."""
    pass

class Lexer:
    """Tokenizer that converts input string into a stream of tokens."""

    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos] if self.text else None

    def error(self, message: str) -> None:
        """Raise a parse error with current position context."""
        raise ParseError(f"Lexer error at position {self.pos}: {message}")

    def advance(self) -> None:
        """Advance to the next character."""
        self.pos += 1
        if self.pos < len(self.text):
            self.current_char = self.text[self.pos]
        else:
            self.current_char = None

    def skip_whitespace(self) -> None:
        """Skip whitespace characters."""
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self) -> Token:
        """Parse a number (integer or float)."""
        result = ""
        decimal_count = 0

        while (self.current_char is not None and 
               (self.current_char.isdigit() or self.current_char == '.')):
            if self.current_char == '.':
                decimal_count += 1
                if decimal_count > 1:
                    self.error("Invalid number with multiple decimal points")
            result += self.current_char
            self.advance()

        if decimal_count == 0:
            return Token(TokenType.INTEGER, int(result))
        else:
            return Token(TokenType.FLOAT, float(result))

    def get_next_token(self) -> Token:
        """Get the next token from the input."""
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue

            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()

            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS)

            if self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS)

            if self.current_char == '*':
                self.advance()
                if self.current_char == '*':
                    self.advance()
                    return Token(TokenType.POWER)
                return Token(TokenType.MULTIPLY)

            if self.current_char == '/':
                self.advance()
                return Token(TokenType.DIVIDE)

            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN)

            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN)

            self.error(f"Unexpected character: '{self.current_char}'")

        return Token(TokenType.EOF)

class Parser:
    """Recursive descent parser for arithmetic expressions."""

    def __init__(self, lexer: Lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self, message: str) -> None:
        """Raise a parse error."""
        raise ParseError(f"Parser error: {message}")

    def eat(self, token_type: TokenType) -> None:
        """Consume a token of expected type."""
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error(f"Expected {token_type}, got {self.current_token.type}")

    def factor(self) -> float:
        """Parse a factor: number or parenthesized expression."""
        token = self.current_token

        if token.type == TokenType.INTEGER:
            self.eat(TokenType.INTEGER)
            return float(token.value)

        elif token.type == TokenType.FLOAT:
            self.eat(TokenType.FLOAT)
            return token.value

        elif token.type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            result = self.expr()
            self.eat(TokenType.RPAREN)
            return result

        elif token.type == TokenType.MINUS:
            # Unary minus
            self.eat(TokenType.MINUS)
            return -self.factor()

        elif token.type == TokenType.PLUS:
            # Unary plus (optional)
            self.eat(TokenType.PLUS)
            return self.factor()

        else:
            self.error(f"Unexpected token in factor: {token}")

    def power(self) -> float:
        """Parse power operator (right-associative)."""
        result = self.factor()

        while self.current_token.type == TokenType.POWER:
            self.eat(TokenType.POWER)
            right = self.power()  # Right-associative: recurse for right operand
            try:
                result = result ** right
            except ZeroDivisionError:
                raise ParseError("Math error: 0 cannot be raised to a negative power")

        return result

    def term(self) -> float:
        """Parse term: multiplication and division."""
        result = self.power()

        while self.current_token.type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            token = self.current_token

            if token.type == TokenType.MULTIPLY:
                self.eat(TokenType.MULTIPLY)
                result *= self.power()

            elif token.type == TokenType.DIVIDE:
                self.eat(TokenType.DIVIDE)
                divisor = self.power()
                if divisor == 0:
                    raise ParseError("Division by zero")
                result /= divisor

        return result

    def expr(self) -> float:
        """Parse expression: addition and subtraction."""
        result = self.term()

        while self.current_token.type in (TokenType.PLUS, TokenType.MINUS):
            token = self.current_token

            if token.type == TokenType.PLUS:
                self.eat(TokenType.PLUS)
                result += self.term()

            elif token.type == TokenType.MINUS:
                self.eat(TokenType.MINUS)
                result -= self.term()

        return result

    def parse(self) -> float:
        """Parse the entire expression."""
        result = self.expr()

        if self.current_token.type != TokenType.EOF:
            self.error(f"Unexpected token at end: {self.current_token}")

        return result

def evaluate(expression: str) -> float:
    """
    Public API to evaluate an arithmetic expression.

    Args:
        expression: String containing arithmetic expression

    Returns:
        float: Result of the evaluation

    Raises:
        ParseError: If expression is malformed or contains errors
    """
    lexer = Lexer(expression)
    parser = Parser(lexer)
    return parser.parse()


