import re
from typing import List, Tuple, Union

class ParseError(Exception):
    """Custom exception for parsing and evaluation errors."""
    pass

class ExpressionEvaluator:
    """
    A recursive-descent parser and evaluator for arithmetic expressions.

    Grammar:
    expression  -> term { ('+' | '-') term }
    term        -> factor { ('*' | '/') factor }
    factor      -> unary { '**' unary }  (Right-associative)
    unary       -> '-' unary | primary
    primary     -> NUMBER | '(' expression ')'
    """

    def __init__(self, text: str):
        self.tokens = self._tokenize(text)
        self.pos = 0

    def _tokenize(self, text: str) -> List[Tuple[str, str]]:
        """Splits the input string into a stream of (type, value) tokens."""
        token_specification = [
            ('NUMBER', r'\d+(\.\d*)?'),  # Integer or decimal
            ('OP',     r'\*\*|[-+*/()]'), # Operators and parentheses
            ('SKIP',   r'\s+'),           # Whitespace
            ('MISMATCH', r'.'),           # Any other character
        ]
        tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)
        tokens = []
        for mo in re.finditer(tok_regex, text):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                tokens.append(('NUMBER', value))
            elif kind == 'OP':
                tokens.append(('OP', value))
            elif kind == 'SKIP':
                continue
            else:
                raise ParseError(f"Unexpected character: {value!r}")
        return tokens

    def _peek(self) -> Union[Tuple[str, str], None]:
        """Returns the current token without consuming it."""
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _consume(self, expected_val: str = None) -> Tuple[str, str]:
        """Consumes and returns the current token. Optionally validates the value."""
        token = self._peek()
        if token is None:
            raise ParseError("Unexpected end of expression")
        if expected_val and token[1] != expected_val:
            raise ParseError(f"Expected '{expected_val}', found '{token[1]}'")
        self.pos += 1
        return token

    def parse_expression(self) -> float:
        """Handles addition and subtraction (lowest precedence)."""
        node = self.parse_term()
        while True:
            token = self._peek()
            if token and token[1] in ('+', '-'):
                op = self._consume()[1]
                right = self.parse_term()
                node = node + right if op == '+' else node - right
            else:
                break
        return node

    def parse_term(self) -> float:
        """Handles multiplication and division."""
        node = self.parse_exponent()
        while True:
            token = self._peek()
            if token and token[1] in ('*', '/'):
                op = self._consume()[1]
                right = self.parse_exponent()
                if op == '/':
                    if right == 0:
                        raise ParseError("Division by zero")
                    node /= right
                else:
                    node *= right
            else:
                break
        return node

    def parse_exponent(self) -> float:
        """Handles exponentiation (Right-associative)."""
        node = self.parse_unary()
        token = self._peek()
        if token and token[1] == '**':
            self._consume() # consume '**'
            # Right-associativity: call parse_exponent recursively
            right = self.parse_exponent()
            node = node ** right
        return node

    def parse_unary(self) -> float:
        """Handles unary minus."""
        token = self._peek()
        if token and token[1] == '-':
            self._consume()
            return -self.parse_unary()
        return self.parse_primary()

    def parse_primary(self) -> float:
        """Handles numbers and parentheses."""
        token = self._peek()
        if token is None:
            raise ParseError("Unexpected end of expression")

        if token[0] == 'NUMBER':
            self._consume()
            return float(token[1])

        if token[1] == '(':
            self._consume('(')
            result = self.parse_expression()
            if self._peek() is None or self._peek()[1] != ')':
                raise ParseError("Unbalanced parentheses: missing ')'")
            self._consume(')')
            return result

        raise ParseError(f"Unexpected token: {token[1]}")

def evaluate(expression: str) -> float:
    """
    Public API to evaluate an arithmetic expression.
    Returns the result as a float.
    """
    evaluator = ExpressionEvaluator(expression)
    result = evaluator.parse_expression()
    if evaluator.pos < len(evaluator.tokens):
        raise ParseError(f"Unexpected token at end of expression: {evaluator.tokens[evaluator.pos][1]}")
    return result

