        ('MISMATCH', r'.'),
    ]
    regex = re.compile('|'.join(f'(?P<{name}>{pattern})' for name, pattern in TOKEN_SPEC))

    def __init__(self, text: str):
        self.tokens = self._tokenize(text)

    def _tokenize(self, text: str) -> List[Token]:
        tokens = []
        for mo in self.regex.finditer(text):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                tokens.append(Token('NUMBER', float(value)))
            elif kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise ParseError(f"Unexpected character: {value}")
            else:
                tokens.append(Token(kind, value))
        return tokens

class Evaluator:
    """
    Grammar:
    expr   -> term (('+'|'-') term)*
    term   -> factor (('*'|'/') factor)*
    factor -> unary ('**' factor)?
    unary  -> '-' unary | primary
    primary -> NUMBER | '(' expr ')'
    """
    def __init__(self, tokens: List[Token]):
        self.tokens = iter(tokens)
        self.current = next(self.tokens, Token('EOF', ''))

    def _consume(self, expected_type: str):
        if self.current.type == expected_type:
            self.current = next(self.tokens, Token('EOF', ''))
        else:
            raise ParseError(f"Expected {expected_type}, got {self.current.type}")

    def parse(self) -> float:
        result = self._expr()
        if self.current.type != 'EOF':
            raise ParseError(f"Unexpected token at end: {self.current.value}")
        return result

    def _expr(self) -> float:
        node = self._term()
        while self.current.type in ('PLUS', 'MINUS'):
            op = self.current.type
            self._consume(op)
            if op == 'PLUS': node += self._term()
            else: node -= self._term()
        return node

    def _term(self) -> float:
        node = self._factor()
        while self.current.type in ('MUL', 'DIV'):
            op = self.current.type
            self._consume(op)
            right = self._factor()
            if op == 'MUL': node *= right
            else:
                if right == 0: raise ParseError("Division by zero")
                node /= right
        return node

    def _factor(self) -> float:
        node = self._unary()
        if self.current.type == 'POW':
            self._consume('POW')
            node = node ** self._factor()
        return node

    def _unary(self) -> float:
        if self.current.type == 'MINUS':
            self._consume('MINUS')
            return -self._unary()
        return self._primary()

    def _primary(self) -> float:
        token = self.current
        if token.type == 'NUMBER':
            self._consume('NUMBER')
            return float(token.value)
        if token.type == 'LPAREN':
            self._consume('LPAREN')
            val = self._expr()
            self._consume('RPAREN')
            return val
        raise ParseError(f"Unexpected token: {token.value}")

def evaluate(expression: str) -> float:
    """Public API to evaluate arithmetic expressions."""
    tokens = Tokenizer(expression).tokens
    return Evaluator(tokens).parse()

# Usage Examples
if __name__ == "__main__":
    # 1. Precedence: 2 + 3 * 4 = 14 (not 20)
    print(f"Precedence: {evaluate('2 + 3 * 4')}") 

    # 2. Parentheses: (2 + 3) * 4 = 20
    print(f"Parentheses: {evaluate('(2 + 3) * 4')}")

    # 3. Unary minus and Power: -2 ** 2 = -4 (unary binds tighter than binary, but power is right-assoc)
    # Note: -2**2 is interpreted as -(2**2) = -4
    print(f"Unary/Power: {evaluate('-2 ** 2')}")

import re
from typing import Union, List

class ParseError(Exception):
    """Custom exception for parsing errors."""
    pass

class Token:
    """Represents a token in the input expression."""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f'Token({self.type}, {self.value})'

class Tokenizer:
    """Tokenizes the input string into a stream of tokens."""
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.tokens: List[Token] = []
        self.tokenize()

    def tokenize(self):
        """Tokenizes the input expression."""
        token_specification = [
            ('NUMBER', r'\d+(\.\d*)?'),   # Integer or decimal number
            ('PLUS', r'\+'),               # Addition
            ('MINUS', r'-'),               # Subtraction
            ('TIMES', r'\*'),              # Multiplication
            ('DIVIDE', r'/'),              # Division
            ('POWER', r'\*\*'),            # Exponentiation
            ('LPAREN', r'\('),             # Left Parenthesis
            ('RPAREN', r'\)'),             # Right Parenthesis
            ('SKIP', r'[ \t]+'),           # Skip over spaces and tabs
            ('MISMATCH', r'.'),            # Any other character
        ]
        tok_regex = '|'.join(f'(?P<{pair[0]}>{pair[1]})' for pair in token_specification)
        for mo in re.finditer(tok_regex, self.expression):
            kind = mo.lastgroup
            value = mo.group(kind)
            if kind == 'NUMBER':
                value = float(value) if '.' in value else int(value)
                self.tokens.append(Token('NUMBER', value))
            elif kind in {'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'POWER', 'LPAREN', 'RPAREN'}:
                self.tokens.append(Token(kind, value))
            elif kind == 'MISMATCH':
                raise ParseError(f'Unexpected character: {value}')
        self.tokens.append(Token('EOF', None))  # End of file token

    def get_next_token(self) -> Token:
        """Returns the next token from the token stream."""
        if self.tokens:
            return self.tokens.pop(0)
        return Token('EOF', None)

class Parser:
    """Parses the token stream and evaluates the expression."""
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer
        self.current_token = self.tokenizer.get_next_token()

    def error(self, message: str):
        """Raises a ParseError with a message."""
        raise ParseError(message)

    def eat(self, token_type: str):
        """Consumes a token of the specified type."""
        if self.current_token.type == token_type:
            self.current_token = self.tokenizer.get_next_token()
        else:
            self.error(f'Expected token {token_type}, got {self.current_token.type}')

    def factor(self) -> float:
        """Parses a factor: NUMBER | LPAREN expr RPAREN | unary MINUS factor."""
        if self.current_token.type == 'NUMBER':
            value = self.current_token.value
            self.eat('NUMBER')
            return value
        elif self.current_token.type == 'LPAREN':
            self.eat('LPAREN')
            result = self.expr()
            self.eat('RPAREN')
            return result
        elif self.current_token.type == 'MINUS':
            self.eat('MINUS')
            return -self.factor()
        self.error('Invalid factor')

    def power(self) -> float:
        """Parses a power: factor ('**' factor)*."""
        result = self.factor()
        while self.current_token.type == 'POWER':
            self.eat('POWER')
            result **= self.factor()
        return result

    def term(self) -> float:
        """Parses a term: power (('*' | '/') power)*."""
        result = self.power()
        while self.current_token.type in {'TIMES', 'DIVIDE'}:
            if self.current_token.type == 'TIMES':
                self.eat('TIMES')
                result *= self.power()
            elif self.current_token.type == 'DIVIDE':
                self.eat('DIVIDE')
                divisor = self.power()
                if divisor == 0:
                    self.error('Division by zero')
                result /= divisor
        return result

    def expr(self) -> float:
        """Parses an expression: term (('+' | '-') term)*."""
        result = self.term()
        while self.current_token.type in {'PLUS', 'MINUS'}:
            if self.current_token.type == 'PLUS':
                self.eat('PLUS')
                result += self.term()
            elif self.current_token.type == 'MINUS':
                self.eat('MINUS')
                result -= self.term()
        return result

    def parse(self) -> float:
        """Parses the entire expression and returns the result."""
        return self.expr()

def evaluate(expression: str) -> float:
    """Public API to evaluate an arithmetic expression."""
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    return parser.parse()

# Usage examples
if __name__ == "__main__":
    print(evaluate("3 + 5"))                     # 8
    print(evaluate("10 + 2 * 6"))                # 22
    print(evaluate("(2 + 3) * (5 - 2)"))         # 15
    print(evaluate("-3 + 4 * 2"))                 # 5
    print(evaluate("2 ** 3 ** 2"))                # 512
    print(evaluate("10 / (5 - 5)"))               # Raises division by zero error

import re
from dataclasses import dataclass
from typing import Optional

# --- 1. Tokenizer (Lexer) ---

class TokenType:
    NUMBER = 'NUMBER'
    PLUS = 'PLUS'
    MINUS = 'MINUS'
    MULTIPLY = 'MULTIPLY'
    DIVIDE = 'DIVIDE'
    LPAREN = 'LPAREN'
    RPAR = 'RPAR'
    EOF = 'EOF'

@dataclass
class Token:
    type: TokenType
    value: Optional[str] = None

class Lexer:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos] if self.text else None

    def advance(self):
        self.pos += 1
        self.current_char = self.text[self.pos] if self.pos < len(self.text) else None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return Token(TokenType.NUMBER, result)

    def get_next_token(self):
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue

            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()

            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS)
            elif self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS)
            elif self.current_char == '*':
                self.advance()
                return Token(TokenType.MULTIPLY)
            elif self.current_char == '/':
                self.advance()
                return Token(TokenType.DIVIDE)
            elif self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN)
            elif self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAR)
            else:
                raise SyntaxError(f"Unexpected character: '{self.current_char}'")

        return Token(TokenType.EOF)

# --- 2. Parser & AST ---

# AST Node Definitions
@dataclass
class NumberNode:
    value: float

@dataclass
class UnaryOpNode:
    op: TokenType
    operand: 'ASTNode'

@dataclass
class BinaryOpNode:
    op: TokenType
    left: 'ASTNode'
    right: 'ASTNode'

class Parser:
    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self, message):
        raise SyntaxError(message)

    def eat(self, token_type):
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error(f"Expected {token_type}, got {self.current_token.type}")

    def factor(self) -> ASTNode:
        """Handles: ( expr ), NUMBER, or unary - +"""
        token = self.current_token

        # Handle Parentheses
        if token.type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            node = self.expr()
            self.eat(TokenType.RPAR)
            return node

        # Handle Numbers
        if token.type == TokenType.NUMBER:
            self.eat(TokenType.NUMBER)
            return NumberNode(float(token.value))

        # Handle Unary Operators (-5, +5)
        if token.type in (TokenType.PLUS, TokenType.MINUS):
            self.eat(token.type)
            node = self.factor() # Recursively parse what follows the sign
            return UnaryOpNode(token.type, node)

        self.error(f"Unexpected token in factor: {token.type}")

    def term(self) -> ASTNode:
        """Handles multiplication and division with proper precedence."""
        node = self.factor()
        while self.current_token.type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            token = self.current_token
            if token.type == TokenType.MULTIPLY:
                self.eat(TokenType.MULTIPLY)
                node = BinaryOpNode(token.type, node, self.factor())
            elif token.type == TokenType.DIVIDE:
                self.eat(TokenType.DIVIDE)
                node = BinaryOpNode(token.type, node, self.factor())
        return node

    def expr(self) -> ASTNode:
        """Handles addition and subtraction. Entry point for recursive descent."""
        node = self.term()
        while self.current_token.type in (TokenType.PLUS, TokenType.MINUS):
            token = self.current_token
            if token.type == TokenType.PLUS:
                self.eat(TokenType.PLUS)
                node = BinaryOpNode(token.type, node, self.term())
            elif token.type == TokenType.MINUS:
                self.eat(TokenType.MINUS)
                node = BinaryOpNode(token.type, node, self.term())
        return node

    def parse(self) -> ASTNode:
        return self.expr()

# --- 3. Evaluator ---

class NodeVisitor:
    def visit_NumberNode(self, node):
        return node.value

    def visit_UnaryOpNode(self, node):
        # UnaryPlus: no-op. UnaryMinus: negation.
        val = self.visit(node.operand)
        if node.op == TokenType.MINUS:
            return -val
        return val

    def visit_BinaryOpNode(self, node):
        left = self.visit(node.left)
        right = self.visit(node.right)

        if node.op == TokenType.PLUS: return left + right
        if node.op == TokenType.MINUS: return left - right
        if node.op == TokenType.MULTIPLY: return left * right
        if node.op == TokenType.DIVIDE:
            if right == 0: raise ZeroDivisionError("Division by zero")
            return left / right

    def visit(self, node):
        method_name = f'visit_{type(node).__name__}'
        visitor = getattr(self, method_name, self.no_visit_method)
        return visitor(node)

    def no_visit_method(self, node):
        raise Exception(f'No visit_{type(node).__name__} method defined')

# --- Driver Code ---

def parse_and_evaluate(expression_str: str) -> float:
    lexer = Lexer(expression_str)
    parser = Parser(lexer)

    try:
        tree = parser.parse()
        # Verify entire input was consumed (optional but good for error checking)
        if parser.current_token.type != TokenType.EOF:
             parser.error("Unexpected tokens at end of input")

        visitor = NodeVisitor()
        return visitor.visit(tree)
    except SyntaxError as e:
        print(f"Syntax Error: {e}")
        return None

if __name__ == "__main__":
    # Basic examples
    tests = [
        "3 + 2 * 2",       # Standard precedence
        "(2 + 3) * 4",     # Parentheses override precedence
        "-5 + 10",         # Unary operator
        "100 / (5 + 15)",  # Nested structure
        "1.5 * 2.5",       # Floating point
    ]

    print("--- Recursive Descent Evaluator ---")
    for ex in tests:
        result = parse_and_evaluate(ex)
        print(f"{ex:<20} = {result}")

import re
from typing import List, Tuple, Union

# --- Grammar Definition ---
# expression  -> term (('+' | '-') term)*
# term        -> factor (('*' | '/') factor)*
# factor      -> unary (('**') unary)*  (Right-associative)
# unary       -> '-' unary | primary
# primary     -> NUMBER | '(' expression ')'

class ParseError(Exception):
    """Custom exception for parsing and evaluation errors."""
    pass

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Tokenizer:
    """Splits the input string into a stream of tokens using regular expressions."""
    TOKEN_SPEC = [
        ('NUMBER', r'\d+(\.\d+)?'),  # Integer or decimal
        ('POW',    r'\*\*'),        # Exponentiation
        ('OP',     r'[+\-*/]'),     # Arithmetic operators
        ('LPAREN', r'\('),          # Left parenthesis
        ('RPAREN', r'\)'),          # Right parenthesis
        ('SKIP',    r'\s+'),        # Whitespace
        ('MISMATCH',r'.'),          # Any other character
    ]

    def __init__(self, text: str):
        self.tokens: List[Token] = []
        self._tokenize(text)

    def _tokenize(self, text: str):
        regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in self.TOKEN_SPEC)
        for mo in re.finditer(regex, text):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                self.tokens.append(Token('NUMBER', value))
            elif kind == 'OP' or kind == 'POW' or kind == 'LPAREN' or kind == 'RPAREN':
                self.tokens.append(Token(kind, value))
            elif kind == 'SKIP':
                continue
            else:
                raise ParseError(f"Unexpected character: {value!r}")
        self.tokens.append(Token('EOF', ''))

class Parser:
    """
    Recursive Descent Parser.
    Evaluates the expression directly during the descent.
    """
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def _current(self) -> Token:
        return self.tokens[self.pos]

    def _eat(self, expected_type: str) -> Token:
        token = self._current()
        if token.type == expected_type:
            self.pos += 1
            return token
        raise ParseError(f"Expected {expected_type}, found {token.type} ('{token.value}')")

    def parse(self) -> float:
        result = self._expression()
        if self._current().type != 'EOF':
            raise ParseError(f"Unexpected token at end of expression: {self._current().value}")
        return float(result)

    def _expression(self) -> float:
        # expression -> term (('+' | '-') term)*
        node = self._term()
        while self._current().type == 'OP' and self._current().value in ('+', '-'):
            op = self._eat('OP').value
            right = self._term()
            node = (node + right) if op == '+' else (node - right)
        return node

    def _term(self) -> float:
        # term -> factor (('*' | '/') factor)*
        node = self._factor()
        while self._current().type == 'OP' and self._current().value in ('*', '/'):
            op = self._eat('OP').value
            right = self._factor()
            if op == '/':
                if right == 0:
                    raise ParseError("Division by zero")
                node /= right
            else:
                node *= right
        return node

    def _factor(self) -> float:
        # factor -> unary (('**') unary)* (Right-associative)
        node = self._unary()
        if self._current().type == 'POW':
            self._eat('POW')
            # Right-associativity: recurse on _factor instead of looping
            right = self._factor() 
            node = node ** right
        return node

    def _unary(self) -> float:
        # unary -> '-' unary | primary
        if self._current().type == 'OP' and self._current().value == '-':
            self._eat('OP')
            return -self._unary()
        return self._primary()

    def _primary(self) -> float:
        # primary -> NUMBER | '(' expression ')'
        token = self._current()
        if token.type == 'NUMBER':
            self._eat('NUMBER')
            return float(token.value)
        elif token.type == 'LPAREN':
            self._eat('LPAREN')
            result = self._expression()
            self._eat('RPAREN') # This will raise ParseError if unbalanced
            return result
        else:
            raise ParseError(f"Unexpected token: {token.value}")

def evaluate(expression: str) -> float:
    """
    Public API to evaluate an arithmetic expression.
    """
    try:
        tokenizer = Tokenizer(expression)
        parser = Parser(tokenizer.tokens)
        return parser.parse()
    except (ParseError, OverflowError) as e:
        raise ParseError(f"Evaluation Error: {e}")

