from dataclasses import dataclass
from typing import List, Union


# ─── Token ──────────────────────────────────────────────────────────────────
@dataclass
class Token:
    type: str
    value: str
    pos: int


# ─── AST Nodes ──────────────────────────────────────────────────────────────
class ASTNode:
    """Base class for all AST nodes."""
    def eval(self) -> float:
        raise NotImplementedError


@dataclass
class NumberNode(ASTNode):
    value: float

    def eval(self) -> float:
        return self.value


@dataclass
class UnaryOpNode(ASTNode):
    op: str         # "-"
    operand: ASTNode

    def eval(self) -> float:
        return -self.operand.eval()


@dataclass
class BinOpNode(ASTNode):
    op: str         # "+", "-", "*", "/", "**"
    left: ASTNode
    right: ASTNode

    def eval(self) -> float:
        left_val = self.left.eval()
        right_val = self.right.eval()
        if self.op == "+":
            return left_val + right_val
        elif self.op == "-":
            return left_val - right_val
        elif self.op == "*":
            return left_val * right_val
        elif self.op == "/":
            if right_val == 0:
                raise ValueError("Division by zero")
            return left_val / right_val
        elif self.op == "**":
            return left_val ** right_val
        else:
            raise ValueError(f"Unknown operator '{self.op}'")


# ─── Tokenizer ──────────────────────────────────────────────────────────────
def tokenize(s: str) -> List[Token]:
    tokens: List[Token] = []
    i = 0
    while i < len(s):
        ch = s[i]

        # whitespace
        if ch.isspace():
            i += 1
            continue

        # number literal
        if ch.isdigit() or ch == '.':
            start = i
            # consume digits and at most one dot
            dot_seen = False
            while i < len(s):
                if s[i].isdigit():
                    i += 1
                elif s[i] == '.':
                    if dot_seen:
                        raise ValueError(f"Multiple decimal points at position {i}")
                    dot_seen = True
                    i += 1
                else:
                    break
            # ensure at least one digit was present
            literal = s[start:i]
            if literal == '.':
                raise ValueError(f"Incomplete number literal at position {start}")
            # Validate that it converts to a float (covers trailing dot, etc.)
            try:
                float(literal)
            except ValueError:
                raise ValueError(f"Invalid number literal '{literal}' at position {start}")
            tokens.append(Token("NUMBER", literal, start))
            continue

        # single‑character operators and parentheses
        if ch in ('+', '-', '*', '/', '(', ')'):
            # ** is two characters – handle it first
            if ch == '*' and i + 1 < len(s) and s[i + 1] == '*':
                tokens.append(Token("**", "**", i))
                i += 2
                continue
            tokens.append(Token(ch, ch, i))
            i += 1
            continue

        # unexpected character
        raise ValueError(f"Unexpected character '{ch}' at position {i}")

    tokens.append(Token("EOF", "", i))
    return tokens


# ─── Recursive‑descent parser ──────────────────────────────────────────────
class Parser:
    def __init__(self, tokens: List[Token]) -> None:
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        return self.tokens[self.pos]

    def consume(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, expected_type: str) -> Token:
        tok = self.peek()
        if tok.type != expected_type:
            raise ValueError(
                f"Expected '{expected_type}', got '{tok.type}' "
                f"(value '{tok.value}') at position {tok.pos}"
            )
        return self.consume()

    def parse(self) -> ASTNode:
        node = self.parse_expression()
        if self.peek().type != "EOF":
            raise ValueError(
                f"Unexpected token '{self.peek().value}' after expression "
                f"at position {self.peek().pos}"
            )
        return node

    # expression = term (('+' | '-') term)*
    def parse_expression(self) -> ASTNode:
        left = self.parse_term()
        while self.peek().type in ('+', '-'):
            op = self.consume().type
            right = self.parse_term()
            left = BinOpNode(op, left, right)
        return left

    # term = unary (('*' | '/') unary)*
    def parse_term(self) -> ASTNode:
        left = self.parse_unary()
        while self.peek().type in ('*', '/'):
            op = self.consume().type
            right = self.parse_unary()
            left = BinOpNode(op, left, right)
        return left

    # unary = '-' unary | power
    def parse_unary(self) -> ASTNode:
        if self.peek().type == '-':
            self.consume()  # consume '-'
            operand = self.parse_unary()
            return UnaryOpNode('-', operand)
        return self.parse_power()

    # power = atom ('**' unary)?
    # right‑associative: the right operand is parsed as a unary again
    def parse_power(self) -> ASTNode:
        left = self.parse_atom()
        if self.peek().type == "**":
            self.consume()
            right = self.parse_unary()
            left = BinOpNode("**", left, right)
        return left

    # atom = NUMBER | '(' expression ')'
    def parse_atom(self) -> ASTNode:
        tok = self.peek()
        if tok.type == "NUMBER":
            self.consume()
            return NumberNode(float(tok.value))
        elif tok.type == '(':
            self.consume()
            node = self.parse_expression()
            self.expect(')')
            return node
        else:
            raise ValueError(
                f"Unexpected token '{tok.value}' at position {tok.pos}, "
                f"expected number or '('"
            )


# ─── Public API ─────────────────────────────────────────────────────────────
def evaluate(expression: str) -> float:
    """Evaluate an arithmetic expression and return the result as a float.

    Supports:
        - integers and floats
        - binary operators +, -, *, /, ** (right‑associative)
        - unary minus
        - parentheses
        - correct precedence: ** > unary minus > * / > + -

    Raises ValueError on malformed input (e.g., unbalanced parentheses,
    unexpected characters, division by zero).

    Examples
    --------
    >>> evaluate("3 + 4 * 2")
    11.0

    >>> evaluate("(2 + 3) * 4")
    20.0

    >>> evaluate("2 ** 3 ** 2")
    512.0

    >>> evaluate("-2 ** 2")
    -4.0

    >>> evaluate("--5")
    5.0

    >>> evaluate("1 / 0")
    Traceback (most recent call last):
        ...
    ValueError: Division by zero
    """
    tokens = tokenize(expression)
    parser = Parser(tokens)
    ast = parser.parse()
    return ast.eval()


# ─── Usage examples ─────────────────────────────────────────────────────────
if __name__ == "__main__":
    # 1. Precedence: multiplication before addition
    print(evaluate("3 + 4 * 2"))          # 11.0

    # 2. Parentheses override precedence
    print(evaluate("(2 + 3) * 4"))        # 20.0

    # 3. Unary minus and right‑associative exponentiation
    print(evaluate("2 ** 3 ** 2"))        # 512.0 (2**(3**2))
    print(evaluate("-2 ** 2"))            # -4.0  (-(2**2))
    print(evaluate("1 - -2"))             # 3.0

    # 4. Division by zero raises a descriptive error
    try:
        evaluate("1 / 0")
    except ValueError as e:
        print(f"Error: {e}")

