from enum import Enum, auto
from typing import Union, List
import re


# Token types
class TokenType(Enum):
    NUMBER = auto()
    PLUS = auto()
    MINUS = auto()
    MULTIPLY = auto()
    DIVIDE = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()


# Token class
class Token:
    def __init__(self, type: TokenType, value: any):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type.name}, {self.value})"


# Lexer (Tokenizer)
class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.current_char = self.text[0] if self.text else None

    def advance(self):
        """Move to next character"""
        self.pos += 1
        self.current_char = self.text[self.pos] if self.pos < len(self.text) else None

    def skip_whitespace(self):
        """Skip whitespace characters"""
        while self.current_char and self.current_char.isspace():
            self.advance()

    def get_number(self) -> Token:
        """Read a number (integer or float)"""
        result = ''
        has_dot = False

        while self.current_char and (self.current_char.isdigit() or self.current_char == '.'):
            if self.current_char == '.':
                if has_dot:
                    break
                has_dot = True
            result += self.current_char
            self.advance()

        return Token(TokenType.NUMBER, float(result) if '.' in result else int(result))

    def get_next_token(self) -> Token:
        """Lexical analyzer - converts text into tokens"""
        while self.current_char:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue

            if self.current_char.isdigit():
                return self.get_number()

            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS, '+')

            if self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS, '-')

            if self.current_char == '*':
                self.advance()
                return Token(TokenType.MULTIPLY, '*')

            if self.current_char == '/':
                self.advance()
                return Token(TokenType.DIVIDE, '/')

            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN, '(')

            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN, ')')

            raise SyntaxError(f"Invalid character: {self.current_char}")

        return Token(TokenType.EOF, None)


# AST Node classes
class ASTNode:
    """Base class for AST nodes"""
    pass


class NumberNode(ASTNode):
    def __init__(self, token: Token):
        self.token = token
        self.value = token.value


class BinaryOpNode(ASTNode):
    def __init__(self, left: ASTNode, op: Token, right: ASTNode):
        self.left = left
        self.op = op
        self.right = right


class UnaryOpNode(ASTNode):
    def __init__(self, op: Token, operand: ASTNode):
        self.op = op
        self.operand = operand


# Recursive Descent Parser
class Parser:
    def __init__(self, lexer: Lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self, message="Invalid syntax"):
        raise SyntaxError(message)

    def eat(self, token_type: TokenType):
        """Consume current token if it matches expected type"""
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error(f"Expected {token_type.name}, got {self.current_token.type.name}")

    def parse(self) -> ASTNode:
        """Parse the entire expression"""
        result = self.expr()

        if self.current_token.type != TokenType.EOF:
            self.error("Unexpected tokens after expression")

        return result

    def expr(self) -> ASTNode:
        """
        expression = term (('+' | '-') term)*
        """
        result = self.term()

        while self.current_token.type in (TokenType.PLUS, TokenType.MINUS):
            token = self.current_token
            if token.type == TokenType.PLUS:
                self.eat(TokenType.PLUS)
                result = BinaryOpNode(result, token, self.term())
            elif token.type == TokenType.MINUS:
                self.eat(TokenType.MINUS)
                result = BinaryOpNode(result, token, self.term())

        return result

    def term(self) -> ASTNode:
        """
        term = factor (('*' | '/') factor)*
        """
        result = self.factor()

        while self.current_token.type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            token = self.current_token
            if token.type == TokenType.MULTIPLY:
                self.eat(TokenType.MULTIPLY)
                result = BinaryOpNode(result, token, self.factor())
            elif token.type == TokenType.DIVIDE:
                self.eat(TokenType.DIVIDE)
                result = BinaryOpNode(result, token, self.factor())

        return result

    def factor(self) -> ASTNode:
        """
        factor = NUMBER | '(' expression ')'
        Handles unary minus as well.
        """
        token = self.current_token

        # Unary minus
        if token.type == TokenType.MINUS:
            self.eat(TokenType.MINUS)
            operand = self.factor()
            return UnaryOpNode(token, operand)

        # Number
        if token.type == TokenType.NUMBER:
            self.eat(TokenType.NUMBER)
            return NumberNode(token)

        # Parenthesized expression
        if token.type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            result = self.expr()
            self.eat(TokenType.RPAREN)
            return result

        self.error(f"Unexpected token: {token.type}")


# Evaluator
class Evaluator:
    def visit(self, node: ASTNode):
        """Visit different node types"""
        method_name = f'visit_{type(node).__name__}'
        visitor = getattr(self, method_name, self.generic_visit)
        return visitor(node)

    def generic_visit(self, node: ASTNode):
        raise Exception(f"No visit_{type(node).__name__} method")

    def visit_NumberNode(self, node: NumberNode):
        return node.value

    def visit_BinaryOpNode(self, node: BinaryOpNode):
        left = self.visit(node.left)
        right = self.visit(node.right)

        if node.op.type == TokenType.PLUS:
            return left + right
        elif node.op.type == TokenType.MINUS:
            return left - right
        elif node.op.type == TokenType.MULTIPLY:
            return left * right
        elif node.op.type == TokenType.DIVIDE:
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            return left / right

    def visit_UnaryOpNode(self, node: UnaryOpNode):
        operand = self.visit(node.operand)

        if node.op.type == TokenType.MINUS:
            return -operand


# Main Parser/Evaluator class
class ArithmeticParser:
    def __init__(self):
        self.lexer = None
        self.parser = None
        self.ast = None
        self.evaluator = Evaluator()

    def parse(self, text: str):
        """Parse and evaluate an expression"""
        self.lexer = Lexer(text)
        self.parser = Parser(self.lexer)
        self.ast = self.parser.parse()
        return self.evaluator.visit(self.ast)

    def get_ast(self, text: str):
        """Get the AST without evaluating"""
        self.lexer = Lexer(text)
        self.parser = Parser(self.lexer)
        return self.parser.parse()

    def evaluate_ast(self, ast: ASTNode):
        """Evaluate an already-built AST"""
        return self.evaluator.visit(ast)


# Helper functions for convenience
def evaluate(expression: str) -> float:
    """Evaluate an arithmetic expression"""
    parser = ArithmeticParser()
    return parser.parse(expression)


def parse_to_ast(expression: str) -> ASTNode:
    """Parse an expression to AST"""
    parser = ArithmeticParser()
    return parser.get_ast(expression)


# Test the implementation
if __name__ == "__main__":
    # Test cases
    test_expressions = [
        "3 + 4",
        "3 - 4",
        "3 * 4",
        "3 / 4",
        "3 + 4 * 2",
        "(3 + 4) * 2",
        "3 * (4 + 2)",
        "-5",
        "-5 + 3",
        "-(3 + 4)",
        "10 / 2 / 5",
        "2 * 3 + 4 * 5",
        "(1 + 2) * (3 + 4)",
    ]

    parser = ArithmeticParser()

    print("=" * 60)
    print("Expression Evaluation Results")
    print("=" * 60)

    for expr in test_expressions:
        try:
            result = parser.parse(expr)
            print(f"{expr:25} = {result}")
        except Exception as e:
            print(f"{expr:25} -> Error: {e}")

    print("\n" + "=" * 60)
    print("AST Example (for: (3 + 4) * 2)")
    print("=" * 60)

    ast = parse_to_ast("(3 + 4) * 2")

    def print_ast(node, indent=0):
        if isinstance(node, NumberNode):
            print(" " * indent + f"Number: {node.value}")
        elif isinstance(node, BinaryOpNode):
            print(" " * indent + f"BinaryOp: {node.op.value}")
            print_ast(node.left, indent + 4)
