import re

class Lexer:
    """Breaks the input string into a list of tokens."""
    def __init__(self, text):
        # Regex for numbers, operators, and parentheses
        self.tokens = re.findall(r'\d+\.?\d*|[+\-*/() ]', text)
        self.pos = 0

    def peek(self):
        """Look at the current token without consuming it."""
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self):
        """Return current token and move to the next."""
        token = self.peek()
        self.pos += 1
        return token

class Parser:
    """Recursive Descent Parser for arithmetic expressions."""
    def __init__(self, lexer):
        self.lexer = lexer

    def parse(self):
        """Start point: Expression"""
        return self.expression()

    def expression(self):
        """Handle Addition and Subtraction (Lowest Precedence)"""
        node = self.term()
        while self.lexer.peek() in ('+', '-'):
            op = self.lexer.consume()
            right = self.term()
            if op == '+': node += right
            else: node -= right
        return node

    def term(self):
        """Handle Multiplication and Division (Medium Precedence)"""
        node = self.factor()
        while self.lexer.peek() in ('*', '/'):
            op = self.lexer.consume()
            right = self.factor()
            if op == '*': 
                node *= right
            else: 
                node /= right
        return node

    def factor(self):
        """Handle Numbers and Parentheses (Highest Precedence)"""
        token = self.lexer.consume()

        if token == '(':
            # Recurse back to the top of the grammar
            result = self.expression()
            self.lexer.consume()  # Consume the closing ')'
            return result

        # Convert token to float if it's a number
        try:
            return float(token)
        except (ValueError, TypeError):
            raise SyntaxError(f"Unexpected token: {token}")

