class ProcessingStats:
    def __init__(self) -> None:
        self.hits = 0
        self.misses = 0
        self.errors = 0

    def to_dict(self) -> Dict[str, int]:
        return {"hits": self.hits, "misses": self.misses, "errors": self.errors}

class DataProcessor:
    def __init__(
        self,
        strict: bool = False,
        verbose: bool = False,
        use_cache: bool = False,
        normalize: bool = False,
        dedupe: bool = False,
        validate: bool = False
    ):
