        if self.normalize and isinstance(item, dict):
            return {k: (v.strip().lower() if isinstance(v, str) else v) 
                    for k, v in item.items()}
        return item

    def _is_valid(self, item: Any) -> bool:
        if self.validate and not isinstance(item, dict):
            self._stats.errors += 1
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
