import re
from typing import Union, List

class ParseError(Exception):
    """Custom exception for parsing errors."""
    pass

class Token:
    """Represents a token in the input expression."""
    def __init__(self, type: str, value: Union[str, float]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Tokenizer:
    """Tokenizes the input string into a stream of tokens."""
    def __init__(self, expression: str):
        self.expression = expression
        self.position = 0
        self.tokens = self.tokenize()

    def tokenize(self) -> List[Token]:
        """Tokenizes the input expression."""
        token_specification = [
            ('NUMBER', r'\d+(\.\d*)?'),  # Integer or decimal number
            ('PLUS', r'\+'),              # Addition
            ('MINUS', r'-'),              # Subtraction
            ('TIMES', r'\*'),             # Multiplication
            ('DIVIDE', r'/'),             # Division
            ('POWER', r'\*\*'),           # Exponentiation
            ('LPAREN', r'\('),            # Left Parenthesis
            ('RPAREN', r'\)'),            # Right Parenthesis
            ('SKIP', r'[ \t]+'),          # Skip over spaces and tabs
            ('MISMATCH', r'.'),           # Any other character
        ]
        tok_regex = '|'.join(f'(?P<{pair[0]}>{pair[1]})' for pair in token_specification)
        line_num = 1
        line_start = 0
        tokens = []

        for mo in re.finditer(tok_regex, self.expression):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                tokens.append(Token('NUMBER', float(value)))
            elif kind in {'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'POWER', 'LPAREN', 'RPAREN'}:
                tokens.append(Token(kind, value))
            elif kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise ParseError(f"Unexpected character '{value}' at position {mo.start()}")

        return tokens

    def next_token(self) -> Token:
        """Returns the next token from the token stream."""
        if self.position < len(self.tokens):
            token = self.tokens[self.position]
            self.position += 1
            return token
        return Token('EOF', None)

class Parser:
    """Parses tokens and builds an AST or evaluates directly."""
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer
        self.current_token = self.tokenizer.next_token()

    def parse(self) -> float:
        """Parses the expression and returns the evaluated result."""
        result = self.expr()
        if self.current_token.type != 'EOF':
            raise ParseError("Unexpected token at the end of expression")
        return result

    def expr(self) -> float:
        """Handles addition and subtraction."""
        result = self.term()
        while self.current_token.type in ('PLUS', 'MINUS'):
            token = self.current_token
            self.current_token = self.tokenizer.next_token()
            if token.type == 'PLUS':
                result += self.term()
            elif token.type == 'MINUS':
                result -= self.term()
        return result

    def term(self) -> float:
        """Handles multiplication and division."""
        result = self.factor()
        while self.current_token.type in ('TIMES', 'DIVIDE'):
            token = self.current_token
            self.current_token = self.tokenizer.next_token()
            if token.type == 'TIMES':
                result *= self.factor()
            elif token.type == 'DIVIDE':
                divisor = self.factor()
                if divisor == 0:
                    raise ParseError("Division by zero")
                result /= divisor
        return result

    def factor(self) -> float:
        """Handles exponentiation and unary minus."""
        if self.current_token.type == 'MINUS':
            self.current_token = self.tokenizer.next_token()
            return -self.factor()
        elif self.current_token.type == 'PLUS':
            self.current_token = self.tokenizer.next_token()
            return self.factor()

        if self.current_token.type == 'NUMBER':
            value = self.current_token.value
            self.current_token = self.tokenizer.next_token()
            return value

        if self.current_token.type == 'LPAREN':
            self.current_token = self.tokenizer.next_token()
            result = self.expr()
            if self.current_token.type != 'RPAREN':
                raise ParseError("Unbalanced parentheses")
            self.current_token = self.tokenizer.next_token()
            return result

        raise ParseError("Unexpected token")

def evaluate(expression: str) -> float:
    """Public API to evaluate an arithmetic expression."""
    tokenizer = Tokenizer(expression)
    parser = Parser(tokenizer)
    return parser.parse()

# Usage examples
if __name__ == "__main__":
    print(evaluate("3 + 5"))                  # Output: 8.0
    print(evaluate("10 + 2 * 6"))             # Output: 22.0
    print(evaluate("(10 + 2) * 6"))           # Output: 72.0
    print(evaluate("-3 + 4 * 2"))             # Output: 5.0
    print(evaluate("2 ** 3 ** 2"))             # Output: 512.0
    print(evaluate("3 + (2 - 5) * 4"))        # Output: -5.0

from typing import List, Union

# --- Error Handling ---

class EvaluationError(Exception):
    """Custom exception for parsing and evaluation errors."""
    pass

# --- Tokenizer (Lexer) ---

class Token:
    def __init__(self, type: str, value: Union[float, str]):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

def tokenize(expression: str) -> List[Token]:
    """
    Converts a string of arithmetic expression into a list of tokens.
    """
    tokens = []
    pos = 0

    while pos < len(expression):
        char = expression[pos]

        # Skip whitespace
        if char.isspace():
            pos += 1
            continue

        # Numbers (Integers and Floats)
        if char.isdigit() or char == '.':
            start = pos
            has_dot = False
            # Read integer part
            while pos < len(expression) and expression[pos].isdigit():
                pos += 1
            # Read decimal part if exists
            if pos < len(expression) and expression[pos] == '.':
                has_dot = True
                pos += 1
                while pos < len(expression) and expression[pos].isdigit():
                    pos += 1

            num_str = expression[start:pos]
            value = float(num_str) if has_dot else int(num_str)
            tokens.append(Token("NUMBER", value))
            continue

        # Operators and Parentheses
        if char == '+':
            tokens.append(Token("PLUS", char))
            pos += 1
        elif char == '-':
            tokens.append(Token("MINUS", char))
            pos += 1
        elif char == '*':
            # Check for ** (exponent)
            if pos + 1 < len(expression) and expression[pos + 1] == '*':
                tokens.append(Token("POW", "**"))
                pos += 2
            else:
                tokens.append(Token("MUL", char))
                pos += 1
        elif char == '/':
            tokens.append(Token("DIV", char))
            pos += 1
        elif char == '(':
            tokens.append(Token("LPAREN", char))
            pos += 1
        elif char == ')':
            tokens.append(Token("RPAREN", char))
            pos += 1
        else:
            raise EvaluationError(f"Unexpected character: '{char}'")

    tokens.append(Token("EOF", None))
    return tokens

# --- Parser & Evaluator ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self):
        return self.tokens[self.pos]

    def eat(self, token_type: str):
        if self.current_token().type == token_type:
            self.pos += 1
        else:
            raise EvaluationError(f"Expected {token_type}, got {self.current_token().type}")

    def parse(self):
        result = self.expr()
        if self.current_token().type != "EOF":
            raise EvaluationError("Unexpected token at end of expression")
        return result

    # Grammar Rules (Lowest Precedence to Highest)

    # 1. Additive (+, -)
    def expr(self):
        result = self.term()

        while self.current_token().type in ("PLUS", "MINUS"):
            op = self.current_token().type
            self.eat(op)
            right = self.term()
            if op == "PLUS":
                result = result + right
            else:
                result = result - right

        return result

    # 2. Multiplicative (*, /)
    def term(self):
        result = self.power()

        while self.current_token().type in ("MUL", "DIV"):
            op = self.current_token().type
            self.eat(op)
            right = self.power()

            if op == "MUL":
                result = result * right
            else:
                if right == 0:
                    raise EvaluationError("Division by zero")
                result = result / right

        return result

    # 3. Exponentiation (**) - Right Associative
    def power(self):
        result = self.unary()

        if self.current_token().type == "POW":
            self.eat("POW")
            # Recursively call power again to handle right-associativity
            right = self.power() 
            result = result ** right

        return result

    # 4. Unary Minus/Plus
    def unary(self):
        if self.current_token().type == "MINUS":
            self.eat("MINUS")
            # Recursively apply unary to the next part
            return -self.unary()
        elif self.current_token().type == "PLUS":
            self.eat("PLUS")
            return self.unary()
        else:
            return self.primary()

    # 5. Primary (Numbers and Grouping)
    def primary(self):
        token = self.current_token()

        if token.type == "NUMBER":
            self.eat("NUMBER")
            return token.value
        elif token.type == "LPAREN":
            self.eat("LPAREN")
            result = self.expr()
            if self.current_token().type != "RPAREN":
                raise EvaluationError("Missing closing parenthesis ')'")
            self.eat("RPAREN")
            return result
        else:
            raise EvaluationError(f"Unexpected token: {token}")

# --- Public API ---

def evaluate(expression: str) -> float:
    """
    Main entry point. Tokenizes, parses, and evaluates the expression.
    """
    try:
        tokens = tokenize(expression)
        parser = Parser(tokens)
        result = parser.parse()
        return float(result)
    except IndexError:
        raise EvaluationError("Malformed input: Expression ended unexpectedly.")
    except EvaluationError:
        # Re-raise our custom errors to keep them descriptive
        raise
    except Exception as e:
        raise EvaluationError(f"An internal error occurred: {e}")

# --- Usage Examples ---

if __name__ == "__main__":
    # 1. Precedence: ** > * > +
    # 2 + 3 * 4 = 2 + 12 = 14
    print(f"2 + 3 * 4 = {evaluate('2 + 3 * 4')}") 

    # 2. Parentheses: Overriding precedence
    # (2 + 3) * 4 = 5 * 4 = 20
    print(f"(2 + 3) * 4 = {evaluate('(2 + 3) * 4')}")

    # 3. Unary Minus and Precedence
    # -2 ** 2: According to requested precedence, ** is higher than unary.
    # So it is -(2 ** 2) = -4.
    print(f"-2 ** 2 = {evaluate('-2 ** 2')}") 

    # 4. Right Associative Exponentiation
    # 2 ** 3 ** 2 should be 2 ** (3 ** 2) = 2 ** 9 = 512
    print(f"2 ** 3 ** 2 = {evaluate('2 ** 3 ** 2')}")

    # 5. Float arithmetic
    print(f"10.5 + 2.5 = {evaluate('10.5 + 2.5')}")

    # Error Handling Examples:
    try:
        evaluate("10 / 0")
    except EvaluationError as e:
        print(f"Caught Error: {e}")

    try:
        evaluate("10 + (5 * 2") # Unbalanced parens
    except EvaluationError as e:
        print(f"Caught Error: {e}")

    try:
        evaluate("10 @ 2") # Unexpected char
    except EvaluationError as e:
        print(f"Caught Error: {e}")

