        self.validation_strategy = validation_strategy if validation_strategy is not None else NoValidation()
        self.deduplication_strategy = deduplication_strategy if deduplication_strategy is not None else NoDeduplication()
        self.normalization_strategy = normalization_strategy if normalization_strategy is not None else NoNormalization()

    def process(self, data: List[Any]) -> List[Any]:
        # Use id(data) as a key for caching the entire input list
        data_id = id(data)
        cached_result = self.cache_strategy.get(data_id)
        if cached_result is not None:
            return cached_result

        result: List[Any] = []
        seen: Set[Any] = set() # Used by deduplication strategy

        for item in data:
            if not self.validation_strategy.validate(item, self.strict, self.verbose):
                continue

            if not self.deduplication_strategy.should_add(item, seen):
                continue

            processed_item = self.normalization_strategy.normalize(item)
            result.append(processed_item)

        self.cache_strategy.set(data_id, result)
        return result

    def get_stats(self) -> Dict[str, int]:
        stats: Dict[str, int] = {}
        if isinstance(self.cache_strategy, InMemoryCache):
            stats.update(self.cache_strategy.get_stats())
        if isinstance(self.validation_strategy, DictValidation):
            stats.update(self.validation_strategy.get_stats())
        return stats

    def reset(self) -> None:
        self.cache_strategy.clear()
        # Validation strategy might have internal state (error counts)
        if isinstance(self.validation_strategy, DictValidation):
            self.validation_strategy._errors = 0 # Direct access for reset, or add a reset method to protocol
        # Deduplication and Normalization strategies are typically stateless per process call,
        # so no explicit reset is needed for them.

# --- Helper function for easy instantiation (optional, but convenient) ---
def create_data_processor(
    strict: bool = False,
    verbose: bool = False,
    cache: bool = False,
    normalize: bool = False,
    dedupe: bool = False,
    validate: bool = False
) -> DataProcessor:
    cache_strategy = InMemoryCache() if cache else NoCache()
    validation_strategy = DictValidation() if validate else NoValidation()
    deduplication_strategy = SimpleDeduplication() if dedupe else NoDeduplication()
    normalization_strategy = DictStringNormalization() if normalize else NoNormalization()

    return DataProcessor(
        strict=strict,
        verbose=verbose,
        cache_strategy=cache_strategy,
        validation_strategy=validation_strategy,
        deduplication_strategy=deduplication_strategy,
        normalization_strategy=normalization_strategy
    )

