import re
from typing import List, Tuple, Union

class ExpressionError(Exception):
    """Custom exception for parsing and evaluation errors."""
    pass

class Token:
    """Represents a single lexical unit in the expression."""
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self):
        return f"Token({self.type}, {self.value})"

class Tokenizer:
    """Splits a string into a stream of tokens using regular expressions."""
    TOKEN_SPEC = [
        ('NUMBER',   r'\d+(\.\d*)?'),  # Integer or decimal
        ('POW',     r'\*\*'),         # Exponentiation
        ('OP',      r'[+\-*/]'),      # Basic operators
        ('LPAREN',  r'\('),           # Left parenthesis
        ('RPAREN',  r'\)'),           # Right parenthesis
        ('WS',      r'\s+'),          # Whitespace
        ('MISMATCH',r'.'),            # Any other character
    ]

    def __init__(self, text: str):
        self.text = text
        self.tokens: List[Token] = self._tokenize()
        self.pos = 0

    def _tokenize(self) -> List[Token]:
        regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in self.TOKEN_SPEC)
        tokens = []
        for mo in re.finditer(regex, self.text):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                tokens.append(Token('NUMBER', value))
            elif kind == 'OP' or kind == 'POW' or kind == 'LPAREN' or kind == 'RPAREN':
                tokens.append(Token(kind, value))
            elif kind == 'WS':
                continue
            elif kind == 'MISMATCH':
                raise ExpressionError(f"Unexpected character: {value!r}")
        return tokens

    def peek(self) -> Union[Token, None]:
        """Look at the current token without consuming it."""
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self) -> Union[Token, None]:
        """Return the current token and advance the position."""
        token = self.peek()
        self.pos += 1
        return token

class Parser:
    """
    Recursive Descent Parser.
    Grammar:
    expression  -> term (( '+' | '-' ) term)*
    term        -> factor (( '*' | '/' ) factor)*
    factor      -> unary_expr ( '**' unary_expr )*  [Right associative]
    unary_expr   -> '-' unary_expr | primary
    primary     -> NUMBER | '(' expression ')'
    """
    def __init__(self, tokenizer: Tokenizer):
        self.tokenizer = tokenizer

    def parse(self) -> float:
        result = self._expression()
        if self.tokenizer.peek() is not None:
            raise ExpressionError(f"Unexpected token at end of expression: {self.tokenizer.peek()}")
        return float(result)

    def _expression(self) -> float:
        node = self._term()
        while (token := self.tokenizer.peek()) and token.type == 'OP' and token.value in ('+', '-'):
            op = self.tokenizer.consume().value
            right = self._term()
            node = (node + right) if op == '+' else (node - right)
        return node

    def _term(self) -> float:
        node = self._factor()
        while (token := self.tokenizer.peek()) and token.type == 'OP' and token.value in ('*', '/'):
            op = self.tokenizer.consume().value
            right = self._factor()
            if op == '/':
                if right == 0:
                    raise ExpressionError("Division by zero")
                node /= right
            else:
                node *= right
        return node

    def _factor(self) -> float:
        # Power (**) is right-associative: we call _factor recursively on the right side
        node = self._unary()
        token = self.tokenizer.peek()
        if token and token.type == 'POW':
            self.tokenizer.consume() # consume **
            right = self._factor()    # Right recursion for right-associativity
            node = node ** right
        return node

    def _unary(self) -> float:
        token = self.tokenizer.peek()
        if token and token.type == 'OP' and token.value == '-':
            self.tokenizer.consume()
            return -self._unary()
        return self._primary()

    def _primary(self) -> float:
        token = self.tokenizer.consume()
        if not token:
            raise ExpressionError("Unexpected end of expression")

        if token.type == 'NUMBER':
            return float(token.value)

        if token.type == 'LPAREN':
            result = self._expression()
            closing = self.tokenizer.consume()
            if not closing or closing.type != 'RPAREN':
                raise ExpressionError("Unbalanced parentheses: Missing ')'")
            return result

        raise ExpressionError(f"Unexpected token: {token.value}")

def evaluate(expression: str) -> float:
    """
    Public API to evaluate an arithmetic expression.
    """
    try:
        tokenizer = Tokenizer(expression)
        parser = Parser(tokenizer)
        return parser.parse()
    except (ExpressionError, OverflowError) as e:
        raise ExpressionError(f"Evaluation Error: {e}")

