import threading
from typing import Any, Dict, List, Set, Optional, Protocol, Tuple

# --- Strategy Interfaces ---

class CacheStrategy(Protocol):
    """Interface for caching behavior."""
    def get(self, key: int) -> Optional[List[Any]]:
        ...

    def set(self, key: int, value: List[Any]) -> None:
        ...

    def record_hit(self) -> None:
        ...

    def record_miss(self) -> None:
        ...

    def reset(self) -> None:
        ...

class ValidationStrategy(Protocol):
    """Interface for validation behavior."""
    def validate(self, item: Any, strict: bool, verbose: bool) -> bool:
        ...

    def record_error(self) -> None:
        ...

    def reset(self) -> None:
        ...

class DeduplicationStrategy(Protocol):
    """Interface for deduplication behavior."""
    def process_item(self, item: Any, seen: Set[Any]) -> Optional[Any]:
        ...

class NormalizationStrategy(Protocol):
    """Interface for normalization behavior."""
    def normalize(self, item: Any) -> Any:
        ...

# --- Concrete Strategy Implementations ---

class NoCache(CacheStrategy):
    """A cache strategy that does no caching."""
    def get(self, key: int) -> Optional[List[Any]]:
        return None

    def set(self, key: int, value: List[Any]) -> None:
        pass

    def record_hit(self) -> None:
        pass

    def record_miss(self) -> None:
        pass

    def reset(self) -> None:
        pass

class InMemoryCache(CacheStrategy):
    """An in-memory cache strategy with statistics."""
    def __init__(self):
        self._cache: Dict[int, List[Any]] = {}
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0}
        self._lock = threading.Lock() # For thread-safe access to cache and stats

    def get(self, key: int) -> Optional[List[Any]]:
        with self._lock:
            if key in self._cache:
                self._stats["hits"] += 1
                return self._cache[key]
            self._stats["misses"] += 1
            return None

    def set(self, key: int, value: List[Any]) -> None:
        with self._lock:
            self._cache[key] = value

    def record_hit(self) -> None:
        # Handled within get()
        pass

    def record_miss(self) -> None:
        # Handled within get()
        pass

    def get_stats(self) -> Dict[str, int]:
        with self._lock:
            return self._stats.copy()

    def reset(self) -> None:
        with self._lock:
            self._cache = {}
            self._stats = {"hits": 0, "misses": 0}

class NoValidation(ValidationStrategy):
    """A validation strategy that performs no validation."""
    def validate(self, item: Any, strict: bool, verbose: bool) -> bool:
        return True

    def record_error(self) -> None:
        pass

    def reset(self) -> None:
        pass

class DictValidation(ValidationStrategy):
    """A validation strategy that checks if items are dictionaries."""
    def __init__(self):
        self._errors: int = 0
        self._lock = threading.Lock()

    def validate(self, item: Any, strict: bool, verbose: bool) -> bool:
        if not isinstance(item, dict):
            self.record_error()
            if strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if verbose:
                print(f"Skipping invalid item: {item}")
            return False
        return True

    def record_error(self) -> None:
        with self._lock:
            self._errors += 1

    def get_errors(self) -> int:
        with self._lock:
            return self._errors

    def reset(self) -> None:
        with self._lock:
            self._errors = 0

class NoDeduplication(DeduplicationStrategy):
    """A deduplication strategy that performs no deduplication."""
    def process_item(self, item: Any, seen: Set[Any]) -> Optional[Any]:
        return item

class SimpleDeduplication(DeduplicationStrategy):
    """A deduplication strategy that uses a set to track seen items."""
    def process_item(self, item: Any, seen: Set[Any]) -> Optional[Any]:
        # For dicts, create a sortable representation for consistent hashing
        key = str(sorted(item.items()) if isinstance(item, dict) else item)
        if key in seen:
            return None # Indicate item should be skipped
        seen.add(key)
        return item

class NoNormalization(NormalizationStrategy):
    """A normalization strategy that performs no normalization."""
    def normalize(self, item: Any) -> Any:
        return item

class DictStringNormalization(NormalizationStrategy):
    """A normalization strategy for dictionary values (strip/lower strings)."""
    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {k: (v.strip().lower() if isinstance(v, str) else v)
                    for k, v in item.items()}
        return item

# --- Refactored DataProcessor ---

class DataProcessor:
    """
    A data processing class that uses strategy patterns for configurable behaviors.
    It is fully self-contained and thread-safe.
    """
    def __init__(self,
                 strict: bool = False,
                 verbose: bool = False,
                 cache_strategy: Optional[CacheStrategy] = None,
                 validation_strategy: Optional[ValidationStrategy] = None,
                 deduplication_strategy: Optional[DeduplicationStrategy] = None,
                 normalization_strategy: Optional[NormalizationStrategy] = None):
        """
        Initializes the DataProcessor with specific strategies.

        Args:
            strict: If True, raises ValueError on validation errors.
            verbose: If True, prints messages for skipped items.
            cache_strategy: An instance of CacheStrategy. Defaults to NoCache.
            validation_strategy: An instance of ValidationStrategy. Defaults to NoValidation.
            deduplication_strategy: An instance of DeduplicationStrategy. Defaults to NoDeduplication.
            normalization_strategy: An instance of NormalizationStrategy. Defaults to NoNormalization.
        """
        self.strict = strict
        self.verbose = verbose

        self._cache_strategy: CacheStrategy = cache_strategy if cache_strategy is not None else NoCache()
        self._validation_strategy: ValidationStrategy = validation_strategy if validation_strategy is not None else NoValidation()
        self._deduplication_strategy: DeduplicationStrategy = deduplication_strategy if deduplication_strategy is not None else NoDeduplication()
        self._normalization_strategy: NormalizationStrategy = normalization_strategy if normalization_strategy is not None else NoNormalization()

    def process(self, data: List[Any]) -> List[Any]:
        """
        Processes a list of data items according to the configured strategies.

        Args:
            data: The list of data items to process.

        Returns:
            A new list containing the processed items.
        """
        # Attempt to retrieve from cache
        cached_result = self._cache_strategy.get(id(data))
        if cached_result is not None:
            return cached_result

        result: List[Any] = []
        seen: Set[Any] = set() # Used by deduplication strategy

        for item in data:
            # 1. Validation
            if not self._validation_strategy.validate(item, self.strict, self.verbose):
                continue # Skip item if validation fails

            # 2. Deduplication
            processed_item = self._deduplication_strategy.process_item(item, seen)
            if processed_item is None: # Item was a duplicate
                continue

            # 3. Normalization
            normalized_item = self._normalization_strategy.normalize(processed_item)

            result.append(normalized_item)

        # Store result in cache
        self._cache_strategy.set(id(data), result)
        return result

    def get_stats(self) -> Dict[str, int]:
        """
        Retrieves combined statistics from all relevant strategies.

        Returns:
            A dictionary containing processing statistics (hits, misses, errors).
        """
        stats: Dict[str, int] = {
            "hits": 0,
            "misses": 0,
            "errors": 0
        }

        if isinstance(self._cache_strategy, InMemoryCache):
            cache_stats = self._cache_strategy.get_stats()
            stats["hits"] = cache_stats.get("hits", 0)
            stats["misses"] = cache_stats.get("misses", 0)

        if isinstance(self._validation_strategy, DictValidation):
            stats["errors"] = self._validation_strategy.get_errors()

        return stats

    def reset_stats(self) -> None:
        """Resets all internal statistics and caches of the strategies."""
        self._cache_strategy.reset()
        self._validation_strategy.reset()
        # Deduplication and Normalization strategies typically don't have resettable state
        # but if they did, their reset methods would be called here.


# --- Factory functions for common configurations ---

def create_default_processor(strict: bool = False, verbose: bool = False) -> DataProcessor:
    """Creates a DataProcessor with no special behaviors enabled."""
    return DataProcessor(strict=strict, verbose=verbose)

def create_caching_processor(strict: bool = False, verbose: bool = False) -> DataProcessor:
    """Creates a DataProcessor with caching enabled."""
    return DataProcessor(
        strict=strict,
        verbose=verbose,
        cache_strategy=InMemoryCache()
    )

def create_full_featured_processor(strict: bool = False, verbose: bool = False) -> DataProcessor:
    """
    Creates a DataProcessor with caching, validation, deduplication, and normalization enabled.
    """
    return DataProcessor(
        strict=strict,
        verbose=verbose,
        cache_strategy=InMemoryCache(),
        validation_strategy=DictValidation(),
        deduplication_strategy=SimpleDeduplication(),
        normalization_strategy=DictStringNormalization()
    )

def create_deduplicating_processor(strict: bool = False, verbose: bool = False) -> DataProcessor:
    """Creates a DataProcessor with deduplication enabled."""
    return DataProcessor(
        strict=strict,
        verbose=verbose,
        deduplication_strategy=SimpleDeduplication()
    )

def create_validating_processor(strict: bool = False, verbose: bool = False) -> DataProcessor:
    """Creates a DataProcessor with validation enabled."""
    return DataProcessor(
        strict=strict,
        verbose=verbose,
        validation_strategy=DictValidation()
    )

def create_normalizing_processor(strict: bool = False, verbose: bool = False) -> DataProcessor:
    """Creates a DataProcessor with normalization enabled."""
    return DataProcessor(
        strict=strict,
        verbose=verbose,
        normalization_strategy=DictStringNormalization()
    )

