import threading

@dataclass(frozen=True)
class ProcessingOptions:
    """Immutable configuration for data processing behavior."""
    strict: bool = False
    verbose: bool = False
    normalize: bool = False
    dedupe: bool = False
    validate: bool = False

class ProcessingStrategy:
    """Abstract base class for processing strategies."""
    def process(self, data: List[Any]) -> List[Any]:
        raise NotImplementedError

class DefaultProcessingStrategy(ProcessingStrategy):
    """Default processing strategy with all features disabled."""
    def process(self, data: List[Any]) -> List[Any]:
        return data.copy()

class ValidationStrategy(ProcessingStrategy):
    """Strategy that validates input data."""
    def __init__(self, strict: bool, verbose: bool):
        self.strict = strict
        self.verbose = verbose

    def process(self, data: List[Any]) -> List[Any]:
        result = []
        for item in data:
            if not isinstance(item, dict):
                if self.strict:
                    raise ValueError(f"Expected dict, got {type(item)}")
                if self.verbose:
                    print(f"Skipping invalid item: {item}")
                continue
            result.append(item)
        return result

class DeduplicationStrategy(ProcessingStrategy):
    """Strategy that removes duplicate items."""
    def __init__(self, normalize: bool):
        self.normalize = normalize

    def process(self, data: List[Any]) -> List[Any]:
        seen: Set[Tuple[Tuple[str, Any], ...]] = set()
        result = []

        for item in data:
            if isinstance(item, dict):
                key = tuple(sorted(item.items()))
            else:
                key = (item,)

            if key in seen:
                continue
            seen.add(key)

            if self.normalize and isinstance(item, dict):
                item = {k: (v.strip().lower() if isinstance(v, str) else v)
                        for k, v in item.items()}
            result.append(item)

        return result

class DataProcessor:
    """Thread-safe data processor with configurable processing strategies."""

    def __init__(self,
                 options: Optional[ProcessingOptions] = None,
                 cache: bool = False):
        self.options = options or ProcessingOptions()
        self.cache = cache
        self._cache: Dict[int, List[Any]] = {}
        self._stats = {"hits": 0, "misses": 0, "errors": 0}
        self._lock = threading.Lock()

        # Build processing pipeline
        self._strategy = DefaultProcessingStrategy()
        if self.options.validate:
            self._strategy = ValidationStrategy(
                self.options.strict, self.options.verbose)
        if self.options.dedupe or self.options.normalize:
            self._strategy = DeduplicationStrategy(self.options.normalize)

    def process(self, data: List[Any]) -> List[Any]:
        data_id = id(data)

        with self._lock:
            if self.cache and data_id in self._cache:
                self._stats["hits"] += 1
                return self._cache[data_id].copy()
            self._stats["misses"] += 1

        try:
            result = self._strategy.process(data)
        except Exception:
            with self._lock:
                self._stats["errors"] += 1
            raise

        if self.cache:
            with self._lock:
