class Validator(ABC):
    """Abstract base for validation strategies."""
    @abstractmethod
    def validate(self, item: Any, stats: Dict[str, int], lock: threading.Lock) -> bool:
        """
        Validate an item.
        - Return True if the item is valid.
        - Return False to skip the item (non‑strict).
        - Raise ValueError to abort processing (strict mode).
        Additionally, increment stats['errors'] under the provided lock.
        """
        ...


class StrictValidator(Validator):
    """Raises ValueError on invalid items."""
    def validate(self, item: Any, stats: Dict[str, int], lock: threading.Lock) -> bool:
        if not isinstance(item, dict):
            with lock:
                stats["errors"] += 1
            raise ValueError(f"Expected dict, got {type(item)}")
        return True


class VerboseValidator(Validator):
    """Prints a message and skips invalid items."""
    def validate(self, item: Any, stats: Dict[str, int], lock: threading.Lock) -> bool:
        if not isinstance(item, dict):
            with lock:
                stats["errors"] += 1
            print(f"Skipping invalid item: {item}")
            return False
        return True


class SilentValidator(Validator):
    """Silently skips invalid items."""
    def validate(self, item: Any, stats: Dict[str, int], lock: threading.Lock) -> bool:
        if not isinstance(item, dict):
            with lock:
                stats["errors"] += 1
            return False
        return True


class Normalizer(ABC):
    """Abstract base for normalization strategies."""
    @abstractmethod
    def normalize(self, item: Dict) -> Dict:
        """Return a normalized version of the item."""
        ...


class DefaultNormalizer(Normalizer):
    """Strips and lowercases string values."""
    def normalize(self, item: Dict) -> Dict:
        return {
            k: (v.strip().lower() if isinstance(v, str) else v)
            for k, v in item.items()
        }


class Deduplicator:
    """Stateful deduplication using a set of string keys."""
    def __init__(self):
        self._seen: Set[str] = set()
        self._lock = threading.Lock()

    def _key(self, item: Any) -> str:
        if isinstance(item, dict):
            return str(sorted(item.items()))
        return str(item)

    def is_duplicate(self, item: Any) -> bool:
        key = self._key(item)
        with self._lock:
            return key in self._seen

    def mark_seen(self, item: Any) -> None:
        key = self._key(item)
        with self._lock:
            self._seen.add(key)

    def reset(self) -> None:
        with self._lock:
            self._seen.clear()


class Cacher:
    """Stateful caching using id() as key."""
    def __init__(self):
        self._cache: Dict[int, List] = {}
        self._lock = threading.Lock()

    def get(self, key: int) -> Optional[List]:
        with self._lock:
            if key in self._cache:
                return self._cache[key]
            return None

    def set(self, key: int, value: List) -> None:
        with self._lock:
            self._cache[key] = value

    def reset(self) -> None:
        with self._lock:
            self._cache.clear()


