class DataProcessor:
    """Processes a list of items with configurable validation,
    deduplication, normalization, and caching.

    All state is instance‑local. Thread‑safe for concurrent calls
    on the same instance.
    """

    def __init__(self,
                 validator: Optional[Validator] = None,
                 normalizer: Optional[Normalizer] = None,
                 deduplicator: Optional[Deduplicator] = None,
                 cacher: Optional[Cacher] = None):
        self._validator = validator
        self._normalizer = normalizer
        self._deduplicator = deduplicator
        self._cacher = cacher

        # Instance‑local statistics
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}
        self._lock = threading.Lock()

    def process(self, data: List) -> List:
        """
        Process the input list.
        Returns a new list with valid, optionally deduplicated and
        normalized items. Caches the result if caching is enabled.
        """
        # ----- caching layer -----
        if self._cacher is not None:
            cached = self._cacher.get(id(data))
            if cached is not None:
                with self._lock:
                    self._stats["hits"] += 1
                return cached
            else:
                with self._lock:
                    self._stats["misses"] += 1

        # ----- main processing loop -----
        result: List = []
        for item in data:
            # 1) Validation
            if self._validator is not None:
                try:
                    valid = self._validator.validate(item, self._stats, self._lock)
                except ValueError:
                    # strict mode – re‑raise immediately
                    raise
                if not valid:
                    continue  # skip invalid item (non‑strict)

            # 2) Deduplication check (before normalization, as in original)
            if self._deduplicator is not None:
                if self._deduplicator.is_duplicate(item):
                    continue

            # 3) Normalization
            if self._normalizer is not None and isinstance(item, dict):
                item = self._normalizer.normalize(item)

            # 4) Append processed item
            result.append(item)

            # 5) Mark as seen for deduplication (after normalization if applied)
            if self._deduplicator is not None:
                self._deduplicator.mark_seen(item)

        # ----- store in cache -----
        if self._cacher is not None:
            self._cacher.set(id(data), result)

        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a snapshot of the current statistics."""
        with self._lock:
            return dict(self._stats)

    def reset(self) -> None:
        """Reset all internal state (statistics, cache, dedup set)."""
        with self._lock:
            self._stats = {"hits": 0, "misses": 0, "errors": 0}
        if self._cacher is not None:
            self._cacher.reset()
        if self._deduplicator is not None:
            self._deduplicator.reset()

