class Token:
    """Represents a single lexical unit of the expression."""
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.type}, {self.value})"

class Parser:
    """
    Recursive descent parser for arithmetic expressions.
    Grammar:
    expression -> term (( '+' | '-' ) term)*
    term       -> factor (( '*' | '/' ) factor)*
    factor     -> unary ( '^' factor )?  (Right-associative power)
    unary      -> '-' unary | primary
    primary    -> NUMBER | '(' expression ')'
    """

    TOKEN_SPEC = [
        ('NUMBER', r'\d+(\.\d*)?'),
        ('OP_POW', r'\*\*'),
        ('OP_MUL_DIV', r'[\*/]'),
        ('OP_ADD_SUB', r'[\+\-]'),
        ('LPAREN', r'\('),
        ('RPAREN', r'\)'),
        ('SKIP', r'\s+'),
        ('MISMATCH', r'.'),
    ]

    def __init__(self, text: str):
        self.tokens = self._tokenize(text)
        self.pos = 0

    def _tokenize(self, text: str) -> List[Token]:
        regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in self.TOKEN_SPEC)
        tokens = []
        for mo in re.finditer(regex, text):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise ExpressionError(f"Unexpected character: {value!r}")
            tokens.append(Token(kind, value))
        return tokens

    def _peek(self) -> Union[Token, None]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _consume(self, expected_type: str = None) -> Token:
        token = self._peek()
        if not token:
            raise ExpressionError("Unexpected end of input")
        if expected_type and token.type != expected_type:
            raise ExpressionError(f"Expected {expected_type}, got {token.type}")
        self.pos += 1
        return token

    def parse(self) -> float:
        result = self._expression()
        if self.pos < len(self.tokens):
            raise ExpressionError(f"Unexpected token at end: {self.tokens[self.pos].value}")
        return float(result)

    def _expression(self) -> float:
        node = self._term()
        while (token := self._peek()) and token.type == 'OP_ADD_SUB':
            op = self._consume().value
            right = self._term()
            node = node + right if op == '+' else node - right
        return node

    def _term(self) -> float:
        node = self._factor()
        while (token := self._peek()) and token.type == 'OP_MUL_DIV':
            op = self._consume().value
            right = self._factor()
            if op == '/':
                if right == 0:
                    raise ExpressionError("Division by zero")
                node /= right
            else:
                node *= right
        return node

    def _factor(self) -> float:
        # Power is right-associative, so we recurse on the right side
        node = self._unary()
        if (token := self._peek()) and token.type == 'OP_POW':
            self._consume()
            right = self._factor()
            node = node ** right
        return node

    def _unary(self) -> float:
        if (token := self._peek()) and token.type == 'OP_ADD_SUB' and token.value == '-':
            self._consume()
            return -self._unary()
        return self._primary()

    def _primary(self) -> float:
        token = self._peek()
        if not token:
            raise ExpressionError("Unexpected end of input")

        if token.type == 'NUMBER':
            self._consume()
            return float(token.value)

        if token.type == 'LPAREN':
            self._consume('LPAREN')
            result = self._expression()
            if not self._peek() or self._peek().type != 'RPAREN':
                raise ExpressionError("Unbalanced parentheses: missing ')'")
            self._consume('RPAREN')
            return result

        raise ExpressionError(f"Unexpected token: {token.value}")

def evaluate(expression: str) -> float:
    """
    Parses and evaluates an arithmetic expression.

    Args:
        expression: A string containing the arithmetic expression.

    Returns:
        The result of the evaluation as a float.

    Raises:
        ExpressionError: If the expression is malformed or contains division by zero.
    """
    parser = Parser(expression)
    return parser.parse()

