class DataProcessor:
    """
    Processes data with configurable strategies for validation,
    normalization, and deduplication. Fully self-contained with
    instance-level caching and statistics.
    """

    def __init__(
        self,
        validation: Optional[ValidationStrategy] = None,
        normalization: Optional[NormalizationStrategy] = None,
        deduplication: Optional[DeduplicationStrategy] = None,
        use_cache: bool = False,
    ) -> None:
        self._validation = validation or NoValidation()
        self._normalization = normalization or NoNormalization()
        self._deduplication = deduplication or NoDeduplication()
        self._use_cache = use_cache

        self._cache = Cache()
        self._stats = Statistics()

    def process(self, data: List[DataItem]) -> ProcessedData:
        data_id = id(data)

        # Check cache
        if self._use_cache:
            cached = self._cache.get(data_id)
            if cached is not None:
                self._stats.hits += 1
                return cached
        self._stats.misses += 1

        result: ProcessedData = []

        for item in data:
            # Validate
            if not self._validation.is_valid(item):
                self._stats.errors += 1
                self._validation.handle_invalid(item)
                continue

            # Deduplicate
            key = self._deduplication.make_key(item)
            if self._deduplication.is_seen(key):
                continue
            self._deduplication.mark_seen(key)

            # Normalize
            item = self._normalization.normalize(item)

            result.append(item)

        # Cache result
        if self._use_cache:
            self._cache.set(data_id, result)

        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a copy of the current statistics."""
        return self._stats.to_dict()

    def reset(self) -> None:
        """Reset cache and statistics."""
        self._cache.clear()
        self._stats.reset()


