class DataProcessor:
    """Processes data with configurable behavior and local state."""

    def __init__(
        self,
        *,
        validate: bool = False,
        dedupe: bool = False,
        normalize: bool = False,
        cache: bool = False,
        strict: bool = False,
        verbose: bool = False
    ):
        # Build processing pipeline based on configuration
        steps: List[ProcessingStep] = []

        if validate:
            steps.append(ValidationStep(strict=strict, verbose=verbose))
        if dedupe:
            steps.append(DeduplicationStep())
        if normalize:
            steps.append(NormalizationStep())

        self.pipeline = ProcessingPipeline(steps)
        self.cache_enabled = cache
        self.cache = Cache() if cache else None
        self.stats = Statistics()

    def process(self, data: List[Any]) -> List[Any]:
        """Process the input data."""
        # Check cache if enabled
        if self.cache_enabled and self.cache:
            cached_result = self.cache.get(id(data))
            if cached_result is not None:
                self.stats.increment("hits")
                return cached_result

        self.stats.increment("misses")

        # Create processing context
        context = {"stats": self.stats}

        # Process data through pipeline
        result = self.pipeline.process(data, context)

        # Cache result if enabled
        if self.cache_enabled and self.cache:
            self.cache.set(id(data), result)

        return result

    def get_stats(self) -> Dict[str, int]:
        """Get current statistics."""
        return self.stats.to_dict()

    def reset(self) -> None:
        """Reset cache and statistics."""
        if self.cache:
            self.cache.clear()
        self.stats.reset()


