from typing import Any, Dict, List, Set
import abc


# ----------------------------------------------------------------------
# Error handling strategies
# ----------------------------------------------------------------------
class ErrorPolicy(abc.ABC):
    """What to do when an invalid item is encountered."""
    @abc.abstractmethod
    def handle_error(self, item: Any) -> None:
        ...


class StrictErrorPolicy(ErrorPolicy):
    def handle_error(self, item: Any) -> None:
        raise ValueError(f"Expected dict, got {type(item)}")


class VerboseErrorPolicy(ErrorPolicy):
    def handle_error(self, item: Any) -> None:
        print(f"Skipping invalid item: {item}")


class SilentErrorPolicy(ErrorPolicy):
    def handle_error(self, item: Any) -> None:
        pass


# ----------------------------------------------------------------------
# Validation strategies
# ----------------------------------------------------------------------
class ValidationPolicy(abc.ABC):
    """Determines whether an item is valid."""
    @abc.abstractmethod
    def validate(self, item: Any, stats: Dict[str, int], error_policy: ErrorPolicy) -> bool:
        """Return True if item is valid, False otherwise."""
        ...


class ValidateStrict(ValidationPolicy):
    def validate(self, item: Any, stats: Dict[str, int], error_policy: ErrorPolicy) -> bool:
        if not isinstance(item, dict):
            stats["errors"] += 1
            error_policy.handle_error(item)
            return False
        return True


class NoValidation(ValidationPolicy):
    def validate(self, item: Any, stats: Dict[str, int], error_policy: ErrorPolicy) -> bool:
        return True


# ----------------------------------------------------------------------
# Normalization strategies
# ----------------------------------------------------------------------
class NormalizationPolicy(abc.ABC):
    """Transforms items."""
    @abc.abstractmethod
    def normalize(self, item: Any) -> Any:
        ...


class NormalizeDict(NormalizationPolicy):
    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {k: (v.strip().lower() if isinstance(v, str) else v)
                    for k, v in item.items()}
        return item


class NoNormalization(NormalizationPolicy):
    def normalize(self, item: Any) -> Any:
        return item


# ----------------------------------------------------------------------
# Deduplication strategies
# ----------------------------------------------------------------------
class DeduplicationPolicy(abc.ABC):
    """Handles deduplication of items."""
    @abc.abstractmethod
    def process(self, item: Any, seen: Set[str]) -> bool:
        """
        Return True if item should be kept (not a duplicate),
        and add its key to 'seen' if kept.
        """
        ...


class DedupeItems(DeduplicationPolicy):
    def process(self, item: Any, seen: Set[str]) -> bool:
        if isinstance(item, dict):
            key = str(sorted(item.items()))
        else:
            key = str(item)
        if key in seen:
            return False
        seen.add(key)
        return True


class NoDeduplication(DeduplicationPolicy):
    def process(self, item: Any, seen: Set[str]) -> bool:
        return True


# ----------------------------------------------------------------------
# Caching strategies
# ----------------------------------------------------------------------
class CachePolicy(abc.ABC):
    """Controls caching of processed results."""
    @abc.abstractmethod
    def get(self, key: int, cache: Dict[int, Any]) -> Any:
        ...

    @abc.abstractmethod
    def set(self, key: int, value: Any, cache: Dict[int, Any]) -> None:
        ...


class CacheEnabled(CachePolicy):
    def get(self, key: int, cache: Dict[int, Any]) -> Any:
        return cache.get(key)

    def set(self, key: int, value: Any, cache: Dict[int, Any]) -> None:
        cache[key] = value


class NoCache(CachePolicy):
    def get(self, key: int, cache: Dict[int, Any]) -> Any:
        return None

    def set(self, key: int, value: Any, cache: Dict[int, Any]) -> None:
        pass


# ----------------------------------------------------------------------
# DataProcessor – fully self‑contained, no global state
# ----------------------------------------------------------------------
class DataProcessor:
    """Processes a list of items with configurable strategies."""

    def __init__(self,
                 validation_policy: ValidationPolicy = NoValidation(),
                 normalization_policy: NormalizationPolicy = NoNormalization(),
                 deduplication_policy: DeduplicationPolicy = NoDeduplication(),
                 cache_policy: CachePolicy = NoCache(),
                 error_policy: ErrorPolicy = SilentErrorPolicy()) -> None:
        self.validation_policy = validation_policy
        self.normalization_policy = normalization_policy
        self.deduplication_policy = deduplication_policy
        self.cache_policy = cache_policy
        self.error_policy = error_policy

        # Instance-local cache and statistics
        self._cache: Dict[int, Any] = {}
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}

    def process(self, data: List[Any]) -> List[Any]:
        """Process the input list and return a filtered / transformed list."""
        key = id(data)
        cached = self.cache_policy.get(key, self._cache)
        if cached is not None:
            self._stats["hits"] += 1
            return cached
        self._stats["misses"] += 1

        result: List[Any] = []
        seen: Set[str] = set()

        for item in data:
            # Validation
            if not self.validation_policy.validate(item, self._stats, self.error_policy):
                continue
            # Deduplication
            if not self.deduplication_policy.process(item, seen):
                continue
            # Normalization
            item = self.normalization_policy.normalize(item)
            result.append(item)

        self.cache_policy.set(key, result, self._cache)
        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a copy of the current statistics."""
        return self._stats.copy()

    def reset(self) -> None:
        """Clear all cached results and reset statistics to zero."""
        self._cache.clear()
        self._stats = {"hits": 0, "misses": 0, "errors": 0}

