"""
Recursive-descent parser and evaluator for arithmetic expressions.

Supports: integers, floats, +, -, *, /, ** (right-associative), unary minus.
Operator precedence: ** > unary minus > * / > + -
"""

from __future__ import annotations
from enum import Enum, auto
from dataclasses import dataclass
from typing import Union


class TokenType(Enum):
    NUMBER = auto()
    PLUS = auto()
    MINUS = auto()
    MULTIPLY = auto()
    DIVIDE = auto()
    POWER = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()


@dataclass(frozen=True)
class Token:
    type: TokenType
    value: Union[float, str, None] = None

    def __repr__(self) -> str:
        if self.value is not None:
            return f"Token({self.type.name}, {self.value!r})"
        return f"Token({self.type.name})"


class ParseError(Exception):
    """Raised when the input cannot be parsed."""
    pass


class EvaluationError(Exception):
    """Raised when evaluation fails (e.g., division by zero)."""
    pass


class Lexer:
    """Tokenizes an arithmetic expression string."""

    def __init__(self, text: str) -> None:
        self._text = text
        self._pos = 0

    def _current_char(self) -> str | None:
        if self._pos >= len(self._text):
            return None
        return self._text[self._pos]

    def _advance(self) -> None:
        self._pos += 1

    def _peek(self, offset: int = 1) -> str | None:
        peek_pos = self._pos + offset
        if peek_pos >= len(self._text):
            return None
        return self._text[peek_pos]

    def _skip_whitespace(self) -> None:
        while self._current_char() is not None and self._current_char().isspace():
            self._advance()

    def _read_number(self) -> float:
        """Read a number literal (int or float)."""
        num_str = ""
        has_dot = False

        while self._current_char() is not None and (
            self._current_char().isdigit() or self._current_char() == "."
        ):
            if self._current_char() == ".":
                if has_dot:
                    raise ParseError(f"Unexpected second decimal point at position {self._pos}")
                has_dot = True
            num_str += self._current_char()
            self._advance()

        if not num_str:
            raise ParseError("Expected number")

        return float(num_str)

    def _read_token(self) -> Token:
        """Read the next token."""
        self._skip_whitespace()

        char = self._current_char()
        if char is None:
            return Token(TokenType.EOF)
        self._advance()

        # Number literal
        if char.isdigit() or (char == "." and self._current_char() is not None and self._current_char().isdigit()):
            # Put back one char for the dot case, then read the full number
            if char == ".":
                self._pos -= 1
            return Token(TokenType.NUMBER, self._read_number())

        # Single-character operators
        operators = {
            "+": TokenType.PLUS,
            "-": TokenType.MINUS,
            "*": TokenType.MULTIPLY,
            "/": TokenType.DIVIDE,
            "(": TokenType.LPAREN,
            ")": TokenType.RPAREN,
        }
        if char in operators:
            return Token(operators[char])

        # Power operator **
        if char == "*":
            if self._current_char() == "*":
                self._advance()
                return Token(TokenType.POWER)
            return Token(TokenType.MULTIPLY)

        raise ParseError(f"Unexpected character: {char!r}")

    def tokenize(self) -> list[Token]:
        """Convert input string into a list of tokens."""
        tokens = []
        while True:
            token = self._read_token()
            tokens.append(token)
            if token.type == TokenType.EOF:
                break
        return tokens


