        """Parse addition and subtraction (lowest precedence)."""
        left = self._parse_term()

        while self._current().type in (TokenType.PLUS, TokenType.MINUS):
            op = self._advance()
            right = self._parse_term()
            if op.type == TokenType.PLUS:
                left = left + right
            else:
                left = left - right

        return left

    def _parse_term(self) -> float:
        """Parse multiplication and division."""
        left = self._parse_unary()

        while self._current().type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            op = self._advance()
            right = self._parse_unary()
            if op.type == TokenType.MULTIPLY:
                left = left * right
            else:
                if right == 0:
                    raise EvaluationError("Division by zero")
                left = left / right

        return left

    def _parse_unary(self) -> float:
        """Parse unary minus (higher precedence than * and /)."""
        if self._current().type == TokenType.MINUS:
            self._advance()
            return -self._parse_unary()
        return self._parse_power()

    def _parse_power(self) -> float:
        """Parse exponentiation (right-associative)."""
        base = self._parse_primary()

        if self._current().type == TokenType.POWER:
            self._advance()
            # Right-associative: 2**3**2 = 2**(3**2) = 512
            exponent = self._parse_power()
            return base ** exponent

        return base

    def _parse_primary(self) -> float:
        """Parse atomic values: numbers and parenthesized expressions."""
        token = self._current()

        # Number literal
        if token.type == TokenType.NUMBER:
            self._advance()
            return token.value  # type: ignore[return-value]

        # Parenthesized expression
        if token.type == TokenType.LPAREN:
            self._advance()
            result = self._parse_expression()
            self._expect(TokenType.RPAREN)
            return result

        raise ParseError(f"Unexpected token: {token}")

    def parse(self) -> float:
        """Parse and evaluate the entire expression."""
        result = self._parse_expression()

        if self._current().type != TokenType.EOF:
            raise ParseError(f"Unexpected token after expression: {self._current()}")

        return result


def evaluate(expression: str) -> float:
    """
    Evaluate an arithmetic expression and return the result as a float.

    Args:
        expression: A string containing an arithmetic expression with
                    integers, floats, +, -, *, /, **, and parentheses.
                    Unary minus is supported.

    Returns:
        The result of the expression as a float.

    Raises:
        ParseError: If the expression is malformed.
        EvaluationError: If evaluation fails (e.g., division by zero).
    """
    if not expression or expression.isspace():
        raise ParseError("Empty expression")

    lexer = Lexer(expression)
    tokens = lexer.tokenize()
    parser = Parser(tokens)
    return parser.parse()


