# Usage examples
# -----------------------------------------------------------------------------

if __name__ == "__main__":
    # Example 1: Operator precedence
    # ** > * > +  =>  2 + 3 * 4 = 14, not 20
    result = evaluate("2 + 3 * 4")
    print(f"2 + 3 * 4 = {result}")  # 14.0

    # Example 2: Parentheses for grouping
    # (2 + 3) * 4 = 20
    result = evaluate("(2 + 3) * 4")
    print(f"(2 + 3) * 4 = {result}")  # 20.0

    # Example 3: Unary minus
    # -3 + 5 = 2
