import collections
from typing import Any, Dict, List, Set, Tuple, Protocol, Optional

# --- Strategy Interfaces ---

class Validator(Protocol):
    def validate(self, item: Any) -> bool:
        """Validates a single item. Returns True if valid, False otherwise."""
        ...

class Normalizer(Protocol):
    def normalize(self, item: Any) -> Any:
        """Normalizes a single item."""
        ...

class Deduplicator(Protocol):
    def process_item(self, item: Any, seen: Set[Any]) -> Optional[Any]:
        """Processes an item for deduplication. Returns the item if unique, else None."""
        ...

class Cache(Protocol):
    def get(self, key: Any) -> Optional[Any]:
        """Retrieves an item from the cache. Returns None if not found."""
        ...

    def set(self, key: Any, value: Any) -> None:
        """Stores an item in the cache."""
        ...

    def clear(self) -> None:
        """Clears the cache."""
        ...

    def get_stats(self) -> Dict[str, int]:
        """Returns cache statistics."""
        ...

# --- Concrete Strategy Implementations ---

class NoValidation:
    def validate(self, item: Any) -> bool:
        return True

class DictTypeValidator:
    def __init__(self, strict: bool = False, verbose: bool = False):
        self.strict = strict
        self.verbose = verbose
        self.errors = 0

    def validate(self, item: Any) -> bool:
        if not isinstance(item, dict):
            self.errors += 1
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return False
        return True

class NoNormalization:
    def normalize(self, item: Any) -> Any:
        return item

class DictStringNormalizer:
    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {k: (v.strip().lower() if isinstance(v, str) else v)
                    for k, v in item.items()}
        return item

class NoDeduplication:
    def process_item(self, item: Any, seen: Set[Any]) -> Optional[Any]:
        return item

class BasicDeduplicator:
    def process_item(self, item: Any, seen: Set[Any]) -> Optional[Any]:
        # For deduplication, we need a hashable key.
        # For dicts, sorting items ensures consistent key generation.
        key: Any
        if isinstance(item, dict):
            # Convert dict to a sorted tuple of (key, value) pairs for hashing
            key = tuple(sorted(item.items()))
        else:
            key = item

        if key in seen:
            return None
        seen.add(key)
        return item

class NoCache:
    def get(self, key: Any) -> Optional[Any]:
        return None

    def set(self, key: Any, value: Any) -> None:
        pass

    def clear(self) -> None:
        pass

    def get_stats(self) -> Dict[str, int]:
        return {"hits": 0, "misses": 0}

class InMemoryCache:
    def __init__(self):
        self._cache: Dict[Any, Any] = {}
        self._hits: int = 0
        self._misses: int = 0

    def get(self, key: Any) -> Optional[Any]:
        if key in self._cache:
            self._hits += 1
            return self._cache[key]
        self._misses += 1
        return None

    def set(self, key: Any, value: Any) -> None:
        self._cache[key] = value

    def clear(self) -> None:
        self._cache.clear()
        self._hits = 0
        self._misses = 0

    def get_stats(self) -> Dict[str, int]:
        return {"hits": self._hits, "misses": self._misses}

# --- Refactored DataProcessor ---

class DataProcessor:
    def __init__(
        self,
        validator: Optional[Validator] = None,
        normalizer: Optional[Normalizer] = None,
        deduplicator: Optional[Deduplicator] = None,
        cache: Optional[Cache] = None,
    ):
        self.validator: Validator = validator if validator is not None else NoValidation()
        self.normalizer: Normalizer = normalizer if normalizer is not None else NoNormalization()
        self.deduplicator: Deduplicator = deduplicator if deduplicator is not None else NoDeduplication()
        self.cache_strategy: Cache = cache if cache is not None else NoCache()

        # Internal statistics for the processor itself, separate from cache stats
        self._processing_errors: int = 0

    def process(self, data: List[Any]) -> List[Any]:
        # Use id(data) as a cache key for the entire input list
        cache_key = id(data)
        cached_result = self.cache_strategy.get(cache_key)
        if cached_result is not None:
            return cached_result

        result: List[Any] = []
        seen: Set[Any] = set() # Used by deduplicator

        for item in data:
            if not self.validator.validate(item):
                if isinstance(self.validator, DictTypeValidator): # Access specific error count if available
                    self._processing_errors = self.validator.errors
                continue

            deduped_item = self.deduplicator.process_item(item, seen)
            if deduped_item is None:
                continue

            normalized_item = self.normalizer.normalize(deduped_item)
            result.append(normalized_item)

        self.cache_strategy.set(cache_key, result)
        return result

    def get_stats(self) -> Dict[str, int]:
        stats = self.cache_strategy.get_stats()
        # Add validation errors to the overall stats
        if isinstance(self.validator, DictTypeValidator):
            stats["validation_errors"] = self.validator.errors
        else:
            stats["validation_errors"] = self._processing_errors # Fallback for other validators
        return stats

    def reset(self) -> None:
        self.cache_strategy.clear()
        self._processing_errors = 0
        if isinstance(self.validator, DictTypeValidator):
            self.validator.errors = 0

# --- Example Usage (demonstrating how to instantiate with desired behaviors) ---

if __name__ == "__main__":
    # Scenario 1: Basic processing with validation and deduplication
    print("--- Scenario 1: Basic Validation and Deduplication ---")
    processor1 = DataProcessor(
        validator=DictTypeValidator(strict=False, verbose=True),
        deduplicator=BasicDeduplicator()
    )
    data1 = [
        {"name": "Alice", "id": 1},
        {"name": "Bob", "id": 2},
        "invalid_item",
        {"name": "Alice", "id": 1}, # Duplicate
        {"name": "Charlie", "id": 3},
        123 # Another invalid item
    ]
    processed_data1 = processor1.process(data1)
    print("Processed Data 1:", processed_data1)
    print("Stats 1:", processor1.get_stats())
    print("-" * 30)

    # Scenario 2: Processing with normalization and caching
    print("--- Scenario 2: Normalization and Caching ---")
    processor2 = DataProcessor(
        normalizer=DictStringNormalizer(),
        cache=InMemoryCache()
    )
    data2 = [
        {"Name": "  JOHN  ", "City": "New York"},
        {"name": "jane", "city": "london "},
    ]
    processed_data2_a = processor2.process(data2)
    print("Processed Data 2 (first run):", processed_data2_a)
    print("Stats 2 (first run):", processor2.get_stats())

    # Process same data again, should hit cache
    processed_data2_b = processor2.process(data2)
    print("Processed Data 2 (second run):", processed_data2_b)
    print("Stats 2 (second run):", processor2.get_stats())

    # Process different data
    data2_b = [
        {"Name": "  JOHN  ", "City": "New York"},
        {"name": "peter", "city": "paris "},
    ]
    processed_data2_c = processor2.process(data2_b)
    print("Processed Data 2 (third run, new data):", processed_data2_c)
    print("Stats 2 (third run):", processor2.get_stats())
    print("-" * 30)

    # Scenario 3: Strict validation
    print("--- Scenario 3: Strict Validation ---")
    processor3 = DataProcessor(
        validator=DictTypeValidator(strict=True)
    )
    data3 = [
        {"key": "value"},
        "not a dict"
    ]
    try:
        processor3.process(data3)
    except ValueError as e:
        print(f"Caught expected error: {e}")
    print("Stats 3:", processor3.get_stats())
    print("-" * 30)

    # Scenario 4: No special behavior (default strategies)
    print("--- Scenario 4: No Special Behavior ---")
    processor4 = DataProcessor()
    data4 = [1, 2, 2, 3, {"a": 1}]
    processed_data4 = processor4.process(data4)
    print("Processed Data 4:", processed_data4)
    print("Stats 4:", processor4.get_stats())
    print("-" * 30)

    # Scenario 5: Resetting a processor
    print("--- Scenario 5: Resetting a Processor ---")
    processor5 = DataProcessor(
        validator=DictTypeValidator(verbose=True),
        cache=InMemoryCache()
    )
    data5_a = [{"a": 1}, "bad", {"a": 1}]
    processor5.process(data5_a)
    print("Stats 5 (after first run):", processor5.get_stats())
    processor5.reset()
    print("Stats 5 (after reset):", processor5.get_stats())
    data5_b = [{"b": 2}, "worse"]
    processor5.process(data5_b)
    print("Stats 5 (after second run):", processor5.get_stats())
    print("-" * 30)

