    """Thread-safe container for processing statistics."""
    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._hits = 0
        self._misses = 0
        self._errors = 0

    def inc_hit(self) -> None:
        with self._lock: self._hits += 1

    def inc_miss(self) -> None:
        with self._lock: self._misses += 1

    def inc_error(self) -> None:
        with self._lock: self._errors += 1

    def to_dict(self) -> Dict[str, int]:
        with self._lock:
            return {"hits": self._hits, "misses": self._misses, "errors": self._errors}

    def reset(self) -> None:
        with self._lock:
            self._hits = 0
            self._misses = 0
            self._errors = 0

# --- Concrete Strategies ---

class ValidatorStep:
    def __call__(self, item: Any, context: ProcessingContext) -> Optional[Any]:
        if not isinstance(item, dict):
            context.stats.inc_error()
            if context.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if context.verbose:
                print(f"Skipping invalid item: {item}")
            return None
        return item

class DeduplicatorStep:
    def __init__(self) -> None:
        self._seen: Set[str] = set()

    def __call__(self, item: Any, context: ProcessingContext) -> Optional[Any]:
        key = str(sorted(item.items()) if isinstance(item, dict) else item)
        if key in self._seen:
            return None
        self._seen.add(key)
        return item

class NormalizerStep:
    def __call__(self, item: Any, context: ProcessingContext) -> Optional[Any]:
        if isinstance(item, dict):
            return {k: (v.strip().lower() if isinstance(v, str) else v)
                    for k, v in item.items()}
        return item

# --- Main Processor ---

class DataProcessor:
    def __init__(self, strict: bool = False, verbose: bool = False, 
                 use_cache: bool = False, normalize: bool = False, 
                 dedupe: bool = False, validate: bool = False):

        self._strict = strict
        self._verbose = verbose
        self._use_cache = use_cache

        # Instance-local state replaces module-global state
        self._stats = ProcessorStats()
        self._cache: Dict[int, List[Any]] = {}
        self._cache_lock = threading.Lock()

        # Composition: Build the pipeline based on flags
        self._pipeline: List[ProcessingStep] = []
        if validate:
            self._pipeline.append(ValidatorStep())
        if dedupe:
            self._pipeline.append(DeduplicatorStep())
        if normalize:
            self._pipeline.append(NormalizerStep())

    def process(self, data: List[Any]) -> List[Any]:
        data_id = id(data)

        if self._use_cache:
            with self._cache_lock:
                if data_id in self._cache:
                    self._stats.inc_hit()
                    return self._cache[data_id]

        self._stats.inc_miss()

        # Fresh state for deduplication per process call
        # We recreate the pipeline or reset the deduplicator if it exists
        current_pipeline = self._build_runtime_pipeline()
        context = ProcessingContext(stats=self._stats, strict=self._strict, verbose=self._verbose)

        result: List[Any] = []
        for item in data:
            processed_item = item
            for step in current_pipeline:
                processed_item = step(processed_item, context)
                if processed_item is None:
                    break

            if processed_item is not None:
                result.append(processed_item)

        if self._use_cache:
            with self._cache_lock:
                self._cache[data_id] = result

        return result

    def _build_runtime_pipeline(self) -> List[ProcessingStep]:
        """
        Ensures that stateful steps (like Deduplicator) are fresh for every 
        call to process(), while stateless steps are reused.
        """
        pipeline = []
        # Re-evaluate the original flags to build the sequence
        # In a more complex system, these would be passed as a list of strategies to __init__
        if any(isinstance(s, ValidatorStep) for s in self._pipeline):
            pipeline.append(ValidatorStep())
        if any(isinstance(s, DeduplicatorStep) for s in self._pipeline):
            pipeline.append(DeduplicatorStep())
        if any(isinstance(s, NormalizerStep) for s in self._pipeline):
            pipeline.append(NormalizerStep())
        return pipeline

    def get_stats(self) -> Dict[str, int]:
        return self._stats.to_dict()

    def reset(self) -> None:
        with self._cache_lock:
            self._cache.clear()
        self._stats.reset()

