    def set(self, data_id: int, result: List[Any]) -> None: ...


# --- Concrete Strategy Implementations ---

class StrictValidation:
    """Validates that items are dictionaries."""
    def validate(self, item: Any) -> None:
        if not isinstance(item, dict):
            raise ValueError(f"Expected dict, got {type(item)}")


class NoValidation:
    """No validation performed."""
    def validate(self, item: Any) -> None:
        pass


class LowercaseNormalization:
    """Normalizes string values to lowercase and strips whitespace."""
    def normalize(self, item: Any) -> Any:
        if not isinstance(item, dict):
            return item
        return {
            k: (v.strip().lower() if isinstance(v, str) else v)
            for k, v in item.items()
        }


