        key = str(sorted(item.items()) if isinstance(item, dict) else item)
        if key in self._seen:
            return True
        self._seen.add(key)
        return False

    def reset(self) -> None:
        self._seen.clear()


class NoDeduplication:
    """No deduplication performed."""
    def is_duplicate(self, item: Any) -> bool:
        return False

    def reset(self) -> None:
        pass


