    """In-memory cache keyed by object identity."""
    def __init__(self) -> None:
        self._cache: Dict[int, List[Any]] = {}

    def get(self, data_id: int) -> Optional[List[Any]]:
        return self._cache.get(data_id)

    def set(self, data_id: int, result: List[Any]) -> None:
        self._cache[data_id] = result


class NoCache:
    """No caching performed."""
    def get(self, data_id: int) -> Optional[List[Any]]:
        return None

    def set(self, data_id: int, result: List[Any]) -> None:
        pass


