    """
    Processes data with configurable strategies for validation,
    normalization, deduplication, and caching.

    All state is instance-level, making the class fully self-contained
    and safe for concurrent use across multiple instances.
    """

    def __init__(
        self,
        validation: Optional[ValidationStrategy] = None,
        normalization: Optional[NormalizationStrategy] = None,
        deduplication: Optional[DeduplicationStrategy] = None,
        caching: Optional[CachingStrategy] = None,
        verbose: bool = False,
    ) -> None:
        self._validation = validation or NoValidation()
        self._normalization = normalization or NoNormalization()
        self._deduplication = deduplication or NoDeduplication()
        self._caching = caching or NoCache()
        self._verbose = verbose
        self._stats = Statistics()

    def process(self, data: Iterable[Any]) -> List[Any]:
        """Process the input data according to configured strategies."""
        data_id = id(data)

        cached_result = self._caching.get(data_id)
        if cached_result is not None:
            self._stats.hits += 1
            return cached_result

        self._stats.misses += 1
        self._deduplication.reset()

        result: List[Any] = []
        for item in data:
            try:
                self._validation.validate(item)
            except ValueError:
                self._stats.errors += 1
                if self._verbose:
                    print(f"Skipping invalid item: {item}")
                continue

            if self._deduplication.is_duplicate(item):
                continue

            item = self._normalization.normalize(item)
            result.append(item)

        self._caching.set(data_id, result)
        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a copy of the current statistics."""
        return self._stats.to_dict()

