    """
    Processes data items with configurable validation, normalization,
    deduplication, and caching.

    All state is instance-local, making this class fully testable and
    safe for concurrent use across multiple instances.
    """

    def __init__(
        self,
        strict: bool = False,
        verbose: bool = False,
        cache: bool = False,
        normalize: bool = False,
        dedupe: bool = False,
        validate: bool = False,
    ):
        self._config = ProcessorConfig(
            strict=strict,
            verbose=verbose,
            cache_enabled=cache,
            normalize=normalize,
            dedupe=dedupe,
            validate=validate,
        )
        self._validation_policy: ValidationPolicy = (
            StrictPolicy() if strict else LenientPolicy()
        )

