        Applies validation, deduplication, normalization, and caching
        based on configuration. Returns a list of processed dictionaries.
        """
        if self._config.cache_enabled:
            cached = self._get_cached(id(data))
            if cached is not None:
                return cached

        result = self._process_items(list(data))

        if self._config.cache_enabled:
            self._set_cached(id(data), result)

        return result

