from abc import ABC, abstractmethod


class CacheStrategy(ABC):
    """Abstract base class for caching strategies."""

    @abstractmethod
    def get(self, key: Any) -> Optional[List[Dict[str, Any]]]:
        """Retrieve cached result for given key."""
        pass

    @abstractmethod
    def set(self, key: Any, value: List[Dict[str, Any]]) -> None:
        """Cache result for given key."""
        pass

    @abstractmethod
    def clear(self) -> None:
        """Clear all cached entries."""
        pass


class MemoryCacheStrategy(CacheStrategy):
    """In-memory caching strategy."""

    def __init__(self) -> None:
        self._cache: Dict[Any, List[Dict[str, Any]]] = {}

    def get(self, key: Any) -> Optional[List[Dict[str, Any]]]:
        return self._cache.get(key)

    def set(self, key: Any, value: List[Dict[str, Any]]) -> None:
        self._cache[key] = value

    def clear(self) -> None:
        self._cache.clear()


class NoCacheStrategy(CacheStrategy):
    """No caching strategy."""

    def get(self, key: Any) -> Optional[List[Dict[str, Any]]]:
        return None

    def set(self, key: Any, value: List[Dict[str, Any]]) -> None:
        pass

    def clear(self) -> None:
        pass


class ValidationStrategy(ABC):
    """Abstract base class for validation strategies."""

    @abstractmethod
    def validate(self, item: Any) -> bool:
        """Validate an item."""
        pass

    @abstractmethod
    def handle_invalid(self, item: Any) -> None:
        """Handle invalid item according to strategy."""
        pass


class StrictValidationStrategy(ValidationStrategy):
    """Strict validation: raise exception on invalid items."""

    def validate(self, item: Any) -> bool:
        return isinstance(item, dict)

    def handle_invalid(self, item: Any) -> None:
        raise ValueError(f"Expected dict, got {type(item)}")


class SkipValidationStrategy(ValidationStrategy):
    """Skip invalid items silently."""

    def validate(self, item: Any) -> bool:
        return isinstance(item, dict)

    def handle_invalid(self, item: Any) -> None:
        pass


class VerboseValidationStrategy(ValidationStrategy):
    """Skip invalid items with verbose logging."""

    def validate(self, item: Any) -> bool:
        return isinstance(item, dict)

    def handle_invalid(self, item: Any) -> None:
        print(f"Skipping invalid item: {item}")


class DeduplicationStrategy(ABC):
    """Abstract base class for deduplication strategies."""

    @abstractmethod
    def should_skip(self, item: Any, seen: Set[str]) -> bool:
        """Determine if item should be skipped due to duplication."""
        pass

    @abstractmethod
    def add_to_seen(self, item: Any, seen: Set[str]) -> None:
        """Add item to seen set."""
        pass


class DictDeduplicationStrategy(DeduplicationStrategy):
    """Deduplication for dictionary items."""

    def should_skip(self, item: Any, seen: Set[str]) -> bool:
        if not isinstance(item, dict):
            return False
        key = str(sorted(item.items()))
        return key in seen

    def add_to_seen(self, item: Any, seen: Set[str]) -> None:
        if isinstance(item, dict):
            key = str(sorted(item.items()))
            seen.add(key)


class NoDeduplicationStrategy(DeduplicationStrategy):
    """No deduplication."""

    def should_skip(self, item: Any, seen: Set[str]) -> bool:
        return False

    def add_to_seen(self, item: Any, seen: Set[str]) -> None:
        pass


class NormalizationStrategy(ABC):
    """Abstract base class for normalization strategies."""

    @abstractmethod
    def normalize(self, item: Dict[str, Any]) -> Dict[str, Any]:
        """Normalize a dictionary item."""
        pass


class StringNormalizationStrategy(NormalizationStrategy):
    """Normalize string values in dictionary."""

    def normalize(self, item: Dict[str, Any]) -> Dict[str, Any]:
        return {
            k: (v.strip().lower() if isinstance(v, str) else v)
            for k, v in item.items()
        }


class NoNormalizationStrategy(NormalizationStrategy):
    """No normalization."""

    def normalize(self, item: Dict[str, Any]) -> Dict[str, Any]:
        return item


class Statistics:
    """Self-contained statistics tracking."""

    def __init__(self) -> None:
        self.hits: int = 0
        self.misses: int = 0
        self.errors: int = -0

    def increment_hits(self) -> None:
        self.hits += 1

    def increment_misses(self) -> None:
        self.misses += 1

    def increment_errors(self) -> None:
        self.errors += 1

    def get_stats(self) -> Dict[str, int]:
        return {"hits": self.hits, "misses": self.misses, "errors": self.errors}

    def reset(self) -> None:
        self.hits = 0
        self.misses = 0
        self.errors = 0


class DataProcessor:
    """Refactored DataProcessor with strategy patterns and no global state."""

    def __init__(
        self,
        cache_strategy: Optional[CacheStrategy] = None,
        validation_strategy: Optional[ValidationStrategy] = None,
        deduplication_strategy: Optional[DeduplicationStrategy] = None,
        normalization_strategy: Optional[NormalizationStrategy] = None,
    ) -> None:
        # Default strategies
        self.cache_strategy = cache_strategy or NoCacheStrategy()
        self.validation_strategy = validation_strategy or SkipValidationStrategy()
        self.deduplication_strategy = deduplication_strategy or NoDeduplicationStrategy()
        self.normalization_strategy = normalization_strategy or NoNormalizationStrategy()

        # Instance-specific statistics
        self.statistics = Statistics()

    def process(self, data: List[Any]) -> List[Dict[str, Any]]:
        # Cache lookup
        cache_key = id(data)
        cached_result = self.cache_strategy.get(cache_key)
        if cached_result is not None:
            self.statistics.increment_hits()
            return cached_result

        self.statistics.increment_misses()

        result: List[Dict[str, Any]] = []
        seen: Set[str] = set()

        for item in data:
            # Validation
            if not self.validation_strategy.validate(item):
                self.statistics.increment_errors()
                self.validation_strategy.handle_invalid(item)
                continue

            # Deduplication
            if self.deduplication_strategy.should_skip(item, seen):
                continue

            # Add to seen set for deduplication
            self.deduplication_strategy.add_to_seen(item, seen)

            # Normalization
            normalized_item = self.normalization_strategy.normalize(item)
            result.append(normalized_item)

        # Cache result
        self.cache_strategy.set(cache_key, result)
        return result

    def get_stats(self) -> Dict[str, int]:
        return self.statistics.get_stats()

    def reset(self) -> None:
        self.statistics.reset()
        self.cache_strategy.clear()


