def create_strict_processor(
    cache: bool = False,
    dedupe: bool = False,
    normalize: bool = False,
) -> DataProcessor:
    """Create processor with strict validation."""
    cache_strategy = MemoryCacheStrategy() if cache else NoCacheStrategy()
    deduplication_strategy = DictDeduplicationStrategy() if dedupe else NoDeduplicationStrategy()
    normalization_strategy = StringNormalizationStrategy() if normalize else NoNormalizationStrategy()

    return DataProcessor(
        cache_strategy=cache_strategy,
        validation_strategy=StrictValidationStrategy(),
