class DataProcessor:
    """
    Composable data processor that eliminates boolean mode-flags and global state.
    Behavior is selected via injected strategy objects.
    """

    def __init__(
        self,
        cache: Optional[CacheStrategy] = None,
        stats: Optional[StatsStrategy] = None,
        validator: Optional[ValidationStrategy] = None,
        deduplicator: Optional[DeduplicationStrategy] = None,
        normalizer: Optional[NormalizationStrategy] = None,
    ) -> None:
        self.cache = cache
        self.stats = stats
        self.validator = validator
        self.deduplicator = deduplicator
        self.normalizer = normalizer

    def process(self, data: List[Any]) -> List[Any]:
        # Use content-based key for reliable caching; fallback to id() if unhashable
        try:
            data_key: Any = tuple(data)
        except TypeError:
            data_key = id(data)

        cached_result = self.cache.get(data_key) if self.cache else None
        if cached_result is not None:
            self.stats.record_hit() if self.stats else None
            return cached_result

        if self.stats:
            self.stats.record_miss()

        result: List[Any] = []
        seen: set = set()

        for item in data:
            if self.validator is not None:
                if not self.validator.is_valid(item):
                    self.stats.record_error() if self.stats else None
                    self.validator.on_invalid(item)
                    continue

            if self.deduplicator is not None:
                if not self.deduplicator.should_keep(item, seen):
                    continue

            if self.normalizer is not None:
                item = self.normalizer.normalize(item)

            result.append(item)

        if self.cache:
            self.cache.put(data_key, result)

        return result

    def get_stats(self) -> Dict[str, int]:
        if self.stats is None:
            return {"hits": 0, "misses": 0, "errors": 0}
        return self.stats.get_stats()

    def reset(self) -> None:
        if self.cache:
            self.cache.reset()
        if self.stats:
            self.stats.reset()

