class Cache:
    """Optional caching layer with instance-level storage."""

    def __init__(self, enabled: bool = False) -> None:
        self._enabled = enabled
        self._storage: Dict[int, List[Dict[str, Any]]] = {}

    def get_or_compute(
        self,
        key: int,
        compute: callable
    ) -> List[Dict[str, Any]]:
        """Return cached result if present, otherwise compute and cache it."""
        if self._enabled and key in self._storage:
            return self._storage[key]

        result = compute()
        if self._enabled:
            self._storage[key] = result
        return result

    def clear(self) -> None:
        self._storage.clear()


class Validator:
    """Validates that items are dictionaries."""

    def __init__(self, strict: bool = False, verbose: bool = False) -> None:
        self._strict = strict
        self._verbose = verbose

    def validate(self, item: Any, stats: Statistics) -> Optional[Dict[str, Any]]:
        """Validate item. Returns None if invalid (to be skipped)."""
        if isinstance(item, dict):
            return item

        stats.errors += 1
        if self._strict:
            raise ValueError(f"Expected dict, got {type(item).__name__}")
        if self._verbose:
            print(f"Skipping invalid item: {item}")
        return None


