        self._seen: Set[str] = set()

    def is_unique(self, item: Any) -> bool:
        """Check and mark item as seen. Returns False if duplicate."""
        key = self._canonical_key(item)
        if key in self._seen:
            return False
        self._seen.add(key)
        return True

    @staticmethod
    def _canonical_key(item: Any) -> str:
        return str(sorted(item.items()) if isinstance(item, dict) else item)

