class DataProcessor:
    """
    Processes data with configurable behaviors.

    Each instance maintains its own cache and statistics,
    making it safe for concurrent use and fully testable.
    """

    def __init__(
        self,
        strict: bool = False,
        verbose: bool = False,
        cache: bool = False,
        normalize: bool = False,
        dedupe: bool = False,
        validate: bool = False,
    ) -> None:
        self._cache = Cache(enabled=cache)
        self._stats = Statistics()
        self._validator = Validator(strict, verbose) if validate else None
        self._normalizer = Normalizer() if normalize else None
        self._deduplicator = Deduplicator() if dedupe else None

