        """Process the data through enabled pipeline stages."""
        cache_key = id(data)

        return self._cache.get_or_compute(cache_key, lambda: self._compute(data))

    def _compute(self, data: List[Any]) -> List[Dict[str, Any]]:
        """Execute the processing pipeline."""
        self._stats.misses += 1
        result: List[Dict[str, Any]] = []

        for item in data:
            processed = self._apply_pipeline(item)
            if processed is not None:
                result.append(processed)

        return result

    def _apply_pipeline(self, item: Any) -> Optional[Dict[str, Any]]:
        """Apply validation, deduplication, and normalization stages."""
        # Stage 1: Validation
        if self._validator:
            item = self._validator.validate(item, self._stats)
            if item is None:
                return None

        # Stage 2: Deduplication
        if self._deduplicator:
            if not self._deduplicator.is_unique(item):
                return None

        # Stage 3: Normalization
        if self._normalizer and isinstance(item, dict):
            item = self._normalizer.normalize(item)

        return item

    def get_stats(self) -> Dict[str, int]:
        """Return a copy of current statistics."""
        return {
            "hits": self._stats.hits,
            "misses": self._stats.misses,
            "errors": self._stats.errors,
        }

    def reset(self) -> None:
        """Clear cache, statistics, and deduplication state."""
        self._cache.clear()
        self._stats.reset()
        if self._deduplicator:
            self._deduplicator.reset()

