    Protocol for defining data processing steps.
    Each strategy should implement a `process_item` method.
    """
    def process_item(self, item: Any) -> Any:
        """
        Applies a specific processing step to a single data item.
        """
        ...

    def get_key(self, item: Any) -> Hashable:
        """
        Generates a key for an item, primarily used for deduplication.
        """
        return item


