    """
    def process_item(self, item: Any) -> Any:
        return item

    def get_key(self, item: Any) -> Hashable:
        return item


class NormalizationStrategy(DataProcessingStrategy):
    """
    Normalizes dictionary items by stripping and lowercasing string values.
    """
    def process_item(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {k: (v.strip().lower() if isinstance(v, str) else v)
                    for k, v in item.items()}
        return item

    def get_key(self, item: Any) -> Hashable:
        # Normalization changes the item, so the key should reflect the normalized state
        normalized_item = self.process_item(item)
        if isinstance(normalized_item, dict):
            # Convert dict to a hashable representation for key generation
            return frozenset(normalized_item.items())
        return normalized_item


