    def __init__(self, strict: bool, verbose: bool, stats: DataProcessorStatistics) -> None:
        self._strict = strict
        self._verbose = verbose
        self._stats = stats

    def process_item(self, item: Any) -> Any:
        if not isinstance(item, dict):
            self._stats.increment_errors()
            if self._strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self._verbose:
                print(f"Skipping invalid item: {item}")
            # Return a special value to indicate invalidity, or raise
            # For this refactor, we'll make the processor responsible for skipping
            return None  # Indicate item should be skipped
        return item

    def get_key(self, item: Any) -> Hashable:
        # Validation does not change the item's identity for keying purposes
        return item


