class DataProcessor:
    """
    Processes a list of data items with configurable steps (validation, normalization, deduplication),
    caching, and statistics tracking.
    """
    def __init__(self,
                 enable_cache: bool = False,
                 enable_dedupe: bool = False,
                 enable_normalize: bool = False,
                 enable_validate: bool = False,
                 strict_validation: bool = False,
                 verbose_validation: bool = False) -> None:

        self._stats = DataProcessorStatistics()
        self._cache_manager: Optional[DataProcessorCache] = DataProcessorCache() if enable_cache else None

        # Build the processing pipeline
        self._processing_pipeline: List[DataProcessingStrategy] = []
        if enable_validate:
            self._processing_pipeline.append(
                ValidationStrategy(strict=strict_validation, verbose=verbose_validation, stats=self._stats)
            )
        if enable_normalize:
            self._processing_pipeline.append(NormalizationStrategy())
        # Deduplication is handled separately as it requires tracking seen items per batch
        self._enable_dedupe = enable_dedupe
        self._dedupe_key_strategy: DataProcessingStrategy = DeduplicationStrategy() if enable_dedupe else NoOpStrategy()


    def process(self, data: List[Any]) -> List[Any]:
        """
        Processes a list of data items according to the configured strategies.

        Args:
            data: A list of data items to be processed.

        Returns:
            A new list containing the processed data items.
        """
        if not isinstance(data, list):
            raise TypeError("Input 'data' must be a list.")

        data_id = id(data) # Use id() for shallow caching of the input list object

        if self._cache_manager:
            cached_result = self._cache_manager.get(data_id)
            if cached_result is not None:
                self._stats.increment_hits()
                return cached_result
            self._stats.increment_misses()
        else:
            self._stats.increment_misses() # Still count a miss if cache is disabled

        result: List[Any] = []
        seen_keys: Set[Hashable] = set()

        for item in data:
            processed_item = item
            skip_item = False

            # Apply pipeline strategies sequentially
            for strategy in self._processing_pipeline:
                processed_item = strategy.process_item(processed_item)
                if processed_item is None and isinstance(strategy, ValidationStrategy):
                    # Validation strategy returned None, indicating item should be skipped
                    skip_item = True
                    break

            if skip_item:
                continue

            # Handle deduplication after all other processing steps,
            # as normalization might change the item's identity.
            if self._enable_dedupe:
                # Use the dedupe key strategy to get the key, which might be
                # different from the item itself if it's a dict.
                dedupe_key = self._dedupe_key_strategy.get_key(processed_item)
                if dedupe_key in seen_keys:
                    continue
                seen_keys.add(dedupe_key)

            result.append(processed_item)

        if self._cache_manager:
            self._cache_manager.set(data_id, result)

        return result

    def get_stats(self) -> Dict[str, int]:
        """
        Returns the current processing statistics.
        """
        return self._stats.get_stats()

    def reset_state(self) -> None:
        """
        Resets the internal cache and statistics.
        """
        self._stats.reset()
        if self._cache_manager:
            self._cache_manager.reset()

