import threading


class StatsTracker:
    """Thread-safe statistics collector."""
    def __init__(self) -> None:
        self._hits: int = 0
        self._misses: int = 0
        self._errors: int = 0
        self._lock = threading.Lock()

    def record_hit(self) -> None:
        with self._lock:
            self._hits += 1

    def record_miss(self) -> None:
        with self._lock:
            self._misses += 1

    def record_error(self) -> None:
        with self._lock:
            self._errors += 1

    def get_stats(self) -> Dict[str, int]:
        with self._lock:
            return {"hits": self._hits, "misses": self._misses, "errors": self._errors}


class Cacher:
    """Thread-safe content cache keyed by object id."""
    def __init__(self) -> None:
        self._cache: Dict[int, List[Any]] = {}
        self._lock = threading.Lock()

    def get(self, key: int) -> Optional[List[Any]]:
        with self._lock:
            return self._cache.get(key)

    def put(self, key: int, value: List[Any]) -> None:
        with self._lock:
            self._cache[key] = value


class Validator:
    """Strategy for input validation and error handling."""
    def __init__(self, strict: bool = False, verbose: bool = False) -> None:
        self.strict = strict
        self.verbose = verbose

    def validate(self, item: Any, stats: StatsTracker) -> Optional[Any]:
        if not isinstance(item, dict):
            stats.record_error()
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return None
        return item


class Deduplicator:
    """Strategy for item deduplication. State is passed in per-call to match original behavior."""
    def process(self, item: Any, seen: Set[str]) -> Optional[Any]:
        key = str(sorted(item.items()) if isinstance(item, dict) else item)
        if key in seen:
            return None
        seen.add(key)
        return item


class Normalizer:
    """Strategy for data normalization."""
    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {k: (v.strip().lower() if isinstance(v, str) else v)
                    for k, v in item.items()}
        return item


@dataclass
class ProcessorConfig:
    """Composition container for processing strategies."""
    validator: Validator = field(default_factory=Validator)
    deduplicator: Deduplicator = field(default_factory=Deduplicator)
    normalizer: Normalizer = field(default_factory=Normalizer)
    cacher: Cacher = field(default_factory=Cacher)
    stats: StatsTracker = field(default_factory=StatsTracker)


class DataProcessor:
    """
    Refactored data processor using composition and strategy pattern.
    Eliminates boolean mode-flags and module-global state.
    Thread-safe and independently testable.
    """
    def __init__(self, config: Optional[ProcessorConfig] = None) -> None:
        self.config = config or ProcessorConfig()
        self._lock = threading.Lock()

    def process(self, data: List[Any]) -> List[Any]:
        with self._lock:
            key = id(data)
            cached = self.config.cacher.get(key)
            if cached is not None:
                self.config.stats.record_hit()
                return cached

            self.config.stats.record_miss()

            result: List[Any] = []
            seen: Set[str] = set()
            for item in data:
                item = self.config.validator.validate(item, self.config.stats)
                if item is None:
                    continue

                item = self.config.deduplicator.process(item, seen)
                if item is None:
                    continue

                item = self.config.normalizer.normalize(item)
                result.append(item)

            self.config.cacher.put(key, result)
            return result

    def get_stats(self) -> Dict[str, int]:
        return self.config.stats.get_stats()

    def reset(self) -> None:
        """Clear cache, statistics, and deduplication state."""
        self.config.cacher = Cacher()
        self.config.stats = StatsTracker()

