from typing import List, Dict, Any, Optional, Set
from abc import ABC, abstractmethod

# Type Aliases
DataItem = Any
Data = List[DataItem]
Stats = Dict[str, int]

class ProcessingContext:
    """
    Holds mutable state shared during a single process() call.
    This ensures that state (like the 'seen' set for deduplication) 
    is isolated per processing run and not shared between calls or instances.
    """
    def __init__(self, stats: Stats, seen: Set[str]):
        self.stats = stats
        self.seen = seen

class Step(ABC):
    """
    Abstract base class for processing steps.
    Implements the Strategy Pattern to allow composable behavior variants.
    """
    @abstractmethod
    def process(self, item: DataItem, context: ProcessingContext) -> Optional[DataItem]:
        """
        Process an item.

        Args:
            item: The item to process.
            context: Shared context containing stats and deduplication state.

        Returns:
            The processed item, or None to skip it (e.g., validation failure or duplicate).
        """
        pass

class ValidationStep(Step):
    """
    Validates that items are dictionaries.
    Supports strict mode (raises error) and verbose mode (prints warnings).
    """
    def __init__(self, strict: bool = False, verbose: bool = False):
        self.strict = strict
        self.verbose = verbose

    def process(self, item: DataItem, context: ProcessingContext) -> Optional[DataItem]:
        if not isinstance(item, dict):
            context.stats["errors"] += 1
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return None
        return item

class DeduplicationStep(Step):
    """
    Removes duplicate items based on their string representation.
    Uses the context's 'seen' set to track items within the current processing run.
    """
    def process(self, item: DataItem, context: ProcessingContext) -> Optional[DataItem]:
        if isinstance(item, dict):
            # Sort items to ensure consistent string representation for keys
            key = str(sorted(item.items()))
        else:
            key = str(item)

        if key in context.seen:
            return None
        context.seen.add(key)
        return item

class NormalizationStep(Step):
    """
    Normalizes string values in dictionaries by stripping whitespace and lowercasing.
    """
    def process(self, item: DataItem, context: ProcessingContext) -> Optional[DataItem]:
        if isinstance(item, dict):
            normalized = {}
            for k, v in item.items():
                if isinstance(v, str):
                    normalized[k] = v.strip().lower()
                else:
                    normalized[k] = v
            return normalized
        return item

class DataProcessor:
    """
    Processes data using a pipeline of composable steps.

    This class eliminates boolean mode-flags by accepting a list of Step instances.
    It is fully self-contained, thread-safe across instances, and independently testable.
    """
    def __init__(
        self,
        steps: Optional[List[Step]] = None,
        cache: Optional[Dict[int, Any]] = None
    ):
        # Default to empty list if no steps provided (no processing behavior)
        self.steps = steps if steps is not None else []
        self.cache = cache
        # Instance-level stats to replace module-global state
        self.stats: Stats = {"hits": 0, "misses": 0, "errors": 0}

    def process(self, data: Data) -> Data:
        # Caching logic
        if self.cache is not None:
            cache_key = id(data)
            if cache_key in self.cache:
                self.stats["hits"] += 1
                return self.cache[cache_key]
            self.stats["misses"] += 1

        result = []
        # Create a fresh context for this processing run
        # This isolates the 'seen' set for deduplication to the current call
        context = ProcessingContext(stats=self.stats, seen=set())

        for item in data:
            current_item = item
            # Apply steps in order
            for step in self.steps:
                current_item = step.process(current_item, context)
                if current_item is None:
                    break # Item was skipped (validation fail or duplicate)

            if current_item is not None:
                result.append(current_item)

        # Store result in cache
        if self.cache is not None:
            self.cache[id(data)] = result

        return result

    def get_stats(self) -> Stats:
        """Returns a copy of the current statistics."""
        return dict(self.stats)

    def reset(self):
        """Resets statistics and clears the cache."""
        self.stats = {"hits": 0, "misses": 0, "errors": 0}
        if self.cache is not None:
            self.cache.clear()

