    def is_valid(self, item: Any) -> bool:
        return isinstance(item, dict)


# --- Deduplicators -----------------------------------------------------
class NoDeduplicator(Deduplicator):
    def reset(self) -> None:
        pass

    def should_include(self, item: Any) -> bool:
        return True


class SetDeduplicator(Deduplicator):
    def __init__(self) -> None:
        self._seen: Set[str] = set()
        self._lock = threading.Lock()

    def reset(self) -> None:
        with self._lock:
            self._seen.clear()

    def should_include(self, item: Any) -> bool:
        key = str(sorted(item.items()) if isinstance(item, dict) else item)
        with self._lock:
            if key in self._seen:
                return False
            self._seen.add(key)
            return True


