class DataProcessor:
    """Self‑contained, thread‑safe processor with strategy‑based behaviours.

    Example usage::

        dp = DataProcessor()
        dp.process([...])

        dp = DataProcessor(
            validator=StrictValidator(),
            deduplicator=SetDeduplicator(),
            normalizer=DictNormalizer(),
            cache=DictCache(),
        )
        dp.process([...])
    """

    def __init__(
        self,
        validator: Optional[Validator] = None,
        deduplicator: Optional[Deduplicator] = None,
        normalizer: Optional[Normalizer] = None,
        cache: Optional[Cache] = None,
    ) -> None:
        self.validator = validator or NoValidator()
        self.deduplicator = deduplicator or NoDeduplicator()
        self.normalizer = normalizer or NoNormalizer()
        self.cache = cache or NoCache()

        # Internal mutable state guarded by a per‑instance lock
        self._lock = threading.Lock()
        self._hits = 0
        self._misses = 0
        self._errors = 0

    # -- Public API -----------------------------------------------------

    def process(self, data: List[Any]) -> List[Any]:
        """Process a batch of items and return the filtered/normalised result."""
        with self._lock:
            return self._process_unlocked(data)

    def get_stats(self) -> Dict[str, int]:
        """Return a snapshot of the current statistics."""
        with self._lock:
            return {
                "hits": self._hits,
                "misses": self._misses,
                "errors": self._errors,
            }

    def reset(self) -> None:
        """Clear all cached data and reset statistics."""
        with self._lock:
            self._hits = 0
            self._misses = 0
            self._errors = 0
            # Cache and deduplicator are reset separately because they
            # manage their own internal locks.
            if isinstance(self.cache, DictCache):
                self.cache = DictCache()  # abandon old store
            self.deduplicator.reset()

    # -- Convenience factory methods (mirror original boolean API) -----

    @classmethod
    def from_flags(
        cls,
        strict: bool = False,
        verbose: bool = False,
        cache: bool = False,
        normalize: bool = False,
        dedupe: bool = False,
        validate: bool = False,
    ) -> "DataProcessor":
        """Create a DataProcessor with behaviour equivalent to the original class.

        This provides backward compatibility for callers that already use
        the boolean flags.  For new code prefer the explicit strategy constructors.
        """
        validator: Validator
        if not validate:
            validator = NoValidator()
        elif strict:
            validator = StrictValidator()
        elif verbose:
            validator = VerboseValidator()
        else:
            validator = SilentValidator()

        deduplicator = SetDeduplicator() if dedupe else NoDeduplicator()
        normalizer = DictNormalizer() if normalize else NoNormalizer()
        cache_obj: Cache
        if cache:
            cache_obj = DictCache()
        else:
            cache_obj = NoCache()

        return cls(
            validator=validator,
            deduplicator=deduplicator,
            normalizer=normalizer,
            cache=cache_obj,
        )

    # -- Internal helpers -----------------------------------------------

    def _process_unlocked(self, data: List[Any]) -> List[Any]:
        """Core processing – caller must hold self._lock."""
        # Cache lookup
        cache_key = id(data)
        cached = self.cache.get(cache_key)
        if cached is not None:
            self._hits += 1
            return cached

        self._misses += 1

        # Prepare deduplicator for a new batch
        self.deduplicator.reset()

        result: List[Any] = []
        for item in data:
            # Validation
            if not self.validator.is_valid(item):
                # StrictValidator raises ValueError, so we never reach here for strict mode.
                # VerboseValidator prints and returns False, SilentValidator returns False.
                self._errors += 1
                continue

            # Deduplication
            if not self.deduplicator.should_include(item):
                continue

            # Normalization
            item = self.normalizer.normalize(item)
            result.append(item)

        # Store in cache
        self.cache.set(cache_key, result)
        return result

