class DataProcessor:
    """
    Processes a list of data items using composable strategies.

    Eliminates boolean mode-flags by accepting strategy instances.
    Eliminates module-global state by maintaining instance-specific state.
    """
    def __init__(
        self,
        cache: Optional[CacheStrategy] = None,
        validator: Optional[Validator] = None,
        normalizer: Optional[Normalizer] = None,
        deduplicator: Optional[Deduplicator] = None
    ):
        self._cache = cache if cache is not None else NoOpCache()
        self._validator = validator if validator is not None else NoOpValidator()
        self._normalizer = normalizer if normalizer is not None else NoOpNormalizer()
        self._deduplicator = deduplicator if deduplicator is not None else NoOpDeduplicator()

        # Instance-specific stats
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}

    def process(self, data: List[Any]) -> List[Any]:
        # Check cache
        if self._cache.has(id(data)):
            self._stats["hits"] += 1
            return self._cache.get(id(data))

        self._stats["misses"] += 1

        result: List[Any] = []
        seen: Set[str] = set()

        for item in data:
            # Validation
            try:
                is_valid = self._validator.validate(item)
            except ValueError:
                self._stats["errors"] += 1
                raise

            if not is_valid:
                self._stats["errors"] += 1
                continue

            # Deduplication
            if self._deduplicator.is_duplicate(item, seen):
                continue
            self._deduplicator.mark_seen(item, seen)

            # Normalization
            item = self._normalizer.normalize(item)

            result.append(item)

        # Cache Store
        self._cache.set(id(data), result)

        return result

    def get_stats(self) -> Dict[str, int]:
        """Returns a copy of the current statistics."""
        return dict(self._stats)

    def reset(self) -> None:
        """Resets statistics and clears the cache."""
        self._stats = {"hits": 0, "misses": 0, "errors": 0}
        self._cache.clear()

