class DataProcessor:
    """
    A thread-safe data processor that applies optional transformations:
    - Validation: ensures items are dictionaries
    - Deduplication: removes duplicate items
    - Normalization: standardizes string values in dictionaries
    - Caching: memoizes results for identical input objects
    """

    def __init__(
        self,
        *,
        validate: bool = False,
        dedupe: bool = False,
        normalize: bool = False,
        strict: bool = False,
        verbose: bool = False,
    ) -> None:
        """
        Initialize the processor with selected behaviors.

        Args:
            validate: If True, skip non-dict items and count errors
            dedupe: If True, remove duplicate items using string representation
            normalize: If True, lowercase and strip string values in dicts
            strict: If True, raise exceptions instead of skipping invalid items
            verbose: If True, print warnings about skipped items
        """
        self._validate = validate
        self._dedupe = dedupe
        self._normalize = normalize
        self._strict = strict
        self._verbose = verbose

        # Thread-safe state
        self._cache: Dict[int, List[Dict[str, Any]]] = {}
        self._stats = {"hits": 0, "misses": 0, "errors": 0}
        self._lock = threading.RLock()

    def process(self, data: Iterable[Any]) -> List[Dict[str, Any]]:
        """
        Process an iterable of items according to configured behaviors.

        Args:
            data: Iterable of items to process

        Returns:
            List of processed dictionary items

        Raises:
            ProcessingError: If strict mode is enabled and validation fails
        """
        if not isinstance(data, Iterable):
            raise TypeError("Input must be an iterable")

        data_id = id(data)

        # Check cache first
        with self._lock:
            if data_id in self._cache:
                self._stats["hits"] += 1
                return self._cache[data_id].copy()
            self._stats["misses"] += 1

        result: List[Dict[str, Any]] = []
        seen: Set[Hashable] = set()

        for item in data:
            try:
                processed_item = self._process_item(item, seen)
                if processed_item is not None:
                    result.append(processed_item)
            except ProcessingError as e:
                if self._strict:
                    raise
                if self._verbose:
                    print(f"Skipping invalid item: {item}")
            except Exception as e:
                with self._lock:
                    self._stats["errors"] += 1
                if self._strict:
                    raise ProcessingError(f"Processing failed: {e}") from e
                if self._verbose:
                    print(f"Error processing item: {item}")

        # Cache result if enabled
        with self._lock:
            self._cache[data_id] = result.copy()

        return result

    def _process_item(
        self, item: Any, seen: Set[Hashable]
    ) -> Optional[Dict[str, Any]]:
        """Process a single item according to configured behaviors."""
        if self._validate:
            if not isinstance(item, dict):
                with self._lock:
                    self._stats["errors"] += 1
                if self._strict:
                    raise ProcessingError(f"Expected dict, got {type(item)}")
                return None

        if self._dedupe:
            key = self._get_dedupe_key(item)
            if key in seen:
                return None
