        if isinstance(item, dict) and self._normalize:
            item = {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }

        return item

    def _get_dedupe_key(self, item: Any) -> Hashable:
        """Generate a hashable key for deduplication."""
        if isinstance(item, dict):
            return tuple(sorted(item.items()))
        return item

    def get_stats(self) -> Dict[str, int]:
        """Return current processing statistics."""
        with self._lock:
            return self._stats.copy()

    def reset(self) -> None:
        """Reset all internal state including cache and statistics."""
        with self._lock:
            self._cache = {}
            self._stats = {"hits": 0, "misses": 0, "errors": 0}

    def __repr__(self) -> str:
        return (
            f"DataProcessor(validate={self._validate}, dedupe={self._dedupe}, "
            f"normalize={self._normalize}, strict={self._strict}, verbose={self._verbose})"
        )

