class ValidationStrategy(ABC):
    """Strategy for validating input items."""

    @abstractmethod
    def validate(self, item: Any) -> bool:
        """Return True if item is valid, False otherwise."""
        pass

    @abstractmethod
    def handle_invalid(self, item: Any, strict: bool) -> None:
        """Handle invalid item according to strictness policy."""
        pass


class DictValidationStrategy(ValidationStrategy):
    """Validate that items are dictionaries."""

    def validate(self, item: Any) -> bool:
        return isinstance(item, dict)

    def handle_invalid(self, item: Any, strict: bool) -> None:
        if strict:
            raise ValueError(f"Expected dict, got {type(item)}")


class NoValidationStrategy(ValidationStrategy):
    """No validation - accept all items."""

    def validate(self, item: Any) -> bool:
        return True

    def handle_invalid(self, item: Any, strict: bool) -> None:
        pass


class DeduplicationStrategy(ABC):
    """Strategy for deduplicating items."""

    @abstractmethod
    def is_duplicate(self, item: Any) -> bool:
        """Return True if item is a duplicate."""
        pass

    @abstractmethod
    def mark_seen(self, item: Any) -> None:
        """Mark item as seen for future duplicate detection."""
        pass

    @abstractmethod
    def reset(self) -> None:
        """Reset the deduplication state."""
        pass


class DictDeduplicationStrategy(DeduplicationStrategy):
    """Deduplicate dictionaries by their sorted string representation."""

    def __init__(self) -> None:
        self.seen_keys: Set[str] = set()

    def is_duplicate(self, item: Any) -> bool:
        if isinstance(item, dict):
            key = str(sorted(item.items()))
        else:
            key = str(item)
        return key in self.seen_keys

    def mark_seen(self, item: Any) -> None:
        if isinstance(item, dict):
            key = str(sorted(item.items()))
        else:
            key = str(item)
        self.seen_keys.add(key)

    def reset(self) -> None:
        self.seen_keys.clear()


class NoDeduplicationStrategy(DeduplicationStrategy):
    """No deduplication - accept all items."""

    def is_duplicate(self, item: Any) -> bool:
        return False

    def mark_seen(self, item: Any) -> None:
        pass

    def reset(self) -> None:
        pass


class NormalizationStrategy(Protocol):
