    def normalize(self, item: Any) -> Any:
        """Return normalized version of item."""
        ...


def dict_normalizer(item: Any) -> Any:
    """Normalize dictionary keys and string values."""
    if not isinstance(item, dict):
        return item

    normalized = {}
    for k, v in item.items():
        if isinstance(v, str):
            normalized[k] = v.strip().lower()
        else:
            normalized[k] = v
    return normalized


def identity_normalizer(item: Any) -> Any:
    """Return item unchanged (no normalization)."""
    return item


