class DataProcessor:
    """
    Process data with configurable validation, deduplication, normalization,
    caching, and logging strategies.
    """

    def __init__(
        self,
        *,
        validation_strategy: Optional[ValidationStrategy] = None,
        deduplication_strategy: Optional[DeduplicationStrategy] = None,
        normalization_strategy: Optional[NormalizationStrategy] = None,
        cache: Optional[Cache] = None,
        logger: Optional[Logger] = None,
        strict: bool = False
    ) -> None:
        """
        Initialize DataProcessor with configurable strategies.

        Args:
            validation_strategy: Strategy for validating input items.
                If None, uses NoValidationStrategy.
            deduplication_strategy: Strategy for deduplicating items.
                If None, uses NoDeduplicationStrategy.
            normalization_strategy: Strategy for normalizing items.
                If None, uses identity_normalizer.
            cache: Cache instance for storing processed results.
                If None, no caching is performed.
            logger: Logger instance for logging messages.
                If None, uses SilentLogger.
            strict: If True, raise exceptions for invalid items when validation
                is enabled. If False, skip invalid items.
        """
        self.validation_strategy = validation_strategy or NoValidationStrategy()
        self.deduplication_strategy = deduplication_strategy or NoDeduplicationStrategy()
        self.normalization_strategy = normalization_strategy or identity_normalizer
        self.cache = cache
        self.logger = logger or SilentLogger()
        self.strict = strict
        self._stats = ProcessingStats()
        self._lock = threading.RLock()

    def process(self, data: List[Any]) -> List[Any]:
        """
        Process the input data according to configured strategies.

        Args:
            data: List of items to process.

        Returns:
            Processed list of items.

        Raises:
            ValueError: If strict mode is enabled and an invalid item is encountered.
        """
        # Check cache first if caching is enabled
        if self.cache is not None:
            with self._lock:
                cache_key = id(data)
                cached_result = self.cache.get(cache_key)
                if cached_result is not None:
                    self._stats.increment_hits()
                    return cached_result.copy()  # Return copy to prevent mutation

                self._stats.increment_misses()

        # Reset deduplication state for new processing run
        self.deduplication_strategy.reset()

        result = []
        for item in data:
            try:
                # Validate item if validation is configured
                if not self.validation_strategy.validate(item):
                    self._stats.increment_errors()
                    self.validation_strategy.handle_invalid(item, self.strict)
                    self.logger.log(f"Skipping invalid item: {item}")
                    continue

                # Check for duplicates if deduplication is configured
                if self.deduplication_strategy.is_duplicate(item):
                    continue

                # Normalize item if normalization is configured
                processed_item = self.normalization_strategy.normalize(item)

                # Mark item as seen for future duplicate detection
                self.deduplication_strategy.mark_seen(item)

                result.append(processed_item)

            except ValueError:
                # Re-raise validation errors from strict mode
                raise
            except Exception as e:
                # Log and skip items that cause unexpected errors
                self._stats.increment_errors()
                self.logger.log(f"Error processing item {item}: {e}")
                if self.strict:
                    raise

        # Cache result if caching is enabled
        if self.cache is not None:
            with self._lock:
                self.cache.set(cache_key, result.copy())  # Store copy to prevent mutation

        return result

    def get_stats(self) -> Dict[str, int]:
        """Return current processing statistics."""
        with self._lock:
            return self._stats.to_dict()

    def reset_stats(self) -> None:
        """Reset processing statistics."""
        with self._lock:
            self._stats.reset()

    def reset_cache(self) -> None:
        """Clear the cache if caching is enabled."""
        if self.cache is not None:
            self.cache.clear()


