from typing import Any, Callable, Dict, Iterable, List, Optional, Protocol, Set, Tuple


class _CacheProtocol(Protocol):
    def get(self, key: int) -> Optional[Any]: ...
    def set(self, key: int, value: Any) -> None: ...
    def clear(self) -> None: ...


class _ValidatorProtocol(Protocol):
    def validate(self, item: Any) -> Optional[Any]: ...


class _DeduperProtocol(Protocol):
    def get_key(self, item: Any) -> Any: ...


class _NormalizerProtocol(Protocol):
    def normalize(self, item: Any) -> Any: ...


class _DictCache:
    """Simple dict‑based cache keyed by the ``id`` of the input object."""
    def __init__(self) -> None:
        self._store: Dict[int, Any] = {}

    def get(self, key: int) -> Optional[Any]:
        return self._store.get(key)

    def set(self, key: int, value: Any) -> None:
        self._store[key] = value

    def clear(self) -> None:
        self._store.clear()


class _NoOpCache:
    """Cache that never stores or returns a value."""
    def get(self, key: int) -> Optional[Any]:
        return None

    def set(self, key: int, value: Any) -> None:  # pragma: no cover - trivial
        return

    def clear(self) -> None:  # pragma: no cover - trivial
        return


class _Validator:
    """Validates that each item is a ``dict``; handles ``strict`` and ``verbose`` flags."""
    def __init__(self, *, strict: bool = False, verbose: bool = False) -> None:
        self.strict = strict
        self.verbose = verbose

    def validate(self, item: Any) -> Optional[Any]:
        if not isinstance(item, dict):
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return None
        return item


class _NoOpValidator:
    """Validator that always passes the item through."""
    def validate(self, item: Any) -> Any:
        return item


class _Deduper:
    """Computes a deduplication key for an item."""
    def get_key(self, item: Any) -> Any:
        if isinstance(item, dict):
            # Sorting ensures {'a':1,'b':2} and {'b':2,'a':1} produce the same key.
            return str(sorted(item.items()))
        return str(item)


class _NoOpDeduper:
    """Deduper that returns a unique key for every item (effectively disabling dedupe)."""
    def get_key(self, item: Any) -> Any:
        # Using ``id`` guarantees uniqueness for the lifetime of the object.
        return id(item)


class _Normalizer:
    """Normalizes string values inside a dict: strips whitespace and lower‑cases."""
    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }
        return item


class _NoOpNormalizer:
    """Normalizer that leaves the item unchanged."""
    def normalize(self, item: Any) -> Any:
        return item


class DataProcessor:
    """
    Processes an iterable of items applying validation, deduplication,
    normalization and optional caching.

    All behaviour is injected via strategy objects; there are no internal
    boolean flags that select behaviour at runtime.
    """

    def __init__(
        self,
        *,
        validator: Optional[_ValidatorProtocol] = None,
        deduper: Optional[_DeduperProtocol] = None,
        normalizer: Optional[_NormalizerProtocol] = None,
        cache: Optional[_CacheProtocol] = None,
    ) -> None:
        self._validator: _ValidatorProtocol = validator or _NoOpValidator()
        self._deduper: _DeduperProtocol = deduper or _NoOpDeduper()
        self._normalizer: _NormalizerProtocol = normalizer or _NoOpNormalizer()
        self._cache: _CacheProtocol = cache or _NoOpCache()
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}

    # -----------------------------------------------------------------
    # Public API
    # -----------------------------------------------------------------
    def process(self, data: Iterable[Any]) -> List[Any]:
        """Process *data* and return a new list with the requested transformations."""
        cache_key = id(data)
        cached = self._cache.get(cache_key)
        if cached is not None:
            self._stats["hits"] += 1
            return list(cached)  # return a shallow copy to protect internal cache

        self._stats["misses"] += 1
        result: List[Any] = []
        seen: Set[Any] = set()

        for item in data:
            # Validation
            validated = self._validator.validate(item)
            if validated is None:
                self._stats["errors"] += 1
                continue
            item = validated

            # Deduplication
            dedup_key = self._deduper.get_key(item)
            if dedup_key in seen:
                continue
            seen.add(dedup_key)

            # Normalization
            item = self._normalizer.normalize(item)

            result.append(item)

        self._cache.set(cache_key, result)
        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a copy of the current statistics."""
        return dict(self._stats)

    def reset(self) -> None:
        """Reset statistics and clear the cache."""
        self._stats = {"hits": 0, "misses": 0, "errors": 0}
        self._cache.clear()


