        # Update statistics
        self.stats.errors += context["errors"]
        if self.cache:
            self.stats.hits = self.cache.hits
            self.stats.misses = self.cache.misses

        # Cache result if caching is enabled
        if self.cache:
            self.cache.set(id(data), result)

        return result

