    def record_hit(self) -> None:
        """Records a cache hit."""
        pass

    @abstractmethod
    def record_miss(self) -> None:
        """Records a cache miss."""
        pass

    @abstractmethod
    def record_error(self) -> None:
        """Records a processing error."""
        pass

    @abstractmethod
    def get_stats(self) -> Dict[str, int]:
        """Returns the current statistics."""
        pass

    @abstractmethod
    def reset(self) -> None:
        """Resets all statistics to zero."""
        pass


# --- Concrete Strategy Implementations ---

class NoValidation(DataValidator):
    """A validator that always considers items valid."""
    def validate(self, item: Any) -> bool:
        return True

    def on_invalid(self, item: Any) -> None:
        pass  # No action needed


class DictTypeValidator(DataValidator):
    """Validates that items are dictionaries."""
    def __init__(self, strict: bool = False, verbose: bool = False, stats: ProcessingStats = None):
        self._strict = strict
        self._verbose = verbose
        self._stats = stats

    def validate(self, item: Any) -> bool:
        return isinstance(item, dict)

    def on_invalid(self, item: Any) -> None:
        if self._stats:
            self._stats.record_error()
        if self._strict:
            raise ValueError(f"Expected dict, got {type(item)}")
        if self._verbose:
            print(f"Skipping invalid item: {item}")


class NoNormalization(DataNormalizer):
    """A normalizer that returns items unchanged."""
    def normalize(self, item: Any) -> Any:
        return item


class DictStringNormalizer(DataNormalizer):
    """Normalizes string values within dictionaries."""
    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {k: (v.strip().lower() if isinstance(v, str) else v)
                    for k, v in item.items()}
        return item


class NoDeduplication(DataDeduplicator):
    """A deduplicator that always returns a unique key."""
    def get_key(self, item: Any) -> Any:
        # Return a unique object ID to ensure no deduplication occurs
        return id(item)


class DictContentDeduplicator(DataDeduplicator):
    """Deduplicates based on dictionary content (sorted items)."""
    def get_key(self, item: Any) -> Any:
        if isinstance(item, dict):
            # Convert dict to a sorted tuple of (key, value) pairs for hashing
            return tuple(sorted(item.items()))
        return item # For non-dict items, use the item itself as key


class InMemoryCache(DataCache):
    """An in-memory cache with thread-safe access."""
    def __init__(self):
        self._cache: Dict[Any, List[Any]] = {}
        self._lock = threading.Lock()

    def get(self, key: Any) -> Union[List[Any], None]:
        with self._lock:
            return self._cache.get(key)

    def put(self, key: Any, value: List[Any]) -> None:
        with self._lock:
            self._cache[key] = value

    def clear(self, key: Any = None) -> None:
        with self._lock:
            if key is not None:
                self._cache.pop(key, None)
            else:
                self._cache.clear()


class NoCache(DataCache):
    """A cache implementation that does nothing."""
    def get(self, key: Any) -> Union[List[Any], None]:
        return None

    def put(self, key: Any, value: List[Any]) -> None:
        pass

    def clear(self, key: Any = None) -> None:
        pass


class ThreadSafeProcessingStats(ProcessingStats):
    """Thread-safe implementation for collecting processing statistics."""
    def __init__(self):
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}
        self._lock = threading.Lock()

    def record_hit(self) -> None:
        with self._lock:
            self._stats["hits"] += 1

    def record_miss(self) -> None:
        with self._lock:
            self._stats["misses"] += 1

    def record_error(self) -> None:
        with self._lock:
            self._stats["errors"] += 1

    def get_stats(self) -> Dict[str, int]:
        with self._lock:
            return dict(self._stats)

    def reset(self) -> None:
        with self._lock:
            self._stats = {"hits": 0, "misses": 0, "errors": 0}


# --- Refactored DataProcessor ---

class DataProcessor:
    """
    Processes a list of data items by applying validation, deduplication,
    normalization, and caching strategies.

    This class uses composition to inject behavior variants, making it
    flexible and independently testable without global state.
    """

    def __init__(
        self,
        validator: DataValidator,
        normalizer: DataNormalizer,
        deduplicator: DataDeduplicator,
        cache: DataCache,
        stats: ProcessingStats
    ):
        """
        Initializes the DataProcessor with specific strategies.

        Args:
            validator: An instance of DataValidator to validate items.
            normalizer: An instance of DataNormalizer to normalize items.
            deduplicator: An instance of DataDeduplicator to generate keys for deduplication.
            cache: An instance of DataCache for caching processed results.
            stats: An instance of ProcessingStats to record processing metrics.
        """
        if not all(isinstance(arg, ABC) for arg in [validator, normalizer, deduplicator, cache, stats]):
             raise TypeError("All strategy arguments must be instances of their respective abstract base classes.")

        self._validator = validator
        self._normalizer = normalizer
        self._deduplicator = deduplicator
        self._cache = cache
        self._stats = stats

    def process(self, data: List[Any]) -> List[Any]:
        """
        Processes a list of data items according to the configured strategies.

        Args:
            data: The list of data items to process.

        Returns:
            A new list containing the processed data items.
        """
        # Use id(data) as a cache key for the input list itself.
        # This assumes the input list's identity uniquely identifies its content for caching.
        # If content-based caching of the input list is needed, a hash of the list's content
        # would be required, which can be complex for mutable types.
        cache_key = id(data)
        cached_result = self._cache.get(cache_key)
        if cached_result is not None:
            self._stats.record_hit()
            return cached_result
        self._stats.record_miss()

        result: List[Any] = []
        seen_keys: Set[Any] = set()

        for item in data:
            if not self._validator.validate(item):
                self._validator.on_invalid(item)
                continue

            dedupe_key = self._deduplicator.get_key(item)
            if dedupe_key in seen_keys:
                continue
            seen_keys.add(dedupe_key)

            processed_item = self._normalizer.normalize(item)
            result.append(processed_item)

        self._cache.put(cache_key, result)
        return result

    def get_stats(self) -> Dict[str, int]:
        """
        Retrieves the current processing statistics.

        Returns:
            A dictionary containing processing statistics (hits, misses, errors).
        """
        return self._stats.get_stats()

    def reset_stats(self) -> None:
        """
        Resets all processing statistics to zero.
        """
        self._stats.reset()

    def clear_cache(self, key: Any = None) -> None:
        """
        Clears the internal cache.

        Args:
            key: If provided, clears only the cache entry for this key.
                 Otherwise, clears the entire cache.
        """
        self._cache.clear(key)


# --- Factory function for convenience ---

def create_data_processor(
    strict: bool = False,
    verbose: bool = False,
    cache_enabled: bool = False,
    normalize_enabled: bool = False,
    dedupe_enabled: bool = False,
    validate_enabled: bool = False
) -> DataProcessor:
    """
    Factory function to create a DataProcessor instance with common configurations.

    Args:
        strict: If True and validation is enabled, raises ValueError on invalid items.
        verbose: If True and validation is enabled, prints messages for skipped invalid items.
        cache_enabled: If True, enables in-memory caching of processed results.
        normalize_enabled: If True, enables normalization of dictionary string values.
        dedupe_enabled: If True, enables deduplication of items based on content.
        validate_enabled: If True, enables validation of items (expects dicts).

    Returns:
        A configured DataProcessor instance.
    """
    stats = ThreadSafeProcessingStats()

    validator: DataValidator
    if validate_enabled:
        validator = DictTypeValidator(strict=strict, verbose=verbose, stats=stats)
    else:
        validator = NoValidation()

    normalizer: DataNormalizer
    if normalize_enabled:
        normalizer = DictStringNormalizer()
    else:
        normalizer = NoNormalization()

    deduplicator: DataDeduplicator
    if dedupe_enabled:
        deduplicator = DictContentDeduplicator()
    else:
        deduplicator = NoDeduplication()

    cache: DataCache
    if cache_enabled:
        cache = InMemoryCache()
    else:
        cache = NoCache()

    return DataProcessor(
        validator=validator,
        normalizer=normalizer,
        deduplicator=deduplicator,
        cache=cache,
        stats=stats
    )

from __future__ import annotations

import threading
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Set, Tuple


@dataclass(frozen=True)
class ProcessingConfig:
    """Immutable configuration defining which processing strategies to apply."""
    validate: bool = False
    strict: bool = False
    verbose: bool = False
    dedupe: bool = False
    normalize: bool = False
    cache: bool = False


class StatsTracker:
    """Thread-safe statistics collector for a single processor instance."""

    def __init__(self) -> None:
        self._hits: int = 0
        self._misses: int = 0
        self._errors: int = 0
        self._lock = threading.Lock()

    def record_hit(self) -> None:
        with self._lock:
            self._hits += 1

    def record_miss(self) -> None:
        with self._lock:
            self._misses += 1

    def record_error(self) -> None:
        with self._lock:
            self._errors += 1

    def get_stats(self) -> Dict[str, int]:
        with self._lock:
            return {"hits": self._hits, "misses": self._misses, "errors": self._errors}

    def reset(self) -> None:
        with self._lock:
            self._hits = 0
            self._misses = 0
            self._errors = 0


class Cacher:
    """Thread-safe cache for processed results."""

    def __init__(self) -> None:
        self._cache: Dict[int, List[Any]] = {}
        self._lock = threading.Lock()

    def get(self, key: int) -> Optional[List[Any]]:
        with self._lock:
            return self._cache.get(key)

    def put(self, key: int, value: List[Any]) -> None:
        with self._lock:
            self._cache[key] = value

    def reset(self) -> None:
        with self._lock:
            self._cache.clear()


class Validator:
    """Handles item validation based on configuration."""

    def __init__(self, config: ProcessingConfig) -> None:
        self._config = config

    def validate(self, item: Any, stats: StatsTracker) -> Tuple[bool, Any]:
        """Returns (is_valid, item). If invalid, handles error logging/raising."""
        if not self._config.validate:
            return True, item

        if not isinstance(item, dict):
            stats.record_error()
            if self._config.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self._config.verbose:
                print(f"Skipping invalid item: {item}")
            return False, item

        return True, item


class Deduplicator:
    """Handles item deduplication based on configuration."""

    def __init__(self, config: ProcessingConfig) -> None:
        self._config = config
        self._seen: Set[str] = set()

    def reset(self) -> None:
        self._seen.clear()

    def should_include(self, item: Any) -> bool:
        if not self._config.dedupe:
            return True

        key = str(sorted(item.items()) if isinstance(item, dict) else item)
        if key in self._seen:
            return False
        self._seen.add(key)
        return True


class Normalizer:
    """Handles item normalization based on configuration."""

    def __init__(self, config: ProcessingConfig) -> None:
        self._config = config

    def normalize(self, item: Any) -> Any:
        if not self._config.normalize or not isinstance(item, dict):
            return item
        return {
            k: (v.strip().lower() if isinstance(v, str) else v)
            for k, v in item.items()
        }


class DataProcessor:
    """
    Processes a sequence of data items through a configurable pipeline.

    Uses composition to combine validation, deduplication, normalization,
    caching, and statistics tracking. All state is instance-scoped and
    thread-safe, making the class independently testable and safe for
    concurrent use across multiple instances.
    """

    def __init__(self, config: Optional[ProcessingConfig] = None) -> None:
        self._config = config or ProcessingConfig()
        self._stats = StatsTracker()
        self._cacher = Cacher() if self._config.cache else None
        self._validator = Validator(self._config)
        self._deduplicator = Deduplicator(self._config)
        self._normalizer = Normalizer(self._config)

    def process(self, data: List[Any]) -> List[Any]:
        """
        Process the input data through the configured pipeline.

        Args:
            data: Iterable of items to process.

        Returns:
            Filtered, deduplicated, and normalized list of items.
        """
        if self._cacher:
            cache_key = id(data)
            cached_result = self._cacher.get(cache_key)
            if cached_result is not None:
                self._stats.record_hit()
                return cached_result
            self._stats.record_miss()

        self._deduplicator.reset()
        result: List[Any] = []

        for item in data:
            is_valid, validated_item = self._validator.validate(item, self._stats)
            if not is_valid:
                continue

            if not self._deduplicator.should_include(validated_item):
                continue

            normalized_item = self._normalizer.normalize(validated_item)
            result.append(normalized_item)

        if self._cacher:
            self._cacher.put(id(data), result)

        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a snapshot of current processing statistics."""
        return self._stats.get_stats()

    def reset(self) -> None:
        """Clear all internal state (cache, stats, deduplication set)."""
        self._stats.reset()
        if self._cacher:
            self._cacher.reset()
        self._deduplicator.reset()

