@runtime_checkable
class ValidatorProtocol(Protocol):
    def validate(self, item: Any, stats: Dict[str, int]) -> Optional[Any]:
        """Return the item if it passes validation, otherwise None.
        Updates *stats* in‑place (e.g. error count)."""
        ...


@runtime_checkable
class DeduperProtocol(Protocol):
    def dedupe(self, items: Iterable[Any]) -> Iterable[Any]:
        """Yield items from *items* with duplicates removed."""
        ...


@runtime_checkable
class NormalizerProtocol(Protocol):
    def normalize(self, item: Any) -> Any:
        """Return a normalized version of *item*."""
        ...


@runtime_checkable
class CacherProtocol(Protocol):
    def get(self, key: int) -> Optional[Any]:
        """Return cached value for *key* or None if absent."""
        ...

    def set(self, key: int, value: Any) -> None:
        """Store *value* under *key* in the cache."""
        ...

    def reset(self) -> None:
        """Clear the cache."""
        ...


# ----------------------------------------------------------------------
# Default strategy implementations
# ----------------------------------------------------------------------
class SimpleValidator:
    """Default validation strategy.

    Args:
        strict: If True, raise ValueError on invalid items.
        verbose: If True, print a message when skipping invalid items.
    """

    def __init__(self, *, strict: bool = False, verbose: bool = False) -> None:
        self.strict = strict
        self.verbose = verbose

    def validate(self, item: Any, stats: Dict[str, int]) -> Optional[Any]:
        if not isinstance(item, dict):
            stats["errors"] += 1
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return None
        return item


class SimpleDeduper:
    """Default deduplication strategy.

    The key is the string representation of ``sorted(item.items())`` for dicts,
    otherwise the item itself.
    """

    def dedupe(self, items: Iterable[Any]) -> Iterable[Any]:
        seen: set = set()
        for item in items:
            key = str(sorted(item.items()) if isinstance(item, dict) else item)
            if key in seen:
                continue
            seen.add(key)
            yield item


class SimpleNormalizer:
    """Default normalization strategy.

    For dict items, string values are stripped and lower‑cased.
    """

    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }
        return item


class SimpleCacher:
    """Simple per‑instance cache."""

    def __init__(self) -> None:
        self._cache: Dict[int, Any] = {}

    def get(self, key: int) -> Optional[Any]:
        return self._cache.get(key)

    def set(self, key: int, value: Any) -> None:
        self._cache[key] = value

    def reset(self) -> None:
        self._cache.clear()


# ----------------------------------------------------------------------
# Refactored DataProcessor
# ----------------------------------------------------------------------
class DataProcessor:
    """Process an iterable of items using pluggable strategies.

    All state (caching, statistics) is owned by the instance, making the
    class safe for concurrent use across different instances.
    """

    def __init__(
        self,
        *,
        validator: Optional[ValidatorProtocol] = None,
        deduper: Optional[DeduperProtocol] = None,
        normalizer: Optional[NormalizerProtocol] = None,
        cacher: Optional[CacherProtocol] = None,
    ) -> None:
        self.validator = validator or SimpleValidator()
        self.deduper = deduper or SimpleDeduper()
        self.normalizer = normalizer or SimpleNormalizer()
        self.cacher = cacher

        # per‑instance statistics
        self.stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def process(self, data: Iterable[Any]) -> List[Any]:
        """Process *data* according to the configured strategies.

        Returns a list of processed items.
        """
        # ----- caching (lookup) -----
        if self.cacher is not None:
            cache_key = id(data)
            cached = self.cacher.get(cache_key)
            if cached is not None:
                self.stats["hits"] += 1
                # Return the cached list directly (same object as before)
                return list(cached)
            self.stats["misses"] += 1
        # If caching is disabled we do not touch hits/misses.

        # ----- validation -----
        if self.validator is not None:
            def validated_items() -> Iterable[Any]:
                for item in data:
                    validated = self.validator.validate(item, self.stats)
                    if validated is not None:
                        yield validated
            data_iter = validated_items()
        else:
            data_iter = data

        # ----- deduplication -----
        if self.deduper is not None:
            data_iter = self.deduper.dedupe(data_iter)

        # ----- normalization -----
        if self.normalizer is not None:
            data_iter = (self.normalizer.normalize(item) for item in data_iter)

        # Materialise the result
        result: List[Any] = list(data_iter)

        # ----- caching (store) -----
        if self.cacher is not None:
            self.cacher.set(id(data), result)

        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a shallow copy of the current statistics."""
        return dict(self.stats)

    def reset(self) -> None:
        """Reset statistics and clear the instance‑level cache (if any)."""
        self.stats = {"hits": 0, "misses": 0, "errors": 0}
        if self.cacher is not None:
            self.cacher.reset()

