class DataProcessor:
    """Process an iterable of items with pluggable validation, dedupe,
    normalization and caching strategies.

    All state lives inside the instance, making it safe for concurrent use
    across different instances (shared mutable state is avoided).
    """

    def __init__(
        self,
        validator: Validator = ValidateStrategy(),
        deduper: Deduper = DedupStrategy(),
        normalizer: Normalizer = NormalizeStrategy(),
        cacher: Cacher = CacheStrategy(),
    ) -> None:
        self.validator = validator
        self.deduper = deduper
        self.normalizer = normalizer
        self.cacher = cacher
        self.stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}

    def process(self, data: Iterable[Any]) -> List[Any]:
        """Process *data* according to the configured strategies.

        Returns a new list containing the processed items.
        """
        cache_key = id(data)
        cached = self.cacher.get(cache_key)
        if cached is not None:
            self.stats["hits"] += 1
            return cached  # type: ignore[return-value]

        self.stats["misses"] += 1

        result: List[Any] = []
        seen: Set[Any] = set()

        for item in data:
