            item = validated

            # Deduplication
            deduped = self.deduper(item, seen)
            if deduped is None:
                continue
            item = deduped

            # Normalization
            item = self.normalizer(item)

            result.append(item)

        self.cacher.set(cache_key, result)
        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a shallow copy of the statistics."""
        return dict(self.stats)

    def reset(self) -> None:
        """Reset statistics and any internal caches."""
        self.stats = {"hits": 0, "misses": 0, "errors": 0}
        if hasattr(self.cacher, "reset"):
            self.cacher.reset()

