        self.validator: ValidationStrategy = validator or _NoOpValidator()
        self.normalizer: NormalizationStrategy = normalizer or _OpNormalizer()
        self.deduper: DeduplicationStrategy = deduper or _NoOpDeduplicator()
        self._cache_enabled: bool = cache
        self._cache: Dict[int, List[Any]] = {}
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}
        self._lock = threading.Lock()

    # -----------------------------------------------------------------
    # Public API
    # -----------------------------------------------------------------
    def process(self, data: Iterable[Any]) -> List[Any]:
        data_id = id(data)

        # Cache lookup (only when caching is enabled)
        if self._cache_enabled:
            with self._lock:
                if data_id in self._cache:
                    self._stats["hits"] += 1
                    return self._cache[data_id]
                self._stats["misses"] += 1
        else:
            # When caching is disabled we do not count hits/misses.
            pass

        result: List[Any] = []
        seen: set = set()

        for item in data:
            # ----- Validation -----
            if not self.validator.validate(item):
                self._stats["errors"] += 1
                if self.validator.strict:
                    raise ValueError(f"Expected dict, got {type(item)}")
                if self.validator.verbose:
                    print(f"Skipping invalid item: {item}")
                continue

            # ----- Normalization -----
            if isinstance(item, dict) and not isinstance(self.normalizer, _NoOpNormalizer):
                item = self.normalizer.normalize(item)

            # ----- Deduplication -----
            if not isinstance(self.deduper, _NoOpDeduplicator):
                key = self.deduper.key(item)
                if key in seen:
                    continue
                seen.add(key)

            result.append(item)

        # Store in cache if enabled
        if self._cache_enabled:
            with self._lock:
                self._cache[data_id] = result

        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a copy of the current statistics."""
        with self._lock:
            return dict(self._stats)

    def reset(self) -> None:
        """Reset cache and statistics to their initial state."""
        with self._lock:
            self._cache.clear()
            self._stats = {"hits": 0, "misses": 0, "errors": 0}


