from dataclasses import dataclass
from typing import Optional
import logging

@dataclass
class ProcessorConfig:
    enabled: bool = True
    debug_mode: bool = False
    max_retries: int = 3

class OrderProcessor:
    def __init__(self, config: Optional[ProcessorConfig] = None,
                 logger: Optional[logging.Logger] = None):
        self.config = config or ProcessorConfig()
        self.logger = logger or logging.getLogger(__name__)

    def process(self, order_id: str) -> str:
        if not self.config.enabled:
            raise RuntimeError("Processor disabled")

        if self.config.debug_mode:
            self.logger.debug(f"Processing order: {order_id}")

        # Process the order
        result = f"order_{order_id}_processed"

        self.logger.info(f"Order processed: {order_id}")
        return result

    def process_with_retry(self, order_id: str) -> str:
        """Process with retry logic"""
        last_error = None

        for attempt in range(self.config.max_retries):
            try:
                return self.process(order_id)
            except Exception as e:
                last_error = e
                self.logger.warning(
                    f"Attempt {attempt + 1} failed: {e}"
                )

        raise RuntimeError(
            f"Failed after {self.config.max_retries} attempts"
        ) from last_error

