        verbose: bool = False,
        cache: bool = False,
        normalize: bool = False,
        dedupe: bool = False,
        validate: bool = False,
    ) -> None:
        # Instance-local state
        self._lock = threading.Lock()
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}
        self._cache: Optional[Dict[int, List]] = {} if cache else None

        # Validation strategy
        self._validator: Callable[[Any], bool] = (
            (lambda item: isinstance(item, dict)) if validate else (lambda _: True)
        )
        # Error handling strategy (strict vs. non‑strict)
