            self._normalize_item if normalize else (lambda item: item)
        )

        # Deduplication strategy
        self._dedupe_enabled = dedupe
        if dedupe:
            self._dedup_key_func: Callable[[Any], str] = self._dedup_key
        else:
            self._dedup_key_func = None  # type: ignore[assignment]

    @staticmethod
    def _strict_error_handler(item: Any) -> None:
        raise ValueError(f"Expected dict, got {type(item)}")

    def _non_strict_error_handler(self, item: Any) -> None:
        if self._verbose:
            print(f"Skipping invalid item: {item}")

