class DataProcessor:
    """
    Configurable data processor with strategy-based behavior.

    This class is fully self-contained, thread-safe, and independently testable.
    """

    def __init__(
        self,
        *,
        validation_strategy: Optional[ValidationStrategy] = None,
        deduplication_strategy: Optional[DeduplicationStrategy] = None,
        normalization_strategy: Optional[NormalizationStrategy] = None,
        error_handling_strategy: Optional[ErrorHandlingStrategy] = None,
        logging_strategy: Optional[LoggingStrategy] = None,
        cache_enabled: bool = False
    ) -> None:
        """
        Initialize the data processor with optional strategies.

        Args:
            validation_strategy: Strategy for validating items
            deduplication_strategy: Strategy for deduplicating items
            normalization_strategy: Strategy for normalizing items
            error_handling_strategy: Strategy for handling errors
            logging_strategy: Strategy for logging messages
            cache_enabled: Whether to enable caching
        """
        self.validation_strategy = validation_strategy or NoOpValidationStrategy()
        self.deduplication_strategy = deduplication_strategy or NoDeduplicationStrategy()
        self.normalization_strategy = normalization_strategy or NoNormalizationStrategy()
        self.error_handling_strategy = error_handling_strategy or LenientErrorHandlingStrategy()
        self.logging_strategy = logging_strategy or SilentLoggingStrategy()

        self.cache_enabled = cache_enabled
        self._cache: Optional[Cache[str, list[Any]]] = Cache() if cache_enabled else None
        self._stats = ProcessingStats()

    def _generate_cache_key(self, data: Iterable[Any]) -> str:
        """Generate a deterministic cache key for the data"""
        # Convert data to a stable representation for caching
        data_list = list(data)
        data_str = json.dumps(data_list, sort_keys=True, default=str)
        return hashlib.sha256(data_str.encode()).hexdigest()

    def process(self, data: Iterable[Any]) -> list[Any]:
        """
        Process the input data according to configured strategies.

        Args:
            data: Iterable of items to process

        Returns:
            Processed list of items
        """
        # Check cache if enabled
        if self.cache_enabled and self._cache:
            cache_key = self._generate_cache_key(data)
            cached_result = self._cache.get(cache_key)
            if cached_result is not None:
                self._stats.increment_hits()
                return cached_result

        self._stats.increment_misses()

        result: list[Any] = []
        seen: set[str] = set()

        for item in data:
            # Validate item
            is_valid, error_msg = self.validation_strategy.validate(item)
            if not is_valid:
                self._stats.increment_errors()
                try:
                    should_continue = self.error_handling_strategy.handle_error(
                        error_msg, self.logging_strategy
                    )
                    if not should_continue:
                        # Error was raised in handle_error
                        continue
                except ValueError:
                    # Error was raised, propagate it
                    raise

                # Log skip if error was handled leniently
                self.logging_strategy.log_skip(item, error_msg)
                continue

            # Deduplicate if configured
            if self.deduplication_strategy.should_skip(item, seen):
                continue

            # Normalize if configured
            processed_item = self.normalization_strategy.normalize(item)
            result.append(processed_item)

        # Cache result if enabled
        if self.cache_enabled and self._cache:
            cache_key = self._generate_cache_key(data)
            self._cache.set(cache_key, result)

        return result

    def get_stats(self) -> dict[str, int]:
        """Get current processing statistics"""
        return self._stats.to_dict()

    def reset_stats(self) -> None:
        """Reset processing statistics"""
        self._stats.reset()

    def clear_cache(self) -> None:
        """Clear the cache if enabled"""
        if self._cache:
            self._cache.clear()


