    def is_duplicate(self, item: Any) -> bool:
        key = self._make_key(item)
        if key in self._seen:
            return True
        self._seen.add(key)
        return False

    def reset(self) -> None:
        self._seen.clear()

    @staticmethod
    def _make_key(item: Any) -> str:
        if isinstance(item, dict):
            return str(sorted(item.items()))
        return str(item)


