    ) -> None:
        """
        Initialize the DataProcessor with optional strategies.

        Args:
            validator: Strategy for validating items. Defaults to DictValidator.
            normalizer: Strategy for normalizing items. Defaults to DefaultNormalizer.
            deduplicator: Strategy for deduplication. Defaults to SetDeduplicator.
            strict: If True, raise ValueError on validation failure.
            verbose: If True, print warnings for invalid items.
            cache: If True, cache results by data identity.
        """
        self._validator: Validator = validator if validator is not None else DictValidator()
        self._normalizer: Normalizer = normalizer if normalizer is not None else DefaultNormalizer()
        self._deduplicator: Deduplicator = deduplicator if deduplicator is not None else SetDeduplicator()
        self._strict = strict
        self._verbose = verbose
        self._cache_enabled = cache

        # Instance-level state (thread-safe)
        self._cache: Dict[int, Any] = {}
        self._stats = ProcessingStats()
        self._lock = RLock()

    def process(self, data: List[Any]) -> List[Any]:
        """
        Process a list of items through the configured pipeline.

        Args:
            data: List of items to process.

        Returns:
            Processed list of items.
        """
        with self._lock:
            data_id = id(data)
            if self._cache_enabled and data_id in self._cache:
                self._stats = ProcessingStats(
                    hits=self._stats.hits + 1,
                    misses=self._stats.misses,
                    errors=self._stats.errors,
                )
                return self._cache[data_id]

            self._stats = ProcessingStats(
                hits=self._stats.hits,
                misses=self._stats.misses + 1,
                errors=self._stats.errors,
            )

            result: List[Any] = []
            self._deduplicator.reset()

            for item in data:
                if not self._validator.validate(item):
                    self._stats = ProcessingStats(
                        hits=self._stats.hits,
                        misses=self._stats.misses,
                        errors=self._stats.errors + 1,
                    )
                    if self._strict:
                        raise ValueError(f"Expected dict, got {type(item).__name__}")
                    if self._verbose:
                        print(f"Skipping invalid item: {item}")
                    continue

                if self._deduplicator.is_duplicate(item):
                    continue

                normalized = self._normalizer.normalize(item)
                result.append(normalized)

            if self._cache_enabled:
                self._cache[data_id] = result

            return result

    def get_stats(self) -> ProcessingStats:
        """
        Return a snapshot of current processing statistics.

        Returns:
            ProcessingStats instance with current counts.
        """
        with self._lock:
            return ProcessingStats(
                hits=self._stats.hits,
                misses=self._stats.misses,
                errors=self._stats.errors,
            )

    def reset(self) -> None:
        """
        Clear cached results and reset statistics.

        Thread-safe: can be called concurrently with process().
        """
        with self._lock:
            self._cache.clear()
            self._stats = ProcessingStats()
            self._deduplicator.reset()

