        """Validates if an item is a dictionary."""
        if not isinstance(item, dict):
            self._processing_errors += 1
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return False
        return True

    def _normalize_item(self, item: Dict[Any, Any]) -> Dict[Any, Any]:
        """Normalizes string values within a dictionary item."""
        return {
            k: (v.strip().lower() if isinstance(v, str) else v)
            for k, v in item.items()
        }

    def _get_dedupe_key(self, item: Any) -> Any:
        """Generates a comparable key for deduplication."""
        if isinstance(item, dict):
