            def dedupe_step(item: Any, seen_keys: Set[str], stats: Dict[str, int]) -> Optional[Any]:
                if _deduplicate_item(item, seen_keys) is None:
                    return None # Item was a duplicate, so skip
                return item
            self._processing_steps.append(dedupe_step)

        if enable_normalize:
            # Normalization step: always returns an item (possibly modified)
            def normalize_step(item: Any, seen_keys: Set[str], stats: Dict[str, int]) -> Any:
                return _normalize_item(item)
            self._processing_steps.append(normalize_step)

