from dataclasses import dataclass, field
from typing import Any, Callable, Protocol
import threading


# --- Protocols for behavior components ---

class Cache(Protocol):
    """Protocol for caching components."""
    def get(self, key: int) -> Any | None: ...
    def set(self, key: int, value: Any) -> None: ...


class Statistics(Protocol):
    """Protocol for statistics components."""
    def record_hit(self) -> None: ...
    def record_miss(self) -> None: ...
    def record_error(self) -> None: ...
    def get_stats(self) -> dict[str, int]: ...
    def reset(self) -> None: ...



# --- Concrete implementations ---

@dataclass
class InMemoryCache:
    """Thread-safe in-memory cache."""
    _store: dict[int, Any] = field(default_factory=dict)
    _lock: threading.Lock = field(default_factory=threading.Lock)

    def get(self, key: int) -> Any | None:
        with self._lock:
            return self._store.get(key)

    def set(self, key: int, value: Any) -> None:
        with self._lock:
            self._store[key] = value


@dataclass
class InMemoryStatistics:
    """Thread-safe in-memory statistics tracker."""
    _stats: dict[str, int] = field(default_factory=lambda: {"hits": 0, "misses": 0, "errors": 0})
    _lock: threading.Lock = field(default_factory=threading.Lock)

    def record_hit(self) -> None:
        with self._lock:
            self._stats["hits"] += 1

    def record_miss(self) -> None:
        with self._lock:
            self._stats["misses"] += 1

    def record_error(self) -> None:
        with self._lock:
            self._stats["errors"] += 1

    def get_stats(self) -> dict[str, int]:
        with self._lock:
            return dict(self._stats)

    def reset(self) -> None:
        with self._lock:
            self._stats = {"hits": 0, "misses": 0, "errors": 0}


# --- Configuration ---

@dataclass(frozen=True)
class ProcessorConfig:
    """Configuration for DataProcessor behavior.

    Use True/False for boolean options. Each instance of DataProcessor
    maintains its own cache and statistics when using default components.
    """
    strict: bool = False
    verbose: bool = False
    cache: bool = False
    normalize: bool = False
    dedupe: bool = False
    validate: bool = False


# --- Behavior handlers ---

class ValidationHandler:
    """Handles item validation with configurable strictness and verbosity."""

    def __init__(self, config: ProcessorConfig) -> None:
        self._strict = config.strict
        self._verbose = config.verbose

    def validate(self, item: Any, stats: Statistics) -> bool:
        """Validate an item. Returns True if valid, False otherwise."""
        if isinstance(item, dict):
            return True

        stats.record_error()

        if self._strict:
            raise ValueError(f"Expected dict, got {type(item)}")

        if self._verbose:
            print(f"Skipping invalid item: {item}")

        return False


class NormalizationHandler:
    """Handles string normalization in dict values."""

    def normalize(self, item: dict[str, Any]) -> dict[str, Any]:
        """Normalize string values in a dictionary."""
        return {
            k: (v.strip().lower() if isinstance(v, str) else v)
            for k, v in item.items()
        }


class DeduplicationHandler:
    """Handles item deduplication."""

    def __init__(self) -> None:
        self._seen: set[str] = set()

    def reset(self) -> None:
        """Reset the deduplication state for a new processing run."""
        self._seen.clear()

    def is_duplicate(self, item: Any) -> bool:
        """Check if item is a duplicate. Adds to seen if not."""
        key = self._make_key(item)
        if key in self._seen:
            return True
        self._seen.add(key)
        return False

    @staticmethod
    def _make_key(item: Any) -> str:
        if isinstance(item, dict):
            return str(sorted(item.items()))
        return str(item)


# --- Main processor ---

class DataProcessor:
    """Processes data with configurable behaviors.

    Each instance maintains its own cache and statistics by default,
    making it safe for concurrent use and easy to test.

    Args:
        config: ProcessorConfig controlling behavior flags.
        cache: Optional custom cache component. If None and config.cache
               is True, creates an in-memory cache.
        statistics: Optional custom statistics component. If None,
                    creates an in-memory statistics tracker.

    Example:
        >>> processor = DataProcessor(ProcessorConfig(validate=True, dedupe=True))
        >>> result = processor.process([{"a": "1"}, {"a": "1"}])
        >>> result
        [{'a': '1'}]
    """

    def __init__(
        self,
        config: ProcessorConfig | None = None,
        cache: Cache | None = None,
        statistics: Statistics | None = None,
    ) -> None:
        self._config = config or ProcessorConfig()
        self._cache = cache if cache is not None else InMemoryCache()
        self._statistics = statistics if statistics is not None else InMemoryStatistics()

        self._validation_handler = ValidationHandler(self._config)
        self._normalization_handler = NormalizationHandler()
        self._deduplication_handler = DeduplicationHandler()

    @property
    def config(self) -> ProcessorConfig:
        """Read-only access to processor configuration."""
        return self._config

    def process(self, data: list[Any]) -> list[Any]:
        """Process a list of items according to configuration.

        Applies validation, deduplication, normalization, and caching
        based on the processor configuration.

        Args:
            data: List of items to process.

        Returns:
            Processed list of items.
        """
        data_id = id(data)

        # Check cache first
        if self._config.cache:
            cached = self._cache.get(data_id)
            if cached is not None:
                self._statistics.record_hit()
                return cached
            self._statistics.record_miss()

        # Reset per-run state
        self._deduplication_handler.reset()

        result: list[Any] = []

        for item in data:
            # Validation
            if self._config.validate:
                if not self._validation_handler.validate(item, self._statistics):
                    continue

            # Deduplication
            if self._config.dedupe:
                if self._deduplication_handler.is_duplicate(item):
                    continue

            # Normalization (only for dicts)
            if self._config.normalize and isinstance(item, dict):
                item = self._normalization_handler.normalize(item)

            result.append(item)

        # Cache result
        if self._config.cache:
            self._cache.set(data_id, result)

        return result

    def get_stats(self) -> dict[str, int]:
        """Return current statistics.

        Returns:
            Dictionary with 'hits', 'misses', and 'errors' counts.
        """
        return self._statistics.get_stats()

    def reset(self) -> None:
        """Reset cache and statistics for this processor instance."""
        if isinstance(self._cache, InMemoryCache):
            self._cache._store.clear()  # type: ignore[attr-defined]
        self._statistics.reset()

