class DataProcessor:
    def __init__(self, config: ProcessorConfig):
        self.config = config
        self._cache: Dict[int, List[Any]] = {}
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}
        self._seen: Set[str] = set()
        self._pipeline = self._build_pipeline()

    def _build_pipeline(self) -> Pipeline:
        steps: List[Callable[[Any], Optional[Any]]] = []
        if self.config.validate:
            steps.append(self._validate_step)
        if self.config.dedupe:
            steps.append(self._dedupe_step)
        if self.config.normalize:
            steps.append(self._normalize_step)
        return Pipeline(steps)

    def _validate_step(self, item: Any) -> Optional[Any]:
        if not isinstance(item, dict):
            self._stats["errors"] += 1
            if self.config.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
