class OverrideConfigMalformed(ConfigError):
    """Raised when the override configuration file is malformed."""


def load_and_merge_configs(
    primary_path: Union[str, Path],
    override_path: Optional[Union[str, Path]] = None,
) -> dict:
    """
    Load and merge two JSON configuration files.

    The primary configuration is required; if it is missing, an empty dict is
    returned.  If the primary file exists but is malformed (invalid JSON or
    not a dict), a `PrimaryConfigMalformed` exception is raised.  The override
    file is optional; if provided and malformed, an `OverrideConfigMalformed`
    exception is raised.  Other I/O errors (e.g. permission denied) are
    re-raised as-is.

    Args:
        primary_path: Path to the primary configuration file.
        override_path: Optional path to an override configuration file.

    Returns:
        A merged dictionary (primary updated with override keys).

    Raises:
        PrimaryConfigMalformed: If the primary file is not valid JSON or not a dict.
        OverrideConfigMalformed: If the override file is not valid JSON or not a dict.
        PermissionError: If a file cannot be read due to permissions.
        ConfigError: For other unexpected errors during file loading.
    """
    # --- Load primary configuration ---
    try:
        with open(primary_path) as f:
            primary = json.load(f)
    except FileNotFoundError:
        logging.warning(f"Primary config not found: {primary_path}")
        return {}
    except json.JSONDecodeError as e:
        raise PrimaryConfigMalformed(
            f"Primary config JSON parse error: {e}"
        ) from e
    except PermissionError:
        raise
    except Exception as e:
        raise ConfigError(
            f"Unexpected error loading primary config: {e}"
        ) from e

    if not isinstance(primary, dict):
        raise PrimaryConfigMalformed("Primary config is not a dict")

    result = dict(primary)

    # --- Load override configuration (optional) ---
    if override_path:
        try:
            with open(override_path) as f:
                override = json.load(f)
        except FileNotFoundError:
            logging.warning(f"Override config not found: {override_path}")
        except json.JSONDecodeError as e:
            raise OverrideConfigMalformed(
                f"Override config JSON parse error: {e}"
            ) from e
        except PermissionError:
            raise
        except Exception as e:
            raise ConfigError(
                f"Unexpected error loading override config: {e}"
            ) from e
        else:
            if not isinstance(override, dict):
                raise OverrideConfigMalformed("Override config is not a dict")
            result.update(override)

    return result

