        self._pipeline: list[ProcessingStep] = []

        if config.validate:
            self._pipeline.append(DictValidator(
                strict=config.strict_validation,
                logger=config.logger
            ))

        if config.deduplicate:
            self._pipeline.append(Deduplicator())

        # Note: Normalizer runs after validation and deduplication
        # but we'll handle it separately since it only applies to dicts

    def process(self, data: Iterable[Any]) -> list[Any]:
        """
        Process a sequence of data items.

        Args:
            data: Iterable of data items to process

        Returns:
            List of processed items

        Raises:
            ValueError: If strict validation is enabled and a non-dict item is found
        """
        with self._lock:
            # Check cache if enabled
            if self.config.cache_enabled:
                data_id = id(data)
                if data_id in self._cache:
                    self._stats.increment_hits()
                    # Return a copy to prevent mutation of cached data
                    return self._cache[data_id].copy()

            self._stats.increment_misses()

            result: list[Any] = []

            for item in data:
                processed_item = self._process_single_item(item)
                if processed_item is not None:
                    result.append(processed_item)

            # Store in cache if enabled
            if self.config.cache_enabled:
                self._cache[id(data)] = result.copy()

            return result

    def _process_single_item(self, item: Any) -> Optional[Any]:
        """Process a single item through the pipeline."""
        current_item = item

        # Run through processing pipeline
        for step in self._pipeline:
            if current_item is None:
                break

            try:
                current_item = step.process_item(current_item)
            except ValueError as e:
                # Only DictValidator raises ValueError
                self._stats.increment_errors()
                raise

        # Apply normalization if enabled (only for dicts)
        if current_item is not None and self.config.normalize and isinstance(current_item, dict):
            normalizer = DictNormalizer()
            current_item = normalizer.process_item(current_item)

        return current_item

    def get_stats(self) -> dict[str, int]:
        """Get current processing statistics."""
        with self._lock:
            return self._stats.as_dict()

    def reset_stats(self) -> None:
        """Reset processing statistics."""
        with self._lock:
            self._stats = ProcessingStats()

    def reset_cache(self) -> None:
        """Clear the cache."""
        with self._lock:
            self._cache.clear()

    def reset(self) -> None:
        """Reset both cache and statistics."""
        with self._lock:
            self.reset_cache()
            self.reset_stats()
            # Reset deduplicator if present
            for step in self._pipeline:
                if isinstance(step, Deduplicator):
                    step.reset()


# Convenience constructors for common configurations
def create_default_processor() -> DataProcessor:
    """Create a processor with default settings (no processing)."""
    return DataProcessor(ProcessingConfig())


def create_validating_processor(strict: bool = False, logger: Optional[Callable[[str], None]] = None) -> DataProcessor:
