from typing import Any, Iterable, List, Optional, Protocol, runtime_checkable


# ----- Strategy protocols -----
@runtime_checkable
class ValidationStrategy(Protocol):
    strict: bool
    verbose: bool

    def is_valid(self, item: Any) -> bool: ...


@runtime_checkable
class DedupeStrategy(Protocol):
    def should_keep(self, item: Any, seen: set) -> bool: ...


@runtime_checkable
class NormalizeStrategy(Protocol):
    def normalize(self, item: Any) -> Any: ...


@runtime_checkable
class CacheStrategy(Protocol):
    def get(self, key: int) -> Optional[Any]: ...
    def set(self, key: int, value: Any) -> None: ...
    def clear(self) -> None: ...


# ----- Concrete strategy implementations -----
class Validation:
    """Validates that items are dicts; handles strict/verbose flags."""
    def __init__(self, strict: bool = False, verbose: bool = False) -> None:
        self.strict = strict
        self.verbose = verbose

    def is_valid(self, item: Any) -> bool:
        return isinstance(item, dict)


class Dedupe:
    """Deduplicates items based on a string representation of their content."""
    def should_keep(self, item: Any, seen: set) -> bool:
        key = str(sorted(item.items()) if isinstance(item, dict) else item)
        if key in seen:
            return False
        seen.add(key)
        return True


class Normalize:
    """Normalizes dict items: strips and lower‑cases string values."""
    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }
        return item


class Cache:
    """Simple key‑value cache using id(data) as the key."""
    def __init__(self) -> None:
        self._storage: dict[int, Any] = {}

    def get(self, key: int) -> Optional[Any]:
        return self._storage.get(key)

    def set(self, key: int, value: Any) -> None:
        self._storage[key] = value

    def clear(self) -> None:
        self._storage.clear()


# ----- Main processor -----
class DataProcessor:
    """
    Processes an iterable of items applying validation, deduplication,
    normalization and caching as dictated by the injected strategies.
    All state is contained within the instance, making it thread‑safe
    for concurrent use across different instances.
    """

    def __init__(
        self,
        validator: Optional[ValidationStrategy] = None,
        deduper: Optional[DedupeStrategy] = None,
        normalizer: Optional[NormalizeStrategy] = None,
        cache: Optional[CacheStrategy] = None,
    ) -> None:
        self.validator = validator
        self.deduper = deduper
        self.normalizer = normalizer
        self.cache = cache
        self._stats: dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}

    def process(self, data: Iterable[Any]) -> List[Any]:
        # ----- Caching lookup -----
        if self.cache is not None:
            key = id(data)
            cached = self.cache.get(key)
            if cached is not None:
                self._stats["hits"] += 1
                return cached
            self._stats["misses"] += 1
        # If no cache strategy is supplied we simply proceed without hit/miss accounting.

        result: List[Any] = []
        seen: set = set()  # used only when a deduper is present

        for item in data:
            # ----- Validation -----
            if self.validator is not None:
                if not self.validator.is_valid(item):
                    self._stats["errors"] += 1
                    if self.validator.strict:
                        raise ValueError(f"Expected dict, got {type(item)}")
                    if self.validator.verbose:
                        print(f"Skipping invalid item: {item}")
                    continue

            # ----- Deduplication -----
            if self.deduper is not None:
                if not self.deduper.should_keep(item, seen):
                    continue

            # ----- Normalization -----
            if self.normalizer is not None:
                item = self.normalizer.normalize(item)

            result.append(item)

        # ----- Store in cache if enabled -----
        if self.cache is not None:
            self.cache.set(id(data), result)

        return result

    def get_stats(self) -> dict[str, int]:
        """Return a copy of the current statistics."""
        return dict(self._stats)

    def reset(self) -> None:
        """Reset statistics and clear the cache (if any)."""
        self._stats = {"hits": 0, "misses": 0, "errors": 0}
        if self.cache is not None:
            self.cache.clear()

