T = TypeVar('T')

class ProcessingStep(Protocol[T]):
    """Protocol for processing steps in the pipeline."""
    def process(self, items: List[T]) -> List[T]:
        ...


@dataclass
class ValidationStep:
    """Validates items in the data."""
    strict: bool = False
    verbose: bool = False

    def process(self, items: List[Any]) -> List[Dict[str, Any]]:
        """Filter out non-dict items based on configuration."""
        result: List[Dict[str, Any]] = []
        for item in items:
            if not isinstance(item, dict):
                if self.strict:
                    raise ValueError(f"Expected dict, got {type(item)}")
                if self.verbose:
                    print(f"Skipping invalid item: {item}")
                continue
            result.append(item)
        return result


@dataclass
class DeduplicationStep:
    """Removes duplicate items from the data."""

    def process(self, items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Remove duplicate items based on their string representation."""
        result: List[Dict[str, Any]] = []
        seen: Set[str] = set()

        for item in items:
            # Create a canonical string representation for deduplication
            key = str(sorted(item.items()))
            if key not in seen:
                seen.add(key)
                result.append(item)

        return result


@dataclass
class NormalizationStep:
    """Normalizes string values in dictionary items."""

    def process(self, items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Normalize string values to lowercase and strip whitespace."""
        result: List[Dict[str, Any]] = []

        for item in items:
            normalized_item = {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }
            result.append(normalized_item)

        return result


@dataclass
class CacheStats:
    """Statistics for cache usage."""
    hits: int = 0
    misses: int = 0
    errors: int = 0

    def increment_hits(self) -> None:
        self.hits += 1

    def increment_misses(self) -> None:
        self.misses += 1

    def increment_errors(self) -> None:
        self.errors += 1

    def to_dict(self) -> Dict[str, int]:
        return {"hits": self.hits, "misses": self.misses, "errors": self.errors}


class Cache:
    """Simple in-memory cache with statistics."""

    def __init__(self) -> None:
        self._cache: Dict[int, Any] = {}
        self._stats = CacheStats()
        self._lock = threading.RLock()  # For thread safety

    def get(self, key: int) -> Optional[Any]:
        """Retrieve item from cache if present."""
        with self._lock:
            if key in self._cache:
                self._stats.increment_hits()
                return self._cache[key]
            self._stats.increment_misses()
            return None

    def set(self, key: int, value: Any) -> None:
        """Store item in cache."""
        with self._lock:
            self._cache[key] = value

    def clear(self) -> None:
        """Clear all cached items."""
        with self._lock:
            self._cache.clear()

    def get_stats(self) -> Dict[str, int]:
        """Get cache statistics."""
        with self._lock:
            return self._stats.to_dict()

    def reset_stats(self) -> None:
        """Reset cache statistics."""
        with self._lock:
            self._stats = CacheStats()


@dataclass
class DataProcessorConfig:
    """Configuration for the data processor."""
    validation: Optional[ValidationStep] = None
    deduplication: Optional[DeduplicationStep] = None
    normalization: Optional[NormalizationStep] = None
    cache: Optional[Cache] = None


class DataProcessor:
    """
    Processes data with configurable pipeline steps.

    The processor applies steps in this order:
    1. Validation (if configured)
    2. Deduplication (if configured)
    3. Normalization (if configured)

    Caching is applied to the entire pipeline result.
    """

    def __init__(self, config: Optional[DataProcessorConfig] = None) -> None:
        self.config = config or DataProcessorConfig()

    def process(self, data: List[Any]) -> List[Any]:
        """
        Process the input data through the configured pipeline.

        Args:
            data: List of items to process. Items are expected to be dicts
                  if validation is enabled.

        Returns:
            Processed list of items.

        Raises:
            ValueError: If validation is strict and a non-dict item is found.
        """
        # Check cache first if caching is enabled
        if self.config.cache is not None:
            cache_key = id(data)
            cached_result = self.config.cache.get(cache_key)
            if cached_result is not None:
                return cached_result

        # Apply processing pipeline
        current_data = data

        # Step 1: Validation
        if self.config.validation is not None:
            try:
                current_data = self.config.validation.process(current_data)
            except ValueError as e:
                if self.config.cache is not None:
                    self.config.cache._stats.increment_errors()
                raise

        # Step 2: Deduplication
        if self.config.deduplication is not None:
            current_data = self.config.deduplication.process(current_data)

        # Step 3: Normalization
        if self.config.normalization is not None:
            current_data = self.config.normalization.process(current_data)

        # Store in cache if enabled
        if self.config.cache is not None:
            self.config.cache.set(id(data), current_data)

        return current_data

    def get_stats(self) -> Dict[str, int]:
        """Get statistics from cache if caching is enabled."""
        if self.config.cache is not None:
            return self.config.cache.get_stats()
        return {"hits": 0, "misses": 0, "errors": 0}

    def reset(self) -> None:
        """Reset cache and statistics if caching is enabled."""
        if self.config.cache is not None:
            self.config.cache.clear()
            self.config.cache.reset_stats()


