    Create a DataProcessor with the specified configuration.

    This provides backward compatibility with the original boolean flags API.
    """
    config = DataProcessorConfig()

    if validate:
        config.validation = ValidationStep(strict=strict, verbose=verbose)

    if dedupe:
        config.deduplication = DeduplicationStep()

    if normalize:
        config.normalization = NormalizationStep()

    if cache:
        config.cache = Cache()

    return DataProcessor(config)

