def _load_json_file(path: Path) -> Dict[str, Any]:
    """Helper to load and validate a JSON file."""
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except FileNotFoundError:
        raise
    except json.JSONDecodeError as e:
        raise ConfigMalformedError(f"Malformed JSON in {path}: {e}") from e
    except OSError as e:
        raise ConfigError(f"System error reading {path}: {e}") from e

    if not isinstance(data, dict):
        raise ConfigMalformedError(f"Config at {path} must be a JSON object (dict)")

    return data

def load_and_merge_configs(primary_path: str, override_path: Optional[str] = None) -> Dict[str, Any]:
    """
    Loads a primary config and an optional override config.

    Raises:
        ConfigMalformedError: If a file exists but is not valid JSON or not a dict.
        ConfigError: For other IO/Permission issues.
    """
    result: Dict[str, Any] = {}
    primary_p = Path(primary_path)

    # Load Primary
    try:
        result = _load_json_file(primary_p)
    except FileNotFoundError:
        logger.warning("Primary config not found: %s", primary_path)
    except (ConfigMalformedError, ConfigError) as e:
        logger.error("Failed to load primary config: %s", e)
        raise

    # Load Override
    if override_path:
        try:
            override = _load_json_file(Path(override_path))
            result.update(override)
        except FileNotFoundError:
            logger.warning("Override config not found: %s", override_path)
        except (ConfigMalformedError, ConfigError) as e:
            logger.error("Failed to load override config: %s", e)
