    result: Dict[str, Any] = {}

    # --- Load primary config ---
    try:
        with open(primary_path) as f:
            primary = json.load(f)
    except FileNotFoundError:
        logger.warning("Primary configuration not found: %s", primary_path)
        return {}
    except (json.JSONDecodeError, PermissionError, OSError) as e:
        raise PrimaryConfigError(
            f"Failed to read or parse primary config '{primary_path}': {e}"
        ) from e

    if not isinstance(primary, dict):
        raise PrimaryConfigError(
            f"Primary config '{primary_path}' is not a JSON object (dict)"
        )

    result.update(primary)

    # --- Load override config (optional) ---
    if override_path is not None:
        try:
            with open(override_path) as f:
                override = json.load(f)
        except FileNotFoundError:
            logger.info("Override configuration not found: %s", override_path)
            # Missing override is not an error; proceed without merging.
            return result
        except (json.JSONDecodeError, PermissionError, OSError) as e:
            raise OverrideConfigError(
                f"Failed to read or parse override config '{override_path}': {e}"
