                f"Override config '{override_path}' is not a JSON object (dict)"
            )

        result.update(override)

    return result

from abc import ABC, abstractmethod
from collections.abc import Iterable, Mapping
from dataclasses import dataclass, field
from typing import Any, Protocol, TypeAlias
from threading import Lock
import weakref

# Type aliases for clarity
DataItem: TypeAlias = Any
ProcessedData: TypeAlias = list[DataItem]
CacheKey: TypeAlias = int  # Using id() of original data as cache key


class ValidationStrategy(Protocol):
    """Protocol for validation strategies."""
    def validate(self, item: DataItem) -> bool: ...

    def on_validation_error(self, item: DataItem) -> None: ...


class NormalizationStrategy(Protocol):
    """Protocol for normalization strategies."""
    def normalize(self, item: DataItem) -> DataItem: ...


class DeduplicationStrategy(Protocol):
    """Protocol for deduplication strategies."""
    def __init__(self) -> None: ...
    def is_duplicate(self, item: DataItem) -> bool: ...
    def mark_seen(self, item: DataItem) -> None: ...


class DefaultValidationStrategy:
    """Default validation strategy that accepts all items."""
    def validate(self, item: DataItem) -> bool:
        return True

    def on_validation_error(self, item: DataItem) -> None:
        pass


class DictValidationStrategy:
    """Validation strategy that requires items to be dictionaries."""
    def __init__(self, strict: bool = False, verbose: bool = False) -> None:
        self.strict = strict
        self.verbose = verbose

    def validate(self, item: DataItem) -> bool:
        return isinstance(item, dict)

    def on_validation_error(self, item: DataItem) -> None:
        if self.strict:
            raise ValueError(f"Expected dict, got {type(item)}")
        if self.verbose:
            print(f"Skipping invalid item: {item}")


class DefaultNormalizationStrategy:
    """Default normalization strategy that returns items unchanged."""
    def normalize(self, item: DataItem) -> DataItem:
        return item


class DictNormalizationStrategy:
    """Normalization strategy for dictionaries."""
    def normalize(self, item: DataItem) -> DataItem:
        if not isinstance(item, dict):
            return item

        normalized = {}
        for key, value in item.items():
            if isinstance(value, str):
                normalized[key] = value.strip().lower()
            else:
                normalized[key] = value
        return normalized


class NoDeduplicationStrategy:
    """Strategy that performs no deduplication."""
    def __init__(self) -> None:
        pass

    def is_duplicate(self, item: DataItem) -> bool:
        return False

    def mark_seen(self, item: DataItem) -> None:
        pass


class DictDeduplicationStrategy:
    """Deduplication strategy for dictionaries."""
    def __init__(self) -> None:
        self.seen_keys: set[str] = set()

    def is_duplicate(self, item: DataItem) -> bool:
        if not isinstance(item, dict):
            return False

        key = str(sorted(item.items()))
        return key in self.seen_keys

    def mark_seen(self, item: DataItem) -> None:
        if isinstance(item, dict):
            key = str(sorted(item.items()))
            self.seen_keys.add(key)


class Cache(ABC):
    """Abstract base class for cache implementations."""
    @abstractmethod
    def get(self, key: CacheKey) -> ProcessedData | None: ...

    @abstractmethod
    def set(self, key: CacheKey, value: ProcessedData) -> None: ...

    @abstractmethod
    def clear(self) -> None: ...


class InMemoryCache(Cache):
    """Thread-safe in-memory cache."""
    def __init__(self) -> None:
        self._cache: dict[CacheKey, ProcessedData] = {}
        self._lock = Lock()

    def get(self, key: CacheKey) -> ProcessedData | None:
        with self._lock:
            return self._cache.get(key)

    def set(self, key: CacheKey, value: ProcessedData) -> None:
        with self._lock:
            self._cache[key] = value

    def clear(self) -> None:
        with self._lock:
            self._cache.clear()


class WeakRefCache(Cache):
    """Cache using weak references to avoid memory leaks."""
    def __init__(self) -> None:
        self._cache: weakref.WeakKeyDictionary[Any, ProcessedData] = weakref.WeakKeyDictionary()
        self._lock = Lock()

    def get(self, key: CacheKey) -> ProcessedData | None:
        with self._lock:
            # WeakKeyDictionary uses objects as keys, not integers
            # We need to store the actual data object reference
            return None  # Simplified - would need original object reference

    def set(self, key: CacheKey, value: ProcessedData) -> None:
        pass  # Simplified implementation

    def clear(self) -> None:
        with self._lock:
            self._cache.clear()


@dataclass
class ProcessingStats:
    """Container for processing statistics."""
    hits: int = 0
    misses: int = 0
    errors: int = 0

    def increment_hits(self) -> None:
        self.hits += 1

    def increment_misses(self) -> None:
        self.misses += 1

    def increment_errors(self) -> None:
        self.errors += 1

    def reset(self) -> None:
        self.hits = 0
        self.misses = 0
        self.errors = 0

    def to_dict(self) -> dict[str, int]:
        return {"hits": self.hits, "misses": self.misses, "errors": self.errors}


class DataProcessor:
    """
    Processes data with configurable validation, normalization, deduplication,
    and caching strategies.

    Thread-safe and self-contained with no global state.
    """

    def __init__(
        self,
        validation_strategy: ValidationStrategy | None = None,
        normalization_strategy: NormalizationStrategy | None = None,
        deduplication_strategy: DeduplicationStrategy | None = None,
        cache: Cache | None = None,
    ) -> None:
        """
        Initialize the data processor with optional strategies.

        Args:
            validation_strategy: Strategy for validating input items
            normalization_strategy: Strategy for normalizing items
            deduplication_strategy: Strategy for deduplicating items
            cache: Cache implementation for storing processed results
        """
        self.validation_strategy = validation_strategy or DefaultValidationStrategy()
        self.normalization_strategy = normalization_strategy or DefaultNormalizationStrategy()
        self.deduplication_strategy = deduplication_strategy or NoDeduplicationStrategy()
        self.cache = cache
        self.stats = ProcessingStats()
        self._lock = Lock()  # For thread-safe statistics updates

    def process(self, data: Iterable[DataItem]) -> ProcessedData:
        """
        Process the input data according to configured strategies.

        Args:
            data: Iterable of data items to process

        Returns:
            List of processed data items
        """
        # Check cache if enabled
        if self.cache is not None:
            cache_key = id(data)
            cached_result = self.cache.get(cache_key)
            if cached_result is not None:
                with self._lock:
                    self.stats.increment_hits()
                return cached_result

        with self._lock:
            self.stats.increment_misses()

        result: ProcessedData = []

        for item in data:
            # Validate item
            if not self.validation_strategy.validate(item):
                with self._lock:
                    self.stats.increment_errors()
                self.validation_strategy.on_validation_error(item)
                continue

            # Check for duplicates
            if self.deduplication_strategy.is_duplicate(item):
                continue

            # Normalize item
            processed_item = self.normalization_strategy.normalize(item)

            # Mark as seen for deduplication
            self.deduplication_strategy.mark_seen(item)

            result.append(processed_item)

        # Store in cache if enabled
        if self.cache is not None:
            self.cache.set(id(data), result)

        return result

    def get_stats(self) -> dict[str, int]:
        """Get current processing statistics."""
        with self._lock:
            return self.stats.to_dict()

    def reset_stats(self) -> None:
        """Reset processing statistics."""
        with self._lock:
            self.stats.reset()

    def clear_cache(self) -> None:
        """Clear the cache if enabled."""
        if self.cache is not None:
            self.cache.clear()


# Factory functions for common configurations
def create_default_processor() -> DataProcessor:
    """Create a processor with default (no-op) strategies."""
    return DataProcessor()


def create_dict_processor(
    strict: bool = False,
    verbose: bool = False,
    normalize: bool = False,
    dedupe: bool = False,
    cache: bool = False,
) -> DataProcessor:
    """
    Create a processor configured for dictionary processing.

    Args:
        strict: If True, raise ValueError on non-dict items
        verbose: If True, print warnings for skipped items
        normalize: If True, normalize dictionary string values
        dedupe: If True, deduplicate dictionaries based on content
        cache: If True, enable in-memory caching

    Returns:
        Configured DataProcessor instance
    """
    validation_strategy = DictValidationStrategy(strict, verbose) if strict or verbose else None
    normalization_strategy = DictNormalizationStrategy() if normalize else None
    deduplication_strategy = DictDeduplicationStrategy() if dedupe else None
    cache_impl = InMemoryCache() if cache else None

    return DataProcessor(
        validation_strategy=validation_strategy,
        normalization_strategy=normalization_strategy,
        deduplication_strategy=deduplication_strategy,
        cache=cache_impl,
    )

