from typing import Dict, Optional

class ConfigError(Exception):
    """Base class for configuration loading errors."""
    pass

class PrimaryConfigMissingError(ConfigError):
    """Raised when the primary configuration file is missing."""
    pass

class PrimaryConfigMalformedError(ConfigError):
    """Raised when the primary configuration file is malformed."""
    pass

class OverrideConfigMalformedError(ConfigError):
    """Raised when the override configuration file is malformed."""
    pass

def load_and_merge_configs(primary_path: str, override_path: Optional[str] = None) -> Dict:
    """
    Load and merge primary and optional override configuration files.

    Args:
        primary_path: Path to the primary configuration file.
        override_path: Optional path to the override configuration file.

    Returns:
        A merged dictionary of configurations. Returns empty dict if primary is missing.

    Raises:
        PrimaryConfigMissingError: If primary config file is missing.
        PrimaryConfigMalformedError: If primary config is malformed.
        OverrideConfigMalformedError: If override config is malformed.
    """
    result: Dict = {}

    try:
        primary_path_obj = Path(primary_path)
    except Exception as e:
        raise PrimaryConfigMalformedError(f"Invalid primary config path: {e}") from e

    if not primary_path_obj.exists():
        raise PrimaryConfigMissingError(f"Primary config not found: {primary_path}")

    if not primary_path_obj.is_file():
        raise PrimaryConfigMalformedError(f"Primary config path is not a file: {primary_path}")

    try:
        with open(primary_path_obj, 'r') as f:
            try:
                primary = json.load(f)
            except json.JSONDecodeError as e:
                raise PrimaryConfigMalformedError(f"JSON parse error in primary: {e}") from e
    except PermissionError as e:
        raise PrimaryConfigMalformedError(f"Permission denied reading primary config: {e}") from e
    except OSError as e:
        raise PrimaryConfigMalformedError(f"Error reading primary config: {e}") from e

    if not isinstance(primary, dict):
        logging.warning("Primary config is not a dict")
    else:
        result.update(primary)

    if override_path:
        try:
            override_path_obj = Path(override_path)
        except Exception as e:
            raise OverrideConfigMalformedError(f"Invalid override config path: {e}") from e

        if not override_path_obj.exists():
            logging.warning(f"Override config not found: {override_path}")
            return result

        if not override_path_obj.is_file():
            logging.warning(f"Override config path is not a file: {override_path}")
            return result

        try:
            with open(override_path_obj, 'r') as f:
                try:
                    override = json.load(f)
                except json.JSONDecodeError as e:
                    raise OverrideConfigMalformedError(f"JSON parse error in override: {e}") from e
        except PermissionError as e:
            logging.warning(f"Permission denied reading override config: {e}")
            return result
        except OSError as e:
            logging.warning(f"Error reading override config: {e}")
            return result

        if not isinstance(override, dict):
            logging.warning("Override config is not a dict")
        else:
            result.update(override)

    return result

import json
import logging
from typing import Dict, Optional, Any

class PrimaryConfigMissingError(Exception):
    """Raised when the primary configuration file cannot be found."""
    pass

class PrimaryConfigMalformedError(Exception):
    """Raised when the primary configuration file is unreadable or contains invalid JSON."""
    pass

class OverrideConfigMalformedError(Exception):
    """Raised when the override configuration file is unreadable or contains invalid JSON."""
    pass

def load_and_merge_configs(primary_path: str, override_path: Optional[str] = None) -> Dict[str, Any]:
    result = {}

    # 1. Load primary configuration
    try:
        with open(primary_path, 'r') as f:
            primary = json.load(f)
    except FileNotFoundError:
        logging.warning(f"Primary config not found: {primary_path}")
        return {}
    except PermissionError:
        logging.error(f"Permission denied reading primary config: {primary_path}")
        raise PrimaryConfigMalformedError(f"Cannot read primary config at {primary_path}") from None
    except json.JSONDecodeError as e:
        logging.error(f"JSON parse error in primary config: {e}", exc_info=True)
        raise PrimaryConfigMalformedError(f"Primary config at {primary_path} is malformed JSON") from e

    if not isinstance(primary, dict):
        logging.warning("Primary config root is not a dictionary")
        raise PrimaryConfigMalformedError("Primary config root is not a dictionary")

    result.update(primary)

    # 2. Load override configuration if provided
    if override_path:
        try:
            with open(override_path, 'r') as f:
                override = json.load(f)
        except FileNotFoundError:
            logging.warning(f"Override config not found: {override_path}")
        except PermissionError:
            logging.error(f"Permission denied reading override config: {override_path}")
            raise OverrideConfigMalformedError(f"Cannot read override config at {override_path}") from None
        except json.JSONDecodeError as e:
            logging.error(f"JSON parse error in override config: {e}", exc_info=True)
            raise OverrideConfigMalformedError(f"Override config at {override_path} is malformed JSON") from e

        if isinstance(override, dict):
            result.update(override)
        else:
            logging.warning("Override config root is not a dictionary, skipping merge")

    return result

