import json
import logging
from pathlib import Path
from typing import Dict, Any, Optional, Union

logger = logging.getLogger(__name__)

class ConfigError(Exception):
    """Base exception for configuration loading errors."""
    pass

class ConfigNotFoundError(ConfigError):
    """Raised when a required config file is missing."""
    pass

class ConfigMalformedError(ConfigError):
    """Raised when a config file contains invalid JSON or is not a dictionary."""
    pass

def _load_json_file(path: Union[str, Path]) -> Dict[str, Any]:
    """Helper to load and validate a JSON config file."""
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except FileNotFoundError:
        raise ConfigNotFoundError(f"Config file not found: {path}")
    except json.JSONDecodeError as e:
        raise ConfigMalformedError(f"Invalid JSON in {path}: {e}")
    except PermissionError as e:
        raise ConfigError(f"Permission denied reading {path}: {e}")

    if not isinstance(data, dict):
        raise ConfigMalformedError(f"Config at {path} must be a JSON object (dict)")

    return data

def load_and_merge_configs(primary_path: Union[str, Path], override_path: Optional[Union[str, Path]] = None) -> Dict[str, Any]:
    """
    Loads primary and optional override configs.

    Raises:
        ConfigMalformedError: If a file exists but is invalid.
        ConfigError: For system-level issues (permissions).
    """
    result: Dict[str, Any] = {}

    # Handle primary config
    try:
        result.update(_load_json_file(primary_path))
    except ConfigNotFoundError:
        logger.warning("Primary config missing at %s", primary_path)
    except ConfigError as e:
        logger.error("Failed to load primary config: %s", e)
        raise

    # Handle override config
    if override_path:
        try:
            result.update(_load_json_file(override_path))
        except ConfigNotFoundError:
            logger.warning("Override config missing at %s", override_path)
        except ConfigError as e:
            logger.error("Failed to load override config: %s", e)
            raise

    return result

