from __future__ import annotations

from typing import Any, Dict, List, Protocol, Set, runtime_checkable


# ----------------------------------------------------------------------
# Strategy interfaces
# ----------------------------------------------------------------------
@runtime_checkable
class Logger(Protocol):
    def log(self, message: str) -> None: ...


@runtime_checkable
class Validator(Protocol):
    def __call__(self, item: Any, stats: Dict[str, int]) -> bool: ...


@runtime_checkable
class Normalizer(Protocol):
    def __call__(self, item: Any) -> Any: ...


@runtime_checkable
class Deduper(Protocol):
    def key_for(self, item: Any) -> Any: ...


@runtime_checkable
class Cacher(Protocol):
    def get(self, data_id: int) -> Any: ...
    def set(self, data_id: int, value: Any) -> None: ...
    def clear(self) -> None: ...


# ----------------------------------------------------------------------
# Concrete strategy implementations
# ----------------------------------------------------------------------
class NoOpLogger:
    """Logger that discards all messages."""
    def log(self, message: str) -> None:  # pragma: no cover - trivial
        pass


class PrintLogger:
    """Logger that prints messages to stdout."""
    def log(self, message: str) -> None:  # pragma: no cover - side effect
        print(message)


class ValidationStrategy:
    """
    Validates that an item is a dict.
    On invalid items it increments the error counter,
    logs (if verbose) and either raises (if strict) or skips.
    """
    def __init__(self, *, strict: bool, verbose: bool, logger: Logger):
        self.strict = strict
        self.verbose = verbose
        self.logger = logger

    def __call__(self, item: Any, stats: Dict[str, int]) -> bool:
        if isinstance(item, dict):
            return True

        # invalid item – update error count
        stats["errors"] = stats.get("errors", 0) + 1

        if self.strict:
            raise ValueError(f"Expected dict, got {type(item)}")
        if self.verbose:
            self.logger.log(f"Skipping invalid item: {item}")
        return False


class NormalizeStrategy:
    """Normalizes dict values: strips and lower‑cases strings."""
    def __init__(self, *, enabled: bool):
        self.enabled = enabled

    def __call__(self, item: Any) -> Any:
        if not self.enabled or not isinstance(item, dict):
            return item
        return {
            k: (v.strip().lower() if isinstance(v, str) else v)
            for k, v in item.items()
        }


class DedupStrategy:
    """Computes a deduplication key when deduping is enabled."""
    def __init__(self, *, enabled: bool):
        self.enabled = enabled

    def key_for(self, item: Any) -> Any:
        if not self.enabled:
            return None
        if isinstance(item, dict):
            return str(sorted(item.items()))
        return str(item)


class CacheStrategy:
    """Simple per‑instance cache keyed by the ``id`` of the input object."""
    def __init__(self, *, enabled: bool):
        self.enabled = enabled
        self._cache: Dict[int, Any] = {}

    def get(self, data_id: int) -> Any:
        if not self.enabled:
            return None
        return self._cache.get(data_id)

    def set(self, data_id: int, value: Any) -> None:
        if self.enabled:
            self._cache[data_id] = value

    def clear(self) -> None:
        self._cache.clear()


# ----------------------------------------------------------------------
# Main processor – completely self‑contained, no module‑globals
# ----------------------------------------------------------------------
class DataProcessor:
    """
    Processes a sequence of items applying validation, deduplication,
    normalization and optional caching. All behavior is injected via
    strategy objects, making the class easy to test and thread‑safe
    (each instance owns its own state).
    """

    def __init__(
        self,
        *,
        validator: Validator,
        normalizer: Normalizer,
        deduper: Deduper,
        cacher: Cacher,
        logger: Logger,
    ) -> None:
        self.validator = validator
        self.normalizer = normalizer
        self.deduper = deduper
        self.cacher = cacher
        self.logger = logger

        # per‑instance statistics
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def process(self, data: List[Any]) -> List[Any]:
        """Process *data* and return the resulting list."""
        data_id = id(data)

        cached = self.cacher.get(data_id)
        if cached is not None:
            self._stats["hits"] += 1
            return cached

        self._stats["misses"] += 1

        result: List[Any] = []
        seen: Set[Any] = set()

        for item in data:
            if not self.validator(item, self._stats):
                continue

            if self.deduper.enabled:
                key = self.deduper.key_for(item)
                if key in seen:
                    continue
                seen.add(key)

            normalized_item = self.normalizer(item)
            result.append(normalized_item)

        self.cacher.set(data_id, result)
        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a shallow copy of the statistics dictionary."""
        return dict(self._stats)

    def reset(self) -> None:
        """Reset statistics and clear the internal cache."""
        self._stats = {"hits": 0, "misses": 0, "errors": 0}
        self.cacher.clear()


# ----------------------------------------------------------------------
# Convenience factory (optional) – builds a DataProcessor from the
# original boolean flags. This is *not* required by the refactor but
# shows how existing callers can migrate without changing their call
# sites.
# ----------------------------------------------------------------------
def build_processor(
    *,
    strict: bool = False,
    verbose: bool = False,
    cache: bool = False,
    normalize: bool = False,
    dedupe: bool = False,
    validate: bool = False,
) -> DataProcessor:
    """
    Factory that mirrors the original ``DataProcessor`` constructor
    using strategy objects under the hood.
    """
    logger = PrintLogger() if verbose else NoOpLogger()
    validator = ValidationStrategy(strict=strict, verbose=verbose, logger=logger)
    normalizer = NormalizeStrategy(enabled=normalize)
    deduper = DedupStrategy(enabled=dedupe)
    cacher = CacheStrategy(enabled=cache)
    # If validation is disabled we replace the validator with a no‑op that
    # always returns True (and never touches stats).
    if not validate:
        class AlwaysValid:
            def __call__(self, item: Any, stats: Dict[str, int]) -> bool:
                return True
        validator = AlwaysValid()

    return DataProcessor(
        validator=validator,
        normalizer=normalizer,
        deduper=deduper,
        cacher=cacher,
        logger=logger,
    )

from __future__ import annotations
from typing import Any, Dict, List, Optional, Protocol


# ----------------------------------------------------------------------
# Strategy protocols
# ----------------------------------------------------------------------
class ValidationStrategy(Protocol):
    """Validate an item and update error statistics."""
    def validate(self, item: Any, stats: Dict[str, int]) -> bool: ...


class DedupStrategy(Protocol):
    """Produce a deduplication key for an item."""
    def key(self, item: Any) -> str: ...


class NormalizationStrategy(Protocol):
    """Normalize an item (e.g., lower‑case strings in dicts)."""
    def normalize(self, item: Any) -> Any: ...


class CacheStrategy(Protocol):
    """Handle caching of processed results and statistics."""
    def get(self, data: Any, stats: Dict[str, int]) -> Optional[List[Any]]: ...
    def store(self, data: Any, result: List[Any]) -> None: ...
    def clear(self) -> None: ...


# ----------------------------------------------------------------------
# Default strategy implementations
# ----------------------------------------------------------------------
class DefaultValidation:
    """Validate that each item is a dict; respects strict/verbose flags."""
    def __init__(self, *, strict: bool = False, verbose: bool = False) -> None:
        self.strict = strict
        self.verbose = verbose

    def validate(self, item: Any, stats: Dict[str, int]) -> bool:
        if not isinstance(item, dict):
            stats["errors"] = stats.get("errors", 0) + 1
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return False
        return True


class KeyDedup:
    """Create a string key suitable for deduplication."""
    def key(self, item: Any) -> str:
        if isinstance(item, dict):
            return str(sorted(item.items()))
        return str(item)


class Normalizer:
    """Normalize dict items: strip whitespace and lower‑case string values."""
    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }
        return item


class SimpleCache:
    """Simple per‑instance cache that also updates hit/miss statistics."""
    def __init__(self) -> None:
        self._cache: Dict[int, List[Any]] = {}

    def get(self, data: Any, stats: Dict[str, int]) -> Optional[List[Any]]:
        key = id(data)
        if key in self._cache:
            stats["hits"] = stats.get("hits", 0) + 1
            return self._cache[key]
        stats["misses"] = stats.get("misses", 0) + 1
        return None

    def store(self, data: Any, result: List[Any]) -> None:
        self._cache[id(data)] = result

    def clear(self) -> None:
        self._cache.clear()


# ----------------------------------------------------------------------
# Main processor – completely self‑contained, no module‑globals
# ----------------------------------------------------------------------
class DataProcessor:
    """
    Process a list of items applying validation, deduplication,
    normalization and optional caching.

    All behavior is injected via strategies; no boolean mode‑flags are used
    inside the processing logic.
    """

    def __init__(
        self,
        *,
        validation: Optional[ValidationStrategy] = None,
        dedupe: Optional[DedupStrategy] = None,
        normalization: Optional[NormalizationStrategy] = None,
        cache: Optional[CacheStrategy] = None,
        strict: bool = False,
        verbose: bool = False,
    ) -> None:
        # Inject supplied strategies or fall back to defaults built from flags.
        self.validation: ValidationStrategy = (
            validation or DefaultValidation(strict=strict, verbose=verbose)
        )
        self.dedupe: DedupStrategy = dedupe or KeyDedup()
        self.normalization: NormalizationStrategy = (
            normalization or Normalizer()
        )
        self.cache: CacheStrategy = cache or SimpleCache()
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}

    # ------------------------------------------------------------------
    # Core processing
    # ------------------------------------------------------------------
    def process(self, data: List[Any]) -> List[Any]:
        # Try to return a cached result for the exact same list object.
        cached = self.cache.get(data, self._stats)
        if cached is not None:
            return cached

        result: List[Any] = []
        seen: set[str] = set()

        for item in data:
            # Validation (may update error stats, may raise, may skip)
            if not self.validation.validate(item, self._stats):
                continue

            # Deduplication
            key = self.dedupe.key(item)
            if key in seen:
                continue
            seen.add(key)

            # Normalization
            normalized = self.normalization.normalize(item)
            result.append(normalized)

        # Store the freshly computed result for future identical inputs.
        self.cache.store(data, result)
        return result

    # ------------------------------------------------------------------
    # Statistics & lifecycle
    # ------------------------------------------------------------------
    def get_stats(self) -> Dict[str, int]:
        """Return a copy of the current statistics."""
        return dict(self._stats)

    def reset(self) -> None:
        """Reset statistics and clear the cache."""
        self._stats = {"hits": 0, "misses": 0, "errors": 0}
        self.cache.clear()

import json
import logging
from pathlib import Path
from typing import Optional, Union


# Custom exceptions for distinguishable error conditions
class ConfigError(Exception):
    """Base config error."""
    pass


class PrimaryConfigMalformed(ConfigError):
    """Raised when the primary config file contains invalid JSON."""
    pass


class PrimaryConfigPermissionError(ConfigError):
    """Raised when the primary config file cannot be read due to permissions."""
    pass


class PrimaryConfigUnexpectedError(ConfigError):
    """Raised for any other unexpected error while reading the primary config."""
    pass


def load_and_merge_configs(
    primary_path: Union[str, Path],
    override_path: Optional[Union[str, Path]] = None
) -> dict:
    """
    Load and merge two JSON configuration files.
    Returns merged dict, or {} if primary is missing.
    Raises specific exceptions for malformed or unreadable primary config.
    Override errors are logged but do not prevent returning the primary config.
    """
    result = {}
    primary_path = Path(primary_path) if not isinstance(primary_path, Path) else primary_path

    # --- Load primary config ---
    try:
        with open(primary_path) as f:
            primary = json.load(f)
            if isinstance(primary, dict):
                result.update(primary)
            else:
                logging.warning(
                    "Primary config is not a dict, ignoring it. Path: %s",
                    primary_path
                )
    except FileNotFoundError:
        logging.warning("Primary config not found: %s", primary_path)
        # Return empty dict as per spec
    except json.JSONDecodeError as e:
        raise PrimaryConfigMalformed(
            f"Primary config malformed: {e}. Path: {primary_path}"
        ) from e
    except PermissionError as e:
        raise PrimaryConfigPermissionError(
            f"Permission denied reading primary config. Path: {primary_path}"
        ) from e
    except Exception as e:
        raise PrimaryConfigUnexpectedError(
            f"Unexpected error reading primary config. Path: {primary_path}: {e}"
        ) from e

    # --- Load override config (optional) ---
    if override_path:
        override_path = Path(override_path) if not isinstance(override_path, Path) else override_path
        try:
