from __future__ import annotations

import threading
from dataclasses import dataclass
from typing import Any, Dict, Iterable, List, Optional, Protocol, Set, runtime_checkable


# ----------------------------------------------------------------------
# Statistics container (per‑instance)
# ----------------------------------------------------------------------
@dataclass
class Stats:
    hits: int = 0
    misses: int = 0
    errors: int = 0

    def copy(self) -> "Stats":
        return Stats(self.hits, self.misses, self.errors)


# ----------------------------------------------------------------------
# Strategy protocols (optional, for documentation / static checking)
# ----------------------------------------------------------------------
@runtime_checkable
class Validator(Protocol):
    def validate(self, item: Any) -> bool: ...


@runtime_checkable
class Normalizer(Protocol):
    def normalize(self, item: Any) -> Any: ...


@runtime_checkable
class Deduplicator(Protocol):
    def should_skip(self, item: Any) -> bool: ...


@runtime_checkable
class Cacher(Protocol):
    def get(self, data_id: int) -> Optional[Any]: ...
    def set(self, data_id: int, value: Any) -> None: ...


# ----------------------------------------------------------------------
# Concrete strategy implementations
# ----------------------------------------------------------------------
class ValidatorImpl:
    """Handles validation, strict mode, verbose logging and error counting."""

    def __init__(
        self,
        strict: bool = False,
        verbose: bool = False,
        stats: Optional[Stats] = None,
    ) -> None:
        self.strict = strict
        self.verbose = verbose
        self.stats = stats or Stats()

    def validate(self, item: Any) -> bool:
        if not isinstance(item, dict):
            self.stats.errors += 1
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return False
        return True


class NormalizerImpl:
    """Optional string‑stripping & lower‑casing normalization for dict values."""

    def __init__(self, enabled: bool = False) -> None:
        self.enabled = enabled

    def normalize(self, item: Any) -> Any:
        if self.enabled and isinstance(item, dict):
            return {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }
        return item


class DeduplicatorImpl:
    """Optional deduplication based on a string representation of the item."""

    def __init__(self, enabled: bool = False) -> None:
        self.enabled = enabled
        self._seen: Set[str] = set()

    def should_skip(self, item: Any) -> bool:
        if not self.enabled:
            return False
        # Build a deterministic key: sorted items for dicts, otherwise str(item)
        key = (
            str(sorted(item.items()))
            if isinstance(item, dict)
            else str(item)
        )
        if key in self._seen:
            return True
        self._seen.add(key)
        return False


class CacherImpl:
    """Optional per‑instance caching with hit/miss statistics."""

    def __init__(
        self,
        enabled: bool = False,
        stats: Optional[Stats] = None,
    ) -> None:
        self.enabled = enabled
        self._cache: Dict[int, Any] = {}
        self.stats = stats or Stats()

    def get(self, data_id: int) -> Optional[Any]:
        if not self.enabled:
            return None
        if data_id in self._cache:
            self.stats.hits += 1
            return self._cache[data_id]
        self.stats.misses += 1
        return None

    def set(self, data_id: int, value: Any) -> None:
        if self.enabled:
            self._cache[data_id] = value


# ----------------------------------------------------------------------
# Main processor – fully self‑contained, uses composition instead of flags
# ----------------------------------------------------------------------
class DataProcessor:
    """
    Processes an iterable of items applying validation, normalization,
    deduplication and optional caching. All behaviour is injected via
    strategy objects; no boolean mode‑flags remain on the class.
    """

    def __init__(
        self,
        validator: Optional[Validator] = None,
        normalizer: Optional[Normalizer] = None,
        deduplicator: Optional[Deduplicator] = None,
        cacher: Optional[Cacher] = None,
        stats: Optional[Stats] = None,
    ) -> None:
        # Default strategies (no‑op equivalents)
        self.validator: Validator = validator or ValidatorImpl()
        self.normalizer: Normalizer = normalizer or NormalizerImpl()
        self.deduplicator: Deduplicator = deduplicator or DeduplicatorImpl()
        self.cacher: Cacher = cacher or CacherImpl()
        self.stats: Stats = stats or Stats()

        # Share the same stats object with strategies that need to update it
        if hasattr(self.validator, "stats"):
            self.validator.stats = self.stats  # type: ignore[attr-defined]
        if hasattr(self.cacher, "stats"):
            self.cacher.stats = self.stats  # type: ignore[attr-defined]

        # Lock to make the instance safe for concurrent use by multiple threads
        self._lock = threading.RLock()

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def process(self, data: Iterable[Any]) -> List[Any]:
        """Process *data* and return the resulting list."""
        with self._lock:
            data_id = id(data)
            cached = self.cacher.get(data_id)
            if cached is not None:
                return cached

            result: List[Any] = []
            for item in data:
                if not self.validator.validate(item):
                    continue
                if self.deduplicator.should_skip(item):
                    continue
                normalized = self.normalizer.normalize(item)
                result.append(normalized)

            self.cacher.set(data_id, result)
            return result

    def get_stats(self) -> Stats:
        """Return a snapshot of the current statistics."""
        with self._lock:
            return self.stats.copy()

    def reset(self) -> None:
        """Reset caches, deduplication state and statistics."""
        with self._lock:
            self.stats = Stats()
            # Refresh stats references in strategies
            if hasattr(self.validator, "stats"):
                self.validator.stats = self.stats  # type: ignore[attr-defined]
            if hasattr(self.cacher, "stats"):
                self.cacher.stats = self.stats  # type: ignore[attr-defined]
            if hasattr(self.cacher, "_cache"):
                self.cacher._cache.clear()  # type: ignore[attr-defined]
            if hasattr(self.deduplicator, "_seen"):
                self.deduplicator._seen.clear()  # type: ignore[attr-defined]


# ----------------------------------------------------------------------
# Convenience factory for the original boolean‑flag based usage
# ----------------------------------------------------------------------
def make_processor(
    *,
    strict: bool = False,
    verbose: bool = False,
    cache: bool = False,
    normalize: bool = False,
    dedupe: bool = False,
    validate: bool = False,
) -> DataProcessor:
    """
    Helper that builds a DataProcessor with the same behaviour as the
    original class when given the boolean flags.
    """
    validator = ValidatorImpl(strict=strict, verbose=verbose) if validate else None
    normalizer = NormalizerImpl(enabled=normalize) if normalize else None
    deduplicator = DeduplicatorImpl(enabled=dedupe) if dedupe else None
    cacher = CacherImpl(enabled=cache) if cache else None
    # Stats object is shared; create one empty instance to be passed around
    shared_stats = Stats()
    return DataProcessor(
        validator=validator,
        normalizer=normalizer,
        deduplicator=deduplicator,
        cacher=cacher,
        stats=shared_stats,
    )

