class ConfigError(Exception):
    """Base exception for configuration loading errors."""
    pass

class PrimaryConfigMissingError(ConfigError):
    """Raised when the primary configuration file is missing."""
    pass

class PrimaryConfigMalformedError(ConfigError):
    """Raised when the primary configuration file is malformed."""
    pass

class OverrideConfigMalformedError(ConfigError):
    """Raised when the override configuration file is malformed."""
    pass

def load_and_merge_configs(primary_path: str, override_path: Optional[str] = None) -> Dict:
    """
    Load and merge primary and optional override configuration files.

    Args:
        primary_path: Path to the primary configuration file (JSON).
        override_path: Optional path to the override configuration file (JSON).

    Returns:
        Merged configuration dictionary. Returns empty dict if primary config is missing.

    Raises:
        PrimaryConfigMissingError: If primary config file is missing.
        PrimaryConfigMalformedError: If primary config is not valid JSON or not a dict.
        OverrideConfigMalformedError: If override config is not valid JSON.
    """
    result: Dict = {}

    # Load primary config
    try:
        primary_path_obj = Path(primary_path)
        if not primary_path_obj.exists():
            raise PrimaryConfigMissingError(f"Primary config not found: {primary_path}")

        if not primary_path_obj.is_file():
            raise PrimaryConfigMalformedError(f"Primary path is not a file: {primary_path}")

        with open(primary_path, "r") as f:
            try:
                primary = json.load(f)
            except json.JSONDecodeError as e:
                raise PrimaryConfigMalformedError(f"JSON parse error in primary config: {e}") from e

            if not isinstance(primary, dict):
                raise PrimaryConfigMalformedError("Primary config is not a dict")
            result.update(primary)

    except PrimaryConfigMissingError:
        logger.warning(f"Primary config not found: {primary_path}")
        return {}
    except PrimaryConfigMalformedError as e:
        logger.error(str(e))
        raise
    except PermissionError as e:
        raise PrimaryConfigMalformedError(f"Permission denied reading primary config: {e}") from e
    except Exception as e:
        raise PrimaryConfigMalformedError(f"Unexpected error loading primary config: {e}") from e

    # Load override config if provided
    if override_path:
        try:
            override_path_obj = Path(override_path)
            if not override_path_obj.exists():
                logger.debug(f"Override config not found: {override_path}")
                return result

            if not override_path_obj.is_file():
                raise OverrideConfigMalformedError(f"Override path is not a file: {override_path}")

            with open(override_path, "r") as f:
                try:
                    override = json.load(f)
                except json.JSONDecodeError as e:
                    raise OverrideConfigMalformedError(f"JSON parse error in override config: {e}") from e

                if not isinstance(override, dict):
                    raise OverrideConfigMalformedError("Override config is not a dict")

                result.update(override)

        except OverrideConfigMalformedError as e:
            logger.error(str(e))
            raise
        except PermissionError as e:
            raise OverrideConfigMalformedError(f"Permission denied reading override config: {e}") from e
        except Exception as e:
            raise OverrideConfigMalformedError(f"Unexpected error loading override config: {e}") from e

    return result

