def load_and_merge_configs(
    primary_path: str,
    override_path: Optional[str] = None
) -> Dict:
    """
    Load and merge primary and optional override configuration files.

    Args:
        primary_path: Path to the primary configuration file (JSON).
        override_path: Optional path to the override configuration file (JSON).

    Returns:
        Merged configuration dictionary. Returns empty dict if primary is missing.

    Raises:
        PrimaryConfigMissingError: If primary_path does not exist.
        PrimaryConfigMalformedError: If primary_path contains invalid JSON.
        PrimaryConfigInvalidTypeError: If primary config is not a dict.
        OverrideConfigMalformedError: If override_path contains invalid JSON.
    """
    result: Dict = {}

    # Load primary config
    primary_path_obj = Path(primary_path)
    if not primary_path_obj.exists():
        raise PrimaryConfigMissingError(f"Primary config not found: {primary_path}")

    try:
        with primary_path_obj.open("r") as f:
            try:
                primary = json.load(f)
            except json.JSONDecodeError as e:
                raise PrimaryConfigMalformedError(
                    f"JSON parse error in primary config: {e}"
                ) from e
    except PermissionError as e:
        raise PrimaryConfigMissingError(
            f"Permission denied reading primary config: {primary_path}"
        ) from e

    if not isinstance(primary, dict):
        raise PrimaryConfigInvalidTypeError(
            f"Primary config is not a dict: {primary_path}"
        )

    result.update(primary)

    # Load override config if provided
    if override_path is not None:
        override_path_obj = Path(override_path)
        if not override_path_obj.exists():
            logger.debug("Override config not found: %s", override_path)
            return result

        try:
            with override_path_obj.open("r") as f:
                try:
                    override = json.load(f)
                except json.JSONDecodeError as e:
                    raise OverrideConfigMalformedError(
                        f"JSON parse error in override config: {e}"
                    ) from e
        except PermissionError as e:
            logger.warning(
                "Permission denied reading override config: %s", override_path
            )
            return result

        if not isinstance(override, dict):
            logger.debug("Override config is not a dict: %s", override_path)
            return result

        result.update(override)

    return result

