from typing import Any, Dict, List, Optional, Protocol


# ------------------------- Strategies -------------------------

class ValidatorProtocol(Protocol):
    def validate(self, item: Any) -> bool: ...


class NormalizerProtocol(Protocol):
    def normalize(self, item: Any) -> Any: ...


class DeduperProtocol(Protocol):
    def key(self, item: Any) -> Any: ...


class CacheProtocol(Protocol):
    def get(self, data_id: int) -> Optional[List[Any]]: ...
    def set(self, data_id: int, value: List[Any]) -> None: ...
    def reset(self) -> None: ...


# ----- Validator implementations -----

class AlwaysValidValidator:
    """Validator that always accepts items (used when validation is disabled)."""
    def validate(self, item: Any) -> bool:  # pragma: no cover - trivial
        return True


class StrictVerboseValidator:
    """Validator that checks for dict items, respects strict/verbose flags."""
    def __init__(self, *, strict: bool = False, verbose: bool = False) -> None:
        self.strict = strict
        self.verbose = verbose

    def validate(self, item: Any) -> bool:
        if not isinstance(item, dict):
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return False
        return True


# ----- Normalizer implementations -----

class NoOpNormalizer:
    """Normalizer that leaves items unchanged."""
    def normalize(self, item: Any) -> Any:  # pragma: no cover - trivial
        return item


class StringLowerNormalizer:
    """Normalizer that strips and lower‑cases string values inside dicts."""
    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }
        return item


# ----- Deduper implementations -----

class NoOpDeduper:
    """Deduper that never signals a duplicate (used when dedup is disabled)."""
    def key(self, item: Any) -> Any:  # pragma: no cover - trivial
        # Return a unique sentinel per call so it never matches another item.
        return object()


class ItemDeduper:
    """Deduper that builds a hashable key from an item."""
    def key(self, item: Any) -> Any:
        if isinstance(item, dict):
            return str(sorted(item.items()))
        return str(item)


# ----- Cache implementations -----

class NoOpCache:
    """Cache that does nothing (used when caching is disabled)."""
    def get(self, data_id: int) -> Optional[List[Any]]:
        return None

    def set(self, data_id: int, value: List[Any]) -> None:  # pragma: no cover - trivial
        pass

    def reset(self) -> None:  # pragma: no cover - trivial
        pass


class DictCache:
    """Simple dict‑based cache keyed by the id of the input data."""
    def __init__(self) -> None:
        self._store: Dict[int, List[Any]] = {}

    def get(self, data_id: int) -> Optional[List[Any]]:
        return self._store.get(data_id)

    def set(self, data_id: int, value: List[Any]) -> None:
        self._store[data_id] = value

    def reset(self) -> None:
        self._store.clear()


# ------------------------- DataProcessor -------------------------

class DataProcessor:
    """
    Processes a sequence of items with pluggable validation, normalization,
    deduplication and caching strategies. All state is contained within the
    instance, making it thread‑safe for concurrent use of different instances.
    """

    def __init__(
        self,
        *,
        validator: Optional[ValidatorProtocol] = None,
        normalizer: Optional[NormalizerProtocol] = None,
        deduper: Optional[DeduperProtocol] = None,
        cache: Optional[CacheProtocol] = None,
    ) -> None:
        self.validator = validator or AlwaysValidValidator()
        self.normalizer = normalizer or NoOpNormalizer()
        self.deduper = deduper or NoOpDeduper()
        self.cache = cache or NoOpCache()

        # Statistics – one set per instance
        self.hits: int = 0
        self.misses: int = 0
        self.errors: int = 0

    # -----------------------------------------------------------------
    def process(self, data: List[Any]) -> List[Any]:
        """Process *data* according to the configured strategies."""
        data_id = id(data)

        cached = self.cache.get(data_id)
        if cached is not None:
            self.hits += 1
            return cached

        self.misses += 1

        result: List[Any] = []
        seen: set = set()

        for item in data:
            # ----- Validation -----
            try:
                if not self.validator.validate(item):
                    self.errors += 1
                    continue
            except ValueError:
                # Validator raised because of strict mode
                self.errors += 1
                continue

            # ----- Deduplication -----
            key = self.deduper.key(item)
            if key in seen:
                continue
            seen.add(key)

            # ----- Normalization -----
            item = self.normalizer.normalize(item)

            result.append(item)

        # Store in cache if caching is enabled
        self.cache.set(data_id, result)
        return result

    # -----------------------------------------------------------------
    def get_stats(self) -> Dict[str, int]:
        """Return a copy of the current statistics."""
        return {"hits": self.hits, "misses": self.misses, "errors": self.errors}

    # -----------------------------------------------------------------
    def reset(self) -> None:
        """Reset statistics and the internal cache."""
        self.cache.reset()
        self.hits = self.misses = self.errors = 0

