def _load_json_file(path: Path) -> Dict[str, Any]:
    """
    Loads a JSON file and validates that it is a dictionary.

    Raises:
        FileNotFoundError: If the file does not exist.
        ConfigMalformedError: If the file is invalid JSON or not a dict.
    """
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except json.JSONDecodeError as e:
        raise ConfigMalformedError(f"Malformed JSON in {path}: {e}") from e
    except OSError as e:
        raise ConfigError(f"System error reading {path}: {e}") from e

    if not isinstance(data, dict):
        raise ConfigMalformedError(f"Config at {path} must be a JSON object (dict)")

    return data

def load_and_merge_configs(primary_path: str, override_path: Optional[str] = None) -> Dict[str, Any]:
    """
    Loads primary and optional override configurations and merges them.

    Returns:
        A merged dictionary. Returns {} if primary_path is missing.

    Raises:
        ConfigMalformedError: If either config file is invalid.
        ConfigError: For other IO/permission issues.
    """
    primary_p = Path(primary_path)
    result: Dict[str, Any] = {}

    # Handle primary config
    if not primary_p.exists():
        logger.warning("Primary config not found at %s", primary_path)
        return {}

    try:
        result.update(_load_json_file(primary_p))
    except ConfigMalformedError as e:
        logger.error("Primary config error: %s", e)
        raise

    # Handle override config
    if override_path:
        override_p = Path(override_path)
        if not override_p.exists():
            logger.warning("Override config not found at %s", override_path)
        else:
            try:
                result.update(_load_json_file(override_p))
            except ConfigMalformedError as e:
                logger.error("Override config error: %s", e)
                raise

    return result

