    except FileNotFoundError:
        logging.warning("Primary config not found: %s", primary_path)
        return {}  # Missing primary → empty result
    except json.JSONDecodeError as exc:
        logging.error(
            "JSON parse error in primary config at %s: %s", primary_path, exc
        )
        raise PrimaryConfigMalformedError(
            f"Failed to parse primary config at {primary_path}"
        ) from exc
    else:
        if not isinstance(primary, dict):
            logging.warning(
                "Primary config at %s is not a dict; treating as empty", primary_path
            )
            # Keep result as empty dict
        else:
            result.update(primary)

    # ---------- Load override config (if any) ----------
    if override_path is not None:
        try:
            with open(override_path, "r") as f:
                override = json.load(f)
        except FileNotFoundError:
            logging.warning("Override config not found: %s; skipping", override_path)
            # Skip merging; result unchanged
        except json.JSONDecodeError as exc:
            logging.error(
