            )
            raise OverrideConfigMalformedError(
                f"Failed to parse override config at {override_path}"
            ) from exc
        else:
            if not isinstance(override, dict):
                logging.warning(
                    "Override config at %s is not a dict; skipping merge", override_path
                )
            else:
                result.update(override)

    return result

