import json
import logging
from pathlib import Path
from typing import Union, Optional, Dict, Any


class PrimaryConfigMalformedError(Exception):
    """Raised when the primary configuration file exists but cannot be parsed or is not a dict."""


class OverrideConfigMalformedError(Exception):
    """Raised when the override configuration file exists but cannot be parsed or is not a dict."""


def load_and_merge_configs(
    primary_path: Union[str, Path],
    override_path: Optional[Union[str, Path]] = None
) -> Dict[str, Any]:
    """
    Load a primary JSON config, optionally merge an override JSON config,
    and return the resulting dictionary.

    - If the primary file is missing, an empty dict is returned (after logging a warning).
    - If the primary file exists but is malformed (invalid JSON or not a dict),
      a PrimaryConfigMalformedError is raised.
    - If an override path is provided and the file exists but is malformed,
      an OverrideConfigMalformedError is raised.
    - Missing override files are logged as a warning and ignored.
    """
    result: Dict[str, Any] = {}

    # ---------- Primary config ----------
    try:
        with open(primary_path, "r", encoding="utf-8") as f:
            primary_raw = f.read()
    except FileNotFoundError:
        logging.warning("Primary config not found: %s", primary_path)
        return {}
    except PermissionError as e:
        logging.error("Permission denied reading primary config %s: %s", primary_path, e)
        raise
    except OSError as e:
        logging.error("Unable to read primary config %s: %s", primary_path, e)
        raise

    try:
        primary = json.loads(primary_raw)
    except json.JSONDecodeError as e:
        logging.error("JSON parse error in primary config %s: %s", primary_path, e)
        raise PrimaryConfigMalformedError(
            f"Primary config '{primary_path}' is not valid JSON"
        ) from e

    if not isinstance(primary, dict):
        logging.error(
            "Primary config %s is not a dict (got %s)", primary_path, type(primary).__name__
        )
        raise PrimaryConfigMalformedError(
            f"Primary config '{primary_path}' must be a JSON object"
        )

    result.update(primary)

    # ---------- Override config ----------
    if override_path is not None:
        try:
            with open(override_path, "r", encoding="utf-8") as f:
                override_raw = f.read()
        except FileNotFoundError:
            logging.warning("Override config not found: %s", override_path)
            return result
        except PermissionError as e:
            logging.error("Permission denied reading override config %s: %s", override_path, e)
            raise
        except OSError as e:
            logging.error("Unable to read override config %s: %s", override_path, e)
            raise

        try:
            override = json.loads(override_raw)
        except json.JSONDecodeError as e:
            logging.error("JSON parse error in override config %s: %s", override_path, e)
            raise OverrideConfigMalformedError(
                f"Override config '{override_path}' is not valid JSON"
            ) from e

        if not isinstance(override, dict):
            logging.error(
                "Override config %s is not a dict (got %s)", override_path, type(override).__name__
            )
            raise OverrideConfigMalformedError(
                f"Override config '{override_path}' must be a JSON object"
            )

        try:
            result.update(override)
        except Exception as e:  # pragma: no cover - defensive
            logging.error("Error merging override config %s: %s", override_path, e)
            raise OverrideConfigMalformedError(
                f"Failed to merge override config '{override_path}'"
            ) from e

    return result

