from typing import NamedTuple, Generic, TypeVar, Optional

T = TypeVar('T')
E = TypeVar('E')

class Success(NamedTuple, Generic[T]):
    value: T

class Failure(NamedTuple, Generic[E]):
    error: E

Result = Success[T] | Failure[E] # Python 3.10+ Union Type

def divide(numerator: float, denominator: float) -> Result[float, str]:
    if denominator == 0:
        return Failure("Cannot divide by zero")
    return Success(numerator / denominator)

