from dataclasses import dataclass
from typing import TypeVar, Generic

T = TypeVar('T')
E = TypeVar('E')

@dataclass(frozen=True)
class Result(Generic[T, E]):
    """Value‑or‑error monad."""
    value: T | None = None
    error:  E | None = None

    @property
    def is_ok(self) -> bool:
        return self.error is None

    @staticmethod
    def ok(val: T) -> 'Result[T, E]':
        return Result(value=val)

    @staticmethod
    def err(err: E) -> 'Result[T, E]':
        return Result(error=err)

# --- file boundary ---

def process(order) -> Result[Order, ProcessError]:
    # Validate
    if not order.is_valid():
        return Result.err(ProcessError.validation_failed(order.id))

    # Reserve inventory
    inv_res = reserve_inventory(order)
    if not inv_res.is_ok:
        return Result.err(inv_res.error)

    # Charge payment
    pay_res = charge_customer(order)
    if not pay_res.is_ok:
        return Result.err(pay_res.error)

    # Schedule shipment
    ship_res = schedule_shipment(order)
    if not ship_res.is_ok:
        return Result.err(ship_res.error)

    order.mark_completed()
    return Result.ok(order)

