import logging
from flask import jsonify

# Custom exceptions – clear, specific
class UserNotFoundError(Exception):
    """Raised when the user does not exist."""
    pass

class ExternalServiceError(Exception):
    """Raised when the external profile service fails."""
    pass

# Repository layer – let specific exceptions bubble up
def fetch_user(user_id):
    try:
        user = db.fetch(user_id)
    except DBError as e:
        raise UserNotFoundError(f"User {user_id} not found") from e
    return user

# Service layer – again, only catch what you can handle
def get_profile(user_id):
    user = fetch_user(user_id)                # may raise UserNotFoundError
    try:
        profile = http.get(f"/profile/{user_id}")
    except HTTPError as e:
        raise ExternalServiceError(f"Failed to fetch profile for {user_id}") from e
    return profile

# Global error handler – the *loud* place
@app.errorhandler(UserNotFoundError)
@app.errorhandler(ExternalServiceError)
def handle_error(e):
    # Log at ERROR level (loud!)
    logging.error(str(e), exc_info=e)   # full stack trace
    # Return a clear JSON payload
    return jsonify({"error": type(e).__name__, "message": str(e)}), 500

