def load_and_merge_configs(
    primary_path: str | Path, override_path: str | Path | None = None
) -> dict:
    """
    Load and merge configuration files.

    Args:
        primary_path: Path to the primary configuration file.
        override_path: Optional path to an override configuration file.

    Returns:
        A merged configuration dictionary. Returns empty dict if primary is missing.

