    try:
        primary_file = primary_path.open("r")
    except FileNotFoundError:
        logger.warning("Primary config not found: %s", primary_path)
        return result
    except PermissionError as e:
        logger.error("Permission denied reading primary config: %s", primary_path)
        raise PrimaryConfigPermissionError(
            f"Permission denied reading {primary_path}"
