        except json.JSONDecodeError as e:
            logger.error("JSON parse error in primary config: %s", e)
            raise PrimaryConfigParseError(
                f"Invalid JSON in {primary_path}: {e}"
            ) from e

    if not isinstance(primary, dict):
        logger.error("Primary config is not a dict: %s", type(primary).__name__)
        raise PrimaryConfigTypeError(
            f"Primary config root must be a dict, got {type(primary).__name__}"
        )

    result.update(primary)

    # Load override configuration if provided
    if override_path is None:
        return result

    override_path = Path(override_path)

    try:
        override_file = override_path.open("r")
    except FileNotFoundError:
        logger.warning("Override config not found: %s", override_path)
        return result
    except PermissionError as e:
        logger.error("Permission denied reading override config: %s", override_path)
        raise OverrideConfigPermissionError(
            f"Permission denied reading {override_path}"
        ) from e

    with override_file:
        try:
            override = json.load(override_file)
        except json.JSONDecodeError as e:
            logger.error("JSON parse error in override config: %s", e)
            raise OverrideConfigParseError(
                f"Invalid JSON in {override_path}: {e}"
            ) from e

    if not isinstance(override, dict):
        logger.error("Override config is not a dict: %s", type(override).__name__)
        raise OverrideConfigTypeError(
            f"Override config root must be a dict, got {type(override).__name__}"
        )

    # Merge override into result
    for key, value in override.items():
        try:
            result[key] = value
        except Exception as e:
            logger.error("Failed to merge override key %r: %s", key, e)
            raise OverrideConfigMergeError(
                f"Failed to merge override key {key!r}: {e}"
            ) from e

    return result

