        PrimaryConfigMalformedError: If primary config contains invalid JSON.
        PrimaryConfigNotDictError: If primary config is not a dictionary.
        OverrideConfigMalformedError: If override config contains invalid JSON.
    """
    result: Dict = {}

    try:
        primary_path_obj = Path(primary_path)
        if not primary_path_obj.exists():
            raise PrimaryConfigMissingError(f"Primary config not found: {primary_path}")

        if not primary_path_obj.is_file():
            raise PrimaryConfigMissingError(f"Primary config path is not a file: {primary_path}")

        try:
            with open(primary_path) as f:
                primary = json.load(f)
        except json.JSONDecodeError as e:
            raise PrimaryConfigMalformedError(f"JSON parse error in primary config: {e}") from e
        except PermissionError as e:
            raise PrimaryConfigMissingError(f"Permission denied reading primary config: {primary_path}") from e
        except Exception as e:
            raise PrimaryConfigMalformedError(f"Unexpected error reading primary config: {e}") from e

        if not isinstance(primary, dict):
            raise PrimaryConfigNotDictError(f"Primary config is not a dict: {primary_path}")

        result.update(primary)

    except PrimaryConfigMissingError:
        logging.warning(f"Primary config not found: {primary_path}")
        return {}
    except PrimaryConfigMalformedError as e:
        logging.error(str(e))
        raise
    except PrimaryConfigNotDictError as e:
        logging.error(str(e))
        raise
    except Exception as e:
        logging.error(f"Unexpected error loading primary config: {e}")
        raise PrimaryConfigMalformedError(f"Unexpected error loading primary config: {e}") from e

    if override_path:
        try:
            override_path_obj = Path(override_path)
            if not override_path_obj.exists():
                logging.debug(f"Override config not found: {override_path}")
                return result

            if not override_path_obj.is_file():
                logging.warning(f"Override config path is not a file: {override_path}")
                return result

            try:
                with open(override_path) as f:
                    override = json.load(f)
            except json.JSONDecodeError as e:
                raise OverrideConfigMalformedError(f"JSON parse error in override config: {e}") from e
            except PermissionError as e:
                logging.warning(f"Permission denied reading override config: {override_path}")
                return result
            except Exception as e:
                logging.warning(f"Unexpected error reading override config: {e}")
                return result

            if not isinstance(override, dict):
                logging.debug("Override config is not a dict - skipping merge")
                return result

            result.update(override)

        except OverrideConfigMalformedError as e:
            logging.error(str(e))
            raise
        except Exception as e:
            logging.warning(f"Unexpected error processing override config: {e}")
            return result

    return result

