from typing import Any, Dict, List, Set


class _ValidationStrategy:
    """Handles validation of items according to strict/verbose flags."""

    def __init__(self, *, strict: bool, verbose: bool) -> None:
        self.strict = strict
        self.verbose = verbose

    def validate(self, item: Any, stats: Dict[str, int]) -> bool:
        """Return True if item should be kept, False otherwise.

        Updates ``stats`` with error counts and may raise or print based on
        configuration.
        """
        if not isinstance(item, dict):
            stats["errors"] += 1
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return False
        return True


class _NormalizationStrategy:
    """Handles normalization of dict items."""

    def __init__(self, *, enabled: bool) -> None:
        self.enabled = enabled

    def normalize(self, item: Any) -> Any:
        """Return a normalized version of ``item`` if applicable."""
        if self.enabled and isinstance(item, dict):
            return {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }
        return item


class _DeduplicationStrategy:
    """Handles deduplication of items."""

    def __init__(self, *, enabled: bool) -> None:
        self.enabled = enabled

    def should_keep(self, item: Any, seen: Set[str]) -> bool:
        """Return True if ``item`` should be kept given the ``seen`` set.

        Updates ``seen`` with the item's key when it is first encountered.
        """
        if not self.enabled:
            return True
        key = str(sorted(item.items()) if isinstance(item, dict) else item)
        if key in seen:
            return False
        seen.add(key)
        return True


class _CachingStrategy:
    """Handles caching of processed results keyed by ``id(data)``."""

    def __init__(self, *, enabled: bool) -> None:
        self.enabled = enabled
        self._cache: Dict[int, List[Any]] = {}

    def get(self, key: int) -> List[Any] | None:
        """Return cached result for ``key`` if present and caching enabled."""
        if not self.enabled:
            return None
        return self._cache.get(key)

    def set(self, key: int, value: List[Any]) -> None:
        """Store ``value`` in the cache under ``key`` if caching enabled."""
        if self.enabled:
            self._cache[key] = value

    def clear(self) -> None:
        """Remove all cached entries."""
        self._cache.clear()


class DataProcessor:
    """Process a sequence of items with optional validation, normalization,
    deduplication, and caching.

    All behavior is configured via strategy objects; no boolean flags are
    exposed on the public constructor. Each instance owns its own cache and
    statistics, making it safe for independent use (including concurrent use
    across different instances).
    """

    def __init__(
        self,
        *,
        validator: _ValidationStrategy = _ValidationStrategy(strict=False, verbose=False),
        normalizer: _NormalizationStrategy = _NormalizationStrategy(enabled=False),
        deduper: _DeduplicationStrategy = _DeduplicationStrategy(enabled=False),
        cacher: _CachingStrategy = _CachingStrategy(enabled=False),
    ) -> None:
        self._validator = validator
        self._normalizer = normalizer
        self._deduper = deduper
        self._cacher = cacher
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}

    def process(self, data: List[Any]) -> List[Any]:
        """Process ``data`` according to the configured strategies.

        Returns a new list containing the processed items.
        """
        cache_key = id(data)
        cached = self._cacher.get(cache_key)
        if cached is not None:
            self._stats["hits"] += 1
            return cached

        self._stats["misses"] += 1

        result: List[Any] = []
        seen: Set[str] = set()
        for item in data:
            if not self._validator.validate(item, self._stats):
                continue
            if not self._deduper.should_keep(item, seen):
                continue
            normalized = self._normalizer.normalize(item)
            result.append(normalized)

        self._cacher.set(cache_key, result)
        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a snapshot of the processor's statistics."""
        return dict(self._stats)

    def reset(self) -> None:
        """Reset statistics and clear the internal cache."""
        self._stats = {"hits": 0, "misses": 0, "errors": 0}
        self._cacher.clear()

