class OverrideConfigMalformedError(ConfigError):
    """Raised when the override config file is inaccessible or contains invalid data."""
    pass

def load_and_merge_configs(primary_path: Union[str, Path], override_path: Union[str, Path, None] = None) -> dict[str, Any]:
    # Load primary config
    try:
        with open(primary_path) as f:
            primary = json.load(f)
    except FileNotFoundError:
        logging.warning(f"Primary config not found: {primary_path}")
        return {}
    except PermissionError as e:
        raise PrimaryConfigMalformedError(f"Primary config is inaccessible: {e}") from e
    except json.JSONDecodeError as e:
        raise PrimaryConfigMalformedError(f"Primary config contains invalid JSON: {e}") from e

    if not isinstance(primary, dict):
        raise PrimaryConfigMalformedError("Primary config is not a dictionary")

    result = dict(primary)

    # Load and merge override config (optional)
    if override_path is not None:
        try:
            with open(override_path) as f:
                override = json.load(f)
        except FileNotFoundError:
            logging.warning(f"Override config not found: {override_path}")
            return result
        except PermissionError as e:
            raise OverrideConfigMalformedError(f"Override config is inaccessible: {e}") from e
        except json.JSONDecodeError as e:
            raise OverrideConfigMalformedError(f"Override config contains invalid JSON: {e}") from e

        if not isinstance(override, dict):
            raise OverrideConfigMalformedError("Override config is not a dictionary")

        result.update(override)

    return result

import json
import logging
from pathlib import Path
from typing import Dict, Any, Optional, Union


class ConfigError(Exception):
    """Base exception for configuration loading errors."""
    pass

class PrimaryMalformedError(ConfigError):
    """Raised when the primary configuration file cannot be parsed or is not a dict."""
    pass

class OverrideMalformedError(ConfigError):
    """Raised when the override configuration file cannot be parsed or is not a dict."""
    pass

class PrimaryAccessError(ConfigError):
    """Raised when the primary configuration file is inaccessible (e.g., permission error)."""
    pass

class OverrideAccessError(ConfigError):
    """Raised when the override configuration file is inaccessible (e.g., permission error)."""
    pass


def load_and_merge_configs(
    primary_path: Union[str, Path],
    override_path: Optional[Union[str, Path]] = None
) -> Dict[str, Any]:
    """
    Load primary and (optionally) override JSON config files and merge them.

    Args:
        primary_path: Path to the primary configuration file.
        override_path: Optional path to an override configuration file.

    Returns:
        A merged dictionary. Returns an empty dict if the primary file is missing
        (after attempting to load the override if provided).

    Raises:
        PrimaryAccessError: If the primary file exists but cannot be read.
        PrimaryMalformedError: If the primary file is not valid JSON or is not a dict.
        OverrideAccessError: If the override file exists but cannot be read.
        OverrideMalformedError: If the override file is not valid JSON or is not a dict.
    """
    # Convert to Path objects for consistency
    primary = Path(primary_path)
    override = Path(override_path) if override_path else None

    logger = logging.getLogger(__name__)
    primary_data: Optional[Dict[str, Any]] = None

    # ---- Load primary configuration ----
    try:
        with open(primary, 'r', encoding='utf-8') as f:
            raw = json.load(f)
        if not isinstance(raw, dict):
            raise PrimaryMalformedError(
                f"Primary config at {primary} is not a dict, got {type(raw).__name__}"
            )
        primary_data = raw
    except FileNotFoundError:
        logger.warning("Primary config not found: %s", primary)
    except PermissionError as e:
        raise PrimaryAccessError(
            f"Permission denied reading primary config: {primary}"
        ) from e
    except json.JSONDecodeError as e:
        raise PrimaryMalformedError(
            f"JSON parse error in primary config {primary}: {e}"
        ) from e

    # ---- Load override configuration ----
    override_data: Optional[Dict[str, Any]] = None
    if override:
        try:
            with open(override, 'r', encoding='utf-8') as f:
                raw = json.load(f)
            if not isinstance(raw, dict):
                raise OverrideMalformedError(
                    f"Override config at {override} is not a dict, got {type(raw).__name__}"
                )
            override_data = raw
        except FileNotFoundError:
            logger.warning("Override config not found: %s", override)
        except PermissionError as e:
            raise OverrideAccessError(
                f"Permission denied reading override config: {override}"
            ) from e
        except json.JSONDecodeError as e:
            raise OverrideMalformedError(
                f"JSON parse error in override config {override}: {e}"
            ) from e

    # ---- Merge ----
    result: Dict[str, Any] = {}
    if primary_data is not None:
        result.update(primary_data)
    if override_data is not None:
        result.update(override_data)

    return result

from typing import Any, Dict, Iterable, List, Optional, Protocol, runtime_checkable


# ---------- Strategy protocols ----------
@runtime_checkable
class Validator(Protocol):
    def validate(self, item: Any, stats: Dict[str, int]) -> bool: ...


@runtime_checkable
class Normalizer(Protocol):
    def normalize(self, item: Any) -> Any: ...


@runtime_checkable
class Deduper(Protocol):
    def key_for(self, item: Any) -> Any: ...


@runtime_checkable
class Cache(Protocol):
    def get(self, key: Any) -> Optional[Any]: ...
    def set(self, key: Any, value: Any) -> None: ...
    def clear(self) -> None: ...


# ---------- Default (no‑op) strategies ----------
class DefaultValidator:
    def validate(self, item: Any, stats: Dict[str, int]) -> bool:
        return True


class DefaultNormalizer:
    def normalize(self, item: Any) -> Any:
        return item


class NoCache:
    def get(self, key: Any) -> Optional[Any]:
        return None

    def set(self, key: Any, value: Any) -> None:
        pass

    def clear(self) -> None:
        pass


# ---------- Concrete strategies ----------
class DictCache:
    """Simple dict‑based cache."""
    def __init__(self) -> None:
        self._store: Dict[Any, Any] = {}

    def get(self, key: Any) -> Optional[Any]:
        return self._store.get(key)

    def set(self, key: Any, value: Any) -> None:
        self._store[key] = value

    def clear(self) -> None:
        self._store.clear()


class StrictVerboseValidator:
    """Validator that respects strict/verbose flags."""
    def __init__(self, strict: bool = False, verbose: bool = False) -> None:
        self.strict = strict
        self.verbose = verbose

    def validate(self, item: Any, stats: Dict[str, int]) -> bool:
        if not isinstance(item, dict):
            stats["errors"] += 1
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return False
        return True


class StripLowerNormalizer:
    """Normalizes string values in dicts: strip whitespace and lower‑case."""
    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }
        return item


class ItemDeduper:
    """Produces a dedup key for an item."""
    def key_for(self, item: Any) -> Any:
        if isinstance(item, dict):
            return str(sorted(item.items()))
        return str(item)


# ---------- Refactored DataProcessor ----------
class DataProcessor:
    """
    Processes an iterable of items with pluggable validation,
    normalization, deduplication and caching strategies.
    All state is contained within the instance, making it
    independently testable and safe for concurrent use.
    """

    def __init__(
        self,
        validator: Optional[Validator] = None,
        normalizer: Optional[Normalizer] = None,
        deduper: Optional[Deduper] = None,
        cacher: Optional[Cache] = None,
    ) -> None:
        self._validator = validator if validator is not None else DefaultValidator()
        self._normalizer = normalizer if normalizer is not None else DefaultNormalizer()
        self._deduper = deduper
        self._cacher = cacher if cacher is not None else NoCache()
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}

    def process(self, data: Iterable[Any]) -> List[Any]:
        # ----- caching -----
        cached = self._cacher.get(id(data))
        if cached is not None:
            self._stats["hits"] += 1
            return list(cached)  # return a shallow copy to avoid accidental cache mutation
        self._stats["misses"] += 1

        result: List[Any] = []
        seen: set = set()

        for item in data:
            # ----- validation -----
            if not self._validator.validate(item, self._stats):
                continue

            # ----- deduplication -----
            if self._deduper is not None:
                key = self._deduper.key_for(item)
                if key in seen:
                    continue
                seen.add(key)

            # ----- normalization -----
            if self._normalizer is not None:
                item = self._normalizer.normalize(item)

            result.append(item)

        # ----- store in cache -----
        if self._cacher is not None:
            self._cacher.set(id(data), result)

        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a copy of the current statistics."""
        return dict(self._stats)

    def reset(self) -> None:
        """Reset statistics and clear the instance‑local cache."""
        self._stats = {"hits": 0, "misses": 0, "errors": 0}
        self._cacher.clear()

