class Table:
    name: str
    rows: List[Dict[str, Any]]

    def select(self, *columns: str) -> 'Table':
        """Select specific columns from the table."""
        if not columns:
            columns = self.rows[0].keys() if self.rows else []

        new_rows = []
        for row in self.rows:
            new_row = {col: row[col] for col in columns if col in row}
            new_rows.append(new_row)

        return Table(self.name, new_rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'Table':
        """Filter rows based on a predicate function."""
        filtered_rows = [row for row in self.rows if predicate(row)]
        return Table(self.name, filtered_rows)

    def join(self, other: 'Table', on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> 'Table':
        """Perform an inner join with another table based on a condition."""
        joined_rows = []
        for left_row in self.rows:
            for right_row in other.rows:
                if on(left_row, right_row):
                    joined_row = {**left_row, **right_row}
                    joined_rows.append(joined_row)
        return Table(f"{self.name}_joined_{other.name}", joined_rows)

    def group_by(self, column: str) -> 'GroupedTable':
        """Group rows by a specific column."""
        from collections import defaultdict
        groups = defaultdict(list)
        for row in self.rows:
            key = row.get(column)
            groups[key].append(row)
        return GroupedTable(self.name, groups)

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        """Sort rows by a specific column."""
        reverse = descending
        sorted_rows = sorted(self.rows, key=lambda x: x.get(column), reverse=reverse)
        return Table(self.name, sorted_rows)

    def limit(self, n: int) -> 'Table':
        """Limit the number of rows returned."""
        return Table(self.name, self.rows[:n])

    def __str__(self) -> str:
        """String representation of the table."""
        if not self.rows:
            return f"Empty {self.name}"

        headers = list(self.rows[0].keys())
        rows_str = [str(row) for row in self.rows]
        return f"{self.name}:\n" + "\n".join([", ".join(headers)] + rows_str)

@dataclass
class GroupedTable:
    name: str
    groups: Dict[Any, List[Dict[str, Any]]]

    def select(self, *columns: str) -> 'Table':
        """Select specific columns from the grouped table."""
        if not columns:
            # Get all unique columns from all groups
            columns = set()
            for group in self.groups.values():
                for row in group:
                    columns.update(row.keys())
            columns = tuple(columns)

        new_rows = []
        for group_key, group_rows in self.groups.items():
            for row in group_rows:
                new_row = {col: row[col] for col in columns if col in row}
                new_row['group_key'] = group_key
                new_rows.append(new_row)

        return Table(f"{self.name}_grouped", new_rows)

    def aggregate(self, operations: Dict[str, str]) -> 'Table':
        """Perform aggregations on grouped data."""
        new_rows = []
        for group_key, group_rows in self.groups.items():
            new_row = {'group_key': group_key}
            for col, op in operations.items():
                if op == 'count':
                    new_row[col] = len(group_rows)
                elif op == 'sum':
                    new_row[col] = sum(row[col] for row in group_rows if col in row)
                elif op == 'avg':
                    values = [row[col] for row in group_rows if col in row]
                    new_row[col] = sum(values) / len(values) if values else 0
                elif op == 'max':
                    new_row[col] = max(row[col] for row in group_rows if col in row)
                elif op == 'min':
                    new_row[col] = min(row[col] for row in group_rows if col in row)
            new_rows.append(new_row)
        return Table(f"{self.name}_aggregated", new_rows)

    def __str__(self) -> str:
        """String representation of the grouped table."""
        if not self.groups:
            return f"Empty {self.name}"

        headers = ['group_key'] + list(next(iter(self.groups.values()))[0].keys())
        rows_str = []
        for key, group in self.groups.items():
            rows_str.append(f"Group {key}:")
            for row in group:
                rows_str.append(str(row))

        return f"{self.name}:\n" + "\n".join(rows_str)

