        """Filter rows based on a predicate function."""
        filtered_rows = [row for row in self.rows if predicate(row)]
        return Table(self.name, filtered_rows)

    def join(
        self,
        other_table: 'Table',
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool]
    ) -> 'Table':
        """Perform an inner join with another table."""
        joined_rows = []
        for left_row in self.rows:
            for right_row in other_table.rows:
                if on(left_row, right_row):
                    joined_row = left_row.copy()
                    joined_row.update(right_row)
                    joined_rows.append(joined_row)

        # Use a combined name for the joined table
        new_name = f"{self.name}_joined_{other_table.name}"
        return Table(new_name, joined_rows)

    def group_by(self, column: str) -> 'GroupedTable':
        """Group rows by a column value."""
        groups = defaultdict(list)
        for row in self.rows:
            key = row.get(column)
            groups[key].append(row)

        return GroupedTable(self.name, groups)

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        """Sort rows by a column value."""
        reverse = descending
        sorted_rows = sorted(
            self.rows,
            key=lambda row: row.get(column, 0),
            reverse=reverse
        )
        return Table(self.name, sorted_rows)

    def limit(self, n: int) -> 'Table':
        """Limit the number of rows returned."""
        return Table(self.name, self.rows[:n])

    def __str__(self) -> str:
        """String representation of the table."""
        if not self.rows:
            return f"Empty {self.name} table"

        # Get all column names from all rows
        columns = set()
        for row in self.rows:
            columns.update(row.keys())
        columns = sorted(columns)

        # Create header
        header = " | ".join(columns)
        separator = "-+-".join(["-" * len(col) for col in columns])

        # Create rows
        row_strs = []
        for row in self.rows:
            row_strs.append(" | ".join(str(row.get(col, "")) for col in columns))

        return f"{header}\n{separator}\n" + "\n".join(row_strs)

