        new_groups = {}
        for key, group_rows in self.groups.items():
            new_group_rows = []
            for row in group_rows:
                selected_row = {col: row[col] for col in columns if col in row}
                new_group_rows.append(selected_row)
            new_groups[key] = new_group_rows

        return GroupedTable(self.name, new_groups)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'GroupedTable':
        """Filter groups based on a predicate function."""
        new_groups = {}
        for key, group_rows in self.groups.items():
            filtered_rows = [row for row in group_rows if predicate(row)]
            if filtered_rows:
                new_groups[key] = filtered_rows

        return GroupedTable(self.name, new_groups)

    def order_by(self, column: str, descending: bool = False) -> 'GroupedTable':
        """Sort groups by a column value."""
        reverse = descending
        sorted_groups = sorted(
            self.groups.items(),
            key=lambda item: item[0] if item[0] is not None else 0,
            reverse=reverse
        )
        new_groups = {k: v for k, v in sorted_groups}
        return GroupedTable(self.name, new_groups)

    def limit(self, n: int) -> 'GroupedTable':
        """Limit the number of groups returned."""
        limited_groups = {}
        for i, (key, group_rows) in enumerate(self.groups.items()):
            if i >= n:
                break
            limited_groups[key] = group_rows

        return GroupedTable(self.name, limited_groups)

    def __str__(self) -> str:
        """String representation of the grouped table."""
        if not self.groups:
            return f"Empty grouped {self.name} table"

        # Get all column names from all rows in all groups
        columns = set()
        for group_rows in self.groups.values():
            for row in group_rows:
                columns.update(row.keys())
        columns = sorted(columns)

        # Create header
        header = " | ".join(columns)
        separator = "-+-".join(["-" * len(col) for col in columns])

        # Create rows for each group
        output = []
        for key, group_rows in self.groups.items():
            output.append(f"Group: {key}")
            output.append(header)
            output.append(separator)
            for row in group_rows:
                output.append(" | ".join(str(row.get(col, "")) for col in columns))
            output.append("")  # Empty line between groups

        return "\n".join(output)

