from typing import List, Dict, Any, Callable, Optional
from itertools import groupby

class Table:
    def __init__(self, data: List[Dict[str, Any]]):
        self.data = data

    def select(self, *columns: str) -> 'Table':
        return Table([{k: row[k] for k in columns if k in row} for row in self.data])

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'Table':
        return Table([row for row in self.data if predicate(row)])

    def join(self, other: 'Table', on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> 'Table':
        joined = []
        for l in self.data:
            for r in other.data:
                if on(l, r):
                    joined.append({**l, **r})
        return Table(joined)

    def group_by(self, column: str) -> Dict[Any, List[Dict[str, Any]]]:
        # Returns a dict of groups rather than a Table, as SQL aggregation 
        # usually transforms the structure significantly.
        sorted_data = sorted(self.data, key=lambda x: x.get(column))
        return {k: list(v) for k, v in groupby(sorted_data, key=lambda x: x.get(column))}

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        return Table(sorted(self.data, key=lambda x: x.get(column), reverse=descending))

    def limit(self, n: int) -> 'Table':
        return Table(self.data[:n])

    def __repr__(self):
        return f"Table({self.data})"

