class ConfigError(Exception):
    """Base exception for config loading errors."""


class ConfigParseError(ConfigError):
    """Raised when the primary config file contains invalid JSON."""


class ConfigTypeError(ConfigError):
    """Raised when the primary config is not a dict."""


class ConfigPermissionError(ConfigError):
    """Raised when the primary config file cannot be read due to permissions."""


class OverrideParseError(ConfigError):
    """Raised when the override config file contains invalid JSON."""


class OverrideTypeError(ConfigError):
    """Raised when the override config is not a dict."""


class OverridePermissionError(ConfigError):
    """Raised when the override config file cannot be read due to permissions."""


def load_and_merge_configs(
    primary_path: Union[str, Path],
    override_path: Optional[Union[str, Path]] = None,
) -> Dict[str, Any]:
    """
    Load a primary JSON config and optionally merge an override JSON config.

    Args:
        primary_path: Path to the primary config file.
        override_path: Optional path to an override config file.

    Returns:
        A merged dictionary. Returns an empty dict if the primary file is missing.

    Raises:
        ConfigParseError: If the primary file contains invalid JSON.
        ConfigTypeError: If the primary file does not contain a dict.
        ConfigPermissionError: If the primary file cannot be read due to permissions.
        OverrideParseError: If the override file contains invalid JSON.
        OverrideTypeError: If the override file does not contain a dict.
        OverridePermissionError: If the override file cannot be read due to permissions.
        ConfigError: For other I/O errors during config loading.
    """
    result: Dict[str, Any] = {}

    # --- Load primary config ---
    try:
        with open(primary_path) as f:
            primary = json.load(f)
    except FileNotFoundError:
        logger.warning("Primary config not found: %s", primary_path)
        return {}
    except PermissionError as e:
        logger.exception("Permission denied reading primary config: %s", primary_path)
        raise ConfigPermissionError(
            f"Permission denied reading primary config: {primary_path}"
        ) from e
    except json.JSONDecodeError as e:
        logger.exception("Invalid JSON in primary config: %s", primary_path)
        raise ConfigParseError(
            f"Invalid JSON in primary config: {primary_path}"
        ) from e
    except OSError as e:
        logger.exception("Unexpected error reading primary config: %s", primary_path)
        raise ConfigError(
            f"Unexpected error reading primary config: {primary_path}"
        ) from e

    if not isinstance(primary, dict):
        raise ConfigTypeError(
            f"Primary config must be a dict, got {type(primary).__name__}: {primary_path}"
        )

    result.update(primary)

    # --- Load override config (optional) ---
    if override_path:
        try:
            with open(override_path) as f:
                override = json.load(f)
        except FileNotFoundError:
            logger.warning("Override config not found: %s", override_path)
            return result
        except PermissionError as e:
            logger.exception("Permission denied reading override config: %s", override_path)
            raise OverridePermissionError(
                f"Permission denied reading override config: {override_path}"
            ) from e
        except json.JSONDecodeError as e:
            logger.exception("Invalid JSON in override config: %s", override_path)
            raise OverrideParseError(
                f"Invalid JSON in override config: {override_path}"
            ) from e
        except OSError as e:
            logger.exception("Unexpected error reading override config: %s", override_path)
            raise ConfigError(
                f"Unexpected error reading override config: {override_path}"
            ) from e

        if not isinstance(override, dict):
            raise OverrideTypeError(
                f"Override config must be a dict, got {type(override).__name__}: {override_path}"
            )

        result.update(override)

    return result

