            f"JSON parse error in primary config at {primary_path}: {e}"
        ) from e

    if not isinstance(primary, dict):
        raise PrimaryConfigMalformedError(
            f"Primary config at {primary_path} is not a dictionary"
        )
    result.update(primary)

    # ----- Load override config (if any) -----
    if override_path is not None:
        try:
            with open(override_path, "r") as f:
                override = json.load(f)
        except FileNotFoundError:
            logger.warning("Override config not found: %s", override_path)
