class Table:
    def __init__(self, name: str, rows: List[Dict[str, Any]]):
        self.name = name
        self.rows = rows

    def select(self, *columns: str) -> 'Table':
        """Select specific columns from the table."""
        if not columns:
            # If no columns specified, return all columns
            return Table(self.name, [row.copy() for row in self.rows])

        new_rows = []
        for row in self.rows:
            new_row = {col: row[col] for col in columns if col in row}
            new_rows.append(new_row)

        return Table(f"{self.name}_selected", new_rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'Table':
        """Filter rows based on a predicate function."""
        filtered_rows = [row for row in self.rows if predicate(row)]
        return Table(f"{self.name}_filtered", filtered_rows)

    def join(self, other: 'Table', on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> 'Table':
        """Perform an inner join with another table based on a predicate."""
        joined_rows = []
        for left_row in self.rows:
            for right_row in other.rows:
                if on(left_row, right_row):
                    joined_row = left_row.copy()
                    joined_row.update(right_row)
                    joined_rows.append(joined_row)

        return Table(f"{self.name}_joined_{other.name}", joined_rows)

    def group_by(self, column: str) -> 'GroupedTable':
        """Group rows by a specific column."""
        groups = {}
        for row in self.rows:
            key = row[column]
            if key not in groups:
                groups[key] = []
            groups[key].append(row)

        return GroupedTable(self.name, groups)

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        """Sort rows by a specific column."""
        sorted_rows = sorted(
            self.rows,
            key=lambda row: row[column],
            reverse=descending
        )
        return Table(f"{self.name}_ordered", sorted_rows)

    def limit(self, n: int) -> 'Table':
        """Limit the number of rows returned."""
        limited_rows = self.rows[:n]
        return Table(f"{self.name}_limited", limited_rows)

    def __repr__(self) -> str:
        return f"Table(name='{self.name}', rows={self.rows})"

class GroupedTable:
    def __init__(self, name: str, groups: Dict[Any, List[Dict[str, Any]]]):
        self.name = name
        self.groups = groups

    def aggregate(self, aggregations: Dict[str, str]) -> 'Table':
        """Apply aggregations to each group."""
        aggregated_rows = []
        for key, group in self.groups.items():
            row = {'group_key': key}
            for col, agg_func in aggregations.items():
                if agg_func == 'count':
                    row[col] = len(group)
                elif agg_func == 'sum':
                    row[col] = sum(row[col] for row in group)
                elif agg_func == 'avg':
                    row[col] = sum(row[col] for row in group) / len(group)
                elif agg_func == 'max':
                    row[col] = max(row[col] for row in group)
                elif agg_func == 'min':
                    row[col] = min(row[col] for row in group)
                else:
                    raise ValueError(f"Unknown aggregation function: {agg_func}")
            aggregated_rows.append(row)

        return Table(f"{self.name}_aggregated", aggregated_rows)

    def __repr__(self) -> str:
        return f"GroupedTable(name='{self.name}', groups={self.groups})"

