from typing import Callable, TypeVar

T = TypeVar('T')
U = TypeVar('U')
E = TypeVar('E', bound=Exception)

def bind(
    func: Callable[[T], U],
    error_type: type[E] = Exception
) -> Callable[[Result[T, E]], Result[U, E]]:
    """Bind a function that may fail."""
    def wrapper(result: Result[T, E]) -> Result[U, E]:
        if not result.is_ok:
            return result  # Pass error through
        try:
            return Result(value=func(result.unwrap()))
        except error_type as e:
            return Result(error=e)
    return wrapper

