class ErrorMapper:
    """Map exceptions to user-facing messages."""

    _mappings = {
        ValidationError: (400, "Invalid request data"),
        AuthenticationError: (401, "Authentication required"),
        PermissionError: (403, "Insufficient permissions"),
        ResourceNotFoundError: (404, "Resource not found"),
        RateLimitError: (429, "Too many requests"),
        DatabaseError: (503, "Service temporarily unavailable"),
    }

    def to_http_response(self, error: Exception) -> tuple[int, dict]:
        """Convert exception to HTTP response."""
        for exc_type, (status, message) in self._mappings.items():
            if isinstance(error, exc_type):
                return status, {"error": message, "detail": str(error)}

        # Default for unmapped errors
        logger.error(f"Unmapped error: {error}", exc_info=True)
        return 500, {"error": "Internal server error"}

