class ValidationStrategy:
    def validate(self, item: Any) -> bool:
        raise NotImplementedError

class DefaultValidationStrategy(ValidationStrategy):
    def __init__(self, strict: bool = False, verbose: bool = False):
        self.strict = strict
        self.verbose = verbose

    def validate(self, item: Any) -> bool:
        if not isinstance(item, dict):
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return False
        return True

class DeduplicationStrategy:
    def get_key(self, item: Any) -> Any:
        raise NotImplementedError

class DefaultDeduplicationStrategy(DeduplicationStrategy):
    def get_key(self, item: Any) -> Any:
        if isinstance(item, dict):
            return str(sorted(item.items()))
        return item

class NormalizationStrategy:
    def normalize(self, item: Any) -> Any:
        raise NotImplementedError

class DefaultNormalizationStrategy(NormalizationStrategy):
    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {k: (v.strip().lower() if isinstance(v, str) else v) for k, v in item.items()}
        return item

class CachingStrategy:
    def get(self, data: Any) -> Optional[List]:
        raise NotImplementedError
    def put(self, data: Any, result: List) -> None:
        raise NotImplementedError

class DefaultCachingStrategy(CachingStrategy):
    def __init__(self):
        self._cache: Dict[int, List] = {}

    def get(self, data: Any) -> Optional[List]:
        return self._cache.get(id(data))

    def put(self, data: Any, result: List) -> None:
        self._cache[id(data)] = result

class StatisticsTracker:
    def __init__(self):
        self.hits: int = 0
        self.misses: int = 0
        self.errors: int = 0

    def record_hit(self) -> None:
        self.hits += 1

    def record_miss(self) -> None:
        self.misses += 1

    def record_error(self) -> None:
        self.errors += 1

    def get_stats(self) -> Dict[str, int]:
        return {"hits": self.hits, "misses": self.misses, "errors": self.errors}

    def reset(self) -> None:
        self.hits = 0
        self.misses = 0
        self.errors = 0

class DataProcessor:
    def __init__(
        self,
        validator: Optional[ValidationStrategy] = None,
        deduplicator: Optional[DeduplicationStrategy] = None,
        normalizer: Optional[NormalizationStrategy] = None,
        cache: Optional[CachingStrategy] = None,
    ):
        self.validator = validator or DefaultValidationStrategy()
        self.deduplicator = deduplicator or DefaultDeduplicationStrategy()
        self.normalizer = normalizer or DefaultNormalizationStrategy()
        self.cache = cache or DefaultCachingStrategy()
        self.stats = StatisticsTracker()

    def process(self, data: List[Any]) -> List[Any]:
        cached_result = self.cache.get(data)
        if cached_result is not None:
            self.stats.record_hit()
            return cached_result

        self.stats.record_miss()
        result: List[Any] = []
        seen: Set[Any] = set()

        for item in data:
            if not self.validator.validate(item):
                self.stats.record_error()
                continue

            key = self.deduplicator.get_key(item)
            if key in seen:
                continue
            seen.add(key)

            normalized = self.normalizer.normalize(item)
            result.append(normalized)

        self.cache.put(data, result)
        return result

    def get_stats(self) -> Dict[str, int]:
        return self.stats.get_stats()

    def reset(self) -> None:
        self.stats.reset()
        if isinstance(self.cache, DefaultCachingStrategy):
            self.cache._cache.clear()

