from typing import List, Dict, Any, Callable, Optional, Union, Tuple
from dataclasses import dataclass
from functools import reduce

@dataclass
class Table:
    name: str
    rows: List[Dict[str, Any]]

    def select(self, *columns: str) -> 'Table':
        """Select specific columns from the table."""
        if not columns:
            columns = list(self.rows[0].keys()) if self.rows else []

        new_rows = []
        for row in self.rows:
            new_row = {col: row[col] for col in columns if col in row}
            new_rows.append(new_row)

        return Table(f"selected_{self.name}", new_rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'Table':
        """Filter rows based on a predicate function."""
        new_rows = [row for row in self.rows if predicate(row)]
        return Table(f"filtered_{self.name}", new_rows)

    def join(self, other: 'Table', on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> 'Table':
        """Perform an inner join with another table."""
        new_rows = []
        for left_row in self.rows:
            for right_row in other.rows:
                if on(left_row, right_row):
                    new_row = {**left_row, **right_row}
                    new_rows.append(new_row)

        return Table(f"joined_{self.name}_{other.name}", new_rows)

    def group_by(self, column: str) -> 'GroupedTable':
        """Group rows by a column value."""
        groups = {}
        for row in self.rows:
            key = row.get(column)
            if key not in groups:
                groups[key] = []
            groups[key].append(row)

        return GroupedTable(f"grouped_{self.name}", groups)

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        """Sort rows by a column value."""
        reverse = descending
        new_rows = sorted(self.rows, key=lambda x: x.get(column), reverse=reverse)
        return Table(f"ordered_{self.name}", new_rows)

    def limit(self, n: int) -> 'Table':
        """Limit the number of rows returned."""
        new_rows = self.rows[:n]
        return Table(f"limited_{self.name}", new_rows)

    def __str__(self) -> str:
        """String representation of the table."""
        if not self.rows:
            return f"Empty {self.name} table"

        headers = list(self.rows[0].keys())
        rows_str = [str(row.values()) for row in self.rows]
        header_str = " | ".join(headers)
        rows_str = "\n".join(rows_str)
        return f"{header_str}\n{rows_str}"

@dataclass
class GroupedTable:
    name: str
    groups: Dict[Any, List[Dict[str, Any]]]

    def select(self, *columns: str) -> 'GroupedTable':
        """Select specific columns from each group."""
        new_groups = {}
        for key, group in self.groups.items():
            new_group = []
            for row in group:
                new_row = {col: row[col] for col in columns if col in row}
                new_group.append(new_row)
            new_groups[key] = new_group

        return GroupedTable(f"selected_{self.name}", new_groups)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'GroupedTable':
        """Filter groups based on a predicate function."""
        new_groups = {}
        for key, group in self.groups.items():
            filtered_group = [row for row in group if predicate(row)]
            if filtered_group:
                new_groups[key] = filtered_group

        return GroupedTable(f"filtered_{self.name}", new_groups)

    def order_by(self, column: str, descending: bool = False) -> 'GroupedTable':
        """Sort groups by a column value."""
        reverse = descending
        sorted_keys = sorted(self.groups.keys(),
                           key=lambda k: self.groups[k][0].get(column),
                           reverse=reverse)
        new_groups = {k: self.groups[k] for k in sorted_keys}
        return GroupedTable(f"ordered_{self.name}", new_groups)

    def limit(self, n: int) -> 'GroupedTable':
        """Limit the number of rows in each group."""
        new_groups = {}
        for key, group in self.groups.items():
            new_groups[key] = group[:n]

        return GroupedTable(f"limited_{self.name}", new_groups)

    def aggregate(self, column: str, operation: str) -> 'Table':
        """Perform an aggregation on a column."""
        new_rows = []
        for key, group in self.groups.items():
            values = [row.get(column) for row in group if column in row]
            if not values:
                continue

            if operation == "count":
                result = len(values)
            elif operation == "sum":
                result = sum(values)
            elif operation == "avg":
                result = sum(values) / len(values)
            elif operation == "max":
                result = max(values)
            elif operation == "min":
                result = min(values)
            else:
                raise ValueError(f"Unknown operation: {operation}")

            new_row = {"group_key": key, "result": result}
            new_rows.append(new_row)

        return Table(f"aggregated_{self.name}", new_rows)

    def __str__(self) -> str:
        """String representation of the grouped table."""
        if not self.groups:
            return f"Empty {self.name} grouped table"

        result = []
        for key, group in self.groups.items():
            result.append(f"Group {key}:")
            if group:
                headers = list(group[0].keys())
                rows_str = [str(row.values()) for row in group]
                header_str = " | ".join(headers)
                rows_str = "\n".join(f"  {row}" for row in rows_str)
                result.append(f"{header_str}\n{rows_str}")
            else:
                result.append("  (empty group)")

        return "\n".join(result)

