from typing import List, Dict, Any, Callable, Optional

class Table:
    """In-memory SQL-like query engine with a composable fluent API.

    Each operation returns a new Table instance (immutable chain), 
    allowing safe method chaining without side effects.
    """

    def __init__(self, name: str, rows: List[Dict[str, Any]]):
        self.name = name
        self.rows = rows

    def select(self, *columns: str) -> "Table":
        """Filter rows to only include specified columns. Pass * or nothing to keep all."""
        if not columns or columns == ("*",):
            return self
        return Table(
            f"{self.name}.select",
            [{k: row[k] for k in columns if k in row} for row in self.rows]
        )

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> "Table":
        """Filter rows based on a boolean predicate function."""
        return Table(
            f"{self.name}.where",
            [row for row in self.rows if predicate(row)]
        )

    def join(self, other: "Table", on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> "Table":
        """Inner join with another table. Conflicting keys are prefixed with table names."""
        new_rows = []
        for l in self.rows:
            for r in other.rows:
                if on(l, r):
                    merged = {f"{self.name}_{k}": v for k, v in l.items()}
                    merged.update({f"{other.name}_{k}": v for k, v in r.items()})
                    new_rows.append(merged)
        return Table(f"{self.name}.join({other.name})", new_rows)

    def group_by(self, column: str) -> "Table":
        """Group rows by a column. Implicitly counts rows per group.
        Note: Real SQL engines require explicit aggregate functions (COUNT, SUM, etc.)."""
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self.rows:
            key = row.get(column)
            groups.setdefault(key, []).append(row)
        return Table(
            f"{self.name}.group_by({column})",
            [{column: k, "count": len(v)} for k, v in groups.items()]
        )

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Sort rows by a column. Missing values are pushed to the end."""
        def sort_key(row: Dict[str, Any]) -> tuple:
            val = row.get(column)
            if val is None:
                return (1, "")
            return (0, val)
        return Table(
            f"{self.name}.order_by({column})",
            sorted(self.rows, key=sort_key, reverse=descending)
        )

    def limit(self, n: int) -> "Table":
        """Return at most n rows."""
        return Table(f"{self.name}.limit({n})", self.rows[:n])

    def to_list(self) -> List[Dict[str, Any]]:
        """Materialize and return the final result set."""
        return self.rows

    def __repr__(self) -> str:
        return f"Table({self.name}, rows={len(self.rows)})"

