from typing import List, Dict, Any, Callable, TypeVar

T = TypeVar('T', bound='Table')

class Table:
    """In-memory SQL-like table supporting fluent query operations."""

    def __init__(self, columns: List[str], rows: List[Dict[str, Any]]):
        self.columns = columns
        self.rows = rows

    def select(self, *columns: str) -> "Table":
        """Project specific columns. Missing keys become None."""
        new_rows = [
            {col: row.get(col) for col in columns}
            for row in self.rows
        ]
        return Table(list(columns), new_rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> "Table":
        """Filter rows based on a predicate function."""
        new_rows = [row for row in self.rows if predicate(row)]
        return Table(self.columns, new_rows)

    def join(self, other: "Table", on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> "Table":
        """Inner join with another table. Colliding columns are prefixed with 'right_'."""
        new_rows = []
        for l_row in self.rows:
            for r_row in other.rows:
                if on(l_row, r_row):
                    merged = {**l_row}
                    for k, v in r_row.items():
                        if k in merged:
                            merged[f"right_{k}"] = v
                        else:
                            merged[k] = v
                    new_rows.append(merged)
        new_cols = [c for c in self.columns if c not in other.columns] + other.columns
        return Table(new_cols, new_rows)

    def group_by(self, column: str) -> "Table":
        """Group rows by a column value. Returns a table with a '_group' column containing lists of rows."""
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self.rows:
            key = row.get(column)
            if key not in groups:
                groups[key] = []
            groups[key].append(row)
        new_rows = [{column: k, "_group": v} for k, v in groups.items()]
        return Table([column, "_group"], new_rows)

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Sort rows by a column. Assumes all rows contain the column."""
        new_rows = sorted(self.rows, key=lambda r: r.get(column), reverse=descending)
        return Table(self.columns, new_rows)

    def limit(self, n: int) -> "Table":
        """Limit the result to n rows."""
        return Table(self.columns, self.rows[:n])

    def __repr__(self) -> str:
        return f"Table(columns={self.columns}, rows={self.rows})"

