from typing import List, Dict, Any, Callable, TypeVar, Optional

T = TypeVar('T', bound='Table')

class Table:
    """In-memory SQL-like query engine with a composable fluent API."""

    def __init__(self, rows: List[Dict[str, Any]]):
        self.rows = rows

    def select(self, *columns: str) -> Table:
        """Return a new Table with only the specified columns."""
        if not columns or columns == ('*',):
            return Table([dict(row) for row in self.rows])
        return Table([{c: row.get(c) for c in columns} for row in self.rows])

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        """Filter rows based on a predicate function."""
        return Table([row for row in self.rows if predicate(row)])

    def join(self, other: Table, on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> Table:
        """Inner join with another table. Right table columns overwrite left on collision."""
        new_rows = []
        for l in self.rows:
            for r in other.rows:
                if on(l, r):
                    new_rows.append({**l, **r})
        return Table(new_rows)

    def group_by(self, column: str) -> Table:
        """Group rows by a column. Returns a Table with each row containing the group key and a 'rows' list."""
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self.rows:
            key = row.get(column)
            groups.setdefault(key, []).append(row)
        return Table([{column: k, 'rows': v} for k, v in groups.items()])

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Sort rows by a column. Missing values are placed at the end."""
        def sort_key(row: Dict[str, Any]) -> Any:
            val = row.get(column)
            if val is None:
                return (1, '')
            return (0, val)
        return Table(sorted(self.rows, key=sort_key, reverse=descending))

    def limit(self, n: int) -> Table:
        """Return the first n rows."""
        return Table(self.rows[:n])

