    def key_for(self, item: Any) -> Any: ...


@runtime_checkable
class NormalizationStrategy(Protocol):
    """Strategy for normalizing an item."""
    def normalize(self, item: Any) -> Any: ...


@runtime_checkable
class CacheStrategy(Protocol):
    """Strategy for caching results."""
    def get(self, key: Any) -> Optional[Any]: ...
