class SimpleValidation:
    """Default validation: checks for dict type."""
    def __init__(self, strict: bool = False, verbose: bool = False) -> None:
        self.strict = strict
        self.verbose = verbose

    def is_valid(self, item: Any) -> bool:
        return isinstance(item, dict)


class SimpleDedup:
    """Default deduplication: uses sorted tuple of dict items or the item itself."""
    def key_for(self, item: Any) -> Any:
        if isinstance(item, dict):
            return tuple(sorted(item.items()))
        return item


class SimpleNormalization:
    """Default normalization: lower‑strips string values in dicts."""
    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }
        return item


class SimpleCache:
    """Simple dict‑based cache keyed by the ``id`` of the input iterable."""
    def __init__(self) -> None:
        self._store: dict[int, Any] = {}

    def get(self, key: Any) -> Optional[Any]:
        if isinstance(key, int):
            return self._store.get(key)
        return None

    def set(self, key: Any, value: Any) -> None:
        if isinstance(key, int):
