class DataProcessor:
    """
    Processes an iterable of items with optional validation, deduplication,
    normalization, and caching. All behavior is configured via strategy objects;
    no boolean mode‑flags are used on the public API.
    """

    def __init__(
        self,
        *,
        validation: Optional[ValidationStrategy] = None,
        dedup: Optional[DedupStrategy] = None,
        normalization: Optional[NormalizationStrategy] = None,
        cache: Optional[CacheStrategy] = None,
    ) -> None:
        self._validation_strategy = validation
        self._dedup_strategy = dedup
        self._normalization_strategy = normalization
        self._cache = cache
        self._hits: int = 0
        self._misses: int = 0
        self._errors: int = 0

    # -----------------------------------------------------------------
    # Processing
    # -----------------------------------------------------------------
    def process(self, data: Iterable[Any]) -> List[Any]:
        data_id = id(data)

        # Cache lookup
        if self._cache is not None:
            cached = self._cache.get(data_id)
            if cached is not None:
                self._hits += 1
                return cached
        self._misses += 1

        result: List[Any] = []
        seen: set[Any] = set() if self._dedup_strategy is not None else None

        for item in data:
            # Validation
            if self._validation_strategy is not None:
                if not self._validation_strategy.is_valid(item):
                    self._errors += 1
                    if self._validation_strategy.strict:
                        raise ValueError(f"Expected dict, got {type(item)}")
                    if self._validation_strategy.verbose:
                        print(f"Skipping invalid item: {item}")
                    continue

            # Deduplication
            if self._dedup_strategy is not None:
                key = self._dedup_strategy.key_for(item)
                if key in seen:
                    continue
                seen.add(key)

            # Normalization
            if self._normalization_strategy is not None:
                item = self._normalization_strategy.normalize(item)

            result.append(item)

        # Store in cache
        if self._cache is not None:
            self._cache.set(data_id, result)

        return result

    # -----------------------------------------------------------------
    # Statistics
    # -----------------------------------------------------------------
    def get_stats(self) -> dict[str, int]:
        """Return a copy of the current statistics."""
        return {"hits": self._hits, "misses": self._misses, "errors": self._errors}

    def reset(self) -> None:
        """Reset statistics and clear the internal cache (if any)."""
        self._hits = self._misses = self._errors = 0
        if self._cache is not None:
            self._cache.clear()

