def load_and_merge_configs(
    primary_path: Union[str, Path],
    override_path: Union[str, Path, None] = None
) -> dict:
    """Load primary JSON config and optionally merge an override config.

    Returns a merged dict. If the primary config file is missing, returns an empty dict.
    Errors are logged and, except for missing files, raised as informative exceptions
    so callers can distinguish between missing, malformed, and other problems.
    """
    result: dict = {}

    # ----- Load primary config -----
    try:
        with open(primary_path, "r") as f:
            primary = json.load(f)
    except FileNotFoundError:
        logging.warning(f"Primary config not found: {primary_path}")
        return {}
    except PermissionError as e:
        logging.error(f"Permission denied reading primary config {primary_path}: {e}")
        raise
    except json.JSONDecodeError as e:
        logging.error(f"JSON parse error in primary config {primary_path}: {e}")
        raise ValueError(f"Primary config malformed: {e}")
    except Exception as e:
        logging.error(f"Unexpected error reading primary config {primary_path}: {e}")
        raise

    if not isinstance(primary, dict):
        logging.warning(f"Primary config is not a dict: {primary_path}")
        return {}
    result.update(primary)

    # ----- Load and merge override config (if any) -----
    if override_path is not None:
        try:
            with open(override_path, "r") as f:
                override = json.load(f)
        except FileNotFoundError:
            logging.warning(f"Override config not found: {override_path}")
            # No override to merge; return what we have so far.
            return result
        except PermissionError as e:
            logging.error(f"Permission denied reading override config {override_path}: {e}")
            raise
        except json.JSONDecodeError as e:
            logging.error(f"JSON parse error in override config {override_path}: {e}")
            raise ValueError(f"Override config malformed: {e}")
        except Exception as e:
            logging.error(f"Unexpected error reading override config {override_path}: {e}")
            raise

        if not isinstance(override, dict):
            logging.warning(f"Override config is not a dict: {override_path}")
            return result

        for key, value in override.items():
            result[key] = value

    return result

from typing import Callable, Any, List, Dict, Optional

class Table:
    """A small in-memory SQL-like query engine with a fluent API."""

    def __init__(self, rows: List[Dict[str, Any]], columns: Optional[List[str]] = None):
        self.rows = rows
        self.columns = columns or (list(rows[0].keys()) if rows else [])

    def select(self, *columns: str) -> "Table":
        """Filter rows to only contain the specified columns."""
        new_rows = [{k: row[k] for k in columns if k in row} for row in self.rows]
        return Table(new_rows, list(columns))

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> "Table":
        """Filter rows where predicate(row) returns True."""
        new_rows = [row for row in self.rows if predicate(row)]
        return Table(new_rows, self.columns)

    def join(self, other: "Table", on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> "Table":
        """Inner join with another table. Overlapping columns are overwritten by the right table."""
        new_rows = []
        for l_row in self.rows:
            for r_row in other.rows:
                if on(l_row, r_row):
                    new_rows.append({**l_row, **r_row})
        new_cols = [c for c in self.columns if c not in other.columns] + other.columns
        return Table(new_rows, new_cols)

    def group_by(self, column: str) -> "Table":
        """Group rows by a column. Returns a table with the group key and a '_group' list of rows."""
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self.rows:
            key = row.get(column)
            groups.setdefault(key, []).append(row)
        new_rows = [{column: k, "_group": v} for k, v in groups.items()]
        return Table(new_rows, [column, "_group"])

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Sort rows by a column. None values are pushed to the end."""
        def sort_key(row: Dict[str, Any]) -> tuple:
            val = row.get(column)
            return (val is None, val)
        new_rows = sorted(self.rows, key=sort_key, reverse=descending)
        return Table(new_rows, self.columns)

    def limit(self, n: int) -> "Table":
        """Return only the first n rows."""
        return Table(self.rows[:n], self.columns)

    def __repr__(self) -> str:
        return f"Table(columns={self.columns}, rows={self.rows})"

