class Table:
    def __init__(self, name: str, rows: Optional[List[Dict[str, Any]]] = None):
        self.name = name
        self.rows = rows if rows is not None else []

    def select(self, *columns: str) -> 'Table':
        """Select specific columns from the table."""
        if not columns:
            # If no columns specified, return all columns
            return Table(self.name, [row.copy() for row in self.rows])

        return Table(
            self.name,
            [{col: row[col] for col in columns if col in row} for row in self.rows]
        )

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'Table':
        """Filter rows based on a predicate function."""
        return Table(
            self.name,
            [row.copy() for row in self.rows if predicate(row)]
        )

    def join(self, other_table: 'Table', on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> 'Table':
        """Perform an inner join with another table."""
        joined_rows = []
        for left_row in self.rows:
            for right_row in other_table.rows:
                if on(left_row, right_row):
                    joined_row = left_row.copy()
                    joined_row.update(right_row)
                    joined_rows.append(joined_row)
        return Table(f"{self.name}_joined_{other_table.name}", joined_rows)

    def group_by(self, column: str) -> 'Table':
        """Group rows by a column value (simple implementation)."""
        grouped = {}
        for row in self.rows:
            key = row.get(column)
            if key not in grouped:
                grouped[key] = []
            grouped[key].append(row.copy())

        # Convert to list of dicts with group key and rows
        result_rows = []
        for key, rows in grouped.items():
            result_rows.append({
                'group_key': key,
                'group_rows': rows
            })
        return Table(f"{self.name}_grouped_by_{column}", result_rows)

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        """Sort rows by a column value."""
        return Table(
            self.name,
            sorted(
                [row.copy() for row in self.rows],
                key=itemgetter(column),
                reverse=descending
            )
        )

    def limit(self, n: int) -> 'Table':
        """Limit the number of rows returned."""
        return Table(
            self.name,
            [row.copy() for row in self.rows[:n]]
        )

    def __str__(self) -> str:
        """String representation of the table (first 5 rows)."""
        header = ", ".join(self.rows[0].keys()) if self.rows else "Empty table"
        rows_str = "\n".join(
            ", ".join(str(v) for v in row.values())
            for row in self.rows[:5]
        )
        return f"Table {self.name}:\n{header}\n{rows_str}\n..."

    def __repr__(self) -> str:
        return f"Table(name={self.name!r}, rows={len(self.rows)} rows)"

