        if not self.rows:
            return f"Table {self.name} (empty)"

        headers = list(self.rows[0].keys())
        header_row = " | ".join(headers)
        separator = "-+-".join(["-" * len(h) for h in headers])
        rows = "\n".join(" | ".join(str(row[h]) for h in headers) for row in self.rows)
        return f"Table {self.name}\n{header_row}\n{separator}\n{rows}"

class Query(Generic[T]):
    def __init__(self, table: Table):
        self.table = table
        self._select_columns: Optional[tuple] = None
        self._where_predicate: Optional[Callable[[Dict[str, Any]], bool]] = None
        self._join_table: Optional[Table] = None
        self._join_condition: Optional[Callable[[Dict[str, Any], Dict[str, Any]], bool]] = None
        self._group_by_column: Optional[str] = None
        self._order_by_column: Optional[str] = None
        self._order_descending: bool = False
        self._limit_count: Optional[int] = None

    def select(self, *columns: str) -> 'Query[T]':
        """Select specific columns from the table."""
        self._select_columns = columns
        return self

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'Query[T]':
        """Filter rows based on a predicate function."""
        self._where_predicate = predicate
        return self

    def join(self, other_table: Table, on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> 'Query[T]':
        """Join with another table using a join condition."""
        self._join_table = other_table
        self._join_condition = on
        return self

    def group_by(self, column: str) -> 'Query[T]':
        """Group rows by a specific column."""
        self._group_by_column = column
        return self

    def order_by(self, column: str, descending: bool = False) -> 'Query[T]':
        """Sort rows by a specific column."""
        self._order_by_column = column
        self._order_descending = descending
        return self

    def limit(self, n: int) -> 'Query[T]':
        """Limit the number of rows returned."""
        self._limit_count = n
        return self

    def execute(self) -> List[Dict[str, Any]]:
        """Execute the query and return the results."""
        # Start with the base table
        result = self.table.rows.copy()

        # Apply WHERE clause
        if self._where_predicate:
            result = [row for row in result if self._where_predicate(row)]

        # Apply JOIN if specified
        if self._join_table and self._join_condition:
            joined_result = []
            for left_row in result:
                for right_row in self._join_table.rows:
                    if self._join_condition(left_row, right_row):
                        joined_row = {**left_row, **right_row}
                        joined_result.append(joined_row)
            result = joined_result

        # Apply GROUP BY if specified
        if self._group_by_column:
            grouped = {}
            for row in result:
                key = row[self._group_by_column]
                if key not in grouped:
                    grouped[key] = []
                grouped[key].append(row)
            result = [{"group_key": k, "group_rows": v} for k, v in grouped.items()]

        # Apply ORDER BY if specified
        if self._order_by_column:
            reverse = self._order_descending
            if self._group_by_column:
                # For grouped results, sort by the first element in the group
                result.sort(key=lambda x: x["group_rows"][0][self._order_by_column], reverse=reverse)
            else:
                result.sort(key=itemgetter(self._order_by_column), reverse=reverse)

        # Apply LIMIT if specified
        if self._limit_count is not None:
            result = result[:self._limit_count]

        # Apply SELECT if columns are specified
        if self._select_columns:
            if self._group_by_column:
                # For grouped results, select the group key and first element's columns
                result = [{"group_key": row["group_key"],
                          **{col: row["group_rows"][0][col] for col in self._select_columns}}
                         for row in result]
            else:
                result = [{col: row[col] for col in self._select_columns if col in row}
                         for row in result]

        return result

    def __iter__(self):
        """Make the query iterable."""
        return iter(self.execute())

    def __str__(self) -> str:
        """String representation of the query."""
        parts = []
        if self._select_columns:
            parts.append(f"SELECT {', '.join(self._select_columns)}")
        else:
            parts.append("SELECT *")

        parts.append(f"FROM {self.table.name}")

        if self._where_predicate:
            parts.append("WHERE <predicate>")

        if self._join_table and self._join_condition:
            parts.append(f"JOIN {self._join_table.name} ON <condition>")

        if self._group_by_column:
            parts.append(f"GROUP BY {self._group_by_column}")

        if self._order_by_column:
            direction = "DESC" if self._order_descending else "ASC"
            parts.append(f"ORDER BY {self._order_by_column} {direction}")

        if self._limit_count is not None:
            parts.append(f"LIMIT {self._limit_count}")

        return " ".join(parts)

