from typing import List, Dict, Callable, Any, Optional
from collections import Counter


class Table:
    """An in-memory table holding rows as a list of dictionaries."""

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        self.rows = rows

    def select(self, *columns: str) -> "Table":
        """Return a new table with only the specified columns."""
        if not columns:
            return Table(self.rows.copy())
        new_rows = []
        for row in self.rows:
            new_row = {col: row[col] for col in columns if col in row}
            new_rows.append(new_row)
        return Table(new_rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> "Table":
        """Return a new table with rows that satisfy the predicate."""
        return Table([row for row in self.rows if predicate(row)])

    def join(
        self,
        other: "Table",
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool],
    ) -> "Table":
        """Return a new table by joining with another table on a condition."""
        new_rows = []
        for left in self.rows:
            for right in other.rows:
                if on(left, right):
                    merged = {**left, **right}  # right overwrites left on key conflict
                    new_rows.append(merged)
        return Table(new_rows)

    def group_by(self, column: str) -> "Table":
        """Return a new table with one row per group, containing the group key and a count."""
        counts = Counter(row[column] for row in self.rows)
        new_rows = [{column: key, "count": count} for key, count in counts.items()]
        return Table(new_rows)

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Return a new table sorted by the given column."""
        return Table(
            sorted(self.rows, key=lambda row: row.get(column), reverse=descending)
        )

    def limit(self, n: int) -> "Table":
        """Return a new table with only the first n rows."""
        return Table(self.rows[:n])

    def __repr__(self) -> str:
        return f"Table({self.rows})"

