        return Table([row for row in self.data if predicate(row)])

    def join(self, other: 'Table', on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> 'Table':
        joined = []
        for left in self.data:
            for right in other.data:
                if on(left, right):
                    joined.append({**left, **right})
        return Table(joined)

    def group_by(self, column: str) -> Dict[Any, List[Dict[str, Any]]]:
        groups = {}
        for row in self.data:
            key = row.get(column)
            groups.setdefault(key, []).append(row)
        return groups

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        sorted_data = sorted(
            self.data, 
            key=lambda x: x.get(column), 
            reverse=descending
        )
        return Table(sorted_data)

    def limit(self, n: int) -> 'Table':
        return Table(self.data[:n])

    def __repr__(self):
        return f"Table(rows={len(self.data)}, data={self.data})"

