import json
import logging
from pathlib import Path
from typing import Any, Dict, Optional, Union


class ConfigError(Exception):
    """Base exception for configuration errors."""
    pass


class PrimaryConfigMalformedError(ConfigError):
    """Raised when the primary configuration file is malformed."""
    pass


class OverrideConfigMalformedError(ConfigError):
    """Raised when the override configuration file is malformed."""
    pass


class ConfigLoadError(ConfigError):
    """Raised for I/O errors (e.g., permission denied) while loading a config file."""
    pass


def load_and_merge_configs(
    primary_path: Union[str, Path],
    override_path: Optional[Union[str, Path]] = None,
) -> Dict[str, Any]:
    """
    Load a primary JSON config and optionally merge an override JSON config.

    Args:
        primary_path: Path to the primary configuration file.
        override_path: Optional path to an override configuration file.

    Returns:
        A merged dictionary. Returns an empty dict if the primary file is missing.

    Raises:
        PrimaryConfigMalformedError: If the primary file exists but is not valid JSON
            or is not a dict.
        OverrideConfigMalformedError: If the override file exists but is not valid JSON
            or is not a dict.
        ConfigLoadError: For other I/O errors (e.g., permission denied) on either file.
    """
    result: Dict[str, Any] = {}
    primary_path = Path(primary_path)

    # --- Load primary config ---
    try:
        with open(primary_path) as f:
            primary = json.load(f)
    except FileNotFoundError:
        logging.warning(f"Primary config not found: {primary_path}. Returning empty config.")
        return {}
    except json.JSONDecodeError as e:
        raise PrimaryConfigMalformedError(
            f"Primary config JSON parse error: {e}"
        ) from e
    except PermissionError as e:
        raise ConfigLoadError(
            f"Permission denied reading primary config: {primary_path}"
        ) from e
    except OSError as e:
        raise ConfigLoadError(
            f"OS error reading primary config: {primary_path}: {e}"
        ) from e

    if not isinstance(primary, dict):
        raise PrimaryConfigMalformedError(
            f"Primary config is not a dict, got {type(primary).__name__}"
        )
    result.update(primary)

    # --- Load override config (if provided) ---
    if override_path:
        override_path = Path(override_path)
        try:
            with open(override_path) as f:
                override = json.load(f)
        except FileNotFoundError:
            logging.warning(f"Override config not found: {override_path}. Skipping override.")
        except json.JSONDecodeError as e:
            raise OverrideConfigMalformedError(
                f"Override config JSON parse error: {e}"
            ) from e
        except PermissionError as e:
            raise ConfigLoadError(
                f"Permission denied reading override config: {override_path}"
            ) from e
        except OSError as e:
            raise ConfigLoadError(
                f"OS error reading override config: {override_path}: {e}"
            ) from e
        else:
            if not isinstance(override, dict):
                raise OverrideConfigMalformedError(
                    f"Override config is not a dict, got {type(override).__name__}"
                )
            result.update(override)

    return result

