from __future__ import annotations
from typing import Any, Optional, Protocol, runtime_checkable, List, Sequence

# ----------------------------------------------------------------------
# Strategy protocols
# ----------------------------------------------------------------------
@runtime_checkable
class Validator(Protocol):
    """Validate an item; return the item if valid, otherwise None."""
    def __call__(self, item: Any) -> Optional[Any]: ...


@runtime_checkable
class Normalizer(Protocol):
    """Normalize an item; return the (possibly transformed) item."""
    def __call__(self, item: Any) -> Any: ...


@runtime_checkable
class Deduplicator(Protocol):
    """Deduplicate an item; return the item if not seen before, otherwise None."""
    def __call__(self, item: Any) -> Optional[Any]: ...
    def clear(self) -> None: ...


@runtime_checkable
class Cacher(Protocol):
    """Cache results keyed by the identity of the input data."""
    def get(self, data: Any) -> Optional[Any]: ...
    def set(self, data: Any, value: Any) -> None: ...
    def clear(self) -> None: ...


# ----------------------------------------------------------------------
# Default (no‑op) strategies
# ----------------------------------------------------------------------
class _AlwaysValidValidator:
    def __call__(self, item: Any) -> Any:
        return item


class _IdentityNormalizer:
    def __call__(self, item: Any) -> Any:
        return item


class _NoOpDeduplicator:
    def __call__(self, item: Any) -> Any:
        return item
    def clear(self) -> None: ...


class _NullCacher:
    def get(self, data: Any) -> Optional[Any]:
        return None
    def set(self, data: Any, value: Any) -> None: ...
    def clear(self) -> None: ...


# ----------------------------------------------------------------------
# Concrete strategies
# ----------------------------------------------------------------------
class SimpleValidator:
    """Validate that an item is a dict; handle strict/verbose modes."""
    def __init__(self, strict: bool = False, verbose: bool = False):
        self.strict = strict
        self.verbose = verbose

    def __call__(self, item: Any) -> Optional[Any]:
        if not isinstance(item, dict):
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return None
        return item


class Normalizer:
    """Strip whitespace and lower‑case string values in dict items."""
    def __call__(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }
        return item


class Deduplicator:
    """Remove duplicates based on a string representation of the item."""
    def __init__(self):
        self._seen: set[str] = set()

    def __call__(self, item: Any) -> Optional[Any]:
        key = (
            str(sorted(item.items()))
            if isinstance(item, dict)
            else str(item)
        )
        if key in self._seen:
            return None
        self._seen.add(key)
        return item

    def clear(self) -> None:
        self._seen.clear()


class Cacher:
    """Simple cache that stores results keyed by ``id(data)``."""
    def __init__(self):
        self._cache: dict[int, Any] = {}

    def get(self, data: Any) -> Optional[Any]:
        return self._cache.get(id(data))

    def set(self, data: Any, value: Any) -> None:
        self._cache[id(data)] = value

    def clear(self) -> None:
        self._cache.clear()


# ----------------------------------------------------------------------
# Main processor – fully self‑contained, no boolean flags
# ----------------------------------------------------------------------
class DataProcessor:
    def __init__(
        self,
        validator: Optional[Validator] = None,
        normalizer: Optional[Normalizer] = None,
        deduplicator: Optional[Deduplicator] = None,
        cacher: Optional[Cacher] = None,
    ):
        self._validator = validator if validator is not None else _AlwaysValidValidator()
        self._normalizer = normalizer if normalizer is not None else _IdentityNormalizer()
        self._deduplicator = deduplicator if deduplicator is not None else _NoOpDeduplicator()
        self._cacher = cacher if cacher is not None else _NullCacher()
        self._stats: dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def process(self, data: Sequence[Any]) -> List[Any]:
        # Cache lookup
        cached = self._cacher.get(data)
        if cached is not None:
            self._stats["hits"] += 1
            return cached  # type: ignore[return-value]

        self._stats["misses"] += 1
        result: List[Any] = []

        for item in data:
            # Validation (may raise or return None)
            try:
                validated = self._validator(item)
            except ValueError:
                self._stats["errors"] += 1
                raise

            if validated is None:
                self._stats["errors"] += 1
                continue
            item = validated

            # Normalization
            item = self._normalizer(item)

            # Deduplication
            deduped = self._deduplicator(item)
            if deduped is None:
                continue
            item = deduped

            result.append(item)

        # Store in cache for future calls with the same ``data`` object
        self._cacher.set(data, result)
        return result

    def get_stats(self) -> dict[str, int]:
        """Return a copy of the internal statistics."""
        return dict(self._stats)

    def reset(self) -> None:
        """Reset statistics and clear all mutable strategy state."""
        self._stats = {"hits": 0, "misses": 0, "errors": 0}
        self._cacher.clear()
        if hasattr(self._deduplicator, "clear"):
            self._deduplicator.clear()  # type: ignore[attr-defined]

