from typing import Callable, List, Dict, Any, Iterator

class Table:
    """In-memory SQL-like query engine with a composable fluent API.

    Each mutating method returns a new Table instance to preserve immutability
    and enable safe method chaining.
    """

    def __init__(self, rows: List[Dict[str, Any]], name: str = "table"):
        if rows and not all(isinstance(r, dict) for r in rows):
            raise ValueError("All rows must be dictionaries.")
        self.rows = rows
        self.name = name

    def _new(self, rows: List[Dict[str, Any]]) -> "Table":
        return Table(rows, name=self.name)

    def select(self, *columns: str) -> "Table":
        """Project specific columns. If none provided, keeps all columns."""
        if not self.rows:
            return self._new([])
        cols = list(columns) if columns else list(self.rows[0].keys())
        return self._new([{k: row[k] for k in cols if k in row} for row in self.rows])

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> "Table":
        """Filter rows based on a boolean predicate."""
        return self._new([row for row in self.rows if predicate(row)])

    def join(self, other: "Table", on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> "Table":
        """Inner join with another table. Collisions are resolved by prefixing with table names."""
        new_rows = []
        for l in self.rows:
            for r in other.rows:
                if on(l, r):
                    merged = {}
                    for k, v in l.items():
                        merged[f"{self.name}.{k}" if self.name else k] = v
                    for k, v in r.items():
                        merged[f"{other.name}.{k}" if other.name else k] = v
                    new_rows.append(merged)
        return self._new(new_rows)

    def group_by(self, column: str) -> "Table":
        """Group rows by a column. Keeps the first encountered row per group.
        Note: Full SQL aggregation (SUM, COUNT, etc.) requires extending this class."""
        if not self.rows:
            return self._new([])
        groups: Dict[Any, Dict[str, Any]] = {}
        for row in self.rows:
            key = row.get(column)
            if key not in groups:
                groups[key] = row
        return self._new(list(groups.values()))

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Sort rows by a column. Assumes homogeneous types within the column."""
        if not self.rows:
            return self._new([])
        return self._new(
            sorted(self.rows, key=lambda r: r.get(column), reverse=descending)
        )

    def limit(self, n: int) -> "Table":
        """Return at most n rows."""
        return self._new(self.rows[:n])

    def to_list(self) -> List[Dict[str, Any]]:
        """Materialize the result as a list of dictionaries."""
        return self.rows

    def __iter__(self) -> Iterator[Dict[str, Any]]:
        return iter(self.rows)

    def __repr__(self) -> str:
        return f"Table(name='{self.name}', rows={self.rows})"

