Row = Dict[str, Any]
Predicate = Callable[[Row], bool]
JoinPredicate = Callable[[Row, Row], bool]

class Table:
    """
    An in-memory table that supports a fluent SQL-like query API.
    Rows are stored as dictionaries.
    """

    def __init__(self, rows: Optional[Iterable[Row]] = None) -> None:
        """
        Initialize the table with an optional iterable of rows.
        If no rows are provided, an empty list is used.
        """
        self._rows: List[Row] = list(rows) if rows is not None else []

    def select(self, *columns: str) -> Table:
        """
        Project the table to only include the specified columns.
        If no columns are specified, all columns are included.
        """
        if not columns:
            return Table(self._rows)

        return Table([{col: row[col] for col in columns} for row in self._rows])

    def where(self, predicate: Predicate) -> Table:
        """
        Filter rows based on a predicate function.
        The predicate takes a row (dict) and returns a boolean.
        """
        if not callable(predicate):
            raise TypeError("Predicate must be callable")

        return Table([row for row in self._rows if predicate(row)])

    def join(self, other: Table, on: JoinPredicate) -> Table:
        """
        Perform an inner join with another table based on a join predicate.
        The join predicate takes two rows (left and right) and returns a boolean.
        """
        if not isinstance(other, Table):
            raise TypeError("Other must be a Table")

        if not callable(on):
            raise TypeError("Join predicate must be callable")

        joined_rows: List[Row] = []
        for left_row in self._rows:
            for right_row in other._rows:
                if on(left_row, right_row):
                    joined_rows.append({**left_row, **right_row})

        return Table(joined_rows)

    def group_by(self, column: str) -> GroupedTable:
        """
        Group rows by the values in the specified column.
        Returns a GroupedTable for further aggregation.
        """
        if not isinstance(column, str):
            raise TypeError("Column must be a string")

        groups: Dict[Any, List[Row]] = defaultdict(list)
        for row in self._rows:
            key = row.get(column)
            groups[key].append(row)

        return GroupedTable(groups)

    def order_by(self, column: str, descending: bool = False) -> Table:
        """
        Sort rows by the values in the specified column.
        """
        if not isinstance(column, str):
            raise TypeError("Column must be a string")

        if not all(column in row for row in self._rows):
            raise KeyError(f"Column '{column}' not found in all rows")

        return Table(
            sorted(
                self._rows,
                key=lambda row: row[column],
                reverse=descending,
            )
        )

    def limit(self, n: int) -> Table:
        """
        Limit the number of rows returned to the first n rows.
        """
        if not isinstance(n, int) or n < 0:
            raise ValueError("Limit must be a non-negative integer")

        return Table(self._rows[:n])

    def __len__(self) -> int:
        """Return the number of rows in the table."""
        return len(self._rows)

    def __iter__(self) -> Iterable[Row]:
        """Iterate over the rows in the table."""
        return iter(self._rows)

    def __repr__(self) -> str:
        """Return a string representation of the table."""
        return f"Table(rows={len(self._rows)})"

@dataclass
class GroupedTable:
    """
    A table that has been grouped by a column.
    Supports aggregation operations.
    """

    groups: Dict[Any, List[Row]]

    def aggregate(self, aggregations: Dict[str, Callable[[List[Any]], Any]]) -> Table:
        """
        Apply aggregations to each group.
        aggregations: a dict mapping output column names to aggregation functions.
        """
        if not isinstance(aggregations, dict):
            raise TypeError("Aggregations must be a dict")

        aggregated_rows: List[Row] = []
        for key, rows in self.groups.items():
            row: Row = {"group_key": key}
            for out_col, agg_func in aggregations.items():
                if not callable(agg_func):
                    raise TypeError(f"Aggregation function for '{out_col}' must be callable")
                # Apply aggregation to the values of the specified column across all rows in the group
                # Default to the group key if the column is not present in any row
                col_values = [r.get(out_col, key) for r in rows]
                row[out_col] = agg_func(col_values)
            aggregated_rows.append(row)

        return Table(aggregated_rows)

