"""In-memory SQL-like query engine with a composable fluent API."""

from typing import Any, Callable, Iterator

Row = dict[str, Any]
Predicate = Callable[[Row], bool]
JoinCondition = Callable[[Row, Row], bool]


class Table:
    """In-memory table supporting SQL-like operations via fluent API."""

    def __init__(self, name: str, rows: list[Row] | None = None) -> None:
        self.name = name
        self._rows: list[Row] = rows if rows is not None else []

    def select(self, *columns: str) -> "Table":
        """Project to only the specified columns."""
        if not columns:
            return Table(self.name, self._rows.copy())

        selected = []
        for row in self._rows:
            new_row = {col: row.get(col) for col in columns if col in row}
            if new_row:
                selected.append(new_row)
        return Table(self.name, selected)

    def where(self, predicate: Predicate) -> "Table":
        """Filter rows by a predicate function."""
        filtered = [row for row in self._rows if predicate(row)]
        return Table(self.name, filtered)

    def join(self, other: "Table", on: JoinCondition) -> "Table":
        """Inner join with another table using a condition."""
        joined = []
        for left in self._rows:
            for right in other._rows:
                if on(left, right):
                    joined.append({**left, **right})
        return Table(f"{self.name}_join_{other.name}", joined)

    def group_by(self, column: str) -> dict[Any, "Table"]:
        """Group rows by column; returns dict of grouped Tables."""
        groups: dict[Any, list[Row]] = {}
        for row in self._rows:
            key = row.get(column)
            if key not in groups:
                groups[key] = []
            groups[key].append(row)
        return {k: Table(f"{self.name}_group_{k}", v) for k, v in groups.items()}

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Sort rows by column."""
        sorted_rows = sorted(
            self._rows,
            key=lambda r: r.get(column),
            reverse=descending,
        )
        return Table(self.name, sorted_rows)

    def limit(self, n: int) -> "Table":
        """Return first n rows."""
        return Table(self.name, self._rows[:n])

    def __iter__(self) -> Iterator[Row]:
        return iter(self._rows)

    def __len__(self) -> int:
        return len(self._rows)

    def to_list(self) -> list[Row]:
        """Materialize to a list of rows."""
        return self._rows.copy()


