from typing import List, Dict, Any, Callable, Optional

# Type alias for a single row (dictionary)
Row = Dict[str, Any]

class Table:
    """
    An in-memory table implementation supporting a fluent SQL-like query API.
    """

    def __init__(self, data: List[Row], name: str = "table"):
        # Create a copy of the data to ensure immutability during operations
        self._data: List[Row] = list(data)
        self._name: str = name

    @property
    def rows(self) -> List[Row]:
        """Returns the underlying list of rows."""
        return self._data

    def _create_new(self, data: List[Row]) -> 'Table':
        """Helper to create a new Table instance from transformed data."""
        return Table(data, self._name)

    # -------------------------------------------------------------------------
    # Query Operations
    # -------------------------------------------------------------------------

    def select(self, *columns: str) -> 'Table':
        """
        Selects specific columns. If no columns are provided, selects all.
        Example: table.select('name', 'age')
        """
        if not columns:
            return self._create_new(self._data)

        # Filter keys in each row
        new_data = []
        for row in self._data:
            new_row = {col: row[col] for col in columns if col in row}
            new_data.append(new_row)

        return self._create_new(new_data)

    def where(self, predicate: Callable[[Row], bool]) -> 'Table':
        """
        Filters rows based on a predicate function.
        Example: table.where(lambda r: r['age'] > 25)
        """
        filtered_data = [row for row in self._data if predicate(row)]
        return self._create_new(filtered_data)

    def join(self, other: 'Table', on: Callable[[Row, Row], bool]) -> 'Table':
        """
        Joins with another table based on a predicate.
        Performs an inner join (cross product filtered by 'on' condition).
        Example: table.join(other_table, lambda l, r: l['id'] == r['user_id'])
        """
        joined_data = []
        for left_row in self._data:
            for right_row in other._data:
                if on(left_row, right_row):
                    # Merge rows (right row overwrites left row if keys collide)
                    merged = {**left_row, **right_row}
                    joined_data.append(merged)

        return self._create_new(joined_data)

    def group_by(self, column: str) -> 'Table':
        """
        Groups rows by a specific column.
        Returns a new table where each row represents a group.
        The grouped rows are stored in a special '_group' key as a list.
        """
        groups: Dict[Any, List[Row]] = {}

        for row in self._data:
            key = row.get(column)
            if key not in groups:
                groups[key] = []
            groups[key].append(row)

        # Transform into a list of dicts representing the groups
        result_data = [
            {column: key, '_group': rows} 
            for key, rows in groups.items()
        ]

        return self._create_new(result_data)

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        """
        Orders the table by a specific column.
        """
        sorted_data = sorted(
            self._data, 
            key=lambda x: x.get(column), 
            reverse=descending
        )
        return self._create_new(sorted_data)

    def limit(self, n: int) -> 'Table':
        """
        Limits the number of rows.
        """
        return self._create_new(self._data[:n])

    def __repr__(self):
        return f"<Table {self._name} rows={len(self._data)}>"

