class Table:
    def __init__(self, rows: List[Dict[str, Any]]):
        if not isinstance(rows, list) or not all(isinstance(row, dict) for row in rows):
            raise ValueError("Rows must be a list of dictionaries.")
        self.rows = rows

    def select(self, *columns: str) -> 'Table':
        if not columns:
            raise ValueError("At least one column must be specified.")
        selected_rows = [{col: row[col] for col in columns if col in row} for row in self.rows]
        return Table(selected_rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'Table':
        filtered_rows = [row for row in self.rows if predicate(row)]
        return Table(filtered_rows)

    def join(self, other_table: 'Table', on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> 'Table':
        joined_rows = []
        for left_row in self.rows:
            for right_row in other_table.rows:
                if on(left_row, right_row):
                    joined_row = {**left_row, **right_row}
                    joined_rows.append(joined_row)
        return Table(joined_rows)

    def group_by(self, column: str) -> Dict[Any, List[Dict[str, Any]]]:
        if not all(column in row for row in self.rows):
            raise ValueError(f"Column '{column}' does not exist in all rows.")
