        for row in self.rows:
            key = row[column]
            if key not in grouped:
                grouped[key] = []
            grouped[key].append(row)
        return grouped

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        if not all(column in row for row in self.rows):
            raise ValueError(f"Column '{column}' does not exist in all rows.")
        sorted_rows = sorted(self.rows, key=lambda row: row[column], reverse=descending)
        return Table(sorted_rows)

    def limit(self, n: int) -> 'Table':
        if not isinstance(n, int) or n < 0:
            raise ValueError("Limit must be a non-negative integer.")
        limited_rows = self.rows[:n]
        return Table(limited_rows)

