        if not columns:
            return self

        def project(row):
            return {col: row[col] for col in columns if col in row}

        return Query(map(project, self._data))

    def join(self, other: 'Table', on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> 'Query':
        """Performs an inner join with another table."""
        def join_generator():
            # We must materialize the other table to avoid repeated iteration
            other_rows = list(other.rows) 
            for left_row in self._data:
                for right_row in other_rows:
                    if on(left_row, right_row):
                        # Merge dictionaries, right side overrides left on key collision
                        yield {**left_row, **right_row}

        return Query(join_generator())

    def order_by(self, column: str, descending: bool = False) -> 'Query':
        """Sorts the data. Note: This materializes the query."""
        sorted_data = sorted(
            self._data, 
            key=lambda x: x.get(column), 
            reverse=descending
        )
        return Query(sorted_data)

    def group_by(self, column: str) -> 'Query':
        """
        Groups data by a column. 
        Returns a list of dicts where the grouped column is the key 
        and 'rows' contains the list of matching records.
        """
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._data:
            val = row.get(column)
            groups.setdefault(val, []).append(row)

        result = [{"group": k, "rows": v} for k, v in groups.items()]
        return Query(result)

    def limit(self, n: int) -> 'Query':
        """Limits the number of returned rows."""
        def limit_gen():
            for i, row in enumerate(self._data):
                if i >= n: break
                yield row
        return Query(limit_gen())

    def execute(self) -> List[Dict[str, Any]]:
        """Materializes the query into a list."""
        return list(self._data)

    def __iter__(self):
        return iter(self._data)

