from typing import Callable, List, Dict, Any, Iterator, TypeVar

T = TypeVar("T", bound="Table")


class Table:
    """In-memory SQL-like query engine with a composable fluent API."""

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        if not isinstance(rows, list):
            raise TypeError("rows must be a list")
        if rows and not all(isinstance(r, dict) for r in rows):
            raise TypeError("Each row must be a dictionary")
        self._base_rows: List[Dict[str, Any]] = rows
        # Store operations as a pipeline to enable lazy evaluation and chaining
        self._operations: List[Callable[[List[Dict[str, Any]]], List[Dict[str, Any]]]] = []

    def _with_op(self, op: Callable[[List[Dict[str, Any]]], List[Dict[str, Any]]]) -> Table:
        """Return a new Table instance with an additional operation appended to the pipeline."""
        new_table = Table.__new__(Table)
        new_table._base_rows = self._base_rows
        new_table._operations = self._operations + [op]
        return new_table

    @property
    def rows(self) -> List[Dict[str, Any]]:
        """Execute the query pipeline lazily and return the resulting rows."""
        result = self._base_rows
        for op in self._operations:
            result = op(result)
        return result

    def __iter__(self) -> Iterator[Dict[str, Any]]:
        return iter(self.rows)

    def __len__(self) -> int:
        return len(self.rows)

    def __repr__(self) -> str:
        return f"Table(rows={self.rows})"

    def select(self, *columns: str) -> Table:
        if not columns:
            raise ValueError("select requires at least one column")
        if not all(isinstance(c, str) and c for c in columns):
            raise ValueError("Columns must be non-empty strings")

        def op(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            # Project only requested columns; gracefully omit missing keys
            return [{c: r[c] for c in columns if c in r} for r in rows]
        return self._with_op(op)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        if not callable(predicate):
            raise TypeError("predicate must be callable")

        def op(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            return [r for r in rows if predicate(r)]
        return self._with_op(op)

    def join(self, other: Table, on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> Table:
        if not isinstance(other, Table):
            raise TypeError("other must be a Table instance")
        if not callable(on):
            raise TypeError("on must be callable")

        def op(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            # Evaluate other lazily so chained queries on the right table work correctly
            other_rows = other.rows
            return [
                {**left, **right}
                for left in rows
                for right in other_rows
                if on(left, right)
            ]
        return self._with_op(op)

    def group_by(self, column: str) -> Table:
        if not isinstance(column, str) or not column:
            raise ValueError("column must be a non-empty string")

        def op(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            # Retain the first encountered row per unique group value.
            # Aggregation functions are outside the scope of this minimal engine.
            seen: Dict[Any, Dict[str, Any]] = {}
            for r in rows:
                key = r.get(column)
                if key not in seen:
                    seen[key] = r
            return list(seen.values())
        return self._with_op(op)

    def order_by(self, column: str, descending: bool = False) -> Table:
        if not isinstance(column, str) or not column:
            raise ValueError("column must be a non-empty string")

        def op(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            # Push None/missing values to the end regardless of sort direction
            def sort_key(r: Dict[str, Any]) -> tuple:
                val = r.get(column)
                return (val is None, val)
            return sorted(rows, key=sort_key, reverse=descending)
        return self._with_op(op)

    def limit(self, n: int) -> Table:
        if not isinstance(n, int) or n < 0:
            raise ValueError("n must be a non-negative integer")

        def op(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            return rows[:n]
        return self._with_op(op)


