class GroupedTable:
    def __init__(self, name: str, groups: Dict[Any, List[Dict[str, Any]]]):
        self.name = name
        self.groups = groups

    def aggregate(self, column: str, operation: str) -> 'Table':
        """Perform an aggregation on a column within each group."""
        new_rows = []
        for key, group in self.groups.items():
            values = [row.get(column) for row in group if column in row]

            if not values:
                continue

            if operation == 'count':
                result = len(values)
            elif operation == 'sum':
                result = sum(values)
            elif operation == 'avg':
