class Table:
    def __init__(self, name: str, rows: List[Dict[str, Any]]):
        self.name = name
        self.rows = rows

    def select(self, *columns: str) -> 'Query':
        return Query(self).select(*columns)

    def where(self, predicate: Callable[[Dict], bool]) -> 'Query':
        return Query(self).where(predicate)

    def join(self, other: 'Table', on: Callable[[Dict, Dict], bool]) -> 'Query':
        return Query(self).join(other, on)

    def group_by(self, column: str) -> 'Query':
        return Query(self).group_by(column)

    def order_by(self, column: str, descending: bool = False) -> 'Query':
        return Query(self).order_by(column, descending)

    def limit(self, n: int) -> 'Query':
        return Query(self).limit(n)

    def __repr__(self):
        return f"Table({self.name}, rows={self.rows})"


class Query:
    def __init__(self, table: Table):
        self._table = table
        self._rows = deepcopy(table.rows)
        self._columns: Optional[List[str]] = None
        self._group_col: Optional[str] = None

    def select(self, *columns: str) -> 'Query':
        if not columns:
            return self
        # Keep only requested columns
        self._rows = [{k: row[k] for k in columns if k in row} for row in self._rows]
        self._columns = list(columns)
        return self

    def where(self, predicate: Callable[[Dict], bool]) -> 'Query':
        self._rows = [row for row in self._rows if predicate(row)]
        return self

    def join(self, other: Table, on: Callable[[Dict, Dict], bool]) -> 'Query':
        joined = []
        for left_row in self._rows:
            for right_row in other.rows:
                if on(left_row, right_row):
                    # Merge dicts, right side wins on collision
                    merged = {**left_row, **right_row}
                    joined.append(merged)
        self._rows = joined
        return self

    def group_by(self, column: str) -> 'Query':
        groups: Dict[Any, List[Dict]] = {}
        for row in self._rows:
            key = row.get(column)
            if key not in groups:
                groups[key] = []
            groups[key].append(row)

        # Return a table with the group key and a list of grouped rows
        self._rows = [{column: k, '_group': v} for k, v in groups.items()]
        self._group_col = column
        return self

    def order_by(self, column: str, descending: bool = False) -> 'Query':
        self._rows.sort(key=lambda r: r.get(column, ''), reverse=descending)
        return self

    def limit(self, n: int) -> 'Query':
        self._rows = self._rows[:n]
        return self

    def execute(self) -> Table:
        return Table(f"QueryResult_{self._table.name}", self._rows)

    def __repr__(self):
        return f"Query({len(self._rows)} rows)"


