import threading
from typing import Protocol, List, Any, Dict, Set, Tuple, Optional


class ProcessingStep(Protocol):
    """Protocol for processing steps that can filter or transform items."""
    def process(self, item: Any, context: "ProcessingContext") -> Optional[Any]:
        ...


class ProcessingContext:
    """Shared mutable state for a single processing run."""
    def __init__(self, stats: Dict[str, int], cache: Dict[int, List[Any]], seen: Set[str]):
        self.stats = stats
        self.cache = cache
        self.seen = seen


class ValidationStep:
    """Validates that items are dictionaries and handles failures based on configuration."""
    def __init__(self, strict: bool = False, verbose: bool = False):
        self.strict = strict
        self.verbose = verbose

    def process(self, item: Any, ctx: ProcessingContext) -> Optional[Any]:
        if not isinstance(item, dict):
            ctx.stats["errors"] += 1
            if self.strict:
                raise ValueError(f"Expected dict, got {type(item)}")
            if self.verbose:
                print(f"Skipping invalid item: {item}")
            return None
        return item


class DeduplicationStep:
    """Removes duplicate items based on a deterministic string key."""
    def process(self, item: Any, ctx: ProcessingContext) -> Optional[Any]:
        key = str(sorted(item.items()) if isinstance(item, dict) else item)
        if key in ctx.seen:
            return None
        ctx.seen.add(key)
        return item


class NormalizationStep:
    """Normalizes string values in dictionaries by stripping and lowercasing."""
    def process(self, item: Any, ctx: ProcessingContext) -> Optional[Any]:
        if isinstance(item, dict):
            return {k: (v.strip().lower() if isinstance(v, str) else v)
                    for k, v in item.items()}
        return item


class DataProcessor:
    """
    Processes a list of data items through a composable pipeline of steps.

    Supports caching results by input object identity and tracks per-instance statistics.
    Thread-safe for concurrent use across multiple instances.
    """
    def __init__(self, steps: List[ProcessingStep], cache_enabled: bool = False):
        self._steps = steps
        self._cache_enabled = cache_enabled
        self._cache: Dict[int, List[Any]] = {}
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}
        self._lock = threading.Lock()

    def process(self, data: List[Any]) -> List[Any]:
        if self._cache_enabled:
            data_id = id(data)
            with self._lock:
                if data_id in self._cache:
                    self._stats["hits"] += 1
                    return self._cache[data_id]
                self._stats["misses"] += 1

        seen: Set[str] = set()
        ctx = ProcessingContext(self._stats, self._cache, seen)
        result: List[Any] = []

        for item in data:
            for step in self._steps:
                item = step.process(item, ctx)
                if item is None:
                    break
            if item is not None:
                result.append(item)

        if self._cache_enabled:
            with self._lock:
                self._cache[id(data)] = result

        return result

    def get_stats(self) -> Dict[str, int]:
        with self._lock:
            return dict(self._stats)

    def reset(self) -> None:
        with self._lock:
            self._cache.clear()
            self._stats = {"hits": 0, "misses": 0, "errors": 0}

