T = TypeVar('T', bound='Table')


class Table:
    """In-memory SQL-like query engine with a composable fluent API.

    Each mutating operation returns a new Table instance to preserve immutability
    and enable safe method chaining.
    """

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        if not isinstance(rows, list):
            raise TypeError("rows must be a list of dicts")
        # Shallow copy of dicts is sufficient for typical flat row structures
        self._rows: List[Dict[str, Any]] = [dict(r) for r in rows]

    def _new(self: T, rows: List[Dict[str, Any]]) -> T:
        return self.__class__(rows)

    def select(self, *columns: str) -> Table:
        if not columns:
            return self._new(self._rows)
        if not self._rows:
            return self._new([])

        for row in self._rows:
            for col in columns:
                if col not in row:
                    raise KeyError(f"Column '{col}' not found in row: {row}")

        return self._new([{col: row[col] for col in columns} for row in self._rows])

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        return self._new([row for row in self._rows if predicate(row)])

    def join(self, other: Table, on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> Table:
        joined = []
        for left in self._rows:
            for right in other._rows:
                if on(left, right):
                    merged = {}
                    for k, v in left.items():
                        if k in merged:
                            raise ValueError(
                                f"Key collision in join: '{k}'. "
                                "Use select() to disambiguate columns before joining."
                            )
                        merged[k] = v
                    for k, v in right.items():
                        if k in merged:
                            raise ValueError(
                                f"Key collision in join: '{k}'. "
                                "Use select() to disambiguate columns before joining."
                            )
                        merged[k] = v
                    joined.append(merged)
        return self._new(joined)

    def group_by(self, column: str) -> Table:
        if not self._rows:
            return self._new([])
        if column not in self._rows[0]:
            raise KeyError(f"Column '{column}' not found")

        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._rows:
            groups.setdefault(row[column], []).append(row)

        # Returns a Table where each row contains the group key and a '_group' 
        # list of original rows. Aggregates are not implemented per spec.
        return self._new([{column: key, '_group': rows} for key, rows in groups.items()])

    def order_by(self, column: str, descending: bool = False) -> Table:
        if not self._rows:
            return self._new([])
        if column not in self._rows[0]:
            raise KeyError(f"Column '{column}' not found")

        return self._new(sorted(self._rows, key=lambda r: r[column], reverse=descending))

    def limit(self, n: int) -> Table:
        if n < 0:
            raise ValueError("n must be non-negative")
        return self._new(self._rows[:n])

    def __len__(self) -> int:
        return len(self._rows)

    def __iter__(self):
        return iter(self._rows)

    def __repr__(self) -> str:
        return f"Table(rows={self._rows})"


