from typing import Any, Callable, Dict, List, Optional, Sequence, TypeVar, Generic, Iterable
from itertools import groupby
from operator import itemgetter

T = TypeVar("T")

class Table:
    """
    An in-memory SQL-like query engine providing a fluent API for 
    manipulating collections of dictionary-based rows.
    """

    def __init__(self, rows: Iterable[Dict[str, Any]]):
        # Store as a list to allow multiple passes over the data
        self._rows = list(rows)

    def select(self, *columns: str) -> "Table":
        """Projects only the specified columns from each row."""
        if not columns:
            return self

        def project(row: Dict[str, Any]) -> Dict[str, Any]:
            try:
                return {col: row[col] for col in columns}
            except KeyError as e:
                raise KeyError(f"Column {e} not found in table schema") from e

        return Table(project(row) for row in self._rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> "Table":
        """Filters rows based on a boolean predicate."""
        return Table(row for row in self._rows if predicate(row))

    def join(self, other: "Table", on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> "Table":
        """
        Performs an inner join with another table based on a join predicate.
        Merges dictionaries; right table keys override left table keys on collision.
        """
        joined_rows = []
        for left_row in self._rows:
            for right_row in other._rows:
                if on(left_row, right_row):
                    # Merge dictionaries (Python 3.9+ syntax)
                    joined_rows.append({**left_row, **right_row})

        return Table(joined_rows)

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Sorts the rows by a specific column."""
        try:
            sorted_rows = sorted(
                self._rows, 
                key=itemgetter(column), 
                reverse=descending
            )
            return Table(sorted_rows)
        except KeyError as e:
            raise KeyError(f"Column {e} not found for sorting") from e

    def limit(self, n: int) -> "Table":
        """Restricts the result set to the first n rows."""
        if n < 0:
            raise ValueError("Limit must be a non-negative integer")
        return Table(self._rows[:n])

    def group_by(self, column: str) -> "GroupedTable":
        """Groups rows by a column, returning a GroupedTable for aggregation."""
        return GroupedTable(self, column)

    def execute(self) -> List[Dict[str, Any]]:
        """Returns the final result set as a list of dictionaries."""
        return self._rows

    def __repr__(self) -> str:
        return f"Table(rows={len(self._rows)})"


class GroupedTable:
    """
    Helper class to handle aggregations after a group_by operation.
    """

    def __init__(self, table: Table, group_column: str):
        self._table = table
        self._group_column = group_column

    def aggregate(self, aggregations: Dict[str, Callable[[List[Dict[str, Any]]], Any]]) -> Table:
        """
        Applies aggregation functions to each group.
        Example: aggregations={"total_sales": lambda rows: sum(r['price'] for r in rows)}
        """
        # Sort is required for itertools.groupby
        try:
            sorted_rows = sorted(self._table._rows, key=itemgetter(self._group_column))
        except KeyError as e:
            raise KeyError(f"Grouping column {e} not found") from e

        results = []
        for key, group in groupby(sorted_rows, key=itemgetter(self._group_column)):
            group_list = list(group)
            row = {self._group_column: key}
            for alias, func in aggregations.items():
                row[alias] = func(group_list)
            results.append(row)

        return Table(results)


