from typing import List, Dict, Any, Callable, Optional

class Table:
    def __init__(self, rows: List[Dict[str, Any]]):
        self._rows = rows

    def select(self, *columns: str) -> 'Table':
        """Return a new Table with only the specified columns (projection).
        If no columns are given, a copy of the current table is returned."""
        if not columns:
            return Table(self._rows[:])
        new_rows = [{col: row[col] for col in columns} for row in self._rows]
        return Table(new_rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'Table':
        """Return a new Table containing only rows that satisfy the predicate."""
        new_rows = [row for row in self._rows if predicate(row)]
        return Table(new_rows)

    def join(self, other: 'Table', on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> 'Table':
        """Inner join with another Table. The join condition is given by the callable `on`,
        which receives a left row and a right row and returns True when they match.
        The resulting rows merge left and right (right keys overwrite left if duplicates)."""
        new_rows = []
        for lrow in self._rows:
            for rrow in other._rows:
                if on(lrow, rrow):
                    merged = {**lrow, **rrow}   # right overwrites left on key conflict
                    new_rows.append(merged)
        return Table(new_rows)

    def group_by(self, column: str) -> 'Table':
        """Group rows by the given column. Returns a new Table where each row represents one group
        and contains the group key (the column value) and a list of original rows under the key 'rows'."""
        groups: Dict[Any, List[Dict]] = {}
        for row in self._rows:
            key = row[column]
            if key not in groups:
                groups[key] = []
            groups[key].append(row)
        new_rows = [{column: k, 'rows': v} for k, v in groups.items()]
        return Table(new_rows)

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        """Return a new Table sorted by the given column (default ascending)."""
        new_rows = sorted(self._rows, key=lambda row: row[column], reverse=descending)
        return Table(new_rows)

    def limit(self, n: int) -> 'Table':
        """Return a new Table with at most the first `n` rows."""
        new_rows = self._rows[:n]
        return Table(new_rows)

    def __repr__(self) -> str:
        """Pretty print the rows as a JSON-like string."""
        import json
        return json.dumps(self._rows, indent=2, default=str)

