Row = Dict[str, Any]
Predicate = Callable[[Row], bool]
JoinCondition = Callable[[Row, Row], bool]

class Table:
    def __init__(self, name: str, rows: Optional[List[Row]] = None):
        self.name = name
        self.rows = rows if rows is not None else []

    def select(self, *columns: str) -> 'Table':
        """Select specific columns from the table."""
        if not columns:
            return self

        new_rows = []
        for row in self.rows:
            new_row = {col: row[col] for col in columns if col in row}
            new_rows.append(new_row)

        return Table(self.name, new_rows)

    def where(self, predicate: Predicate) -> 'Table':
        """Filter rows based on a predicate function."""
        filtered_rows = [row for row in self.rows if predicate(row)]
        return Table(self.name, filtered_rows)

    def join(self, other: 'Table', on: JoinCondition) -> 'Table':
        """Perform an inner join with another table."""
        joined_rows = []
        for left_row in self.rows:
            for right_row in other.rows:
                if on(left_row, right_row):
                    joined_row = {**left_row, **right_row}
                    joined_rows.append(joined_row)
        return Table(f"{self.name}_joined_{other.name}", joined_rows)

    def group_by(self, column: str) -> 'GroupedTable':
        """Group rows by a column value."""
        groups = {}
        for row in self.rows:
            key = row.get(column)
            if key not in groups:
                groups[key] = []
            groups[key].append(row)
        return GroupedTable(self.name, groups)

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        """Sort rows by a column value."""
        reverse = descending
        sorted_rows = sorted(self.rows, key=lambda x: x.get(column), reverse=reverse)
        return Table(self.name, sorted_rows)

    def limit(self, n: int) -> 'Table':
        """Limit the number of rows returned."""
        return Table(self.name, self.rows[:n])

    def __repr__(self) -> str:
        return f"Table(name={self.name}, rows={len(self.rows)})"

class GroupedTable:
    def __init__(self, name: str, groups: Dict[Any, List[Row]]):
        self.name = name
        self.groups = groups

    def select(self, *columns: str) -> 'Table':
        """Select columns after grouping."""
        new_rows = []
        for group_key, group_rows in self.groups.items():
            for row in group_rows:
                new_row = {col: row[col] for col in columns if col in row}
                new_rows.append(new_row)
        return Table(self.name, new_rows)

    def aggregate(self, column: str, operation: str) -> 'Table':
        """Perform an aggregation on a column."""
        operations = {
            'count': lambda g: len(g),
            'sum': lambda g: sum(r[column] for r in g),
            'avg': lambda g: sum(r[column] for r in g) / len(g),
            'min': lambda g: min(r[column] for r in g),
            'max': lambda g: max(r[column] for r in g),
        }

        if operation not in operations:
            raise ValueError(f"Unsupported operation: {operation}")

        new_rows = []
        for key, group in self.groups.items():
            new_row = {
                'group_key': key,
                f'{column}_{operation}': operations[operation](group)
            }
            new_rows.append(new_row)

        return Table(f"{self.name}_agg_{operation}", new_rows)

    def __repr__(self) -> str:
        return f"GroupedTable(name={self.name}, groups={len(self.groups)})"

