            [{col: row[col] for col in columns if col in row} for row in self.rows]
        )

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'Table':
        """Filter rows based on a predicate function."""
        return Table(
            self.name,
            [row.copy() for row in self.rows if predicate(row)]
        )

    def join(
        self,
        other: 'Table',
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool]
    ) -> 'Table':
