from typing import Any, Callable, Dict, List, Optional

class Table:
    """
    A lightweight in-memory SQL-like query engine.
    Each row is a dictionary mapping column names to values.
    All query methods return a new Table instance (immutable chain).
    """

    def __init__(self, rows: List[Dict[str, Any]]):
        self._rows = rows

    def __repr__(self) -> str:
        return f"Table({self._rows})"

    # ---- Query building methods ----

    def select(self, *columns: str) -> "Table":
        """Return a new Table with only the specified columns."""
        new_rows = [
            {col: row[col] for col in columns if col in row}
            for row in self._rows
        ]
        return Table(new_rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> "Table":
        """Return a new Table containing only rows that satisfy the predicate."""
        new_rows = [row for row in self._rows if predicate(row)]
        return Table(new_rows)

    def join(
        self,
        other: "Table",
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool],
    ) -> "Table":
        """
        Perform an inner join with another Table.
        The `on` function takes a left row and a right row and returns True if they match.
        Combined rows are produced by merging the two dicts (right overwrites left on key conflicts).
        """
        new_rows = []
        for left in self._rows:
            for right in other._rows:
                if on(left, right):
                    merged = {**left, **right}
                    new_rows.append(merged)
        return Table(new_rows)

    def group_by(self, column: str) -> "Table":
        """
        Group rows by the given column and return a new Table with two columns:
        the grouping column and a 'count' for each distinct value.
        """
        groups: Dict[Any, List[Dict]] = {}
        for row in self._rows:
            key = row[column]
            groups.setdefault(key, []).append(row)

        new_rows = [
            {column: key, "count": len(rows)}
            for key, rows in groups.items()
        ]
        return Table(new_rows)

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Return a new Table sorted by the given column."""
        new_rows = sorted(
            self._rows,
            key=lambda r: r.get(column),
            reverse=descending,
        )
        return Table(new_rows)

    def limit(self, n: int) -> "Table":
        """Return a new Table consisting of the first n rows."""
        return Table(self._rows[:n])


# ===================== USAGE EXAMPLES =====================

