        if not self._rows:
            return Table([])
        if column not in self._rows[0]:
            raise KeyError(f"Column '{column}' not found in table")
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._rows:
            key = row[column]
            groups.setdefault(key, []).append(row)
        group_rows: List[Dict[str, Any]] = [
            {column: key, "_rows": rows}
            for key, rows in groups.items()
        ]
        return Table(group_rows)

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Return a new Table sorted by the given column."""
        if not self._rows:
            return Table([])
        if column not in self._rows[0]:
            raise KeyError(f"Column '{column}' not found in table")
        return Table(
            sorted(self._rows, key=lambda row: row[column], reverse=descending)
        )

    def limit(self, n: int) -> "Table":
        """Return a new Table with only the first n rows."""
        if not isinstance(n, int) or n < 0:
            raise ValueError("limit() requires a non-negative integer")
        if n == 0:
            return Table([])
        return Table(self._rows[:n])

    def _validate_column(self, column: str) -> None:
        """Helper to check that column exists in first row (if any)."""
        if not self._rows:
            return  # cannot validate, empty table
        if column not in self._rows[0]:
            raise KeyError(
                f"Column '{column}' not in table. Available: "
                f"{list(self._rows[0].keys())}"
