from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, Iterator, List, Optional, Union


@dataclass
class Table:
    """In-memory table storing rows as dictionaries."""

    _data: List[Dict[str, Any]]
    _name: str = "anonymous"

    def __post_init__(self) -> None:
        self._data = list(self._data)  # Defensive copy

    def select(self, *columns: str) -> Table:
        """Project only the specified columns."""
        if not columns:
            return Table(self._data, self._name)

        if self._data:
            missing = set(columns) - set(self._data[0].keys())
            if missing:
                raise ValueError(f"Columns not found: {missing}")

        selected = [
            {col: row[col] for col in columns if col in row}
            for row in self._data
        ]
        return Table(selected, f"{self._name}_selected")

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        """Filter rows using a predicate function."""
        filtered = [row for row in self._data if predicate(row)]
        return Table(filtered, f"{self._name}_filtered")

    def join(
        self,
        other: Table,
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool],
    ) -> Table:
        """Inner join with another table using a predicate."""
        result = []
        for left in self._data:
            for right in other._data:
                if on(left, right):
                    result.append({**left, **right})
        return Table(result, f"{self._name}_joined")

    def group_by(self, column: str) -> GroupedTable:
        """Group rows by the specified column."""
        if self._data and column not in self._data[0]:
            raise ValueError(f"Column '{column}' not found in table")

        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._data:
            key = row.get(column)
            groups.setdefault(key, []).append(row)

        return GroupedTable(groups, column, self._name)

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Sort rows by the specified column."""
        if self._data and column not in self._data[0]:
            raise ValueError(f"Column '{column}' not found in table")

        sorted_data = sorted(
            self._data,
            key=lambda row: row.get(column),
            reverse=descending,
        )
        return Table(sorted_data, f"{self._name}_ordered")

    def limit(self, n: int) -> Table:
        """Return at most n rows."""
        if n < 0:
            raise ValueError("Limit must be non-negative")
        return Table(self._data[:n], f"{self._name}_limited")

    def to_list(self) -> List[Dict[str, Any]]:
        """Materialize the table as a list of dictionaries."""
        return list(self._data)

    def __iter__(self) -> Iterator[Dict[str, Any]]:
        return iter(self._data)

    def __len__(self) -> int:
        return len(self._data)


@dataclass
class GroupedTable:
    """Intermediate result from group_by, providing aggregation methods."""

    _groups: Dict[Any, List[Dict[str, Any]]]
    _group_column: str
    _source_name: str

    def _aggregate(
        self,
        agg_name: str,
        func: Callable[[List[Dict[str, Any]]], Any],
        column: Optional[str] = None,
    ) -> Table:
        data = []
        for key, rows in self._groups.items():
            result = {self._group_column: key, agg_name: func(rows, column) if column else func(rows)}
            data.append(result)
        return Table(data, f"{self._source_name}_{agg_name}")

    def count(self, column: Optional[str] = None) -> Table:
        """Count rows, optionally counting non-null values of a column."""
        def count_rows(rows: List[Dict[str, Any]], col: Optional[str]) -> int:
            if col is None:
                return len(rows)
            return sum(1 for r in rows if r.get(col) is not None)
        return self._aggregate("count", count_rows, column)

    def sum(self, column: str) -> Table:
        """Sum numeric values in the specified column."""
        def sum_rows(rows: List[Dict[str, Any]], col: str) -> Union[int, float]:
            return sum(r.get(col, 0) for r in rows)
        return self._aggregate("sum", sum_rows, column)

    def avg(self, column: str) -> Table:
        """Average numeric values in the specified column."""
        def avg_rows(rows: List[Dict[str, Any]], col: str) -> Optional[float]:
            values = [r.get(col, 0) for r in rows if r.get(col) is not None]
            return sum(values) / len(values) if values else None
        return self._aggregate("avg", avg_rows, column)

    def min(self, column: str) -> Table:
        """Minimum value in the specified column."""
        def min_rows(rows: List[Dict[str, Any]], col: str) -> Optional[Any]:
            return min((r.get(col) for r in rows if r.get(col) is not None), default=None)
        return self._aggregate("min", min_rows, column)

    def max(self, column: str) -> Table:
        """Maximum value in the specified column."""
        def max_rows(rows: List[Dict[str, Any]], col: str) -> Optional[Any]:
            return max((r.get(col) for r in rows if r.get(col) is not None), default=None)
        return self._aggregate("max", max_rows, column)


