from __future__ import annotations

import threading
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Set, Tuple


@dataclass
class DataProcessorConfig:
    """Configuration for processing steps and behavior modes."""
    strict: bool = False
    verbose: bool = False
    cache: bool = False
    normalize: bool = False
    dedupe: bool = False
    validate: bool = False


class DataProcessor:
    """Processes a sequence of items with optional validation, deduplication, normalization, and caching.

    All state is instance-scoped, making the class safe for concurrent use across multiple instances.
    """

    def __init__(self, config: Optional[DataProcessorConfig] = None) -> None:
        self.config = config or DataProcessorConfig()
        self._cache: Dict[int, List[Any]] = {}
        self._stats: Dict[str, int] = {"hits": 0, "misses": 0, "errors": 0}
        self._lock = threading.Lock()

    def process(self, data: List[Any]) -> List[Any]:
        """Process the input data according to the configured pipeline."""
        if self.config.cache and id(data) in self._cache:
            with self._lock:
                self._stats["hits"] += 1
            return self._cache[id(data)]

        with self._lock:
            self._stats["misses"] += 1

        result: List[Any] = []
        seen: Set[str] = set()

        for item in data:
            if self.config.validate:
                if not isinstance(item, dict):
                    with self._lock:
                        self._stats["errors"] += 1
                    if self.config.strict:
                        raise ValueError(f"Expected dict, got {type(item)}")
                    if self.config.verbose:
                        print(f"Skipping invalid item: {item}")
                    continue

            if self.config.dedupe:
                key = str(sorted(item.items()) if isinstance(item, dict) else item)
                if key in seen:
                    continue
                seen.add(key)

            if self.config.normalize and isinstance(item, dict):
                item = {
                    k: (v.strip().lower() if isinstance(v, str) else v)
                    for k, v in item.items()
                }

            result.append(item)

        if self.config.cache:
            with self._lock:
                self._cache[id(data)] = result

        return result

    def get_stats(self) -> Dict[str, int]:
        """Return a snapshot of the current processing statistics."""
        with self._lock:
            return dict(self._stats)

    def reset(self) -> None:
        """Clear all cached data and reset statistics."""
        with self._lock:
            self._cache.clear()
            self._stats["hits"] = 0
            self._stats["misses"] = 0
            self._stats["errors"] = 0

