        under ``None``.
        """
        counts: Dict[Any, int] = {}
        for row in self._rows:
            key = row.get(column)
            counts[key] = counts.get(key, 0) + 1

        grouped_rows = [
            {column: key, "count": cnt} for key, cnt in counts.items()
        ]
        return Table(grouped_rows)

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Return a new table sorted by *column* (stable sort).

        Missing keys are treated as ``None`` and sort before any value.
        """
        def sort_key(row: Dict[str, Any]) -> Any:
            val = row.get(column)
            # Treat None as less than anything else
            return (0 if val is None else 1, val)

        sorted_rows = sorted(self._rows, key=sort_key, reverse=descending)
        return Table(sorted_rows)

    def limit(self, n: int) -> Table:
        """Return a new table with at most the first *n* rows."""
        if n < 0:
            raise ValueError(f"limit must be non-negative, got {n}")
        return Table(self._rows[:n])

    # ------------------------------------------------------------------
    # Utility methods
    # ------------------------------------------------------------------

    def __repr__(self) -> str:
        return f"Table({len(self._rows)} rows)"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Table):
            return NotImplemented
        return self._rows == other._rows

