class Table:
    """In-memory SQL-like query engine with a composable fluent API."""

    def __init__(self, rows: List[Dict[str, Any]]):
        self._rows = rows

    @property
    def rows(self) -> List[Dict[str, Any]]:
        """Materialized result of the query chain."""
        return self._rows

    def select(self, *columns: str) -> Table:
        """Project only the specified columns. Missing columns are silently skipped."""
        new_rows = []
        for row in self._rows:
            new_rows.append({col: row[col] for col in columns if col in row})
        return Table(new_rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        """Filter rows where `predicate(row)` returns True."""
        return Table([row for row in self._rows if predicate(row)])

    def join(self, other: Table, on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> Table:
        """Inner join with another table. Column conflicts are resolved by prefixing 
        with 'l_' (left table) and 'r_' (right table)."""
        new_rows = []
        for l_row in self._rows:
            for r_row in other._rows:
                if on(l_row, r_row):
                    merged = {f"l_{k}": v for k, v in l_row.items()}
                    merged.update({f"r_{k}": v for k, v in r_row.items()})
                    new_rows.append(merged)
        return Table(new_rows)

    def group_by(self, column: str) -> Table:
        """Group rows by `column`. Returns a Table where each row contains:
        - 'group_key': the grouping value
        - 'rows': list of original rows belonging to that group
        """
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._rows:
            key = row.get(column)
            groups.setdefault(key, []).append(row)
        grouped_rows = [{'group_key': k, 'rows': v} for k, v in groups.items()]
        return Table(grouped_rows)

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Sort rows by `column`. Rows with missing/None values are placed at the end."""
        def sort_key(row: Dict[str, Any]) -> tuple:
            val = row.get(column)
            return (1, 0) if val is None else (0, val)
        return Table(sorted(self._rows, key=sort_key, reverse=descending))

    def limit(self, n: int) -> Table:
        """Return at most `n` rows."""
        return Table(self._rows[:n])

    def to_list(self) -> List[Dict[str, Any]]:
        """Explicitly materialize the query result."""
        return self._rows

    def __repr__(self) -> str:
        preview = self._rows[:3] + (["..."] if len(self._rows) > 3 else [])
        return f"Table(rows={preview}, total={len(self._rows)})"

