from __future__ import annotations

from typing import Any, Callable, Dict, List, Optional, Sequence


class Table:
    """An immutable, in-memory table with a fluent SQL-like query API.

    Each row is a dict mapping column names to values. The column order is
    preserved through operations.
    """

    def __init__(self, rows: Sequence[Dict[str, Any]], columns: Optional[Sequence[str]] = None) -> None:
        """Initialize from a sequence of dicts.

        Args:
            rows: Sequence of dicts (order preserved).
            columns: Optional explicit column order. If omitted, inferred from
                the first non-empty row (keys in insertion order for Python 3.7+).
        """
        if columns is None:
            # Infer columns from the first row
            columns = list(rows[0].keys()) if rows else []
        self._columns = list(columns)
        self._rows = [dict(row) for row in rows]  # shallow copy

    def __repr__(self) -> str:
        cols = ", ".join(self._columns)
        return f"Table({len(self._rows)} rows, columns=[{cols}])"

    # ---- Query operations (all return new Table) ----

    def select(self, *columns: str) -> Table:
        """Return a new table with only the specified columns, in given order.

        Raises KeyError if any column does not exist.
        """
        table_cols = set(self._columns)
        for col in columns:
            if col not in table_cols:
                raise KeyError(f"Column '{col}' does not exist in table")
        new_rows = []
        for row in self._rows:
            new_row = {col: row[col] for col in columns}
            new_rows.append(new_row)
        return Table(new_rows, columns=list(columns))

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        """Return a new table containing only rows satisfying *predicate*."""
        new_rows = [row for row in self._rows if predicate(row)]
        return Table(new_rows, columns=self._columns)

    def join(self, other: Table, on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> Table:
        """Return a new table as an inner join of self and *other*.

        The resulting rows have columns from both tables.  Duplicate column
        names raise a ValueError.
        """
        # Check for column name conflicts
        self_cols = set(self._columns)
        other_cols = set(other._columns)
        common = self_cols & other_cols
        if common:
            raise ValueError(
                f"Tables have overlapping column names: {common}. "
                "Rename columns or use alias before join."
            )

        new_rows: List[Dict[str, Any]] = []
        for left_row in self._rows:
            for right_row in other._rows:
                if on(left_row, right_row):
                    merged = {**left_row, **right_row}
                    new_rows.append(merged)
        # Column order: self columns then other columns
        return Table(new_rows, columns=list(self._columns) + list(other._columns))

    def group_by(self, column: str) -> Table:
        """Group rows by *column* and return a table with one row per group.

        Each group row has two columns:
          - *column*: the group key value
          - 'count': number of rows in that group

        This is a simplified aggregation (count).  For advanced aggregations
        the user would typically extend this method.
        """
        if column not in self._columns:
            raise KeyError(f"Column '{column}' does not exist for group_by")
        groups: Dict[Any, int] = {}
        for row in self._rows:
            key = row[column]
            groups[key] = groups.get(key, 0) + 1
        new_rows = [{column: key, "count": cnt} for key, cnt in groups.items()]
        return Table(new_rows, columns=[column, "count"])

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Return a new table sorted by *column* values."""
        if column not in self._columns:
            raise KeyError(f"Column '{column}' does not exist for order_by")
        new_rows = sorted(self._rows, key=lambda r: r[column], reverse=descending)
        return Table(new_rows, columns=self._columns)

    def limit(self, n: int) -> Table:
        """Return a new table containing at most *n* rows (first rows preserved)."""
        if n < 0:
            raise ValueError("Limit must be non-negative")
        new_rows = self._rows[:n]
        return Table(new_rows, columns=self._columns)


# ===== Usage examples =====

if __name__ == "__main__":
