import logging
from typing import Any, Callable, Iterable, List, Dict, Optional, TypeVar, Generic

# Configure logging for the engine
logger = logging.getLogger(__name__)

T = TypeVar("T")

class QueryResult(Generic[T]):
    """
    A wrapper around a dataset that provides a fluent API for 
    SQL-like transformations.
    """

    def __init__(self, data: Iterable[Dict[str, Any]]):
        # Convert to list to materialize the sequence and allow multiple passes
        self._data = list(data)

    def select(self, *columns: str) -> "QueryResult":
        """Projects only the specified columns from the dataset."""
        if not columns:
            return self

        projected = []
        for row in self._data:
            try:
                projected.append({col: row[col] for col in columns})
            except KeyError as e:
                logger.error(f"Column {e} not found in row: {row}")
                raise KeyError(f"Column {e} does not exist in the current dataset") from e

        return QueryResult(projected)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> "QueryResult":
        """Filters rows based on a boolean predicate function."""
        return QueryResult(filter(predicate, self._data))

    def join(
        self, 
        other: "Table", 
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool]
    ) -> "QueryResult":
        """
        Performs an inner join with another Table based on a join predicate.
        """
        joined_data = []
        # Nested loop join implementation
        for left_row in self._data:
            for right_row in other.rows:
                if on(left_row, right_row):
                    # Merge dictionaries; right_row values overwrite left_row on key collision
                    joined_data.append({**left_row, **right_row})

        return QueryResult(joined_data)

    def group_by(self, column: str) -> List[Dict[str, Any]]:
        """
        Groups data by a column. 
        Returns a list of dicts where the key is the group value and 'rows' is the list of matches.
        Note: This terminates the fluent chain as it changes the data structure.
        """
        groups: Dict[str, List[Dict[str, Any]]] = {}
        for row in self._data:
            val = row.get(column)
            if val not in groups:
                groups[val] = []
            groups[val].append(row)

        return [{"group": k, "rows": v} for k, v in groups.items()]

    def order_by(self, column: str, descending: bool = False) -> "QueryResult":
        """Sorts the dataset by a specific column."""
        try:
            sorted_data = sorted(
                self._data, 
                key=lambda x: x[column], 
                reverse=descending
            )
            return QueryResult(sorted_data)
        except KeyError as e:
            logger.error(f"Sort column {e} not found")
            raise KeyError(f"Column {e} does not exist") from e

    def limit(self, n: int) -> "QueryResult":
        """Limits the number of returned rows."""
        if n < 0:
            raise ValueError("Limit must be a non-negative integer")
        return QueryResult(self._data[:n])

    def execute(self) -> List[Dict[str, Any]]:
        """Materializes the final result set."""
        return self._data


class Table:
    """
    Represents a database table containing a collection of rows.
    """

    def __init__(self, name: str, rows: List[Dict[str, Any]]):
        self.name = name
        self.rows = rows

    def query(self) -> QueryResult:
        """Entry point for the fluent query API."""
        return QueryResult(self.rows)


