from typing import List, Dict, Any, Callable, Optional, Iterable, TypeVar, Generic
from operator import itemgetter

# Type alias for a row: a dictionary mapping column names to values
Row = Dict[str, Any]

class Table:
    def __init__(self, rows: Iterable[Row], name: str = "untitled"):
        self._rows = list(rows)
        self.name = name

    def select(self, *columns: str) -> 'Table':
        """Projects specific columns from the rows."""
        if not columns:
            return Table(self._rows, self.name)

        new_rows = [
            {col: row[col] for col in columns if col in row}
            for row in self._rows
        ]
        return Table(new_rows, self.name)

    def where(self, predicate: Callable[[Row], bool]) -> 'Table':
        """Filters rows based on a boolean predicate."""
        new_rows = [row for row in self._rows if predicate(row)]
        return Table(new_rows, self.name)

    def join(self, other: 'Table', on: Callable[[Row, Row], bool]) -> 'Table':
        """Performs an inner join with another table based on a custom predicate."""
        joined_rows = []
        for left_row in self._rows:
            for right_row in other._rows:
                if on(left_row, right_row):
                    # Merge dictionaries; right_row takes precedence on key collisions
                    joined_rows.append({**left_row, **right_row})
        return Table(joined_rows, f"{self.name}_joined_{other.name}")

    def group_by(self, column: str) -> 'Table':
        """
        Groups rows by a column. 
        Returns a table where each row contains the key and a list of grouped records.
        """
        groups: Dict[Any, List[Row]] = {}
        for row in self._rows:
            val = row.get(column)
            groups.setdefault(val, []).append(row)

        # Transform groups into a list of rows for the next Table instance
        new_rows = [{column: k, "group": v} for k, v in groups.items()]
        return Table(new_rows, f"{self.name}_grouped")

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        """Sorts the rows by a specific column."""
        # Use a lambda to handle missing keys gracefully (treating them as None)
        sorted_rows = sorted(
            self._rows, 
            key=lambda x: x.get(column), 
            reverse=descending
        )
        return Table(sorted_rows, self.name)

    def limit(self, n: int) -> 'Table':
        """Limits the result set to n rows."""
        return Table(self._rows[:n], self.name)

    def execute(self) -> List[Row]:
        """Returns the final materialized list of rows."""
        return self._rows

    def __repr__(self) -> str:
        return f"Table(name={self.name}, rows={len(self._rows)})"

