from typing import List, Dict, Callable, Any, Optional

Row = Dict[str, Any]
Predicate = Callable[[Row], bool]
JoinPredicate = Callable[[Row, Row], bool]


class Table:
    """In-memory table holding a list of dictionary rows."""

    def __init__(self, rows: List[Row]):
        if not isinstance(rows, list):
            raise TypeError("Table rows must be a list of dictionaries.")
        self.rows: List[Row] = rows

    def select(self, *columns: str) -> "Query":
        return Query(self).select(*columns)

    def where(self, predicate: Predicate) -> "Query":
        return Query(self).where(predicate)

    def join(self, other: "Table", on: JoinPredicate) -> "Query":
        return Query(self).join(other, on)

    def group_by(self, column: str) -> "Query":
        return Query(self).group_by(column)

    def order_by(self, column: str, descending: bool = False) -> "Query":
        return Query(self).order_by(column, descending)

    def limit(self, n: int) -> "Query":
        return Query(self).limit(n)


class Query:
    """Fluent query builder that accumulates operations before execution."""

    def __init__(self, table: Table):
        self._table = table
        self._columns: Optional[List[str]] = None
        self._predicate: Optional[Predicate] = None
        self._join_table: Optional[Table] = None
        self._join_on: Optional[JoinPredicate] = None
        self._group_column: Optional[str] = None
        self._order_column: Optional[str] = None
        self._descending: bool = False
        self._limit: Optional[int] = None

    def select(self, *columns: str) -> "Query":
        self._columns = list(columns)
        return self

    def where(self, predicate: Predicate) -> "Query":
        self._predicate = predicate
        return self

    def join(self, other: Table, on: JoinPredicate) -> "Query":
        self._join_table = other
        self._join_on = on
        return self

    def group_by(self, column: str) -> "Query":
        self._group_column = column
        return self

    def order_by(self, column: str, descending: bool = False) -> "Query":
        self._order_column = column
        self._descending = descending
        return self

    def limit(self, n: int) -> "Query":
        if n < 0:
            raise ValueError("Limit must be non-negative.")
        self._limit = n
        return self

    def execute(self) -> List[Row]:
        """
        Executes the accumulated query pipeline.
        Order of operations: WHERE -> JOIN -> SELECT -> GROUP BY -> ORDER BY -> LIMIT
        """
        rows = [dict(r) for r in self._table.rows]

        # 1. Filter rows
        if self._predicate:
            rows = [r for r in rows if self._predicate(r)]

        # 2. Join with another table
        if self._join_table and self._join_on:
            joined = []
            for r1 in rows:
                for r2 in self._join_table.rows:
                    if self._join_on(r1, r2):
                        merged = {**r1, **r2}
                        if set(r1.keys()) & set(r2.keys()):
                            raise ValueError("Column name collision during join")
                        joined.append(merged)
            rows = joined

        # 3. Project columns
        if self._columns:
            if not rows:
                return []
            for col in self._columns:
                if col not in rows[0]:
                    raise KeyError(f"Column '{col}' not found in rows")
            rows = [{k: r[k] for k in self._columns} for r in rows]

        # 4. Group rows
        if self._group_column:
            if not rows or self._group_column not in rows[0]:
                raise KeyError(f"Group column '{self._group_column}' not found")
            groups: Dict[Any, List[Row]] = {}
            for r in rows:
                key = r[self._group_column]
                groups.setdefault(key, []).append(r)
            rows = [{"group": k, "rows": v} for k, v in groups.items()]

        # 5. Sort rows
        if self._order_column:
            if not rows or self._order_column not in rows[0]:
                raise KeyError(f"Order column '{self._order_column}' not found")
            rows = sorted(rows, key=lambda r: r[self._order_column], reverse=self._descending)

        # 6. Limit results
        if self._limit is not None:
            rows = rows[: self._limit]

        return rows


# ---------------------------------------------------------------------------
# Usage Examples
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    # Example 1: Basic filtering, projection, sorting, and limiting
    employees = Table([
        {"id": 1, "name": "Alice", "dept": "Engineering", "salary": 95000},
        {"id": 2, "name": "Bob", "dept": "Marketing", "salary": 72000},
        {"id": 3, "name": "Charlie", "dept": "Engineering", "salary": 88000},
