    print("Example 1:", result1)
    # Output: [{'name': 'Alice', 'salary': 95000}, {'name': 'Charlie', 'salary': 88000}]

    # Example 2: Join two tables
    departments = Table([
        {"dept": "Engineering", "budget": 500000},
        {"dept": "Marketing", "budget": 300000},
    ])

    result2 = (
