"""
In-memory SQL-like query engine.

Thread-safety note:
The engine is stateless per execution and returns shallow copies of rows.
Concurrent reads are safe. Mutations to returned dictionaries are not synchronized.
"""

from __future__ import annotations

import logging
from typing import Callable, Dict, List, Any, Iterator

logger = logging.getLogger(__name__)


class Table:
    """Holds a list of dictionary rows representing a relational table."""

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        self._validate_rows(rows)
        self.rows: List[Dict[str, Any]] = rows

    @staticmethod
    def _validate_rows(rows: List[Dict[str, Any]]) -> None:
        if not isinstance(rows, list):
            raise TypeError("rows must be a list")
        for idx, row in enumerate(rows):
            if not isinstance(row, dict):
                raise TypeError(f"Row at index {idx} must be a dict")

    def query(self) -> Query:
        """Return a fluent query builder for this table."""
        return Query(self)


class Query:
    """Fluent query builder that applies transformations lazily."""

    def __init__(self, base_table: Table) -> None:
        self._base_table = base_table
        self._operations: List[Callable[[List[Dict[str, Any]]], List[Dict[str, Any]]]] = []

    def _add_operation(self, op: Callable[[List[Dict[str, Any]]], List[Dict[str, Any]]]) -> Query:
        self._operations.append(op)
        return self

    def execute(self) -> List[Dict[str, Any]]:
        """Execute the query pipeline and return the resulting rows."""
        data = [dict(row) for row in self._base_table.rows]
        for op in self._operations:
            try:
                data = op(data)
            except Exception as e:
                logger.error("Query operation failed: %s", e, exc_info=True)
                raise
        return data

    def __iter__(self) -> Iterator[Dict[str, Any]]:
        return iter(self.execute())

    def __len__(self) -> int:
        return len(self.execute())

    def select(self, *columns: str) -> Query:
        def op(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            result = []
            for row in rows:
                missing = set(columns) - set(row.keys())
                if missing:
                    raise KeyError(f"Row missing columns: {missing}")
                result.append({col: row[col] for col in columns})
            return result
        return self._add_operation(op)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Query:
        def op(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            return [row for row in rows if predicate(row)]
        return self._add_operation(op)

    def join(self, other: Table, on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> Query:
        def op(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            result = []
            for left in rows:
                for right in other.rows:
                    if on(left, right):
                        merged = {**left, **right}
                        collisions = set(left.keys()) & set(right.keys())
                        if collisions:
                            raise ValueError(f"Key collision during join: {collisions}")
                        result.append(merged)
            return result
        return self._add_operation(op)

    def group_by(self, column: str) -> Query:
        def op(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            groups: Dict[Any, List[Dict[str, Any]]] = {}
            for row in rows:
                if column not in row:
                    raise KeyError(f"Row missing group column: {column}")
                groups.setdefault(row[column], []).append(row)
            return [{column: key, "_group": members} for key, members in groups.items()]
        return self._add_operation(op)

    def order_by(self, column: str, descending: bool = False) -> Query:
        def op(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            if not rows:
                return rows
            for row in rows:
                if column not in row:
                    raise KeyError(f"Column '{column}' missing in row: {row}")
            return sorted(rows, key=lambda r: r[column], reverse=descending)
        return self._add_operation(op)

    def limit(self, n: int) -> Query:
        if n < 0:
            raise ValueError("limit must be non-negative")
        def op(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            return rows[:n]
        return self._add_operation(op)


