def test_query_engine() -> None:
    """Basic validation of query operations and edge cases."""
    data = Table([
        {"x": 1, "y": "a"},
        {"x": 2, "y": "b"},
        {"x": 3, "y": "a"},
    ])

    # select + where
    assert data.query().select("x").where(lambda r: r["x"] > 1).execute() == [{"x": 2}, {"x": 3}]

    # limit
    assert data.query().limit(1).execute() == [{"x": 1, "y": "a"}]

