        """Filter rows with a predicate function."""
        return Table([row for row in self.rows if predicate(row)])

    def join(
        self,
        other: "Table",
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool],
    ) -> "Table":
        """Inner join – combines left and right rows when `on(l, r)` is True."""
        joined: List[Dict[str, Any]] = []
        for l in self.rows:
            for r in other.rows:
                if on(l, r):
                    # right‑hand values overwrite left‑hand values on clash
                    joined.append({**l, **r})
        return Table(joined)

