            if val not in seen:
                seen.add(val)
                distinct.append({column: val})
        return Table(distinct)

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Sort rows by the given column."""
        return Table(
            sorted(self.rows, key=lambda r: r.get(column), reverse=descending)
        )

    def limit(self, n: int) -> "Table":
        """Keep only the first *n* rows."""
        return Table(self.rows[:n])

    # ------------------------------------------------------------------ #
    # Convenience / representation
    # ------------------------------------------------------------------ #
    def __repr__(self) -> str:
        if not self.rows:
            return "<Table: 0 rows>"
        header = ", ".join(self.rows[0].keys())
        lines = [header]
        for row in self.rows:
            lines.append(", ".join(str(row.get(col, "")) for col in self.rows[0].keys()))
        return f"<Table: {len(self.rows)} rows>\n" + "\n".join(lines)


