from dataclasses import dataclass, field, replace
from typing import Any, Callable, Dict, List, Optional, Tuple, Union
import operator

# ================= EXPRESSION DSL =================
class Expr:
    def __init__(self, name: str):
        self.name = name
    def __add__(self, other): return BinOp(self, '+', other)
    def __sub__(self, other): return BinOp(self, '-', other)
    def __mul__(self, other): return BinOp(self, '*', other)
    def __floordiv__(self, other): return BinOp(self, '/', other)
    def __gt__(self, other): return CmpOp(self, '>', other)
    def __lt__(self, other): return CmpOp(self, '<', other)
    def __eq__(self, other): return CmpOp(self, '==', other)
    def __ge__(self, other): return CmpOp(self, '>=', other)
    def __le__(self, other): return CmpOp(self, '<=', other)
    def as_(self, alias: str) -> 'AliasExpr':
        return AliasExpr(self, alias)

@dataclass
class BinOp(Expr):
    left: Any
    op: str
    right: Any

@dataclass
class CmpOp(Expr):
    left: Any
    op: str
    right: Any

@dataclass
class AliasExpr(Expr):
    expr: Any
    alias: str

# Simple factory
def col(name: str) -> Expr:
    return Expr(name)

# ================= EXPRESSION EVALUATOR =================
OPS = {
    '+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv,
    '==': operator.eq, '!=': operator.ne, '>': operator.gt, '<': operator.lt,
    '>=': operator.ge, '<=': operator.le
}

def evaluate(expr: Any, row: Dict[str, Any]) -> Any:
    if isinstance(expr, (int, float, str, bool, type(None))):
        return expr
    if isinstance(expr, AliasExpr):
        val, alias = evaluate(expr.expr, row), expr.alias
        return (val, alias)
    if isinstance(expr, (BinOp, CmpOp)):
        l = evaluate(expr.left, row)
        r = evaluate(expr.right, row)
        return OPS[expr.op](l, r)
    if isinstance(expr, Expr):
        return row.get(expr.name)
    raise TypeError(f"Unsupported expression: {type(expr)}")

# ================= QUERY BUILDER =================
@dataclass(frozen=True)
class Query:
    data: List[Dict[str, Any]]
    _select: List[Any] = field(default_factory=list)
    _where: List[Any] = field(default_factory=list)
    _group_by: List[Union[str, Expr]] = field(default_factory=list)
    _order_by: List[Tuple[Union[str, Expr], bool]] = field(default_factory=list)
    _limit: Optional[int] = None
    _offset: int = 0

    def _copy(self, **changes) -> 'Query':
        return replace(self, **changes)

    def select(self, *cols: Any) -> 'Query':
        return self._copy(_select=list(cols))

    def where(self, condition: Any) -> 'Query':
        return self._copy(_where=self._where + [condition])

    def group_by(self, *columns: Union[str, Expr]) -> 'Query':
        return self._copy(_group_by=list(columns))

    def order_by(self, *columns: Union[str, Expr], ascending: bool = True) -> 'Query':
        return self._copy(_order_by=[(col, ascending) for col in columns])

    def limit(self, n: int) -> 'Query':
        return self._copy(_limit=n)

    def offset(self, n: int) -> 'Query':
        return self._copy(_offset=n)

    # ================= EXECUTION PIPELINE =================
    def execute(self) -> List[Dict[str, Any]]:
        rows = list(self.data)

        # 1. WHERE
        for cond in self._where:
            rows = [r for r in rows if evaluate(cond, r)]

        # 2. GROUP BY (simplified: aggregates mean/stddev for numeric cols)
        if self._group_by:
            groups: Dict[tuple, List[Dict]] = {}
            for r in rows:
                key = tuple(evaluate(c, r) for c in self._group_by)
                groups.setdefault(key, []).append(r)

            processed = []
            for key, grp in groups.items():
                merged = {}
                for c in self._group_by:
                    merged[evaluate(c, grp[0])] = evaluate(c, grp[0])
                # Auto-aggregate numeric columns if not explicitly aliased
                for r in grp:
                    for k, v in r.items():
                        if isinstance(v, (int, float)) and k not in merged:
                            avg = sum(row[k] for row in grp) / len(grp)
                            merged[f"avg({k})"] = round(avg, 2)
            rows = [merged]  # Simplified; production would map to projections
        else:
            # Flatten groups if not used
            if self._group_by:
                # Handled above, else keep original
                pass

        # 3. SELECT / PROJECTION
        if self._select:
            projected = []
            for r in rows:
                out = {}
                for expr in self._select:
                    val = evaluate(expr, r)
                    if isinstance(val, tuple):
                        out[val[1]] = val[0]
                    else:
                        # Fallback to column name or alias
                        alias = getattr(expr, 'alias', getattr(expr, 'name', str(expr)))
                        out[alias] = val
                projected.append(out)
            rows = projected
        elif self._group_by:
            # Keep grouped structure
            pass

        # 4. ORDER BY
        if self._order_by:
            def sort_key(r):
                keys = []
                for expr, asc in self._order_by:
                    v = evaluate(expr, r) if isinstance(expr, Expr) else r.get(expr)
                    # Handle None-safe sorting
                    keys.append((v is None, ~asc if asc else asc, v if v is not None else ""))
                return keys
            rows = sorted(rows, key=sort_key)

        # 5. LIMIT / OFFSET
        offset = self._offset
        limit = self._limit if self._limit is not None else len(rows)
        rows = rows[offset:offset + limit]

        return rows

