from typing import List, Dict, Callable, Any, Optional, Union

class Table:
    def __init__(self, rows: List[Dict[str, Any]]):
        self.rows = rows

    def select(self, *columns: str) -> 'Table':
        """Select specific columns from the table."""
        if not columns:
            raise ValueError("At least one column must be specified.")
        self.rows = [{col: row[col] for col in columns if col in row} for row in self.rows]
        return self

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> 'Table':
        """Filter rows based on a predicate function."""
        self.rows = [row for row in self.rows if predicate(row)]
        return self

    def join(self, other_table: 'Table', on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> 'Table':
        """Join with another table based on a condition."""
        if not isinstance(other_table, Table):
            raise TypeError("other_table must be an instance of Table.")

        joined_rows = []
        for left_row in self.rows:
            for right_row in other_table.rows:
                if on(left_row, right_row):
                    joined_rows.append({**left_row, **right_row})
        self.rows = joined_rows
        return self

    def group_by(self, column: str) -> 'Table':
        """Group rows by a specific column."""
        if not any(column in row for row in self.rows):
            raise ValueError(f"Column '{column}' does not exist in the table.")

        grouped_rows = {}
        for row in self.rows:
            key = row[column]
            if key not in grouped_rows:
                grouped_rows[key] = []
            grouped_rows[key].append(row)

        self.rows = [grouped_rows[key] for key in grouped_rows]
        return self

    def order_by(self, column: str, descending: bool = False) -> 'Table':
        """Order rows by a specific column."""
        if not any(column in row for row in self.rows):
            raise ValueError(f"Column '{column}' does not exist in the table.")

        self.rows.sort(key=lambda row: row[column], reverse=descending)
        return self

    def limit(self, n: int) -> 'Table':
        """Limit the number of rows returned."""
        if n < 0:
            raise ValueError("Limit must be a non-negative integer.")
        self.rows = self.rows[:n]
        return self

    def get_rows(self) -> List[Dict[str, Any]]:
        """Return the current rows."""
        return self.rows

