"""In-memory SQL-like query engine with a fluent, composable API."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Callable, Iterator, Protocol, TypeVar, overload

T = TypeVar("T")
Row = dict[str, Any]
Predicate = Callable[[Row], bool]
JoinPredicate = Callable[[Row, Row], bool]


class Table(Protocol):
    """Protocol defining the interface for table-like objects."""

    def __iter__(self) -> Iterator[Row]:
        ...


@dataclass
class InMemoryTable:
    """In-memory table holding a collection of row dictionaries."""

    name: str
    _rows: list[Row] = field(default_factory=list)

    def __post_init__(self) -> None:
        object.__setattr__(self, "_rows", self._rows.copy() if self._rows else [])

    def insert(self, row: Row) -> None:
        self._rows.append(row)

    def __iter__(self) -> Iterator[Row]:
        return iter(self._rows)

    def select(self, *columns: str) -> QueryBuilder:
        return QueryBuilder(source=self).select(*columns)

    def where(self, predicate: Predicate) -> QueryBuilder:
        return QueryBuilder(source=self).where(predicate)

    def join(
        self, other: Table, on: JoinPredicate, prefix: str = "right_"
    ) -> QueryBuilder:
        return QueryBuilder(source=self).join(other, on, prefix)

    def group_by(self, column: str) -> QueryBuilder:
        return QueryBuilder(source=self).group_by(column)

    def order_by(self, column: str, descending: bool = False) -> QueryBuilder:
        return QueryBuilder(source=self).order_by(column, descending)

    def limit(self, n: int) -> QueryBuilder:
        return QueryBuilder(source=self).limit(n)


@dataclass
class QueryBuilder:
    """Fluent query builder that composes operations lazily."""

    source: Table
    _select_columns: tuple[str, ...] | None = None
    _where_predicate: Predicate | None = None
    _joins: list[tuple[Table, JoinPredicate, str]] = field(default_factory=list)
    _group_by_column: str | None = None
    _order_by_column: str | None = None
    _order_descending: bool = False
    _limit_count: int | None = None

    def select(self, *columns: str) -> QueryBuilder:
        self._select_columns = columns
        return self

    def where(self, predicate: Predicate) -> QueryBuilder:
        self._where_predicate = predicate
        return self

    def join(self, other: Table, on: JoinPredicate, prefix: str = "right_") -> QueryBuilder:
        self._joins.append((other, on, prefix))
        return self

    def group_by(self, column: str) -> QueryBuilder:
        self._group_by_column = column
        return self

    def order_by(self, column: str, descending: bool = False) -> QueryBuilder:
        self._order_by_column = column
        self._order_descending = descending
        return self

    def limit(self, n: int) -> QueryBuilder:
        if n < 0:
            raise ValueError(f"Limit must be non-negative, got {n}")
        self._limit_count = n
        return self

    def _execute(self) -> Iterator[Row]:
        """Execute the query plan and yield result rows."""
        rows = iter(self.source)

        # Apply joins
        for other, on_predicate, prefix in self._joins:
            rows = self._apply_join(rows, other, on_predicate, prefix)

        # Apply where filter
        if self._where_predicate is not None:
            rows = (row for row in rows if self._where_predicate(row))

        # Collect for further operations
        rows = list(rows)

        # Apply group_by
        if self._group_by_column is not None:
            rows = self._apply_group_by(rows, self._group_by_column)

        # Apply order-by
        if self._order_by_column is not None:
            rows = sorted(
                rows,
                key=lambda r: r.get(self._order_by_column),
                reverse=self._order_descending,
            )

        # Apply limit
        if self._limit_count is not None:
            rows = rows[: self._limit_count]

        # Apply select (projection)
        if self._select_columns is not None:
            rows = [{col: row.get(col) for col in self._select_columns} for row in rows]

        return iter(rows)

    def _apply_join(
        self, left_rows: Iterator[Row], right_table: Table, on: JoinPredicate, prefix: str
    ) -> Iterator[Row]:
        """Perform an inner join between left rows and right table."""
        right_rows = list(right_table)
        result = []

        for left_row in left_rows:
            for right_row in right_rows:
                if on(left_row, right_row):
                    merged = {**left_row, **{f"{prefix}{k}": v for k, v in right_row.items()}}
                    result.append(merged)

        return iter(result)

    def _apply_group_by(self, rows: list[Row], column: str) -> list[Row]:
        """Group rows by column, keeping first row of each group with count."""
        groups: dict[Any, list[Row]] = {}
        for row in rows:
            key = row.get(column)
            if key not in groups:
                groups[key] = []
            groups[key].append(row)

        return [
            {**group_rows[0], "_group_count": len(group_rows), "_group_key": key}
            for key, group_rows in groups.items()
        ]

    def __iter__(self) -> Iterator[Row]:
        return self._execute()

    @overload
    def __getitem__(self, index: int) -> Row: ...
    @overload
    def __getitem__(self, index: slice) -> list[Row]: ...

    def __getitem__(self, index: int | slice) -> Row | list[Row]:
        rows = list(self)
        return rows[index]

    def first(self) -> Row | None:
        """Return the first row or None if empty."""
        return next(iter(self), None)

    def to_list(self) -> list[Row]:
        """Materialize the query result as a list."""
        return list(self)

    def count(self) -> int:
        """Return the number of rows in the result."""
        return sum(1 for _ in self)


