from typing import Any, Callable, Dict, List, Optional, Sequence, TypeVar, Generic
from itertools import groupby
from operator import itemgetter
import logging

# Configure logging for the engine
logger = logging.getLogger(__name__)

T = TypeVar("T")

class QueryEngine(Generic[T]):
    """
    A fluent API for performing SQL-like operations on in-memory datasets.
    The engine uses lazy-like composition by returning new QueryEngine instances
    until the data is materialized.
    """

    def __init__(self, data: Sequence[Dict[str, Any]]):
        # We store data as a list to ensure we have a stable snapshot for operations
        self._data = list(data)

    def select(self, *columns: str) -> "QueryEngine":
        """Projects the dataset onto the specified columns."""
        if not columns:
            return self

        try:
            new_data = [
                {col: row[col] for col in columns} 
                for row in self._data
            ]
            return QueryEngine(new_data)
        except KeyError as e:
            logger.error(f"Column {e} not found in dataset")
            raise KeyError(f"Invalid column selection: {e}")

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> "QueryEngine":
        """Filters rows based on a boolean predicate function."""
        if not callable(predicate):
            raise TypeError("Predicate must be a callable function.")

        new_data = [row for row in self._data if predicate(row)]
        return QueryEngine(new_data)

    def join(self, other: "QueryEngine", on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> "QueryEngine":
        """
        Performs an inner join with another QueryEngine instance.
        The 'on' lambda defines the join condition between left and right rows.
        """
        if not callable(on):
            raise TypeError("Join condition 'on' must be a callable.")

        joined_data = []
        for left_row in self._data:
            for right_row in other._data:
                if on(left_row, right_row):
                    # Merge dictionaries; right_row overrides left_row on key collisions
                    joined_data.append({**left_row, **right_row})

        return QueryEngine(joined_data)

    def group_by(self, column: str) -> Dict[Any, List[Dict[str, Any]]]:
        """
        Groups the data by a specific column. 
        Note: This terminates the fluent chain and returns a dictionary.
        """
        if not self._data:
            return {}

        # Sort is required for itertools.groupby to work correctly
        sorted_data = sorted(self._data, key=itemgetter(column))
        return {k: list(v) for k, v in groupby(sorted_data, key=itemgetter(column))}

    def order_by(self, column: str, descending: bool = False) -> "QueryEngine":
        """Sorts the dataset by the specified column."""
        try:
            new_data = sorted(self._data, key=itemgetter(column), reverse=descending)
            return QueryEngine(new_data)
        except KeyError as e:
            logger.error(f"Sort column {e} not found")
            raise KeyError(f"Invalid sort column: {e}")

    def limit(self, n: int) -> "QueryEngine":
        """Limits the number of rows returned."""
        if n < 0:
            raise ValueError("Limit must be a non-negative integer.")

        return QueryEngine(self._data[:n])

    def execute(self) -> List[Dict[str, Any]]:
        """Materializes the current state of the query into a list."""
        return self._data

