"""
A tiny in‑memory SQL‑like query engine.

Example
-------
>>> from query_engine import Table, QueryBuilder

>>> data = Table([
...     {"name": "Alice", "dept": "HR",  "salary": 5000},
...     {"name": "Bob",   "dept": "IT",  "salary": 6000},
...     {"name": "Carol","dept": "HR",  "salary": 5500},
...     {"name": "Dave", "dept": "IT",  "salary": 7000},
... ])

>>> # Simple projection
>>> data.select("name", "salary").execute().rows
[{'name': 'Alice', 'salary': 5000},
 {'name': 'Bob',   'salary': 6000},
 {'name': 'Carol', 'salary': 5500},
 {'name': 'Dave',  'salary': 7000}]

>>> # Filter, order and limit
>>> (data
...  .where(lambda r: r["salary"] > 5000)
...  .order_by("salary", descending=True)
...  .limit(2)
...  .execute().rows)
[{'name': 'Dave', 'dept': 'IT', 'salary': 7000},
 {'name': 'Bob',  'dept': 'IT', 'salary': 6000}]

>>> # Group‑by (produces a count per group)
>>> data.group_by("dept").execute().rows
[{'dept': 'HR', '_count': 2}, {'dept': 'IT', '_count': 2}]

>>> # Join two tables
>>> depts = Table([
...     {"dept": "HR", "manager": "Eve"},
...     {"dept": "IT", "manager": "Frank"}
... ])
>>> (data
...  .join(depts, on=lambda l, r: l["dept"] == r["dept"])
...  .select("name", "dept", "manager")
...  .execute().rows)
[{'name': 'Alice', 'dept': 'HR', 'manager': 'Eve'},
 {'name': 'Bob',   'dept': 'IT', 'manager': 'Frank'},
 {'name': 'Carol', 'dept': 'HR', 'manager': 'Eve'},
 {'name': 'Dave',  'dept': 'IT', 'manager': 'Frank'}]
"""

from typing import (
    Any,
    Callable,
    Dict,
    Iterator,
    List,
    Tuple,
    Union,
    Optional,
)


# --------------------------------------------------------------------------- #
#  Types
# --------------------------------------------------------------------------- #
Row = Dict[str, Any]                     # a single record
Predicate = Callable[[Row], bool]       # filter predicate
JoinCondition = Callable[[Row, Row], bool]


# --------------------------------------------------------------------------- #
#  Table
# --------------------------------------------------------------------------- #
class Table:
    """
    Simple in‑memory table.

    Parameters
    ----------
    rows : List[Dict[str, Any]]
        The data to store. Each dict is a row.
    """

    __slots__ = ("rows",)

    def __init__(self, rows: List[Row]) -> None:
        self.rows: List[Row] = rows

    # ------------------------------------------------------------------ #
    #  Public query API – each returns a QueryBuilder
    # ------------------------------------------------------------------ #
    def select(self, *columns: str) -> "QueryBuilder":
        """Return a builder that projects only the given columns."""
        return QueryBuilder(self).select(*columns)

    def where(self, predicate: Predicate) -> "QueryBuilder":
        """Return a builder that filters rows with *predicate*."""
        return QueryBuilder(self).where(predicate)

    def join(self, other: "Table", on: JoinCondition) -> "QueryBuilder":
        """Return a builder that inner‑joins with *other* using *on*."""
        return QueryBuilder(self).join(other, on)

    def group_by(self, column: str) -> "QueryBuilder":
        """Return a builder that groups rows by *column* (emits `_count`)."""
        return QueryBuilder(self).group_by(column)

    def order_by(self, column: str, descending: bool = False) -> "QueryBuilder":
        """Return a builder that sorts on *column*."""
        return QueryBuilder(self).order_by(column, descending)

    def limit(self, n: int) -> "QueryBuilder":
        """Return a builder that keeps only the first *n* rows."""
        return QueryBuilder(self).limit(n)

    # ------------------------------------------------------------------ #
    #  Utilities
    # ------------------------------------------------------------------ #
    def __repr__(self) -> str:
        return f"Table({self.rows!r})"

    def __len__(self) -> int:
        return len(self.rows)

    def __iter__(self) -> Iterator[Row]:
        return iter(self.rows)


# --------------------------------------------------------------------------- #
#  QueryBuilder
# --------------------------------------------------------------------------- #
class QueryBuilder:
    """
    Fluent query builder.

    Internally it stores the source rows and a list of operations.
    When you call :meth:`execute` (or iterate over the builder) the
    operations are applied in order.
    """

    __slots__ = ("_source_rows", "_ops")

    def __init__(
        self,
        source: Union[Table, List[Row]],
        ops: Optional[List[Tuple[Any, ...]]] = None,
    ) -> None:
        # Accept either a Table or a plain list of rows.
        if isinstance(source, Table):
            self._source_rows: List[Row] = source.rows
        else:
            self._source_rows = source
        self._ops: List[Tuple[Any, ...]] = ops if ops is not None else []

    # ------------------------------------------------------------------ #
    #  Public query API – each returns a new QueryBuilder
    # ------------------------------------------------------------------ #
    def select(self, *columns: str) -> "QueryBuilder":
        """Projection operation."""
        return self._extend(("select", columns))

    def where(self, predicate: Predicate) -> "QueryBuilder":
        """Filtering operation."""
        return self._extend(("where", predicate))

    def join(self, other: Table, on: JoinCondition) -> "QueryBuilder":
        """Inner‑join operation."""
        return self._extend(("join", other, on))

    def group_by(self, column: str) -> "QueryBuilder":
        """Group‑by operation (produces a `_count` field)."""
        return self._extend(("group_by", column))

    def order_by(self, column: str, descending: bool = False) -> "QueryBuilder":
        """Sort operation."""
        return self._extend(("order_by", column, descending))

    def limit(self, n: int) -> "QueryBuilder":
        """Take‑first‑n operation."""
        return self._extend(("limit", n))

    # ------------------------------------------------------------------ #
    #  Execution
    # ------------------------------------------------------------------ #
    def execute(self) -> Table:
        """
        Run the recorded pipeline and return the resulting :class:`Table`.
        """
        rows = self._source_rows[:]          # work on a copy
        for op in self._ops:
            rows = self._dispatch(op, rows)
        return Table(rows)

    def __iter__(self) -> Iterator[Row]:
        """Allow direct iteration (triggers execution)."""
        return iter(self.execute())

    # ------------------------------------------------------------------ #
    #  Private helpers
    # ------------------------------------------------------------------ #
    def _extend(self, op: Tuple[Any, ...]) -> "QueryBuilder":
        """Create a new builder with an extra operation."""
        return QueryBuilder(self._source_rows, self._ops + [op])

    def _dispatch(self, op: Tuple[Any, ...], rows: List[Row]) -> List[Row]:
        """Apply a single operation to the current row set."""
        kind = op[0]

        if kind == "select":
            return self._op_select(rows, op[1])
        if kind == "where":
            return self._op_where(rows, op[1])
        if kind == "join":
            return self._op_join(rows, op[1].rows, op[2])
        if kind == "group_by":
            return self._op_group_by(rows, op[1])
        if kind == "order_by":
            return self._op_order_by(rows, op[1], op[2])
        if kind == "limit":
            return rows[: op[1]]
        raise ValueError(f"Unknown operation {kind!r}")

    # ---- operators -------------------------------------------------------- #
    @staticmethod
    def _op_select(rows: List[Row], columns: Tuple[str, ...]) -> List[Row]:
        if not columns:                     # empty → all columns
            return rows
        return [{col: row[col] for col in columns if col in row} for row in rows]

    @staticmethod
    def _op_where(rows: List[Row], pred: Predicate) -> List[Row]:
        return [row for row in rows if pred(row)]

    @staticmethod
    def _op_join(
        left_rows: List[Row],
        right_rows: List[Row],
        on: JoinCondition,
    ) -> List[Row]:
        out: List[Row] = []
        for l in left_rows:
            for r in right_rows:
                if on(l, r):
                    out.append({**l, **r})     # shallow‑merge, later wins
        return out

    @staticmethod
    def _op_group_by(rows: List[Row], column: str) -> List[Row]:
        """Simple group‑by that returns `{column: <value>, '_count': <size>}`."""
        buckets: Dict[Any, List[Row]] = {}
        for row in rows:
            key = row.get(column)
            buckets.setdefault(key, []).append(row)

        result: List[Row] = []
        for key, group in buckets.items():
            result.append({column: key, "_count": len(group)})
        return result

    @staticmethod
    def _op_order_by(rows: List[Row], column: str, descending: bool) -> List[Row]:
        def sort_key(row: Row) -> Tuple[int, Any]:
            """Put rows missing the column at the end."""
            val = row.get(column)
            return (0, val) if val is not None else (1, val)

        return sorted(rows, key=sort_key, reverse=descending)

    # ------------------------------------------------------------------ #
    #  Debug helpers
    # ------------------------------------------------------------------ #
    def __repr__(self) -> str:
        return f"QueryBuilder(source_rows={self._source_rows!r}, ops={self._ops!r})"

