#!/usr/bin/env python3
"""
In-Memory SQL-like Query Engine with Fluent Composable API.

Supports: Where, Select, OrderBy, GroupBy, Distinct, Join,
          Limit, Take, Skip, Count, Sum, Avg, Min, Max, etc.
"""

from __future__ import annotations

import operator
import math
from abc import ABC, abstractmethod
from collections.abc import Iterator
from functools import reduce
from dataclasses import dataclass, field
from enum import Enum, auto
from typing import (
    Any, Callable, Generic, TypeVar,
    overload,
)
from copy import deepcopy

# ──────────────────── Type Aliases ────────────────────

T = TypeVar("T")
U = TypeVar("U")


# ──────────────────── Core Data Structures ────────────────────

class NullType:
    """Represents SQL NULL."""
    _instance: NullType | None = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __bool__(self):
        return False

    def __repr__(self):
        return "NULL"

    def __eq__(self, other):
        return other is self or isinstance(other, (NullType, type(None)))

    def __is_not__(self, other):
        return not (other is self or isinstance(other, (NullType, type(None))))


Null = NullType()


class JoinType(Enum):
    INNER = auto()
    LEFT = auto()
    RIGHT = auto()
    FULL = auto()


class SortOrder(Enum):
    ASC = auto()
    DESC = auto()


# ──────────────────── Expression Nodes ────────────────────

class Expression(ABC):
    """Base class for query expressions."""
    @abstractmethod
    def resolve(self, row: dict[str, Any]) -> Any: ...

    @abstractmethod
    def __hash__(self) -> int: ...


class ColumnRef(Expression):
    def __init__(self, name: str):
        self.name = name

    def resolve(self, row: dict[str, Any]) -> Any:
        return row.get(self.name)

    def __eq__(self, other):
        return isinstance(other, ColumnRef) and other.name == self.name

    def __hash__(self):
        return hash(("column", self.name))

    def __repr__(self):
        return f"Col({self.name})"


class Literal(Expression):
    def __init__(self, value: Any):
        self.value = value

    def resolve(self, row: dict[str, Any]) -> Any:
        return self.value

    def __eq__(self, other):
        return isinstance(other, Literal) and other.value == self.value

    def __hash__(self):
        return hash(("literal", hash(self.value)))

    def __repr__(self):
        return f"Lit({self.value!r})"


class BinaryOp(Expression):
    _op_map = {
        "==": operator.eq,
        "!=": operator.ne,
        "<": operator.lt,
        "<=": operator.le,
        ">": operator.gt,
        ">=": operator.ge,
        "+": operator.add,
        "-": operator.sub,
        "*": operator.mul,
        "/": operator.truediv,
        "and": operator.and_,
        "or": operator.or_,
        "is": lambda a, b: a is b or a is Null,
        "is not": lambda a, b: a is not b and a is not Null,
    }

    def __init__(self, left: Expression, op: str, right: Expression):
        self.left = left
        self.op = op
        self.right = right

    def resolve(self, row: dict[str, Any]) -> Any:
        left = self.left.resolve(row)
        right = self.right.resolve(row)
        fn = self._op_map.get(self.op)
        if fn is None:
            raise ValueError(f"Unknown operator: {self.op}")
        # Handle NULL propagation
        if left is None or left is Null:
            return None
        if right is None or right is Null:
            return None
        # Handle IN operator (special case)
        if self.op == "in":
            return left in right
        if self.op == "not in":
            return left not in right
        if self.op == "like":
            pattern = self.right.resolve(row)
            import fnmatch
            return fnmatch.fnmatch(str(left), pattern)
        if self.op == "not like":
            pattern = self.right.resolve(row)
            import fnmatch
            return not fnmatch.fnmatch(str(left), pattern)
        try:
            result = fn(left, right)
        except TypeError:
            return False
        return result

    def __eq__(self, other):
        return (isinstance(other, BinaryOp)
                and self.op == other.op
                and self.left == other.left
                and self.right == other.right)

    def __hash__(self):
        return hash(("binary", self.op, self.left, self.right))

    def __repr__(self):
        return f"{self.left} {self.op} {self.right}"


class Not(Expression):
    def __init__(self, inner: Expression):
        self.inner = inner

    def resolve(self, row: dict[str, Any]) -> Any:
        result = self.inner.resolve(row)
        if result is None or result is Null:
            return None
        return not result

    def __eq__(self, other):
        return isinstance(other, Not) and self.inner == other.inner

    def __hash__(self):
        return hash(("not", self.inner))

    def __repr__(self):
        return f"NOT {self.inner}"


# ──────────────────── Aggregations ────────────────────

class Aggregation(Expression):
    def __init__(self, expr: Expression, alias: str | None = None):
        self.expr = expr
        self.alias = alias or f"{type(self).__name__.lower()}({expr.name if isinstance(expr, ColumnRef) else 'expr'})"

    def resolve(self, row: dict[str, Any]) -> Any:
        raise NotImplementedError


class Count(Aggregation):
    def resolve(self, rows: list[dict[str, Any]]) -> Any:
        if rows is None:
            return 0
        if self.expr is None:
            return len(rows)
        return sum(1 for r in rows if self.expr.resolve(r) is not None and self.expr.resolve(r) is not Null)


class Sum(Aggregation):
    def resolve(self, rows: list[dict[str, Any]]) -> Any:
        if rows is None:
            return 0
        valid = [self.expr.resolve(r) for r in rows]
        valid = [v for v in valid if v is not None and v is not Null]
        return sum(valid) if valid else None


class Avg(Aggregation):
    def resolve(self, rows: list[dict[str, Any]]) -> Any:
        if rows is None:
            return None
        valid = [self.expr.resolve(r) for r in rows]
        valid = [v for v in valid if v is not None and v is not Null]
        if not valid:
            return None
        return sum(valid) / len(valid)


class Min(Aggregation):
    def resolve(self, rows: list[dict[str, Any]]) -> Any:
        if rows is None:
            return None
        valid = [self.expr.resolve(r) for r in rows]
        valid = [v for v in valid if v is not None and v is not Null]
        return min(valid) if valid else None


class Max(Aggregation):
    def resolve(self, rows: list[dict[str, Any]]) -> Any:
        if rows is None:
            return None
        valid = [self.expr.resolve(r) for r in rows]
        valid = [v for v in valid if v is not None and v is not Null]
        return max(valid) if valid else None


# ──────────────────── Clause Builders ────────────────────

TBuilder = TypeVar("TBuilder", bound="QueryBuilder")


class _SelectBuilder:
    """Handles Select and projection logic."""

    def __init__(self, parent: QueryBuilder):
        self.parent = parent

    def where(self, predicate: Callable[[dict[str, Any]], bool]) -> TBuilder:
        """Filter rows by a lambda predicate."""
        expr = predicate
        if hasattr(expr, 'resolve'):
            predicate = lambda r, p=expr: bool(p.resolve(r))
        self.parent._where_preds.append(predicate)
        return self.parent

    def and_(self, predicate: Callable[[dict[str, Any]], bool]) -> TBuilder:
        """AND another predicate."""
        return self.parent.and_(predicate)

    def or_(self, predicate: Callable[[dict[str, Any]], bool]) -> TBuilder:
        """OR another predicate."""
        return self.parent.or_(predicate)

    def select(
        self,
        *fields: str | Callable[[dict[str, Any]], Any] | tuple[str, Callable[[dict[str, Any]], Any]],
    ) -> "QueryBuilder":
        """Project selected columns or computed expressions."""
        if hasattr(self.parent, '_current_source') and self.parent._current_source != "SELECT":
            raise ValueError("Cannot mix multiple SELECT sources in one QueryBuilder. "
                           "Create a new QueryBuilder() and chain with From().")
        self.parent._current_source = "SELECT"
        # Store field names and their expressions
        self.parent._select_fields = []
        for field in fields:
            if isinstance(field, tuple) and len(field) == 2:
                alias, expr = field
                if callable(expr):
                    self.parent._select_fields.append((alias, expr))
                else:
                    self.parent._select_fields.append((alias, self._expr_from_value(expr)))
            elif callable(field):
                # Lambda projection - need a safe name
                import uuid
                alias = f"_expr_{uuid.uuid4().hex[:6]}"
                self.parent._select_fields.append((alias, field))
            else:
                self.parent._select_fields.append((field, self._expr_from_value(field)))
        return self.parent

    def distinct(self) -> "QueryBuilder":
        self.parent._distinct = True
        return self.parent

    def group_by(self, *fields: str | Callable[[dict[str, Any]], Any]) -> TBuilder:
        self.parent._group_by_fields = [
            self._expr_from_value(f) if not isinstance(f, Expression) else f
            for f in fields
        ]
        return self.parent

    def having(self, predicate: Callable[[dict[str, Any]], bool]) -> TBuilder:
        self.parent._having_pred = predicate
        return self.parent

    def order_by(
        self,
        *fields: str | tuple[str, SortOrder] | Callable[[dict[str, Any]], Any],
    ) -> TBuilder:
        for f in fields:
            if isinstance(f, tuple) and len(f) == 2:
                self.parent._order_by.append((self._expr_from_value(f[0]), f[1]))
            elif isinstance(f, str):
                self.parent._order_by.append((self._expr_from_value(f), SortOrder.ASC))
            elif callable(f):
                import uuid
                alias = f"_expr_{uuid.uuid4().hex[:6]}"
                self.parent._order_by.append((f, SortOrder.ASC))
        return self.parent

    def limit(self, n: int) -> TBuilder:
        self.parent._limit = n
        return self.parent

    def take(self, n: int) -> TBuilder:
        return self.limit(n)

    def skip(self, n: int) -> TBuilder:
        self.parent._skip = n
        return self.parent

    def as_(self, name: str) -> TBuilder:
        self.parent._alias = name
        return self.parent

    @staticmethod
    def _expr_from_value(value: Any) -> Expression:
        if isinstance(value, str) and not callable(value):
            return ColumnRef(value)
        return Literal(value)


class _JoinBuilder:
    """Handles Join operations."""

    def __init__(self, parent: QueryBuilder):
        self.parent = parent
        self._join_type = JoinType.INNER

    def inner_join(
        self,
        source: list[dict[str, Any]] | QuerySource,
        left_key: str | Callable[[dict[str, Any]], Any],
        right_key: str | Callable[[dict[str, Any]], Any],
    ) -> "QueryBuilder":
        return self._join(source, self._join_type, left_key, right_key)

    def left_join(
        self,
        source: list[dict[str, Any]] | QuerySource,
        left_key: str | Callable[[dict[str, Any]], Any],
        right_key: str | Callable[[dict[str, Any]], Any],
    ) -> "QueryBuilder":
        self._join_type = JoinType.LEFT
        return self._join(source, self._join_type, left_key, right_key)

    def right_join(
        self,
        source: list[dict[str, Any]] | QuerySource,
        left_key: str | Callable[[dict[str, Any]], Any],
        right_key: str | Callable[[dict[str, Any]], Any],
    ) -> "QueryBuilder":
        self._join_type = JoinType.RIGHT
        return self._join(source, self._join_type, left_key, right_key)

    def full_join(
        self,
        source: list[dict[str, Any]] | QuerySource,
        left_key: str | Callable[[dict[str, Any]], Any],
        right_key: str | Callable[[dict[str, Any]], Any],
    ) -> "QueryBuilder":
        self._join_type = JoinType.FULL
        return self._join(source, self._join_type, left_key, right_key)

    def _join(
        self,
        source: list[dict[str, Any]] | QuerySource,
        jtype: JoinType,
        left_key: str | Callable[[dict[str, Any]], Any],
        right_key: str | Callable[[dict[str, Any]], Any],
    ) -> "QueryBuilder":
        # Store join info for later execution
        source_table = source if isinstance(source, list) else list(source)
        if callable(left_key):
            lk = left_key
        elif isinstance(left_key, ColumnRef):
            lk = lambda r, c=left_key: c.resolve(r)
        else:
            lk = lambda r, c=left_key: r.get(c)

        if callable(right_key):
            rk = right_key
        elif isinstance(right_key, ColumnRef):
            rk = lambda r, rc=right_key: rc.resolve(r)
        else:
            rk = lambda r, rc=right_key: r.get(rc)

        self.parent._joins.append({
            "type": jtype,
            "source": source_table,
            "left_key": lk,
            "right_key": rk,
            "used": False,
        })
        # Mark the SELECT source as used if this comes from SelectBuilder
        if hasattr(self.parent, '_select_fields') and self.parent._select_fields:
            self.parent._joins[-1]["used"] = True
        return self.parent


class _AggregateBuilder:
    """Handles aggregation helper functions."""

    class Count:
        def __init__(self, expr: Expression | str | None = None):
