# ──────────────────── Main Query Builder ────────────────────

class QuerySource:
    """Wraps an in-memory data source."""
    def __init__(self, data: list[dict[str, Any]], name: str | None = None):
        self.data = data
        self.name = name or "source"

    def __iter__(self) -> Iterator[dict[str, Any]]:
        return iter(self.data)

    def __length_hint__(self) -> int:
        return len(self.data)

    def __repr__(self):
        return f"QuerySource({self.name!r}, len={len(self.data)})"


class QueryBuilder:
    """
    Fluent, composable query builder for in-memory data.

    Usage:
        employees = [
            {"name": "Alice", "dept": "Engineering", "salary": 90000, "age": 30},
            {"name": "Bob", "dept": "Sales", "salary": 60000, "age": 25},
            ...
        ]

        result = (Query.from_(employees)
                  .where(lambda r: r["salary"] > 70000)
                  .order_by("salary", desc=True)
                  .select("name", "dept")
                  .to_list())
    """

    @staticmethod
    def from_(source: list[dict[str, Any]] | QuerySource) -> "QueryBuilder":
        qb = QueryBuilder()
        return qb.from_source(source)

    def __init__(self):
        self._source: list[dict[str, Any]] | None = None
        self._where_preds: list[Callable[[dict[str, Any]], bool]] = []
        self._select_fields: list[tuple[str, Callable[[dict[str, Any]], Any]]
                                 | tuple[str, Expression]] | None = None
        self._order_by: list[tuple[Expression | Callable[[dict[str, Any]], Any], SortOrder]] = []
        self._group_by_fields: list[Expression | str | Callable[[dict[str, Any]], Any]] = []
        self._having_pred: Callable[[dict[str, Any]], bool] | None = None
        self._distinct: bool = False
        self._limit: int | None = None
        self._skip: int = 0
        self._joins: list[dict[str, Any]] = []
        self._alias: str | None = None
        self._current_source: str | None = None

    def from_source(self, source: list[dict[str, Any]] | QuerySource) -> "QueryBuilder":
        """Start a query with a data source."""
        self._source = source if isinstance(source, list) else list(source)
        return self

    def where(
        self,
        predicate: Callable[[dict[str, Any]], bool] | str | Expression,
    ) -> "QueryBuilder":
        """Filter rows by a lambda, expression, or SQL-like string."""
        if callable(predicate):
            self._where_preds.append(predicate)
        elif isinstance(predicate, Expression):
            self._where_preds.append(lambda r, p=predicate: bool(p.resolve(r)))
        elif isinstance(predicate, str):
            compiled = self._compile_string(predicate)
            self._where_preds.append(compiled)
        return self

    def and_(self, predicate: Callable[[dict[str, Any]], bool] | str | Expression) -> "QueryBuilder":
        """Alias for where — adds another filter clause."""
        return self.where(predicate)

    def or_(self, predicate: Callable[[dict[str, Any]], bool] | str | Expression) -> "QueryBuilder":
        """Add an OR predicate (applied as final filter)."""
        if callable(predicate):
            self._or_preds = getattr(self, '_or_preds', []) + [predicate]
        elif isinstance(predicate, Expression):
            self._or_preds = getattr(self, '_or_preds', []) + [
                lambda r, p=predicate: bool(p.resolve(r))
            ]
        elif isinstance(predicate, str):
            compiled = self._compile_string(predicate)
            self._or_preds = getattr(self, '_or_preds', []) + [compiled]
        return self

    def _compile_string(self, s: str) -> Callable[[dict[str, Any]], bool]:
        """Convert a simple SQL-like WHERE string to a lambda.

        Supported: =, !=, <, <=, >, >=, is, is not, in, not in, like
        Keywords: and, or, not
        """
        tokens = self._tokenize(s)
        return self._build_predicate(tokens)

    @staticmethod
    def _tokenize(s: str) -> list[str]:
        s = s.strip()
        tokens: list[str] = []
        current = ""
        i = 0
        while i < len(s):
            ch = s[i]
            if ch == "'":
                # Quoted string
                end = s.find("'", i + 1)
                if end == -1:
                    end = len(s)
                tokens.append(f"'{s[i+1:end]}'")
                i = end + 1
                continue
            # Multi-char operators
            if s[i:i+2] in ("!=", "<=", ">=", "is ", "in ", "not in", "and ", "or ", "like ", "not ", "in "):
                # Try longer matches first
                for op in ("not in", "is not", "<=", ">=", "!=", "like", "and", "or", "is not"):
                    if s[i:i+len(op)] == op:
                        tokens.append(op)
                        i += len(op)
                        current = ""
                        break
                else:
                    current += ch
                    i += 1
            elif ch in ("=", "<", ">"):
                tokens.append(ch)
                i += 1
                current = ""
            else:
                current += ch
                i += 1
        if current.strip():
            tokens.append(current.strip())
        return tokens

    def _build_predicate(self, tokens: list[str]) -> Callable[[dict[str, Any]], bool]:
        """Build a predicate from tokens (very simple recursive descent)."""
        def parse_or(start: int):
            left, end = parse_and(start)
            while end < len(tokens) and tokens[end].lower() == "or":
                right, end = parse_and(end + 1)
                l, r = left, right
                left = lambda row, l=l, r=r: self._eval_op_row(row, l, "OR", r)
            return left, end

        def parse_and(start: int):
            left, end = parse_comparison(start)
            while end < len(tokens) and tokens[end].lower() == "and":
                right, end = parse_comparison(end + 1)
                l, r = left, right
                left = lambda row, l=l, r=r: self._eval_op_row(row, l, "AND", r)
            return left, end

        def parse_comparison(start: int):
            # Simple left-hand value
            left_val = self._parse_value(tokens[start])
            if start + 1 >= len(tokens):
                return lambda row, lv=left_val: bool(lv), start + 1

            # Check for multi-char operator
            op = tokens[start + 1].lower() if start + 1 < len(tokens) else ""
            if start + 2 < len(tokens):
                right_val = self._parse_value(tokens[start + 2])
            else:
                right_val = None

            if op in ("in", "not in", "like", "not like"):
                # Handle list values
                return lambda row, lv=left_val, op=op, rv=right_val: self._compare_with_list(row, lv, op, rv), start + 3
            elif op == "is":
                return lambda row, lv=left_val, rv=right_val: self._is_nil(row, lv, rv, False), start + 3
            elif op == "is not":
                return lambda row, lv=left_val, rv=right_val: self._is_nil(row, lv, rv, True), start + 3
            else:
                return lambda row, lv=left_val, op=op, rv=right_val: self._compare_vals(row, lv, op, rv), start + 3

        predicate, _ = parse_or(0)
        return predicate

    def _parse_value(self, s: str) -> Any:
        s = s.strip()
        if s.upper() == "NULL":
            return None
        if s.startswith("'") and s.endswith("'"):
            return s[1:-1]
        if s.upper() == "TRUE":
            return True
        if s.upper() == "FALSE":
            return False
        try:
            return int(s)
        except ValueError:
            pass
        try:
            return float(s)
        except ValueError:
            pass
        return s

    @staticmethod
    def _eval_op_row(row, left, op, right):
        l = left(row) if callable(left) else left
        r = right(row) if callable(right) else right
        if op == "AND":
            return bool(l) and bool(r)
        if op == "OR":
            return bool(l) or bool(r)
        return bool(l)

    @staticmethod
    def _compare_vals(row, left, op, right):
        l = left(row) if callable(left) else left
        r = right(row) if callable(right) else right
        if l is None or r is None:
            return None
        ops = {
            "==": operator.eq,
            "!=": operator.ne,
            "=": operator.eq,
            "!=": operator.ne,
            "<": operator.lt,
            "<=": operator.le,
            ">": operator.gt,
            ">=": operator.ge,
        }
        fn = ops.get(op)
        if fn:
            return fn(l, r)
        return False

    @staticmethod
    def _compare_with_list(row, left, op, right):
        l = left(row) if callable(left) else left
        r = right(row) if callable(right) else right
        if op == "in":
            if r is None:
                return None
            return l in r
        if op == "not in":
            if r is None:
                return None
            return l not in r
        if op in ("like", "not like"):
            if r is None:
                return None
            import fnmatch
            result = fnmatch.fnmatch(str(l), str(r))
            return not result if op == "not like" else result
        return False

    @staticmethod
    def _is_nil(row, left, right, negated):
        l = left(row) if callable(left) else left
        return (l is None or l is Null) if not negated else (l is not None and l is not Null)

    def select(
        self,
        *fields: str | Callable[[dict[str, Any]], Any] | tuple[str, Callable[[dict[str, Any]], Any]],
    ) -> "QueryBuilder":
        """Project selected columns or computed expressions."""
        self._current_source = "SELECT"
        self._select_fields = self._expand_fields(fields)
        return self

    def _expand_fields(
        self,
        fields,
    ) -> list[tuple[str, Callable[[dict[str, Any]], Any]] | tuple[str, Expression]]:
        result = []
        for f in fields:
            if isinstance(f, tuple) and len(f) == 2:
                alias, expr = f
                if callable(expr):
                    result.append((alias, expr))
                elif isinstance(expr, str):
                    result.append((alias, ColumnRef(expr)))
                else:
                    result.append((alias, Literal(expr)))
            elif callable(f):
                import uuid
                alias = f"_expr_{uuid.uuid4().hex[:6]}"
                result.append((alias, f))
            elif isinstance(f, str):
                result.append((f, ColumnRef(f)))
            else:
                result.append((f"_{id(f)}", Literal(f)))
        return result

    def distinct(self) -> "QueryBuilder":
        """Remove duplicate rows."""
        self._distinct = True
        return self

    def group_by(self, *fields: str | Callable[[dict[str, Any]], Any]) -> "QueryBuilder":
        """Group rows by specified fields."""
        self._group_by_fields = []
        for f in fields:
            if callable(f):
                import uuid
                self._group_by_fields.append(f)
            elif isinstance(f, str):
                self._group_by_fields.append(f)
            else:
                raise TypeError(f"Unsupported group_by field: {type(f)}")
        return self

    def having(
        self,
        predicate: Callable[[dict[str, Any]], bool] | str | Expression,
    ) -> "QueryBuilder":
        """Filter grouped results."""
        if callable(predicate):
            self._having_pred = predicate
        elif isinstance(predicate, str):
            self._having_pred = self._compile_string(predicate)
        elif isinstance(predicate, Expression):
            self._having_pred = lambda r, p=predicate: bool(p.resolve(r))
        return self

    def order_by(
        self,
        *fields: str | tuple[str, SortOrder] | Callable[[dict[str, Any]], Any],
    ) -> "QueryBuilder":
        """Sort by one or more fields."""
        for f in fields:
            if isinstance(f, tuple) and len(f) == 2:
                self._order_by.append((f[0], f[1]))
            elif isinstance(f, str):
                self._order_by.append((ColumnRef(f), SortOrder.ASC))
            elif callable(f):
                self._order_by.append((f, SortOrder.ASC))
        return self

    def order_by_desc(self, *fields: str | tuple[str, SortOrder]) -> "QueryBuilder":
        """Sort descending."""
        for f in fields:
            if isinstance(f, tuple) and len(f) == 2:
                self._order_by.append((f[0], f[1]))
            elif isinstance(f, str):
                self._order_by.append((ColumnRef(f), SortOrder.DESC))
            else:
                self._order_by.append((f, SortOrder.DESC))
        return self

    def order_by_asc(self, *fields: str) -> "QueryBuilder":
        """Sort ascending (default)."""
        for f in fields:
            self._order_by.append((ColumnRef(f), SortOrder.ASC))
        return self

    def limit(self, n: int) -> "QueryBuilder":
        """Take at most n rows."""
        self._limit = n
        return self

    def take(self, n: int) -> "QueryBuilder":
        """Alias for limit."""
        return self.limit(n)

    def skip(self, n: int) -> "QueryBuilder":
        """Skip first n rows."""
        self._skip = n
        return self

    def inner_join(
        self,
        source: list[dict[str, Any]] | QuerySource,
        left_key: str | Callable[[dict[str, Any]], Any],
        right_key: str | Callable[[dict[str, Any]], Any],
    ) -> "QueryBuilder":
        """Inner join with another table."""
        return self._add_join(JoinType.INNER, source, left_key, right_key)

    def left_join(
        self,
        source: list[dict[str, Any]] | QuerySource,
        left_key: str | Callable[[dict[str, Any]], Any],
        right_key: str | Callable[[dict[str, Any]], Any],
    ) -> "QueryBuilder":
        """Left join with another table."""
        return self._add_join(JoinType.LEFT, source, left_key, right_key)

    def _add_join(
        self,
        jtype: JoinType,
        source: list[dict[str, Any]] | QuerySource,
        left_key: str | Callable[[dict[str, Any]], Any],
        right_key: str | Callable[[dict[str, Any]], Any],
    ) -> "QueryBuilder":
        source_table = source if isinstance(source, list) else list(source)
        self._build_join_funcs(left_key, right_key, source_table, jtype)
        return self

    @staticmethod
    def _build_join_funcs(
        lk, rk, source_table, jtype
    ):
        """Add join info to QueryBuilder."""
        pass

    # ──── Aggregate helpers ────

    @property
    def count(self) -> _AggregateBuilder.Count:
        return _AggregateBuilder.Count()

    @property
    def sum(self) -> _AggregateBuilder.Sum:
        return _AggregateBuilder.Sum()

    @property
    def avg(self) -> _AggregateBuilder.Avg:
        return _AggregateBuilder.Avg()

    @property
    def min(self) -> _AggregateBuilder.Min:
        return _AggregateBuilder.Min()

    @property
    def max(self) -> _AggregateBuilder.Max:
        return _AggregateBuilder.Max()

    # ──── Execution methods ────

    def to_list(self) -> list[dict[str, Any]]:
        """Execute and return as list of dicts."""
        return list(self.execute())

    def to_dict(self, key: str = "id") -> dict[str, dict[str, Any]]:
        """Execute and return as dictionary keyed by a field."""
        result = {}
        for row in self.execute():
            k = row.get(key)
            if k is not None:
                result[k] = row
        return result

    def to_tuple(self) -> tuple[dict[str, Any], ...]:
        """Execute and return as tuple."""
        return tuple(self.execute())

    def to_set(self) -> tuple[dict[str, Any], ...]:
        """Execute and return as unique set."""
        seen = []
        for row in self.execute():
            key = tuple(sorted(row.items()))
            if key not in seen:
                seen.append(key)
        return tuple(dict(kv) for kv in seen)

    def first(self) -> dict[str, Any] | None:
        """Return the first result or None."""
        for row in self.execute():
            return row
        return None

    def first_or_default(self, default: dict[str, Any] | None = None) -> dict[str, Any]:
        """Return first result or default."""
        for row in self.execute():
            return row
        return default or {}

    def any(self) -> bool:
        """Check if any rows satisfy the query."""
        try:
            next(self.execute())
            return True
        except StopIteration:
            return False

    def count(self) -> int:
        """Return number of rows matching the query."""
        return sum(1 for _ in self.execute())

    def sum(self, field: str) -> float | None:
        """Sum a field across all rows."""
        if self._source is None:
            raise RuntimeError("No source set")
        total = 0
        has_value = False
        for row in self._source:
            val = row.get(field)
            if val is not None and val is not Null:
                try:
                    total += val
                    has_value = True
                except TypeError:
                    pass
        return total if has_value else None

    def aggregate(self, agg_dict: dict[str, str]) -> list[dict[str, Any]]:
        """
        Perform aggregations.

        agg_dict = {
            "department": None,               # grouping
            "avg_salary": "avg:salary",       # aggregation
            "max_age": "max:age",             # aggregation
            "cnt": "count:*",                 # count
        }
        """
        if self._source is None:
            raise RuntimeError("No source set")

        # Parse aggregation spec
        groups = set()
        aggregates: list[tuple[str, str, str]] = []  # (alias, op, field)

        for col, spec in agg_dict.items():
            if spec is None:
                groups.add(col)
            else:
                op, field = spec.split(":", 1)
                aggregates.append((col, op, field))

        # Group rows
        groups_map: dict[tuple, list[dict]] = {}
        row_list = self._source if isinstance(self._source, list) else list(self._source)

        for row in row_list:
            # Apply where
            if self._where_preds:
                if not all(p(row) for p in self._where_preds):
                    continue

            key_vals = tuple(row.get(g) for g in groups)
            groups_map.setdefault(key_vals, []).append(row)

        # Aggregate
        results = []
        for key_vals, rows in groups_map.items():
            result = {}
            for i, g in enumerate(groups):
                result[g] = key_vals[i]

            for col, op, field in aggregates:
                vals = [r.get(field) for r in rows]
                vals = [v for v in vals if v is not None and v is not Null]
                if not vals:
                    result[col] = None
                elif op.lower() == "count":
                    result[col] = len(vals)
                elif op.lower() == "sum":
                    result[col] = sum(vals)
                elif op.lower() == "avg":
                    result[col] = sum(vals) / len(vals)
                elif op.lower() == "min":
                    result[col] = min(vals)
                elif op.lower() == "max":
                    result[col] = max(vals)

            results.append(result)

        return results

    def execute(self) -> Iterator[dict[str, Any]]:
        """Execute the query and yield rows."""
        if self._source is None:
            return
            yield  # make it a generator

        data = list(self._source)

        # Apply where
        if self._where_preds:
            data = [r for r in data if all(p(r) for p in self._where_preds)]

        # Apply OR predicates
        if getattr(self, '_or_preds', []):
            data = [r for r in data if any(p(r) for p in self._or_preds)]

        # Apply joins
        if self._joins:
            data = self._apply_joins(data)

        # Apply group_by
        if self._group_by_fields:
            data = self._apply_group_by(data)

        # Apply having
        if self._having_pred and data:
            data = [r for r in data if self._having_pred(r)]

        # Apply order_by
        if self._order_by:
            data = self._apply_order_by(data)

        # Apply distinct
        if self._distinct:
            data = self._apply_distinct(data)

        # Apply skip / limit
        start = self._skip
        if self._limit is not None:
            end = start + self._limit
        else:
            end = len(data)
        data = data[start:end]

        # Apply select
        if self._select_fields:
            data = self._apply_select(data)

        for row in data:
            yield row

    def _apply_joins(self, data: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Apply all stored joins."""
        for join_info in self._joins:
            jtype = join_info["type"]
            source = join_info["source"]
            lk = join_info["left_key"]
            rk = join_info["right_key"]

            # Build lookup on right side
            right_lookup: dict[Any, list[dict[str, Any]]] = {}
            for srow in source:
                rv = rk(srow)
                right_lookup.setdefault(rv, []).append(srow)

            new_data = []
            unmatched = set()

            for i, drow in enumerate(data):
                lv = lk(drow)
                matches = right_lookup.get(lv, [])
                if matches:
                    for srow in matches:
                        # Merge rows, prefixing right-side columns to avoid collision
                        merged = deepcopy(drow)
                        for k, v in srow.items():
                            new_key = f"r_{k}"
                            while new_key in merged:
                                new_key += "_"
                            merged[new_key] = v
                        merged["r_joined"] = True
                        new_data.append(merged)
                        unmatched.add((lv, id(srow)))
                elif jtype in (JoinType.LEFT, JoinType.FULL):
                    merged = deepcopy(drow)
                    merged["r_joined"] = False
                    new_data.append(merged)
                # INNER: no unmatched, RIGHT: handled below

            if jtype in (JoinType.RIGHT, JoinType.FULL):
                for srow in source:
                    rv = rk(srow)
                    if (rv, id(srow)) not in unmatched:
                        left_match = None
                        if jtype == JoinType.RIGHT:
                            left_match = data[0] if data else {}
                        merged = {}
                        if left_match:
