"""In-memory SQL-like query engine with a fluent, composable API."""

from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, Iterator, List, Optional, TypeVar, Generic, overload

T = TypeVar("T", bound=Dict[str, Any])


@dataclass
class GroupedResult(Generic[T]):
    """Result of a group_by operation, supporting aggregations."""

    _grouped: Dict[Any, List[Dict[str, Any]]]
    _group_column: str

    def count(self, column: str | None = None) -> Table[T]:
        """Count rows per group. If column specified, count non-null values."""
        result = []
        for key, rows in self._grouped.items():
            if column:
                count = sum(1 for r in rows if r.get(column) is not None)
            else:
                count = len(rows)
            result.append({self._group_column: key, "count": count})
        return Table(result)

    def sum(self, column: str) -> Table[T]:
        """Sum values of column per group."""
        result = []
        for key, rows in self._grouped.items():
            total = sum(r.get(column, 0) for r in rows if r.get(column) is not None)
            result.append({self._group_column: key, "sum": total})
        return Table(result)

    def avg(self, column: str) -> Table[T]:
        """Average values of column per group."""
        result = []
        for key, rows in self._grouped.items():
            values = [r[column] for r in rows if r.get(column) is not None]
            avg_val = sum(values) / len(values) if values else None
            result.append({self._group_column: key, "avg": avg_val})
        return Table(result)

    def min(self, column: str) -> Table[T]:
        """Minimum value of column per group."""
        result = []
        for key, rows in self._grouped.items():
            values = [r[column] for r in rows if r.get(column) is not None]
            min_val = min(values) if values else None
            result.append({self._group_column: key, "min": min_val})
        return Table(result)

    def max(self, column: str) -> Table[T]:
        """Maximum value of column per group."""
        result = []
        for key, rows in self._grouped.items():
            values = [r[column] for r in rows if r.get(column) is not None]
            max_val = max(values) if values else None
            result.append({self._group_column: key, "max": max_val})
        return Table(result)

    def to_dict(self) -> Dict[Any, List[Dict[str, Any]]]:
        """Return the grouped data as a dictionary."""
        return self._grouped


@dataclass
class Table(Generic[T]):
    """
    In-memory table holding rows as dictionaries.

    Provides a fluent API for querying and transforming data:
    select, where, join, group_by, order_by, limit.
    """

    _rows: List[Dict[str, Any]] = field(default_factory=list)

    def __init__(self, rows: Optional[List[Dict[str, Any]]] = None) -> None:
        self._rows = list(rows) if rows else []

    def __iter__(self) -> Iterator[Dict[str, Any]]:
        return iter(self._rows)

    def __len__(self) -> int:
        return len(self._rows)

    def __repr__(self) -> str:
        return f"Table(rows={self._rows!r})"

    def to_list(self) -> List[Dict[str, Any]]:
        """Return a copy of all rows as a list."""
        return list(self._rows)

    def select(
        self,
        *columns: str | tuple[str, str]
    ) -> Table[T]:
        """
        Select columns to keep, optionally renaming them.

        Args:
            *columns: Column names (str) or (old_name, new_name) tuples.

        Returns:
            New Table with selected columns.
        """
        if not columns:
            return Table(list(self._rows))

        result = []
        for row in self._rows:
            new_row = {}
            for col in columns:
                if isinstance(col, tuple):
                    old_name, new_name = col
                    if old_name in row:
                        new_row[new_name] = row[old_name]
                else:
                    if col in row:
                        new_row[col] = row[col]
            result.append(new_row)
        return Table(result)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table[T]:
        """
        Filter rows using a predicate function.

        Args:
            predicate: Function that takes a row dict and returns bool.

        Returns:
            New Table with only rows where predicate(row) is True.
        """
        return Table([row for row in self._rows if predicate(row)])

    def join(
        self,
        other: Table[T],
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool]
    ) -> Table[T]:
        """
        Perform an inner join with another table.

        Args:
            other: Table to join with.
            on: Predicate taking (left_row, right_row) returning bool.

        Returns:
            New Table with combined rows from both tables.
        """
        result = []
        for left_row in self._rows:
            for right_row in other._rows:
                if on(left_row, right_row):
                    merged = {**left_row, **right_row}
                    result.append(merged)
        return Table(result)

    def group_by(self, column: str) -> GroupedResult[T]:
        """
        Group rows by a column value.

        Args:
            column: Column name to group by.

        Returns:
            GroupedResult with aggregation methods (count, sum, avg, min, max).
        """
        grouped: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._rows:
            key = row.get(column)
            if key not in grouped:
                grouped[key] = []
            grouped[key].append(row)
        return GroupedResult(grouped, column)

    def order_by(self, column: str, descending: bool = False) -> Table[T]:
        """
        Sort rows by a column.

        Args:
            column: Column name to sort by.
            descending: If True, sort in descending order.

        Returns:
            New Table with sorted rows.
        """
        return Table(
            sorted(
                self._rows,
                key=lambda r: r.get(column),
                reverse=descending
            )
        )

    def limit(self, n: int) -> Table[T]:
        """
        Limit the number of rows.

        Args:
            n: Maximum number of rows to return.

        Returns:
            New Table with at most n rows.
        """
        return Table(self._rows[:n])


# ---------------------------------------------------------------------------
# Usage Examples
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    # Example 1: Basic query with select, where, order_by, limit
    users = Table([
        {"id": 1, "name": "Alice", "age": 30, "dept_id": 1},
        {"id": 2, "name": "Bob", "age": 25, "dept_id": 2},
        {"id": 3, "name": "Charlie", "age": 35, "dept_id": 1},
        {"id": 4, "name": "Diana", "age": 28, "dept_id": 3},
    ])

    result = (
        users
        .select("name", "age")
        .where(lambda r: r["age"] > 26)
        .order_by("age")
        .limit(2)
        .to_list()
    )
    print("Example 1 — Basic query:")
    for row in result:
        print(f"  {row}")
    # Output: [{'name': 'Diana', 'age': 28}, {'name': 'Alice', 'age': 30}]

    # Example 2: Join two tables
    departments = Table([
        {"dept_id": 1, "dept_name": "Engineering"},
        {"dept_id": 2, "dept_name": "Sales"},
        {"dept_id": 3, "dept_name": "Marketing"},
    ])

    result = (
        users
        .join(departments, on=lambda l, r: l["dept_id"] == r["dept_id"])
        .select("name", "dept_name")
        .to_list()
    )
    print("\nExample 2 — Join:")
    for row in result:
        print(f"  {row}")
    # Output: [{'name': 'Alice', 'dept_name': 'Engineering'}, ...]

    # Example 3: Group by with aggregation
    orders = Table([
        {"customer_id": 1, "product": "Widget", "amount": 100},
        {"customer_id": 1, "product": "Gadget", "amount": 200},
        {"customer_id": 2, "product": "Widget", "amount": 150},
        {"customer_id": 2, "product": "Gadget", "amount": 50},
        {"customer_id": 3, "product": "Widget", "amount": 75},
    ])

    result = (
        orders
        .group_by("customer_id")
        .sum("amount")
        .to_list()
    )
    print("\nExample 3 — Group by with aggregation:")
    for row in result:
        print(f"  {row}")
    # Output: [{'customer_id': 1, 'sum': 300}, {'customer_id': 2, 'sum': 200}, {'customer_id': 3, 'sum': 75}]

    # Example 4: Select with column renaming
    result = (
