from collections import defaultdict
import logging
from dataclasses import dataclass, field
from functools import wraps
import copy

# Type aliases for clarity
Row = Dict[str, Any]
Predicate = Callable[[Row], bool]
JoinCondition = Callable[[Row, Row], bool]
ColumnName = Union[str, List[str]]

# Setup logging for error visibility
logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger(__name__)

T = TypeVar('T', bound='Table')

def validate_table_operation(func: Callable) -> Callable:
    """Decorator to validate table state before operations."""
    @wraps(func)
    def wrapper(self: Table, *args: Any, **kwargs: Any) -> Any:
        if not self._rows:
            logger.warning(f"Operation {func.__name__} on empty table")
        return func(self, *args, **kwargs)
    return wrapper


@dataclass
class QueryResult:
    """Immutable container for query results with metadata."""
    rows: List[Row] = field(default_factory=list)
    columns: List[str] = field(default_factory=list)

    def __len__(self) -> int:
        return len(self.rows)

    def __iter__(self) -> Iterator[Row]:
        return iter(self.rows)

    def __getitem__(self, index: int) -> Row:
        return self.rows[index]

    def to_list(self) -> List[Row]:
        """Return a deep copy of rows to prevent mutation."""
        return copy.deepcopy(self.rows)


class Table:
    """In-memory table with SQL-like query operations."""

    def __init__(self, rows: Optional[List[Row]] = None) -> None:
        """
        Initialize table with rows.

        Args:
            rows: List of dictionaries representing table rows.
                  Each dict must have consistent keys across all rows.
        """
        self._rows: List[Row] = []
        self._columns: List[str] = []

        if rows:
            self._validate_rows(rows)
            self._rows = copy.deepcopy(rows)
            self._columns = list(rows[0].keys()) if rows else []

    def _validate_rows(self, rows: List[Row]) -> None:
        """Validate row structure consistency."""
        if not rows:
            return

        if not all(isinstance(row, dict) for row in rows):
            raise TypeError("All rows must be dictionaries")

        first_keys = set(rows[0].keys())
        for i, row in enumerate(rows[1:], start=1):
            if set(row.keys()) != first_keys:
                raise ValueError(
                    f"Row {i} has different columns than first row. "
                    f"Expected: {sorted(first_keys)}, Got: {sorted(row.keys())}"
                )

    @property
    def columns(self) -> List[str]:
        """Return column names."""
        return self._columns.copy()

    @property
    def row_count(self) -> int:
        """Return number of rows."""
        return len(self._rows)

    def add_row(self, row: Row) -> None:
        """Add a single row to the table."""
        if not self._columns:
            self._columns = list(row.keys())
            self._rows.append(copy.deepcopy(row))
        else:
            if set(row.keys()) != set(self._columns):
                raise ValueError(
                    f"Row columns don't match table columns. "
                    f"Expected: {sorted(self._columns)}, Got: {sorted(row.keys())}"
                )
            self._rows.append(copy.deepcopy(row))

    @validate_table_operation
    def select(self: T, *columns: ColumnName) -> T:
        """
        Select specific columns from the table.

        Args:
            *columns: Column names to select. Use '*' for all columns.
                     Can also pass a list of column names.

        Returns:
            New Table instance with selected columns.
        """
        if not columns:
            raise ValueError("At least one column must be specified")

        # Handle '*' for all columns
        if len(columns) == 1 and columns[0] == '*':
            return self._copy()

        # Flatten list arguments
        selected_columns: List[str] = []
        for col in columns:
            if isinstance(col, list):
                selected_columns.extend(col)
            else:
                selected_columns.append(col)

        # Validate columns exist
        for col in selected_columns:
            if col not in self._columns:
                raise ValueError(f"Column '{col}' not found in table")

        # Project rows
        new_rows = [
            {col: row[col] for col in selected_columns}
            for row in self._rows
        ]

        return Table(new_rows)

    @validate_table_operation
    def where(self: T, predicate: Predicate) -> T:
        """
        Filter rows based on predicate.

        Args:
            predicate: Function that takes a row and returns bool.

        Returns:
            New Table instance with filtered rows.
        """
        filtered_rows = [
            copy.deepcopy(row) for row in self._rows 
            if predicate(row)
        ]
        return Table(filtered_rows)

    @validate_table_operation
    def join(self: T, other: Table, on: JoinCondition) -> T:
        """
        Perform inner join with another table.

        Args:
            other: Table to join with.
            on: Function that takes (left_row, right_row) and returns bool.

        Returns:
            New Table instance with joined rows.
        """
        # Handle column name conflicts by prefixing
        left_prefix = "left_"
        right_prefix = "right_"

        joined_rows: List[Row] = []

        for left_row in self._rows:
            for right_row in other._rows:
                if on(left_row, right_row):
                    # Merge rows with prefixed column names
                    merged_row: Row = {}

                    # Add left columns with prefix
                    for key, value in left_row.items():
                        merged_row[f"{left_prefix}{key}"] = value

                    # Add right columns with prefix
                    for key, value in right_row.items():
                        merged_row[f"{right_prefix}{key}"] = value

                    joined_rows.append(merged_row)

        return Table(joined_rows)

    @validate_table_operation
    def group_by(self: T, column: str) -> Dict[Any, Table]:
        """
        Group rows by column value.

        Args:
            column: Column name to group by.

        Returns:
            Dictionary mapping group values to Table instances.
        """
        if column not in self._columns:
            raise ValueError(f"Column '{column}' not found in table")

        groups: Dict[Any, List[Row]] = defaultdict(list)

        for row in self._rows:
            key = row[column]
            groups[key].append(copy.deepcopy(row))

        return {
            key: Table(rows) 
            for key, rows in groups.items()
        }

    @validate_table_operation
    def order_by(self: T, column: str, descending: bool = False) -> T:
        """
        Sort rows by column value.

        Args:
            column: Column name to sort by.
            descending: Sort in descending order if True.

        Returns:
            New Table instance with sorted rows.
        """
        if column not in self._columns:
            raise ValueError(f"Column '{column}' not found in table")

        # Handle None values by treating them as smallest
        def sort_key(row: Row) -> Any:
            value = row[column]
            return (value is None, value)

        sorted_rows = sorted(
            self._rows, 
            key=sort_key, 
            reverse=descending
        )

        return Table(copy.deepcopy(sorted_rows))

    @validate_table_operation
    def limit(self: T, n: int) -> T:
        """
        Limit number of rows returned.

        Args:
            n: Maximum number of rows to return.

        Returns:
            New Table instance with limited rows.
        """
        if n < 0:
            raise ValueError("Limit must be non-negative")

        limited_rows = self._rows[:n]
        return Table(copy.deepcopy(limited_rows))

    def _copy(self: T) -> T:
        """Create a deep copy of the table."""
        return Table(copy.deepcopy(self._rows))

    def execute(self) -> QueryResult:
        """
        Execute the query and return results.

        Returns:
            QueryResult containing rows and metadata.
        """
        return QueryResult(
            rows=copy.deepcopy(self._rows),
            columns=self._columns.copy()
        )

    def __repr__(self) -> str:
        return f"Table(rows={len(self._rows)}, columns={self._columns})"

    def __iter__(self) -> Iterator[Row]:
        return iter(self._rows)


