import copy


class Table:
    """
    A lightweight in-memory table represented as a list of dictionaries (rows).
    Provides a fluent API for common SQL-like operations.
    """

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        self._rows = rows

    def rows(self) -> List[Dict[str, Any]]:
        """Return a copy of the internal list of rows."""
        return copy.deepcopy(self._rows)

    def select(self, *columns: str) -> "Table":
        """
        Project the table to only the specified columns.
        If no columns are provided, return the table as-is.
        """
        if not columns:
            return Table(self._rows[:])

        new_rows = []
        for row in self._rows:
            new_row = {col: row[col] for col in columns if col in row}
            new_rows.append(new_row)
        return Table(new_rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> "Table":
        """
        Filter rows where predicate(row) returns True.
        """
        new_rows = [row for row in self._rows if predicate(row)]
        return Table(new_rows)

    def join(
        self,
        other: "Table",
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool],
    ) -> "Table":
        """
        Perform an inner join with another Table.
        `on` is a function (left_row, right_row) -> bool.
        The resulting rows are merged (right overwrites left on key conflicts).
        """
        new_rows = []
        for left_row in self._rows:
            for right_row in other._rows:
                if on(left_row, right_row):
                    merged = {**left_row, **right_row}
                    new_rows.append(merged)
        return Table(new_rows)

    def group_by(self, column: str) -> "Table":
        """
        Group rows by the value of `column`.
        Returns a new Table where each row has the column value (key)
        and a column 'group' containing the list of rows in that group.
        """
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._rows:
            key = row[column]
            groups.setdefault(key, []).append(row)

        new_rows = [
            {column: key, "group": group_rows} for key, group_rows in groups.items()
        ]
        return Table(new_rows)

    def order_by(
        self, column: str, descending: bool = False
    ) -> "Table":
        """
        Sort rows by the given column. Default ascending; set descending=True for descending.
        """
        sorted_rows = sorted(
            self._rows,
            key=lambda row: row.get(column),
            reverse=descending,
        )
        return Table(sorted_rows)

    def limit(self, n: int) -> "Table":
        """
        Return only the first n rows.
        """
        return Table(self._rows[:n])

    def __repr__(self) -> str:
        return f"Table(rows={self._rows})"


