from __future__ import annotations
from typing import List, Dict, Callable, Any


class Table:
    """In-memory SQL-like query engine with a fluent API."""

    def __init__(self, data: List[Dict[str, Any]], name: str = "") -> None:
        # Deep-ish copy to prevent external mutation of internal state
        self._data: List[Dict[str, Any]] = [dict(row) for row in data]
        self._name: str = name

    def select(self, *columns: str) -> Table:
        """Project rows to only include the specified columns."""
        new_data = [{col: row[col] for col in columns} for row in self._data]
        return Table(new_data, self._name)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        """Filter rows based on a predicate function."""
        new_data = [row for row in self._data if predicate(row)]
        return Table(new_data, self._name)

    def join(self, other: Table, on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> Table:
        """Inner join with another table using a predicate."""
        new_data = []
        for left in self._data:
            for right in other._data:
                if on(left, right):
                    merged = {}
                    # Prefix keys with table names to avoid collisions
                    for k, v in left.items():
                        merged[f"{self._name}.{k}" if self._name else k] = v
                    for k, v in right.items():
                        merged[f"{other._name}.{k}" if other._name else k] = v
                    new_data.append(merged)
        return Table(new_data, f"{self._name}_join_{other._name}")

    def group_by(self, column: str) -> Table:
        """Group rows by a column and return count per group."""
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._data:
            key = row.get(column)
            if key not in groups:
                groups[key] = []
            groups[key].append(row)

        new_data = [{"group": k, "count": len(v)} for k, v in groups.items()]
        return Table(new_data, self._name)

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Sort rows by a column. Rows missing the column are placed at the end."""
        def sort_key(row: Dict[str, Any]) -> tuple:
            val = row.get(column)
            # (is_none, value) ensures None sorts last regardless of direction
            return (val is None, val)
        new_data = sorted(self._data, key=sort_key, reverse=descending)
        return Table(new_data, self._name)

    def limit(self, n: int) -> Table:
        """Limit the number of returned rows."""
        return Table(self._data[:n], self._name)

    def to_list(self) -> List[Dict[str, Any]]:
        """Return the current data as a list of dicts."""
        return [dict(row) for row in self._data]

    def __repr__(self) -> str:
        return f"Table({self._name!r}, rows={len(self._data)})"

