from typing import List, Dict, Any, Callable, Union, Optional
import operator

Row = Dict[str, Any]

class Table:
    def __init__(self, rows: List[Row], name: str = None):
        self.rows = rows
        self.name = name or "unnamed"

    # Start a query from this table
    def select(self, *columns) -> "Query":
        return Query(self).select(*columns)

    def where(self, predicate) -> "Query":
        return Query(self).where(predicate)

    # ... other query methods can be exposed for convenience

# --- file boundary ---

class Query:
    def __init__(self, table: Table):
        self.source = table  # base table
        self.steps: List[Step] = []

    def select(self, *columns) -> "Query":
        new_query = self._copy()
        new_query.steps.append(SelectStep(columns))
        return new_query

    def where(self, predicate: Union[Callable, "Expr"]) -> "Query":
        new_query = self._copy()
        new_query.steps.append(FilterStep(predicate))
        return new_query

    def group_by(self, *columns) -> "Query":
        new_query = self._copy()
        new_query.steps.append(GroupByStep(columns))
        return new_query

    def aggregate(self, **aggregations) -> "Query":
        new_query = self._copy()
        new_query.steps.append(AggregateStep(aggregations))
        return new_query

    def having(self, predicate) -> "Query":
        new_query = self._copy()
        new_query.steps.append(HavingStep(predicate))
        return new_query

    def order_by(self, *columns, descending: bool = False) -> "Query":
        new_query = self._copy()
        new_query.steps.append(OrderByStep(columns, descending))
        return new_query

    def limit(self, n: int, offset: int = 0) -> "Query":
        new_query = self._copy()
        new_query.steps.append(LimitOffsetStep(n, offset))
        return new_query

    def distinct(self) -> "Query":
        new_query = self._copy()
        new_query.steps.append(DistinctStep())
        return new_query

    def join(self, other_table: Union[Table, "Query"],
             on: "Expr", how: str = "inner") -> "Query":
        new_query = self._copy()
        new_query.steps.append(JoinStep(other_table, on, how))
        return new_query

    def _copy(self) -> "Query":
        q = Query(self.source)
        q.steps = self.steps.copy()
        return q

    def execute(self) -> List[Row]:
        rows = list(self.source.rows)  # make a copy
        for step in self.steps:
            rows = step.apply(rows)
        return rows

# --- file boundary ---

class Step:
    def apply(self, rows: List[Row]) -> List[Row]:
        raise NotImplementedError

class FilterStep(Step):
    def __init__(self, predicate):
        self.predicate = predicate

    def apply(self, rows):
        return [r for r in rows if self.predicate(r)]

class SelectStep(Step):
    def __init__(self, columns):
        self.columns = columns

    def apply(self, rows):
        return [{k: r[k] for k in self.columns if k in r} for r in rows]

class JoinStep(Step):
    def __init__(self, other_table_or_query, on_expr, how='inner'):
        self.other = other_table_or_query
        self.on = on_expr
        self.how = how

    def apply(self, left_rows):
        if isinstance(self.other, Query):
            right_rows = self.other.execute()
        else:
            right_rows = self.other.rows
        # Perform join using a simple nested-loop (O(n*m)) – optimization possible
        # 'on' is an Expr object that can evaluate to True/False for a (l,r) pair
        result = []
        if self.how == 'inner':
            for l in left_rows:
                for r in right_rows:
                    if self.on(l, r):
                        merged = {**l, **r}
                        result.append(merged)
        # handle left, right, outer similarly (with None columns)
        return result

class GroupByStep(Step):
    def __init__(self, columns):
        self.columns = columns

    def apply(self, rows):
        # Groups rows into buckets keyed by tuple of column values
        groups = {}
        for r in rows:
            key = tuple(r[c] for c in self.columns)
            if key not in groups:
                groups[key] = []
            groups[key].append(r)
        # Return a list of dicts with group keys and raw rows (to be aggregated later)
        return [{"_key": key, "_rows": grp} for key, grp in groups.items()]

class AggregateStep(Step):
    def __init__(self, aggregations: Dict[str, Callable]):
        # e.g., {"avg_salary": lambda rows: sum(r['salary'] for r in rows)/len(rows)}
        self.aggs = aggregations

    def apply(self, rows):
        # Expects rows from GroupByStep (with _key, _rows)
        result = []
        for entry in rows:
            new_row = dict(zip(self.columns if hasattr(self,'columns') else [], entry['_key']))
            for name, agg_func in self.aggs.items():
                new_row[name] = agg_func(entry['_rows'])
            result.append(new_row)
        return result

# ... similar for OrderByStep, LimitOffsetStep, DistinctStep, HavingStep

# --- file boundary ---

class Expr:
    def __call__(self, row): 
        raise NotImplementedError
    def __eq__(self, other):
        return ComparisonExpr(self, operator.eq, value(other))
    def __gt__(self, other):
        return ComparisonExpr(self, operator.gt, value(other))
    # ... etc

class ColumnRef(Expr):
    def __init__(self, col_name):
        self.col = col_name
    def __call__(self, row):
        return row.get(self.col)

class Literal(Expr):
    def __init__(self, value):
        self.value = value
    def __call__(self, row):
        return self.value

class ComparisonExpr(Expr):
    def __init__(self, left, op, right):
        self.left = left
        self.op = op
        self.right = right
    def __call__(self, row):
        return self.op(self.left(row), self.right(row))

# Helper functions
def col(name): return ColumnRef(name)
def lit(val): return Literal(val)

