        self.refill_rate = refill_rate  # tokens per second
        self.buckets: Dict[str, tuple[float, float]] = {} # (tokens, last_refill)

    def allow(self, client_id: str) -> bool:
        now = time.time()
        tokens, last_refill = self.buckets.get(client_id, (self.capacity, now))

        # Refill
        tokens = min(self.capacity, tokens + (now - last_refill) * self.refill_rate)

        if tokens >= 1:
            self.buckets[client_id] = (tokens - 1, now)
            return True
        self.buckets[client_id] = (tokens, now)
        return False

# 2. Leaky Bucket
class LeakyBucket(RateLimiter):
    def __init__(self, capacity: int, leak_rate: float):
        self.capacity = capacity
        self.leak_rate = leak_rate # seconds per request
        self.last_leak: Dict[str, float] = {}
        self.water: Dict[str, float] = {}

    def allow(self, client_id: str) -> bool:
        now = time.time()
        water = self.water.get(client_id, 0)
        last_leak = self.last_leak.get(client_id, now)

        # Leak water based on time passed
        water = max(0, water - (now - last_leak) / self.leak_rate)

        if water < self.capacity:
            self.water[client_id] = water + 1
            self.last_leak[client_id] = now
            return True
        return False

# 3. Sliding Window Log
class SlidingWindowLog(RateLimiter):
    def __init__(self, max_requests: int, window_size: int):
        self.max_requests = max_requests
        self.window_size = window_size
        self.logs: Dict[str, deque] = {}

    def allow(self, client_id: str) -> bool:
        now = time.time()
        if client_id not in self.logs:
            self.logs[client_id] = deque()

        # Remove expired logs
        while self.logs[client_id] and self.logs[client_id][0] <= now - self.window_size:
            self.logs[client_id].popleft()

        if len(self.logs[client_id]) < self.max_requests:
            self.logs[client_id].append(now)
            return True
        return False

# 4. Sliding Window Counter
class SlidingWindowCounter(RateLimiter):
    def __init__(self, max_requests: int, window_size: int):
        self.max_requests = max_requests
        self.window_size = window_size
        # Stores {client_id: {timestamp_bucket: count}}
        self.counters: Dict[str, Dict[int, int]] = {}

    def allow(self, client_id: str) -> bool:
        now = int(time.time())
        if client_id not in self.counters:
            self.counters[client_id] = {}

        # Clean old buckets
        self.counters[client_id] = {t: c for t, c in self.counters[client_id].items() 
                                    if t > now - self.window_size}

        total_count = sum(self.counters[client_id].values())
        if total_count < self.max_requests:
            self.counters[client_id][now] = self.counters[client_id].get(now, 0) + 1
            return True
        return False

# --- file boundary ---

def test_limiter(limiter: RateLimiter, name: str):
    print(f"--- Testing {name} ---")
    for i in range(5):
        allowed = limiter.allow("user_1")
        print(f"Request {i+1}: {'Allowed' if allowed else 'Blocked'}")
