    (LeakyBucket(capacity=3, leak_rate=0.5), "Leaky Bucket"),
    (SlidingWindowLog(max_requests=3, window_size=1), "Sliding Window Log"),
    (SlidingWindowCounter(max_requests=3, window_size=1), "Sliding Window Counter")
]

for limiter, name in limiters:
    test_limiter(limiter, name)

