    def allow(self, client_id: str) -> bool:
        now = time.time()
        last = self.last_leak.get(client_id, now)
        water = self.water.get(client_id, 0)

        # Leak
        water = max(0, water - (now - last) * self.leak_rate)

        if water < self.capacity:
            self.water[client_id] = water + 1
            self.last_leak[client_id] = now
            return True
        return False

# 3. Sliding Window Log: Precise, but memory intensive
class SlidingWindowLog(RateLimiter):
    def __init__(self, limit: int, window_size: int):
        self.limit = limit
        self.window_size = window_size
        self.logs: Dict[str, deque] = {}

    def allow(self, client_id: str) -> bool:
        now = time.time()
        if client_id not in self.logs:
            self.logs[client_id] = deque()

        # Remove expired
        while self.logs[client_id] and self.logs[client_id][0] < now - self.window_size:
            self.logs[client_id].popleft()

        if len(self.logs[client_id]) < self.limit:
            self.logs[client_id].append(now)
            return True
        return False

# 4. Sliding Window Counter: Memory efficient approximation
class SlidingWindowCounter(RateLimiter):
    def __init__(self, limit: int, window_size: int):
        self.limit = limit
        self.window_size = window_size
        self.curr_window: Dict[str, int] = {}
        self.prev_window: Dict[str, int] = {}
        self.window_start: Dict[str, float] = {}

    def allow(self, client_id: str) -> bool:
        now = time.time()
        start = self.window_start.get(client_id, now)

        if now - start > self.window_size:
            self.prev_window[client_id] = self.curr_window.get(client_id, 0)
            self.curr_window[client_id] = 0
            self.window_start[client_id] = now
            start = now

        weight = (self.window_size - (now - start)) / self.window_size
        count = (self.prev_window.get(client_id, 0) * weight) + self.curr_window.get(client_id, 0)

        if count < self.limit:
            self.curr_window[client_id] = self.curr_window.get(client_id, 0) + 1
            return True
        return False

