from __future__ import annotations
from typing import List, Dict, Any, Callable, Iterable, Tuple


class Table:
    """
    Simple in‑memory table that holds a list of dict rows.
    All query methods return a new Table instance, enabling a fluent API.
    """

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        # Store a shallow copy so the original data is not mutated accidentally.
        self._rows: List[Dict[str, Any]] = [dict(r) for r in rows]

    # ------------------------------------------------------------------ #
    # Helper for chaining – each public method returns a new Table.
    # ------------------------------------------------------------------ #
    def _new(self, rows: List[Dict[str, Any]]) -> "Table":
        return Table(rows)

    # ------------------------------------------------------------------ #
    # Query primitives
    # ------------------------------------------------------------------ #
    def select(self, *columns: str) -> "Table":
        """Project only the given columns (if none given, keep all)."""
        if not columns:
            return self._new(self._rows)

        def project(row: Dict[str, Any]) -> Dict[str, Any]:
            return {c: row[c] for c in columns if c in row}

        return self._new([project(r) for r in self._rows])

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> "Table":
        """Filter rows with a predicate function."""
        return self._new([r for r in self._rows if predicate(r)])

    def join(
        self,
        other: Table,
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool],
    ) -> "Table":
        """Inner join – cartesian product filtered by ``on``."""
        joined: List[Dict[str, Any]] = []
        for l in self._rows:
            for r in other._rows:
                if on(l, r):
                    # Right‑hand values overwrite left‑hand on key clash.
                    joined.append({**l, **r})
        return self._new(joined)

    def group_by(self, column: str) -> "Table":
        """
        Very simple aggregation: count rows per group.
        Result rows contain the group column and a '_count' field.
        """
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._rows:
            key = row.get(column)
            groups.setdefault(key, []).append(row)

        aggregated: List[Dict[str, Any]] = [
            {column: key, "_count": len(rows)} for key, rows in groups.items()
        ]
        return self._new(aggregated)

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Sort rows by the given column."""
        try:
            sorted_rows = sorted(
                self._rows,
                key=lambda r: r[column],
                reverse=descending,
            )
        except KeyError as exc:
            raise KeyError(f"Column '{column}' not found in table") from exc
        return self._new(sorted_rows)

    def limit(self, n: int) -> "Table":
        """Keep only the first ``n`` rows."""
        if n < 0:
            raise ValueError("limit must be non‑negative")
        return self._new(self._rows[:n])

    # ------------------------------------------------------------------ #
    # Convenience / representation
    # ------------------------------------------------------------------ #
    def __repr__(self) -> str:
        return f"Table({len(self._rows)} rows)"

    def rows(self) -> List[Dict[str, Any]]:
        """Return a shallow copy of the current rows (useful for inspection)."""
        return [dict(r) for r in self._rows]


# ---------------------------------------------------------------------- #
# Usage examples
# ---------------------------------------------------------------------- #
if __name__ == "__main__":
    # Example 1: simple filtering and projection
    employees = Table(
        [
            {"id": 1, "name": "Alice", "dept": "Sales", "salary": 70000},
            {"id": 2, "name": "Bob",   "dept": "Engineering", "salary": 95000},
            {"id": 3, "name": "Carol", "dept": "Sales", "salary": 65000},
            {"id": 4, "name": "Dave",  "dept": "Engineering", "salary": 120000},
        ]
    )

    high_earners = (
        employees.where(lambda r: r["salary"] > 80000)
                 .select("id", "name", "dept")
                 .order_by("salary", descending=True)
    )
    print("High earners:", high_earners.rows())
    # → [{'id': 4, 'name': 'Dave', 'dept': 'Engineering'},
    #    {'id': 2, 'name': 'Bob',   'dept': 'Engineering'}]

    # Example 2: join + aggregation
    departments = Table(
        [
            {"dept_id": 10, "dept": "Sales",      "location": "NY"},
            {"dept_id": 20, "dept": "Engineering","location": "SF"},
        ]
    )

    # Join employees with departments on dept name, then count per location
    staff_by_location = (
        employees.join(
            departments,
            on=lambda l, r: l["dept"] == r["dept"],
        )
        .group_by("location")
        .order_by("_count", descending=True)
    )
    print("\nStaff per location:", staff_by_location.rows())
    # → [{'location': 'SF', '_count': 2}, {'location': 'NY', '_count': 2}]

    # Example 3: chaining limit after ordering
    top_two_paid = employees.order_by("salary", descending=True).limit(2)
    print("\nTop two paid:", top_two_paid.rows())
    # → [{'id': 4, 'name': 'Dave', 'dept': 'Engineering', 'salary': 120000},
    #    {'id': 2, 'name': 'Bob',   'dept': 'Engineering', 'salary': 95000}]

import time
from abc import ABC, abstractmethod
from collections import deque
from typing import Dict, List

class RateLimiter(ABC):
    """Base interface for all rate limiting algorithms."""
    @abstractmethod
    def allow(self, client_id: str) -> bool:
        """Returns True if the request is allowed, False otherwise."""
        pass

class TokenBucket(RateLimiter):
    """
    Allows bursts of traffic. Tokens are added at a fixed rate.
    If the bucket is full, new tokens are discarded.
    """
    def __init__(self, capacity: int, refill_rate: float):
        self.capacity = capacity
        self.refill_rate = refill_rate  # tokens per second
        self.buckets: Dict[str, Dict[str, float]] = {}

    def allow(self, client_id: str) -> bool:
        now = time.time()
        if client_id not in self.buckets:
            self.buckets[client_id] = {"tokens": float(self.capacity), "last_update": now}

        bucket = self.buckets[client_id]
        # Refill tokens based on time elapsed
        elapsed = now - bucket["last_update"]
        bucket["tokens"] = min(self.capacity, bucket["tokens"] + elapsed * self.refill_rate)
        bucket["last_update"] = now

        if bucket["tokens"] >= 1:
            bucket["tokens"] -= 1
            return True
        return False

class LeakyBucket(RateLimiter):
    """
    Smooths out bursts. Requests leak out of the bucket at a constant rate.
    If the bucket overflows, requests are rejected.
    """
    def __init__(self, capacity: int, leak_rate: float):
        self.capacity = capacity
        self.leak_rate = leak_rate  # requests per second
        self.buckets: Dict[str, Dict[str, float]] = {}

    def allow(self, client_id: str) -> bool:
        now = time.time()
        if client_id not in self.buckets:
            self.buckets[client_id] = {"level": 0.0, "last_update": now}

        bucket = self.buckets[client_id]
        # Leak tokens based on time elapsed
        elapsed = now - bucket["last_update"]
        bucket["level"] = max(0.0, bucket["level"] - elapsed * self.leak_rate)
        bucket["last_update"] = now

        if bucket["level"] < self.capacity:
            bucket["level"] += 1
            return True
        return False

class SlidingWindowLog(RateLimiter):
    """
    Precise window. Stores timestamps of every request.
    Memory intensive for high-volume clients.
    """
    def __init__(self, window_size: float, max_requests: int):
        self.window_size = window_size
        self.max_requests = max_requests
        self.logs: Dict[str, deque] = {}

    def allow(self, client_id: str) -> bool:
        now = time.time()
        if client_id not in self.logs:
            self.logs[client_id] = deque()

        log = self.logs[client_id]
        # Remove timestamps outside the current window
        while log and log[0] <= now - self.window_size:
            log.popleft()

        if len(log) < self.max_requests:
            log.append(now)
            return True
        return False

class SlidingWindowCounter(RateLimiter):
    """
    Approximate window. Combines current window count and previous window count.
    Memory efficient and prevents boundary bursts.
    """
    def __init__(self, window_size: float, max_requests: int):
        self.window_size = window_size
        self.max_requests = max_requests
        # Stores {client_id: {window_timestamp: count}}
        self.counts: Dict[str, Dict[float, int]] = {}

    def allow(self, client_id: str) -> bool:
        now = time.time()
        current_window = now - (now % self.window_size)
        prev_window = current_window - self.window_size

        if client_id not in self.counts:
            self.counts[client_id] = {}

        client_data = self.counts[client_id]

        # Get counts for current and previous window
        curr_count = client_data.get(current_window, 0)
        prev_count = client_data.get(prev_window, 0)

        # Calculate weight of previous window
        overlap_weight = (current_window + self.window_size - now) / self.window_size
        approx_count = curr_count + (prev_count * overlap_weight)

        if approx_count < self.max_requests:
            client_data[current_window] = curr_count + 1
            # Cleanup old windows to prevent memory leak
            self.counts[client_id] = {k: v for k, v in client_data.items() if k >= prev_window}
            return True
        return False

# ==========================================
# Usage Example
# ==========================================
if __name__ == "__main__":
    # Configuration: 5 requests per 2 seconds
    limiters: Dict[str, RateLimiter] = {
        "Token Bucket": TokenBucket(capacity=5, refill_rate=2.5),
        "Leaky Bucket": LeakyBucket(capacity=5, leak_rate=2.5),
        "Sliding Log": SlidingWindowLog(window_size=2.0, max_requests=5),
        "Sliding Counter": SlidingWindowCounter(window_size=2.0, max_requests=5),
    }

    user = "user_123"

    for name, limiter in limiters.items():
        print(f"\nTesting {name}:")
        # Try to send 7 requests rapidly
        for i in range(1, 8):
            allowed = limiter.allow(user)
            print(f" Request {i}: {'✅ Allowed' if allowed else '❌ Denied'}")

        # Wait a bit and try again
        print(" Waiting 1 second...")
        time.sleep(1)
        print(f" Request 8: {'✅ Allowed' if limiter.allow(user) else '❌ Denied'}")

