"""In-memory SQL-like query engine with a fluent, composable API."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Callable, Dict, Iterator, List, Literal, TypeVar, overload

T = TypeVar("T")
Row = Dict[str, Any]
Predicate = Callable[[Row], bool]
JoinCondition = Callable[[Row, Row], bool]


@dataclass
class Table:
    """In-memory table holding a list of dictionary rows.

    Supports fluent chaining: table.where(...).select(...).order_by(...).limit(...)
    """

    _rows: List[Row] = field(default_factory=list)
    _name: str = "anonymous"

    def __post_init__(self) -> None:
        # Ensure all rows are dicts (defensive copy)
        self._rows = [dict(r) for r in self._rows]

    @classmethod
    def from_dicts(cls, rows: List[Row], name: str = "t") -> Table:
        """Factory to create a Table from a list of dictionaries."""
        return cls(rows, name)

    # --- Transformation methods (fluent API) ---

    def select(self, *columns: str) -> Table:
        """Select specific columns, returning a new Table."""
        if not columns:
            return Table(self._rows[:], f"select({self._name})")

        selected = []
        for row in self._rows:
            selected.append({col: row[col] for col in columns if col in row})
        return Table(selected, f"select({self._name})")

    def where(self, predicate: Predicate) -> Table:
        """Filter rows using a predicate function."""
        filtered = [row for row in self._rows if predicate(row)]
        return Table(filtered, f"where({self._name})")

    def join(self, other: Table, on: JoinCondition) -> Table:
        """Inner join with another table using a condition function."""
        joined = []
        for left in self._rows:
            for right in other._rows:
                if on(left, right):
                    # Merge rows, with right-side keys prefixed to avoid collision
                    merged: Row = {**left}
                    for k, v in right.items():
                        merged[k if k not in left else f"{other._name}.{k}"] = v
                    joined.append(merged)
        return Table(joined, f"join({self._name}, {other._name})")

    def group_by(self, column: str) -> GroupedTable:
        """Group rows by a column, returning a GroupedTable for aggregations."""
        groups: Dict[Any, List[Row]] = {}
        for row in self._rows:
            key = row.get(column)
            if key not in groups:
                groups[key] = []
            groups[key].append(row)
        return GroupedTable(groups, column, self._name)

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Sort rows by a column."""
        sorted_rows = sorted(
            self._rows,
            key=lambda r: r.get(column),
            reverse=descending,
        )
        return Table(sorted_rows, f"order_by({self._name})")

    def limit(self, n: int) -> Table:
        """Limit the number of rows."""
        return Table(self._rows[:n], f"limit({self._name})")

    # --- Terminal methods ---

    def to_list(self) -> List[Row]:
        """Return the underlying rows as a list of dictionaries."""
        return self._rows.copy()

    def first(self) -> Row | None:
        """Return the first row, or None if empty."""
        return self._rows[0] if self._rows else None

    def count(self) -> int:
        """Return the number of rows."""
        return len(self._rows)

    def __iter__(self) -> Iterator[Row]:
        return iter(self._rows)

    def __repr__(self) -> str:
        return f"Table({self._name}, {len(self._rows)} rows)"


@dataclass
class GroupedTable:
    """Result of group_by, supports aggregation functions."""

    _groups: Dict[Any, List[Row]]
    _group_column: str
    _source_name: str

    def _aggregate(
        self,
        agg_name: str,
        agg_func: Callable[[List[Row]], Any],
        agg_column: str | None = None,
    ) -> Table:
        """Generic aggregation helper."""
        rows = []
        for key, group_rows in self._groups.items():
            result: Row = {self._group_column: key}
            if agg_column:
                result[f"{agg_name}_{agg_column}"] = agg_func(group_rows, agg_column)
            else:
                result[agg_name] = agg_func(group_rows)
            rows.append(result)
        return Table(rows, f"{agg_name}({self._source_name})")

    def sum(self, column: str) -> Table:
        """Sum a column within each group."""
        def _sum(rows: List[Row], col: str) -> float:
            return sum(r.get(col, 0) for r in rows)

        return self._aggregate("sum", _sum, column)

    def count(self) -> Table:
        """Count rows in each group."""
        def _count(rows: List[Row]) -> int:
            return len(rows)

        return self._aggregate("count", _count)

    def avg(self, column: str) -> Table:
        """Average of a column within each group."""
        def _avg(rows: List[Row], col: str) -> float:
            values = [r.get(col, 0) for r in rows]
            return sum(values) / len(values) if values else 0.0

        return self._aggregate("avg", _avg, column)

    def min(self, column: str) -> Table:
        """Minimum of a column within each group."""
        def _min(rows: List[Row], col: str) -> Any:
            return min((r.get(col) for r in rows), default=None)

        return self._aggregate("min", _min, column)

    def max(self, column: str) -> Table:
        """Maximum of a column within each group."""
        def _max(rows: List[Row], col: str) -> Any:
            return max((r.get(col) for r in rows), default=None)

        return self._aggregate("max", _max, column)


