from __future__ import annotations

from typing import Any, Callable, Dict, List


class Table:
    """A lightweight, immutable‑ish table backed by a list of dict rows.

    Each method returns a new ``Table`` instance, enabling a fluent API.
    """

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        """Create a table from an iterable of mapping rows.

        Args:
            rows: Sequence of dictionaries representing table rows.
        """
        # Defensive copy – callers should not be able to mutate our internal state.
        self._rows: List[Dict[str, Any]] = [dict(r) for r in rows]
        for i, r in enumerate(self._rows):
            if not isinstance(r, dict):
                raise TypeError(f"Row {i} is not a dict")

    # ------------------------------------------------------------------ #
    # Read‑only access
    # ------------------------------------------------------------------ #
    @property
    def rows(self) -> List[Dict[str, Any]]:
        """Return a shallow copy of the internal row list."""
        return [dict(r) for r in self._rows]

    # ------------------------------------------------------------------ #
    # Core verbs
    # ------------------------------------------------------------------ #
    def select(self, *columns: str) -> "Table":
        """Project only the given columns (or all columns if none are supplied)."""
        if not columns:
            return Table(self._rows)  # return a copy

        # Validate column names up‑front to give a clear error.
        missing = {c for c in columns if any(c not in r for r in self._rows)}
        if missing:
            raise KeyError(f"Column(s) {missing} not present in all rows")

        projected = [{c: r[c] for c in columns} for r in self._rows]
        return Table(projected)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> "Table":
        """Filter rows by a predicate function."""
        if not callable(predicate):
            raise TypeError("predicate must be callable")
        filtered = [r for r in self._rows if predicate(r)]
        return Table(filtered)

    def join(
        self,
        other: Table,
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool],
    ) -> "Table":
        """Inner join with another table using a binary predicate."""
        if not callable(on):
            raise TypeError("on must be callable")
        joined: List[Dict[str, Any]] = []
        for left in self._rows:
            for right in other._rows:
                if on(left, right):
                    combined = left.copy()
                    combined.update(right)  # right overrides left on key clash
                    joined.append(combined)
        return Table(joined)

    def group_by(self, column: str) -> "Table":
        """Return the distinct values of *column* as a one‑column table."""
        if not self._rows:
            return Table([])

        # Let KeyError propagate if column is absent – clearer than a silent fail.
        seen: set[Any] = set()
        groups: List[Dict[str, Any]] = []
        for row in self._rows:
            val = row[column]
            if val not in seen:
                seen.add(val)
                groups.append({column: val})
        return Table(groups)

    def order_by(self, column: str, descending: bool = False) -> "Table":
        """Sort rows by *column*."""
        if not self._rows:
            return Table([])

        # Validate column existence for all rows.
        if any(column not in r for r in self._rows):
            raise KeyError(f"Column '{column}' not found in every row")
        sorted_rows = sorted(
            self._rows, key=lambda r: r[column], reverse=descending
        )
        return Table(sorted_rows)

    def limit(self, n: int) -> "Table":
        """Return the first *n* rows."""
        if not isinstance(n, int) or n < 0:
            raise ValueError("limit must be a non‑negative integer")
        return Table(self._rows[:n])

    # ------------------------------------------------------------------ #
    # Representation
    # ------------------------------------------------------------------ #
    def __repr__(self) -> str:
        return f"Table({self._rows!r})"


# ---------------------------------------------------------------------- #
# Usage examples
# ---------------------------------------------------------------------- #
if __name__ == "__main__":
    # Example 1: simple filter and projection
    employees = Table(
        [
            {"id": 1, "name": "Alice", "dept": "Sales", "salary": 70_000},
            {"id": 2, "name": "Bob", "dept": "Engineering", "salary": 90_000},
            {"id": 3, "name": "Carol", "dept": "Sales", "salary": 75_000},
            {"id": 4, "name": "Dave", "dept": "Engineering", "salary": 95_000},
        ]
    )

    high_sales = (
        employees
        .where(lambda r: r["dept"] == "Sales" and r["salary"] > 72_000)
        .select("id", "name", "salary")
    )
    print("High‑earning salespeople:", high_sales.rows)

    # Example 2: inner join
    departments = Table(
        [
            {"dept_id": 10, "dept": "Sales", "location": "NY"},
            {"dept_id": 20, "dept": "Engineering", "location": "SF"},
        ]
    )

    joined = (
        employees
        .join(departments, on=lambda l, r: l["dept"] == r["dept"])
        .select("id", "name", "location")
        .order_by("name")
    )
    print("Joined table:", joined.rows)

    # Example 3: grouping, ordering and limiting
    dept_list = (
        employees
        .group_by("dept")
        .order_by("dept")
        .limit(2)
    )
    print("First two departments:", dept_list.rows)

