class FluentQuery(Generic[T]):
    """
    Main query class providing fluent API for SQL-like operations.
    """

    def __init__(self, data: Iterable[T], context: Optional[QueryContext] = None):
        self._data: List[T] = list(data)
        self._context = context or QueryContext()
        self._operations: List[Callable] = []
        self._current_operation: Optional[str] = None

    # Core operations

    def select(self, *columns: Union[str, Column, Callable]) -> 'FluentQuery[Dict]':
        """
        SELECT operation. Can select specific columns or transform items.
        """
        def _select_transform(item: Any) -> Any:
            if len(columns) == 0:
                return item

            # If columns are strings/Column objects
            if all(isinstance(col, (str, Column)) for col in columns):
                if isinstance(item, dict):
                    # Select specific keys
                    col_names = [str(col) for col in columns]
                    return {k: item.get(k) for k in col_names}
                else:
                    # For objects, create dict with attributes
                    result = {}
                    for col in columns:
                        col_name = str(col)
                        if hasattr(item, col_name):
                            result[col_name] = getattr(item, col_name)
                        else:
                            result[col_name] = None
                    return result
            else:
                # If columns are callables (transformations)
                results = []
                for col in columns:
                    if isinstance(col, (str, Column)):
                        # Access property
                        col_name = str(col)
                        if isinstance(item, dict):
                            results.append(item.get(col_name))
                        else:
                            results.append(getattr(item, col_name, None))
                    elif callable(col):
                        # Apply transformation
                        results.append(col(item))
                    else:
                        results.append(col)

                if len(results) == 1:
                    return results[0]
                else:
                    # Return tuple if multiple columns
                    return tuple(results)

        self._operations.append(_select_transform)
        self._current_operation = 'select'
        return cast('FluentQuery[Dict]', self)

    def where(self, condition: Union[Callable, str]) -> 'FluentQuery[T]':
        """
        WHERE operation with lambda or string expression.
        """
        if isinstance(condition, str):
            # Parse simple string conditions like "age > &0"
            def _parse_string_condition(item: Any) -> bool:
                # Simple placeholder replacement
                condition_str = condition

                # Replace &0, &1, etc. with item properties
                if isinstance(item, dict):
                    for i in range(10):
                        placeholder = f"&{i}"
                        if placeholder in condition_str:
                            # Use first key for &0
                            if i == 0:
                                keys = list(item.keys())
                                if keys:
                                    condition_str = condition_str.replace(placeholder, str(item[keys[0]]))
                return eval(condition_str, {"item": item})
            self._operations.append(lambda items: [item for item in items if _parse_string_condition(item)])
        else:
            self._operations.append(lambda items: [item for item in items if condition(item)])

        self._current_operation = 'where'
        return self

    def order_by(self, key: Union[str, Callable, Column], 
                 descending: bool = False) -> 'FluentQuery[T]':
        """
        ORDER BY operation.
        """
        def _order_transform(items: List[T]) -> List[T]:
            if isinstance(key, (str, Column)):
                key_str = str(key)
                if isinstance(items[0], dict):
                    return sorted(items, 
                                  key=lambda x: x.get(key_str),
                                  reverse=descending)
                else:
                    return sorted(items,
                                  key=lambda x: getattr(x, key_str, None),
                                  reverse=descending)
            else:
                return sorted(items, key=key, reverse=descending)

        self._operations.append(_order_transform)
        self._current_operation = 'order_by'
        return self

    def group_by(self, key: Union[str, Callable, Column]) -> 'FluentQuery[Dict[Any, List[T]]]':
        """
        GROUP BY operation.
        """
        def _group_transform(items: List[T]) -> Dict[Any, List[T]]:
            groups = defaultdict(list)

            if isinstance(key, (str, Column)):
                key_str = str(key)
                for item in items:
                    if isinstance(item, dict):
                        group_key = item.get(key_str)
                    else:
                        group_key = getattr(item, key_str, None)
                    groups[group_key].append(item)
            else:
                for item in items:
                    group_key = key(item)
                    groups[group_key].append(item)

            return dict(groups)

        self._operations.append(_group_transform)
        self._current_operation = 'group_by'
        return cast('FluentQuery[Dict[Any, List[T]]]', self)

    def join(self, other: Iterable[V], 
             on: Optional[Callable[[T, V], bool]] = None,
             left_key: Optional[Union[str, Callable]] = None,
             right_key: Optional[Union[str, Callable]] = None) -> 'FluentQuery[Tuple[T, V]]':
        """
        JOIN operation (inner join).
        """
        other_list = list(other)

        def _join_transform(items: List[T]) -> List[Tuple[T, V]]:
            result = []

            if on:
                # Custom join condition
                for left in items:
                    for right in other_list:
                        if on(left, right):
                            result.append((left, right))
            elif left_key and right_key:
                # Key-based join
                for left in items:
                    left_val = _get_value(left, left_key)
                    for right in other_list:
                        right_val = _get_value(right, right_key)
                        if left_val == right_val:
