        return self.sum(column) / count

    def min(self, column: Union[str, Column, Callable]) -> Any:
        """MIN aggregation."""
        result = self.execute()
        values = []

        for item in result:
            if isinstance(column, (str, Column)):
                col_name = str(column)
                if isinstance(item, dict):
                    val = item.get(col_name)
                else:
                    val = getattr(item, col_name, None)
            else:
                val = column(item)

            if val is not None:
                values.append(val)

        return min(values) if values else None

    def max(self, column: Union[str, Column, Callable]) -> Any:
        """MAX aggregation."""
        result = self.execute()
        values = []

        for item in result:
            if isinstance(column, (str, Column)):
                col_name = str(column)
                if isinstance(item, dict):
                    val = item.get(col_name)
                else:
                    val = getattr(item, col_name, None)
            else:
                val = column(item)

            if val is not None:
                values.append(val)

        return max(values) if values else None

    # Utility methods

    def execute(self) -> List[T]:
        """Execute all operations and return result."""
        current_data = self._data

        for operation in self._operations:
            current_data = operation(current_data)

        return current_data

    def to_list(self) -> List[T]:
        """Alias for execute."""
        return self.execute()

    def first(self) -> Optional[T]:
        """Get first item."""
        result = self.execute()
        return result[0] if result else None

    def last(self) -> Optional[T]:
        """Get last item."""
        result = self.execute()
        return result[-1] if result else None

    def any(self) -> bool:
        """Check if any items exist."""
        return len(self.execute()) > 0

    def all(self, condition: Callable) -> bool:
        """Check if all items satisfy condition."""
        return all(condition(item) for item in self.execute())

    # Chaining utilities

    def map(self, func: Callable) -> 'FluentQuery':
        """Map transformation."""
        self._operations.append(lambda items: [func(item) for item in items])
        return self

    def filter(self, func: Callable) -> 'FluentQuery[T]':
        """Filter transformation."""
        self._operations.append(lambda items: [item for item in items if func(item)])
        return self

    def take(self, n: int) -> 'FluentQuery[T]':
        """Take n items."""
        return self.limit(n)

    def chunk(self, size: int) -> 'FluentQuery[List[T]]':
        """Split into chunks."""
        def _chunk_transform(items: List[T]) -> List[List[T]]:
