from abc import ABC, abstractmethod
import time
from collections import deque

class RateLimiter(ABC):
    @abstractmethod
    def allow(self, client_id: str) -> bool:
        pass

# --- file boundary ---

class TokenBucket(RateLimiter):
    def __init__(self, capacity: int, refill_rate: float):
        self.capacity = capacity
        self.refill_rate = refill_rate  # tokens per second
        self.buckets = {}

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        state = self.buckets.get(client_id, [self.capacity, now])

        # Refill
        elapsed = now - state[1]
        state[0] = min(self.capacity, state[0] + elapsed * self.refill_rate)
        state[1] = now

        if state[0] >= 1:
            state[0] -= 1
            self.buckets[client_id] = state
            return True
        return False

class LeakyBucket(RateLimiter):
    def __init__(self, capacity: int, leak_rate: float):
        self.capacity = capacity
        self.leak_rate = leak_rate  # units per second
        self.buckets = {}

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        last_leak, water = self.buckets.get(client_id, (now, 0))

        # Leak
        elapsed = now - last_leak
        water = max(0, water - elapsed * self.leak_rate)

        if water + 1 <= self.capacity:
            self.buckets[client_id] = (now, water + 1)
            return True
        return False

class SlidingWindowLog(RateLimiter):
    def __init__(self, limit: int, window_size: int):
        self.limit = limit
        self.window_size = window_size
        self.logs = {}

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        window_start = now - self.window_size

        log = self.logs.get(client_id, deque())
        # Remove expired
        while log and log[0] < window_start:
            log.popleft()

        if len(log) < self.limit:
            log.append(now)
            self.logs[client_id] = log
            return True
        return False

class SlidingWindowCounter(RateLimiter):
    def __init__(self, limit: int, window_size: int):
        self.limit = limit
        self.window_size = window_size
        self.counters = {} # {client_id: {window_start: count}}

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        curr_win = int(now // self.window_size)
        prev_win = curr_win - 1

        data = self.counters.setdefault(client_id, {curr_win: 0, prev_win: 0})

        # Weighted count: (count in prev * overlap) + count in curr
        weight = (self.window_size - (now % self.window_size)) / self.window_size
        total = (data.get(prev_win, 0) * weight) + data.get(curr_win, 0)

        if total < self.limit:
            data[curr_win] += 1
            return True
        return False

# --- file boundary ---

def test_limiter(limiter: RateLimiter, name: str):
    print(f"--- Testing {name} ---")
    for i in range(5):
        allowed = limiter.allow("user_1")
        print(f"Request {i+1}: {'Allowed' if allowed else 'Denied'}")
        time.sleep(0.1)

if __name__ == "__main__":
    limiters = [
        ("Token Bucket", TokenBucket(capacity=3, refill_rate=1)),
        ("Leaky Bucket", LeakyBucket(capacity=3, leak_rate=1)),
        ("Sliding Log", SlidingWindowLog(limit=3, window_size=1)),
        ("Sliding Counter", SlidingWindowCounter(limit=3, window_size=1))
    ]

    for name, limiter in limiters:
        test_limiter(limiter, name)

from __future__ import annotations

from typing import List, Dict, Any, Callable, Optional, Tuple
import copy


class Table:
    """
    Simple in‑memory relational table.

    Each row is a ``dict`` mapping column names to values.
    All methods return a new ``Table`` instance, enabling a fluent API.
    """

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        # Store a deep copy so the original data is never mutated by the table.
        self._rows: List[Dict[str, Any]] = copy.deepcopy(rows)

    # ------------------------------------------------------------------ #
    # Core query operations
    # ------------------------------------------------------------------ #
    def select(self, *columns: str) -> Table:
        """
        Project only the given columns.
        If no columns are supplied, all columns are kept.
        """
        if not columns:
            return Table(self._rows)

        projected: List[Dict[str, Any]] = []
        for row in self._rows:
            projected.append({col: row[col] for col in columns if col in row})
        return Table(projected)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        """Filter rows by a predicate function."""
        filtered = [row for row in self._rows if predicate(row)]
        return Table(filtered)

    def join(
        self,
        other: Table,
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool],
    ) -> Table:
        """
        Inner join with another table.
        The resulting row is a merge of the left and right rows
        (right‑hand values overwrite left‑hand keys on collision).
        """
        joined: List[Dict[str, Any]] = []
        for lrow in self._rows:
            for rrow in other._rows:
                if on(lrow, rrow):
                    merged = {**lrow, **rrow}
                    joined.append(merged)
        return Table(joined)

    def group_by(self, column: str) -> Table:
        """
        Group rows by the given column.
        Each group becomes a row containing the column value and a ``_count`` field.
        """
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._rows:
            key = row.get(column)
            groups.setdefault(key, []).append(row)

        grouped: List[Dict[str, Any]] = []
        for key, rows in groups.items():
            grouped.append({column: key, "_count": len(rows)})
        return Table(grouped)

    def order_by(
        self, column: str, descending: bool = False
    ) -> Table:
        """Sort rows by the given column."""
        sorted_rows = sorted(
            self._rows,
            key=lambda r: r.get(column),
            reverse=descending,
        )
        return Table(sorted_rows)

    def limit(self, n: int) -> Table:
        """Return at most the first ``n`` rows."""
        if n < 0:
            raise ValueError("limit must be non‑negative")
        return Table(self._rows[:n])

    # ------------------------------------------------------------------ #
    # Utility / introspection
    # ------------------------------------------------------------------ #
    def rows(self) -> List[Dict[str, Any]]:
        """Return a shallow copy of the internal row list."""
        return copy.deepcopy(self._rows)

    def __repr__(self) -> str:
        return f"Table({len(self._rows)} rows)"


# ---------------------------------------------------------------------- #
# Usage examples
# ---------------------------------------------------------------------- #
if __name__ == "__main__":
    # Example 1: simple filtering and projection
    employees = Table(
        [
            {"id": 1, "name": "Alice", "dept": "ENG", "salary": 70000},
            {"id": 2, "name": "Bob",   "dept": "HR",  "salary": 50000},
            {"id": 3, "name": "Cara",  "dept": "ENG", "salary": 80000},
            {"id": 4, "name": "Dan",   "dept": "MKT", "salary": 60000},
        ]
    )

    high_eng = (
        employees
        .where(lambda r: r["dept"] == "ENG" and r["salary"] > 65000)
        .select("id", "name", "salary")
    )
    print("High‑earning engineers:", high_eng.rows())

    # Example 2: join, group‑by and ordering
    departments = Table(
        [
            {"dept": "ENG", "location": "NY"},
            {"dept": "HR",  "location": "SF"},
            {"dept": "MKT", "location": "LA"},
        ]
    )

    # Join employees with departments, count employees per location,
    # then order by count descending.
    staff_by_location = (
        employees
        .join(departments, on=lambda l, r: l["dept"] == r["dept"])
        .group_by("location")
        .order_by("_count", descending=True)
    )
    print("Staff count per location:", staff_by_location.rows())

    # Example 3: chaining limit after ordering
    top_paid = (
        employees
        .select("name", "salary")
        .order_by("salary", descending=True)
        .limit(2)
    )
    print("Top 2 salaries:", top_paid.rows())

