T = TypeVar("T", bound="Query")

class Table:
    """In-memory table holding a list of dict rows."""
    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        self.rows = rows

    def query(self) -> Query:
        """Return a new Query object for fluent chaining."""
        return Query(self.rows)

class Query:
    """Fluent query builder for in-memory tables."""
    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        self._rows = rows
        self._select_cols: Optional[List[str]] = None
        self._where_pred: Optional[Callable[[Dict[str, Any]], bool]] = None
        self._join_table: Optional[Table] = None
        self._join_on: Optional[Callable[[Dict[str, Any], Dict[str, Any]], bool]] = None
        self._group_by_col: Optional[str] = None
        self._order_by_col: Optional[str] = None
        self._descending: bool = False
        self._limit: Optional[int] = None

    def select(self: T, *columns: str) -> T:
        """Filter to specific columns. If none provided, keep all."""
        self._select_cols = list(columns) if columns else None
        return self

    def where(self: T, predicate: Callable[[Dict[str, Any]], bool]) -> T:
        """Filter rows based on a predicate function."""
        self._where_pred = predicate
        return self

    def join(self: T, other: Table, on: Callable[[Dict[str, Any], Dict[str, Any]], bool]) -> T:
        """Inner join with another table using a predicate."""
        self._join_table = other
        self._join_on = on
        return self

    def group_by(self: T, column: str) -> T:
        """Group rows by a column value. Subsequent operations work on groups."""
        self._group_by_col = column
        return self

    def order_by(self: T, column: str, descending: bool = False) -> T:
        """Sort rows by a column."""
        self._order_by_col = column
        self._descending = descending
        return self

    def limit(self: T, n: int) -> T:
        """Limit the number of returned rows."""
        self._limit = n
        return self

    def execute(self) -> List[Dict[str, Any]]:
        """Apply transformations and return the result."""
        rows = deepcopy(self._rows)

        # 1. WHERE
        if self._where_pred:
            rows = [r for r in rows if self._where_pred(r)]

        # 2. JOIN
        if self._join_table and self._join_on:
            joined = []
            for l_row in rows:
                for r_row in self._join_table.rows:
                    if self._join_on(l_row, r_row):
                        merged = {**l_row}
                        for k, v in r_row.items():
                            if k in merged:
                                merged[f"r_{k}"] = v
                            else:
                                merged[k] = v
                        joined.append(merged)
            rows = joined

        # 3. GROUP BY
        if self._group_by_col:
            groups: Dict[Any, List[Dict[str, Any]]] = {}
            for r in rows:
                key = r.get(self._group_by_col)
                groups.setdefault(key, []).append(r)
            # Represent groups as dicts for consistent downstream handling
            rows = [{"__group_key__": k, "__group_rows__": v} for k, v in groups.items()]

        # 4. SELECT
        if self._select_cols:
            rows = [{k: r[k] for k in self._select_cols if k in r} for r in rows]

        # 5. ORDER BY
        if self._order_by_col:
            rows.sort(key=lambda r: r.get(self._order_by_col, None), reverse=self._descending)

        # 6. LIMIT
        if self._limit is not None:
            rows = rows[:self._limit]

        return rows

