                            if k in merged:
                                merged[f"r_{k}"] = v
                            else:
                                merged[k] = v
                        joined.append(merged)
            rows = joined

        # 3. GROUP BY
        if self._group_by_col:
            groups: Dict[Any, List[Dict[str, Any]]] = {}
            for r in rows:
                key = r.get(self._group_by_col)
                groups.setdefault(key, []).append(r)
            # Represent groups as dicts for consistent downstream handling
            rows = [{"__group_key__": k, "__group_rows__": v} for k, v in groups.items()]

        # 4. SELECT
        if self._select_cols:
            rows = [{k: r[k] for k in self._select_cols if k in r} for r in rows]

        # 5. ORDER BY
        if self._order_by_col:
            rows.sort(key=lambda r: r.get(self._order_by_col, None), reverse=self._descending)

        # 6. LIMIT
        if self._limit is not None:
            rows = rows[:self._limit]

        return rows

