from typing import Any, Callable, Dict, List


class Table:
    """A lightweight in‑memory relational table.

    Each row is a ``dict`` mapping column names to values.
    All query methods return a new ``Table`` instance, enabling a fluent,
    composable API.
    """

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        """Create a table from an iterable of row dictionaries."""
        self._rows: List[Dict[str, Any]] = list(rows)

    # -----------------------------------------------------------------
    # Read‑only access
    # -----------------------------------------------------------------
    @property
    def rows(self) -> List[Dict[str, Any]]:
        """Return the current rows (caller should treat as read‑only)."""
        return self._rows

    # -----------------------------------------------------------------
    # Query building blocks
    # -----------------------------------------------------------------
    def select(self, *columns: str) -> Table:
        """Project only the given columns.
        If no columns are supplied, all columns are retained.
        """
        if not columns:
            return Table(self._rows.copy())

        projected: List[Dict[str, Any]] = []
        for row in self._rows:
            # Keep only requested columns that actually exist in the row
            projected.append({col: row[col] for col in columns if col in row})
        return Table(projected)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        """Filter rows by a predicate function."""
        filtered = [row for row in self._rows if predicate(row)]
        return Table(filtered)

    def join(
        self,
        other: Table,
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool],
    ) -> Table:
        """Inner join with another table using the supplied ``on`` predicate."""
        joined: List[Dict[str, Any]] = []
        for left in self._rows:
            for right in other._rows:
                if on(left, right):
                    # Right‑hand values overwrite left‑hand values on key clash
                    joined.append({**left, **right})
        return Table(joined)

    def group_by(self, column: str) -> Table:
        """Group rows by the value of ``column``.
        Each resulting row contains the group key under ``column`` and a list
        of the original rows under the special key ``_rows``.
        """
        groups: Dict[Any, List[Dict[str, Any]]] = {}
        for row in self._rows:
            key = row.get(column)
            groups.setdefault(key, []).append(row)

        grouped: List[Dict[str, Any]] = [
            {column: key, "_rows": group_rows} for key, group_rows in groups.items()
        ]
        return Table(grouped)

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Sort rows by ``column`` (missing values are treated as ``None``)."""
        sorted_rows = sorted(
            self._rows, key=lambda r: r.get(column), reverse=descending
        )
        return Table(sorted_rows)

    def limit(self, n: int) -> Table:
        """Return at most the first ``n`` rows."""
        if n < 0:
            raise ValueError("limit must be non‑negative")
        return Table(self._rows[:n])

    # -----------------------------------------------------------------
    # Debugging / representation
    # -----------------------------------------------------------------
    def __repr__(self) -> str:
        return f"Table({self._rows!r})"


# -----------------------------------------------------------------
# Usage examples
# -----------------------------------------------------------------
if __name__ == "__main__":
    # Example 1: simple filtering and projection
    employees = Table(
        [
            {"id": 1, "name": "Alice", "dept": "ENG", "salary": 70000},
            {"id": 2, "name": "Bob",   "dept": "HR",  "salary": 50000},
            {"id": 3, "name": "Cara",  "dept": "ENG", "salary": 80000},
            {"id": 4, "name": "Dan",   "dept": "SALES","salary": 60000},
        ]
    )

    high_eng = (
        employees
        .where(lambda r: r["dept"] == "ENG" and r["salary"] > 65000)
        .select("id", "name", "salary")
    )
    print("High‑earning engineers:", high_eng.rows)

    # Example 2: inner join
    departments = Table(
        [
            {"dept": "ENG", "location": "Building A"},
            {"dept": "HR",  "location": "Building B"},
            {"dept": "SALES","location": "Building C"},
        ]
    )

    emp_with_loc = employees.join(
        departments,
        on=lambda l, r: l["dept"] == r["dept"]
    ).select("id", "name", "dept", "location")
    print("Employees with location:", emp_with_loc.rows)

    # Example 3: grouping, ordering and limiting
    # Count employees per department, order by count descending, take top 2
    dept_counts = (
        employees
        .group_by("dept")
        .select("dept", "_rows")               # keep group key and rows
        .order_by("_rows", descending=True)    # sort by size of _rows list
        .limit(2)
        .select("dept")                        # final projection
    )
    print("Top 2 departments by headcount:", dept_counts.rows)

from __future__ import annotations

import threading
from abc import ABC, abstractmethod
from typing import Any, Dict, List, Optional, Set, Tuple


# ---------------------------------------------------------------------------
# Strategy interfaces and default implementations
# ---------------------------------------------------------------------------

class ValidationPolicy(ABC):
    """Encapsulates validation logic and error handling for invalid items."""

    @abstractmethod
    def is_valid(self, item: Any) -> bool:
        """Return True if *item* is valid, False otherwise."""
        ...

    @abstractmethod
    def on_invalid(self, item: Any) -> None:
        """Called when *item* is invalid. May raise or log."""
        ...


class NoValidation(ValidationPolicy):
    """Accepts all items without validation."""

    def is_valid(self, item: Any) -> bool:
        return True

    def on_invalid(self, item: Any) -> None:
        pass  # never called because is_valid always returns True


class StrictValidation(ValidationPolicy):
    """Raises ValueError on invalid items."""

    def is_valid(self, item: Any) -> bool:
        return isinstance(item, dict)

    def on_invalid(self, item: Any) -> None:
        raise ValueError(f"Expected dict, got {type(item)}")


class VerboseValidation(ValidationPolicy):
    """Prints a warning and skips invalid items."""

    def is_valid(self, item: Any) -> bool:
        return isinstance(item, dict)

    def on_invalid(self, item: Any) -> None:
        print(f"Skipping invalid item: {item}")


class SilentValidation(ValidationPolicy):
    """Silently skips invalid items."""

    def is_valid(self, item: Any) -> bool:
        return isinstance(item, dict)

    def on_invalid(self, item: Any) -> None:
        pass


class NormalizationStrategy(ABC):
    """Transforms individual items (e.g., string stripping/lowering)."""

    @abstractmethod
    def normalize(self, item: Any) -> Any:
        ...


class NoNormalization(NormalizationStrategy):
    def normalize(self, item: Any) -> Any:
        return item


class StandardNormalization(NormalizationStrategy):
    """For dict items, strip and lower all string values."""

    def normalize(self, item: Any) -> Any:
        if isinstance(item, dict):
            return {
                k: (v.strip().lower() if isinstance(v, str) else v)
                for k, v in item.items()
            }
        return item


class DeduplicationStrategy(ABC):
    """Tracks seen items and filters duplicates."""

    @abstractmethod
    def is_duplicate(self, item: Any) -> bool:
        ...

    @abstractmethod
    def add(self, item: Any) -> None:
        ...


class NoDeduplication(DeduplicationStrategy):
    def is_duplicate(self, item: Any) -> bool:
        return False

    def add(self, item: Any) -> None:
        pass


class KeyBasedDeduplication(DeduplicationStrategy):
    """Deduplicates by a string key derived from sorted dict items."""

    def __init__(self) -> None:
        self._seen: Set[str] = set()

    def is_duplicate(self, item: Any) -> bool:
        key = self._make_key(item)
        return key in self._seen

    def add(self, item: Any) -> None:
        key = self._make_key(item)
        self._seen.add(key)

    @staticmethod
    def _make_key(item: Any) -> str:
        if isinstance(item, dict):
            return str(sorted(item.items()))
        return str(item)


class CacheStrategy(ABC):
    """Caches processed results keyed by input object identity."""

    @abstractmethod
    def get(self, key: int) -> Optional[List[Any]]:
        ...

    @abstractmethod
    def set(self, key: int, value: List[Any]) -> None:
        ...

    @abstractmethod
    def clear(self) -> None:
        ...


class NoCache(CacheStrategy):
    def get(self, key: int) -> Optional[List[Any]]:
        return None

    def set(self, key: int, value: List[Any]) -> None:
        pass

    def clear(self) -> None:
        pass


class InMemoryCache(CacheStrategy):
    def __init__(self) -> None:
        self._cache: Dict[int, List[Any]] = {}

    def get(self, key: int) -> Optional[List[Any]]:
        return self._cache.get(key)

    def set(self, key: int, value: List[Any]) -> None:
        self._cache[key] = value

    def clear(self) -> None:
        self._cache.clear()


class Statistics:
    """Thread-safe collector for hits, misses, and errors."""

    def __init__(self) -> None:
        self._hits = 0
        self._misses = 0
        self._errors = 0
        self._lock = threading.Lock()

    def hit(self) -> None:
        with self._lock:
            self._hits += 1

    def miss(self) -> None:
        with self._lock:
            self._misses += 1

    def error(self) -> None:
        with self._lock:
            self._errors += 1

    def snapshot(self) -> Dict[str, int]:
        with self._lock:
            return {
                "hits": self._hits,
                "misses": self._misses,
                "errors": self._errors,
            }

    def reset(self) -> None:
        with self._lock:
            self._hits = 0
            self._misses = 0
            self._errors = 0


# ---------------------------------------------------------------------------
# Refactored DataProcessor
# ---------------------------------------------------------------------------

class DataProcessor:
    """
    Processes a list of items with configurable validation, normalization,
    deduplication, and caching.

    All mutable state (cache, statistics, deduplication sets) is instance-local
    and protected by a lock, making this class safe for concurrent use across
    multiple instances.

    Parameters
    ----------
    validation : ValidationPolicy, optional
        Policy for validating items. Defaults to NoValidation.
    normalization : NormalizationStrategy, optional
        Strategy for normalizing items. Defaults to NoNormalization.
    deduplication : DeduplicationStrategy, optional
        Strategy for deduplicating items. Defaults to NoDeduplication.
    cache : CacheStrategy, optional
        Strategy for caching results. Defaults to NoCache.
    """

    def __init__(
        self,
        validation: Optional[ValidationPolicy] = None,
        normalization: Optional[NormalizationStrategy] = None,
        deduplication: Optional[DeduplicationStrategy] = None,
        cache: Optional[CacheStrategy] = None,
    ) -> None:
        self._validation = validation or NoValidation()
        self._normalization = normalization or NoNormalization()
        self._deduplication = deduplication or NoDeduplication()
        self._cache = cache or NoCache()
        self._stats = Statistics()
        self._lock = threading.Lock()

    def process(self, data: List[Any]) -> List[Any]:
        """
        Process *data* according to the configured strategies.

        Returns a new list of processed items. The original *data* is not
        modified.
        """
        with self._lock:
            # Check cache
            cache_key = id(data)
            cached = self._cache.get(cache_key)
            if cached is not None:
                self._stats.hit()
                return cached

            self._stats.miss()

            result: List[Any] = []
            for item in data:
                # Validation
                if not self._validation.is_valid(item):
                    self._stats.error()
                    self._validation.on_invalid(item)
                    continue

                # Deduplication
                if self._deduplication.is_duplicate(item):
                    continue
                self._deduplication.add(item)

                # Normalization
                item = self._normalization.normalize(item)

                result.append(item)

            # Cache the result
            self._cache.set(cache_key, result)
            return result

    def get_stats(self) -> Dict[str, int]:
        """Return a snapshot of the current statistics."""
        return self._stats.snapshot()

    def reset(self) -> None:
        """Clear all cached results and reset statistics."""
        with self._lock:
            self._cache.clear()
            self._stats.reset()

from __future__ import annotations

from typing import Any, Callable, Dict, List, Optional


class Table:
    """An in-memory table backed by a list of dict rows.

    Supports a fluent, composable API for common SQL-like operations:
    select, where, join, group_by, order_by, and limit.
    """

    def __init__(self, rows: List[Dict[str, Any]]) -> None:
        self._rows = rows

    # ------------------------------------------------------------------
    # Public API – each method returns a new Table (immutable style)
    # ------------------------------------------------------------------

    def select(self, *columns: str) -> Table:
        """Return a new table containing only the specified columns.

        If no columns are given, all columns are kept (like SELECT *).
        """
        if not columns:
            return Table(list(self._rows))

        new_rows: List[Dict[str, Any]] = []
        for row in self._rows:
            new_row = {col: row[col] for col in columns if col in row}
            new_rows.append(new_row)
        return Table(new_rows)

    def where(self, predicate: Callable[[Dict[str, Any]], bool]) -> Table:
        """Return a new table with rows that satisfy *predicate*."""
        return Table([row for row in self._rows if predicate(row)])

    def join(
        self,
        other: Table,
        on: Callable[[Dict[str, Any], Dict[str, Any]], bool],
    ) -> Table:
        """Inner join with *other* table.

        *on* is a callable ``(left_row, right_row) -> bool``.
        Result rows are merged dicts (right overwrites left on key conflict).
        """
        new_rows: List[Dict[str, Any]] = []
        for left in self._rows:
            for right in other._rows:
                if on(left, right):
                    merged = {**left, **right}
                    new_rows.append(merged)
        return Table(new_rows)

    def group_by(self, column: str) -> Table:
        """Group rows by *column* and return a table with one row per group.

        Each result row contains:
            - the group key (the value of *column*)
            - a ``count`` column with the number of rows in that group.
        """
        groups: Dict[Any, int] = {}
        for row in self._rows:
            key = row[column]
            groups[key] = groups.get(key, 0) + 1

        new_rows = [{column: key, "count": cnt} for key, cnt in groups.items()]
        return Table(new_rows)

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Return a new table sorted by *column*.

        If *descending* is True, sort in descending order.
        """
        sorted_rows = sorted(
            self._rows,
            key=lambda row: row.get(column),
            reverse=descending,
        )
        return Table(sorted_rows)

    def limit(self, n: int) -> Table:
        """Return a new table with at most the first *n* rows."""
        return Table(self._rows[:n])

    # ------------------------------------------------------------------
    # Display helpers
    # ------------------------------------------------------------------

    def __repr__(self) -> str:
        if not self._rows:
            return "Table(empty)"
        # Show first few rows as a simple table
        cols = list(self._rows[0].keys())
        header = " | ".join(cols)
        lines = [header, "-" * len(header)]
        for row in self._rows[:5]:
            lines.append(" | ".join(str(row.get(c, "")) for c in cols))
        if len(self._rows) > 5:
            lines.append(f"... ({len(self._rows)} rows total)")
        return "\n".join(lines)

    def __len__(self) -> int:
        return len(self._rows)

    def to_list(self) -> List[Dict[str, Any]]:
        """Return the underlying list of rows (a copy)."""
        return list(self._rows)


