if __name__ == "__main__":
    # Example 1: basic filtering, sorting, limiting
    employees = Table([
        {"name": "Alice", "dept": "Engineering", "salary": 120_000},
        {"name": "Bob", "dept": "Sales", "salary": 90_000},
        {"name": "Charlie", "dept": "Engineering", "salary": 110_000},
