from __future__ import annotations
from dataclasses import dataclass
from typing import (
    Any, 
    Callable, 
    Iterable, 
    List, 
    Dict, 
    Optional, 
    TypeVar, 
    Generic, 
    Sequence
)
from operator import itemgetter

T = TypeVar("T")

class QueryEngineError(Exception):
    """Base exception for query engine errors."""
    pass

@dataclass(frozen=True)
class Row:
    """
    A read-only representation of a table row.
    Wraps a dictionary to provide a consistent interface.
    """
    data: Dict[str, Any]

    def __getitem__(self, key: str) -> Any:
        return self.data[key]

    def __repr__(self) -> str:
        return f"Row({self.data})"

class Table:
    """
    An in-memory SQL-like query engine.
    Supports a fluent API for composing data transformations.
    """

    def __init__(self, name: str, rows: Iterable[Dict[str, Any]]):
        self.name = name
        # Store as a list of Rows for consistency and immutability of individual records
        self._rows: List[Row] = [Row(row) for row in rows]

    def __iter__(self):
        return iter(self._rows)

    def __len__(self):
        return len(self._rows)

    def select(self, *columns: str) -> Table:
        """Project only the specified columns."""
        if not columns:
            return self

        new_rows = []
        for row in self._rows:
            # Create a new dict containing only the requested keys
            projected = {col: row[col] for col in columns if col in row.data}
            new_rows.append(projected)

        return Table(self.name, new_rows)

    def where(self, predicate: Callable[[Row], bool]) -> Table:
        """Filter rows based on a predicate function."""
        filtered = [row.data for row in self._rows if predicate(row)]
        return Table(self.name, filtered)

    def join(self, other: Table, on: Callable[[Row, Row], bool]) -> Table:
        """
        Perform an inner join with another table based on a predicate.
        The resulting rows contain the merged data of both tables.
        """
        joined_rows = []
        for left_row in self._rows:
            for right_row in other._rows:
                if on(left_row, right_row):
                    # Merge dictionaries. Right table overrides left on key collision.
                    merged = {**left_row.data, **right_row.data}
                    joined_rows.append(merged)

        return Table(f"{self.name}_joined_{other.name}", joined_rows)

    def order_by(self, column: str, descending: bool = False) -> Table:
        """Sort the rows by a specific column."""
        try:
            # Use itemgetter for performance on the underlying dicts
            sorted_data = sorted(
                [row.data for row in self._rows], 
                key=itemgetter(column), 
                reverse=descending
            )
        except KeyError:
            raise QueryEngineError(f"Column '{column}' not found for sorting.")

        return Table(self.name, sorted_data)

    def limit(self, n: int) -> Table:
        """Restrict the result set to n rows."""
        return Table(self.name, self._rows[:n])

    def group_by(self, column: str) -> Dict[Any, List[Row]]:
        """
        Group rows by a column. 
        Note: This is a terminal operation returning a Dict rather than a Table,
        as grouped data changes the dimensionality of the result.
        """
        groups: Dict[Any, List[Row]] = {}
        for row in self._rows:
            val = row[column]
            groups.setdefault(val, []).append(row)
        return groups

    def collect(self) -> List[Dict[str, Any]]:
        """Return the final result set as a list of dictionaries."""
        return [row.data for row in self._rows]


