import time
import collections
from abc import ABC, abstractmethod
from typing import Dict, List, Deque

class RateLimiter(ABC):
    @abstractmethod
    def allow(self, client_id: str) -> bool:
        """Returns True if the request is allowed, False otherwise."""
        pass

class TokenBucket(RateLimiter):
    def __init__(self, capacity: float, refill_rate: float):
        self.capacity = capacity
        self.refill_rate = refill_rate
        self.buckets: Dict[str, float] = {}
        self.last_refill: Dict[str, float] = {}

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        tokens = self.buckets.get(client_id, self.capacity)
        last = self.last_refill.get(client_id, now)

        # Refill tokens based on elapsed time
        tokens = min(self.capacity, tokens + (now - last) * self.refill_rate)

        if tokens >= 1:
            self.buckets[client_id] = tokens - 1
            self.last_refill[client_id] = now
            return True

        self.buckets[client_id] = tokens
        self.last_refill[client_id] = now
        return False

class LeakyBucket(RateLimiter):
    def __init__(self, capacity: int, leak_rate: float):
        self.capacity = capacity
        self.leak_rate = leak_rate  # seconds per request
        self.next_allowed_time: Dict[str, float] = {}

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        last_allowed = self.next_allowed_time.get(client_id, now)

        # The bucket "leaks" at a constant rate
        start_time = max(now, last_allowed)
        if start_time - now < self.capacity * self.leak_rate:
            self.next_allowed_time[client_id] = start_time + self.leak_rate
            return True
        return False

class SlidingWindowLog(RateLimiter):
    def __init__(self, limit: int, window_seconds: int):
        self.limit = limit
        self.window = window_seconds
        self.logs: Dict[str, Deque[float]] = collections.defaultdict(collections.deque)

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        log = self.logs[client_id]

        # Remove expired timestamps
        while log and log[0] <= now - self.window:
            log.popleft()

        if len(log) < self.limit:
            log.append(now)
            return True
        return False

class SlidingWindowCounter(RateLimiter):
    def __init__(self, limit: int, window_seconds: int):
        self.limit = limit
        self.window = window_seconds
        self.curr_window: Dict[str, Dict[int, int]] = collections.defaultdict(dict)

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        win_start = int(now // self.window)
        prev_win_start = win_start - 1

        # Clean up old data
        self.curr_window[client_id] = {k: v for k, v in self.curr_window[client_id].items() 
                                       if k >= prev_win_start}

        prev_count = self.curr_window[client_id].get(prev_win_start, 0)
        curr_count = self.curr_window[client_id].get(win_start, 0)

        # Weighted average of previous and current window
        weight = (now % self.window) / self.window
        if (prev_count * (1 - weight) + curr_count) < self.limit:
            self.curr_window[client_id][win_start] = curr_count + 1
            return True
        return False

