from typing import Dict, Deque, Protocol

# Define a protocol for our rate limiters
class RateLimiter(Protocol):
    def allow(self, client_id: str) -> bool:
        ...

# Token Bucket Rate Limiter
class TokenBucket:
    def __init__(self, capacity: int, fill_rate: float):
        self.capacity = capacity  # Max tokens
        self.fill_rate = fill_rate  # Tokens per second
        self.buckets: Dict[str, Dict[str, float]] = {} # client_id -> {'tokens': float, 'last_fill_time': float}

    def allow(self, client_id: str) -> bool:
        if client_id not in self.buckets:
            self.buckets[client_id] = {'tokens': float(self.capacity), 'last_fill_time': time.time()}

        bucket = self.buckets[client_id]
        now = time.time()

        # Calculate how many tokens to add since last check
        time_passed = now - bucket['last_fill_time']
        tokens_to_add = time_passed * self.fill_rate

        # Add tokens, but don't exceed capacity
        bucket['tokens'] = min(bucket['tokens'] + tokens_to_add, float(self.capacity))
        bucket['last_fill_time'] = now

        if bucket['tokens'] >= 1.0: # We need at least 1 token to allow
            bucket['tokens'] -= 1.0
            return True
        else:
            return False

# Leaky Bucket Rate Limiter
class LeakyBucket:
    def __init__(self, capacity: int, leak_rate: float):
        self.capacity = capacity # Max requests in the bucket
        self.leak_rate = leak_rate # Requests per second that leak out
        self.buckets: Dict[str, Deque[float]] = {} # client_id -> deque of request timestamps

    def allow(self, client_id: str) -> bool:
        if client_id not in self.buckets:
            self.buckets[client_id] = deque()

        bucket = self.buckets[client_id]
        now = time.time()

        # Remove requests that have "leaked" out
        while bucket and (now - bucket[0]) > (1.0 / self.leak_rate):
            bucket.popleft()

        if len(bucket) < self.capacity:
            bucket.append(now)
            return True
        else:
            return False

# Sliding Window Log Rate Limiter
class SlidingWindowLog:
    def __init__(self, window_size_seconds: int, max_requests: int):
        self.window_size_seconds = window_size_seconds
        self.max_requests = max_requests
        self.request_logs: Dict[str, Deque[float]] = {} # client_id -> deque of request timestamps

    def allow(self, client_id: str) -> bool:
        if client_id not in self.request_logs:
            self.request_logs[client_id] = deque()

        logs = self.request_logs[client_id]
        now = time.time()

        # Remove old requests outside the window
        while logs and logs[0] <= now - self.window_size_seconds:
            logs.popleft()

        if len(logs) < self.max_requests:
            logs.append(now)
            return True
        else:
            return False

# Sliding Window Counter Rate Limiter
class SlidingWindowCounter:
    def __init__(self, window_size_seconds: int, max_requests: int):
        self.window_size_seconds = window_size_seconds
        self.max_requests = max_requests
        # client_id -> {'current_window_start': float, 'current_window_count': int, 'previous_window_count': int}
        self.windows: Dict[str, Dict[str, float | int]] = {}

    def allow(self, client_id: str) -> bool:
        if client_id not in self.windows:
            self.windows[client_id] = {
                'current_window_start': time.time(),
                'current_window_count': 0,
                'previous_window_count': 0
            }

        window = self.windows[client_id]
        now = time.time()

        # Check if we've moved to a new window
        if now >= window['current_window_start'] + self.window_size_seconds:
            # Shift the current window to become the previous window
            window['previous_window_count'] = window['current_window_count']
            window['current_window_count'] = 0
            window['current_window_start'] = now

        # Calculate the overlap percentage
        elapsed_in_current_window = now - window['current_window_start']
        overlap_percentage = max(0.0, 1.0 - (elapsed_in_current_window / self.window_size_seconds))

        # Estimate requests in the current effective window
        estimated_requests = (window['previous_window_count'] * overlap_percentage) + window['current_window_count']

        if estimated_requests < self.max_requests:
            window['current_window_count'] += 1
            return True
        else:
            return False


