import time
from abc import ABC, abstractmethod
from typing import Dict, List

# Base interface for all rate limiters
class RateLimiter(ABC):
    @abstractmethod
    def allow(self, client_id: str) -> bool:
        """Check if a request from client_id should be allowed."""
        pass


class TokenBucketLimiter(RateLimiter):
    """
    Tokens are added at a fixed rate. Each request consumes 1 token.
    If bucket is empty, request is denied.
    """
    def __init__(self, capacity: int, refill_rate: float):
        self.capacity = capacity
        self.refill_rate = refill_rate  # tokens per second
        self.buckets: Dict[str, dict] = {}

    def allow(self, client_id: str) -> bool:
        now = time.time()
        if client_id not in self.buckets:
            self.buckets[client_id] = {"tokens": self.capacity, "last_refill": now}

        bucket = self.buckets[client_id]
        # Add tokens based on elapsed time
        elapsed = now - bucket["last_refill"]
        bucket["tokens"] = min(self.capacity, bucket["tokens"] + elapsed * self.refill_rate)
        bucket["last_refill"] = now

        if bucket["tokens"] >= 1:
            bucket["tokens"] -= 1
            return True
        return False


class LeakyBucketLimiter(RateLimiter):
    """
    Requests fill a bucket that leaks at a constant rate.
    If bucket is full, new requests are rejected.
    """
    def __init__(self, capacity: int, leak_rate: float):
        self.capacity = capacity
        self.leak_rate = leak_rate  # requests per second that leak out
        self.buckets: Dict[str, dict] = {}

    def allow(self, client_id: str) -> bool:
        now = time.time()
        if client_id not in self.buckets:
            self.buckets[client_id] = {"volume": 0, "last_leak": now}

        bucket = self.buckets[client_id]
        # Leak out some volume
        elapsed = now - bucket["last_leak"]
        bucket["volume"] = max(0, bucket["volume"] - elapsed * self.leak_rate)
        bucket["last_leak"] = now

        if bucket["volume"] < self.capacity:
            bucket["volume"] += 1
            return True
        return False


class SlidingWindowLogLimiter(RateLimiter):
    """
    Keeps a list of timestamps for each client.
    Removes timestamps older than the window size.
    """
    def __init__(self, max_requests: int, window_size: float):
        self.max_requests = max_requests
        self.window_size = window_size  # seconds
        self.logs: Dict[str, List[float]] = {}

    def allow(self, client_id: str) -> bool:
        now = time.time()
        if client_id not in self.logs:
            self.logs[client_id] = []

        # Remove expired timestamps
        cutoff = now - self.window_size
        self.logs[client_id] = [t for t in self.logs[client_id] if t > cutoff]

        if len(self.logs[client_id]) < self.max_requests:
            self.logs[client_id].append(now)
            return True
        return False


class SlidingWindowCounterLimiter(RateLimiter):
    """
    More memory efficient than the log version.
    Uses two counters and weights the previous window's count based on overlap.
    """
    def __init__(self, max_requests: int, window_size: float):
        self.max_requests = max_requests
        self.window_size = window_size
        self.counters: Dict[str, dict] = {}

    def allow(self, client_id: str) -> bool:
        now = time.time()
        if client_id not in self.counters:
            self.counters[client_id] = {
                "current_count": 0,
                "previous_count": 0,
                "window_start": now
            }

        counter = self.counters[client_id]

        # Move to next window if enough time has passed
        if now - counter["window_start"] >= self.window_size:
            counter["previous_count"] = counter["current_count"]
            counter["current_count"] = 0
            counter["window_start"] = now

        # Calculate weighted count from previous window
        elapsed = now - counter["window_start"]
        weight = 1.0 - (elapsed / self.window_size)
        effective_count = counter["previous_count"] * weight + counter["current_count"]

        if effective_count < self.max_requests:
            counter["current_count"] += 1
            return True
        return False


