    print("--- Token Bucket (cap=5, refill=1/sec) ---")
    tb = TokenBucketLimiter(capacity=5, refill_rate=1.0)
    for i in range(7):
        print(f"Request {i+1}: {tb.allow('user_1')}")

    print("\n--- Leaky Bucket (cap=3, leak=1/sec) ---")
    lb = LeakyBucketLimiter(capacity=3, leak_rate=1.0)
    for i in range(5):
        print(f"Request {i+1}: {lb.allow('user_2')}")

    print("\n--- Sliding Window Log (max=3, window=2s) ---")
    swl = SlidingWindowLogLimiter(max_requests=3, window_size=2.0)
    for i in range(5):
        print(f"Request {i+1}: {swl.allow('user_3')}")

    print("\n--- Sliding Window Counter (max=3, window=2s) ---")
    swc = SlidingWindowCounterLimiter(max_requests=3, window_size=2.0)
    for i in range(5):
        print(f"Request {i+1}: {swc.allow('user_4')}")

