import time
import collections
from typing import Protocol


class RateLimiter(Protocol):
    """Interface for rate limiting algorithms."""
    def allow(self, client_id: str) -> bool: ...


class TokenBucket(RateLimiter):
    """Allows bursts up to capacity, then enforces a steady refill rate."""
    def __init__(self, rate: float, capacity: int) -> None:
        if rate <= 0 or capacity <= 0:
            raise ValueError("rate and capacity must be positive")
        self.rate = rate
        self.capacity = capacity
        self._state: dict[str, dict[str, float]] = {}

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        if client_id not in self._state:
            self._state[client_id] = {"tokens": float(self.capacity), "last_time": now}

        state = self._state[client_id]
        elapsed = now - state["last_time"]
        # Refill tokens proportionally to elapsed time, capped at capacity
        state["tokens"] = min(self.capacity, state["tokens"] + elapsed * self.rate)
        state["last_time"] = now

        if state["tokens"] >= 1.0:
            state["tokens"] -= 1.0
            return True
        return False


class LeakyBucket(RateLimiter):
    """Smooths request bursts by enforcing a constant drain rate."""
    def __init__(self, rate: float, capacity: int) -> None:
        if rate <= 0 or capacity <= 0:
            raise ValueError("rate and capacity must be positive")
        self.rate = rate
        self.capacity = capacity
        self._state: dict[str, dict[str, float]] = {}

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        if client_id not in self._state:
            self._state[client_id] = {"queue": 0.0, "last_time": now}

        state = self._state[client_id]
        elapsed = now - state["last_time"]
        # Drain the bucket at a constant rate
        state["queue"] = max(0.0, state["queue"] - elapsed * self.rate)
        state["last_time"] = now

        if state["queue"] < self.capacity:
            state["queue"] += 1.0
            return True
        return False


class SlidingWindowLog(RateLimiter):
    """Tracks exact request timestamps for precise window enforcement."""
    def __init__(self, max_requests: int, window_seconds: float) -> None:
        if max_requests <= 0 or window_seconds <= 0:
            raise ValueError("max_requests and window_seconds must be positive")
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self._state: dict[str, collections.deque[float]] = {}

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        if client_id not in self._state:
            self._state[client_id] = collections.deque()

        window = self._state[client_id]
        cutoff = now - self.window_seconds
        # Remove timestamps that have fallen outside the current window
        while window and window[0] <= cutoff:
            window.popleft()

        if len(window) < self.max_requests:
            window.append(now)
            return True
        return False


class SlidingWindowCounter(RateLimiter):
    """Efficient approximation of a sliding window using two counters."""
    def __init__(self, max_requests: int, window_seconds: float) -> None:
        if max_requests <= 0 or window_seconds <= 0:
            raise ValueError("max_requests and window_seconds must be positive")
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self._state: dict[str, dict[str, float | int]] = {}

    def allow(self, client_id: str) -> bool:
        now = time.monotonic()
        if client_id not in self._state:
            self._state[client_id] = {"prev_count": 0, "curr_start": now, "curr_count": 0}

        state = self._state[client_id]
        # Slide windows when the current window expires
        if now >= state["curr_start"] + self.window_seconds:
            state["prev_count"] = state["curr_count"]
            state["curr_start"] = now
            state["curr_count"] = 0

        elapsed = now - state["curr_start"]
        weight = elapsed / self.window_seconds
        # Interpolate between previous and current window counts to avoid boundary spikes
        weighted_count = state["prev_count"] * (1.0 - weight) + state["curr_count"]

        if weighted_count < self.max_requests:
            state["curr_count"] += 1
            return True
        return False


