from __future__ import annotations
import operator
import itertools
from typing import Any, Callable, Iterable, List, Tuple, Dict, Optional

# ----------------------------------------------------------------------
# 1. Expression helpers (tiny DSL for predicates & projections)
# ----------------------------------------------------------------------
class Expr:
    """Wrap a lambda so we can store it in the AST and later call it."""
    def __init__(self, fn: Callable[[Any], Any]):
        self.fn = fn

    def __call__(self, row: Any) -> Any:
        return self.fn(row)

    # overload &, | for convenience
    def __and__(self, other: Expr) -> Expr:
        return Expr(lambda r: self.fn(r) and other.fn(r))

    def __or__(self, other: Expr) -> Expr:
        return Expr(lambda r: self.fn(r) or other.fn(r))

    def __invert__(self) -> Expr:
        return Expr(lambda r: not self.fn(r))

# factories for common comparisons
def eq(field: str, value: Any) -> Expr:
    return Expr(lambda r: r.get(field) == value)

def ne(field: str, value: Any) -> Expr:
    return Expr(lambda r: r.get(field) != value)

def gt(field: str, value: Any) -> Expr:
    return Expr(lambda r: r.get(field) > value)

def ge(field: str, value: Any) -> Expr:
    return Expr(lambda r: r.get(field) >= value)

def lt(field: str, value: Any) -> Expr:
    return Expr(lambda r: r.get(field) < value)

def le(field: str, value: Any) -> Expr:
    return Expr(lambda r: r.get(field) <= value)

def like(field: str, pattern: str) -> Expr:
    import re
    regex = re.compile(pattern.replace("%", ".*").replace("_", "."))
    return Expr(lambda r: bool(regex.match(str(r.get(field, "")))))

# ----------------------------------------------------------------------
# 2. AST node definitions
# ----------------------------------------------------------------------
class Scan:
    def __init__(self, name: str):
        self.name: str = name

class Filter:
    def __init__(self, pred: Expr, child):
        self.pred: Expr = pred
        self.child = child

class Project:
    def __init__(self, exprs: List[Tuple[Expr, Optional[str]]], child):
        self.exprs: List[Tuple[Expr, Optional[str]]] = exprs
        self.child = child

class Sort:
    def __init__(self, keys: List[Tuple[Expr, bool]], child):
        # keys: (expr, asc_bool)
        self.keys: List[Tuple[Expr, bool]] = keys
        self.child = child

class Limit:
    def __init__(self, n: int, child):
        self.n: int = n
        self.child = child

class Offset:
    def __init__(self, n: int, child):
        self.n: int = n
        self.child = child

class Join:
    def __init__(self, left, right, left_key: str, right_key: str):
        self.left = left
        self.right = right
        self.left_key = left_key
        self.right_key = right_key

