                return iter(tables[node.name])
            if isinstance(node, Filter):
                src = eval_node(node.child)
                return (row for row in src if node.pred(row))
            if isinstance(node, Project):
                src = eval_node(node.child)
                for row in src:
                    projected = {}
                    for expr, alias in node.exprs:
                        val = expr(row)
                        key = alias if alias is not None else expr.fn.__name__
                        projected[key] = val
                    yield projected
            if isinstance(node, Sort):
                src = list(eval_node(node.child))
                src.sort(key=lambda r: tuple(k(r) for k, _ in node.keys),
                         reverse=[not asc for _, asc in node.keys])
                return iter(src)
            if isinstance(node, Limit):
                src = eval_node(node.child)
                return itertools.islice(src, node.n)
            if isinstance(node, Offset):
                src = eval_node(node.child)
                return itertools.islice(src, node.n, None)
            raise TypeError(f"Unsupported AST node: {type(node)}")

        result_iter = eval_node(self._root)
        # Materialize to list so the caller gets a concrete collection
        return list(result_iter)

