class FixedWindow(RateLimiter):
    def __init__(self, window_size: float, max_requests: int):
        self.window_size = window_size
        self.max_requests = max_requests
        self.windows: dict[str, dict] = {}

    def allow_request(self, key: str, tokens: int = 1) -> bool:
        now = time.monotonic()
        if key not in self.windows:
            self.windows[key] = {"count": 0, "window_start": now}

        window = self.windows[key]
        # Reset if a new window has begun
        if now - window["window_start"] >= self.window_size:
            window["count"] = 0
            window["window_start"] = now

        if window["count"] + tokens <= self.max_requests:
            window["count"] += tokens
            return True
        return False

    def reset(self, key: str):
        self.windows.pop(key, None)

