class TokenBucket(RateLimiter):
    def __init__(self, capacity: int, refill_rate: float, refill_interval: float = 1.0):
        self.capacity = capacity
        self.refill_rate = refill_rate          # tokens per refill_interval
        self.refill_interval = refill_interval
        self.buckets: dict[str, float] = {}     # key -> current tokens
        self.last_refill: dict[str, float] = {} # key -> last update timestamp

    def _refill(self, key: str, now: float):
        elapsed = now - self.last_refill.get(key, now)
        tokens_to_add = (elapsed / self.refill_interval) * self.refill_rate
        self.buckets[key] = min(self.capacity,
                                self.buckets.get(key, self.capacity) + tokens_to_add)
        self.last_refill[key] = now

    def allow_request(self, key: str, cost: int = 1) -> bool:
        now = time.time()
        self._refill(key, now)
        if self.buckets.get(key, self.capacity) >= cost:
            self.buckets[key] -= cost
            return True
        return False

    def get_remaining(self, key: str) -> int:
        now = time.time()
        self._refill(key, now)
        return int(self.buckets.get(key, self.capacity))

    def reset_time(self, key: str) -> float:
        return self.last_refill.get(key, time.time()) + self.refill_interval

