class LeakyBucket(RateLimiter):
    def __init__(self, capacity: int, drain_rate: float, drain_interval: float = 1.0):
        self.capacity = capacity
        self.drain_rate = drain_rate
        self.drain_interval = drain_interval
        self.queues: dict[str, deque] = defaultdict(deque)

    def _drain(self, key: str, now: float):
        q = self.queues[key]
        while q and now - q[0] >= self.drain_interval / self.drain_rate:
            q.popleft()

    def allow_request(self, key: str, cost: int = 1) -> bool:
        now = time.time()
        self._drain(key, now)
        q = self.queues[key]
        if len(q) + cost <= self.capacity:
            for _ in range(cost):
                q.append(now)
            return True
        return False

    # ... remaining methods similar

