class SlidingWindowCounter(RateLimiter):
    def __init__(self, limit: int, window_seconds: float):
        self.limit = limit
        self.window = window_seconds
        self.counters: dict[str, list] = defaultdict(lambda: [0.0, 0, 0])  # [start_time, curr_count, prev_count]

    def allow_request(self, key: str, cost: int = 1) -> bool:
        now = time.time()
        window_start = now - (now % self.window)
        entry = self.counters[key]
        prev_window_start = window_start - self.window

        # Advance window if needed
        if entry[0] != window_start:
            entry[0] = window_start
            entry[2] = entry[1]
            entry[1] = 0

        # Weighted estimate: how much of the previous window still overlaps
        elapsed = now - window_start
        weight = (self.window - elapsed) / self.window
        current_est = entry[1] + weight * entry[2]

        if current_est + cost <= self.limit:
            entry[1] += cost
            return True
        return False

