class AndLimiter(RateLimiter):
    """All children must allow the request."""
    def __init__(self, children: list[RateLimiter]):
        self.children = children

    def allow_request(self, key: str, cost: int = 1) -> bool:
        for child in self.children:
            if not child.allow_request(key, cost):
                return False
        return True

    def get_remaining(self, key: str) -> int:
        return min(c.get_remaining(key) for c in self.children)

    def reset_time(self, key: str) -> float:
        return max(c.reset_time(key) for c in self.children)

