"""Core in-memory key-value store implementation."""

import time
import threading
from typing import Any, Dict, List, Optional


class KVStore:
    """Thread-safe in-memory key-value store with TTL and bulk operations.

    All public methods are atomic (protected by a reentrant lock).
    Expired keys are cleaned up lazily on access, or explicitly via `cleanup()`.
    """

    def __init__(self) -> None:
        self._data: Dict[str, tuple[Any, Optional[float]]] = {}
        self._lock = threading.RLock()

    def _is_expired(self, key: str) -> bool:
        """Check and remove expired key. Returns True if missing or expired."""
        if key not in self._data:
            return True
        _, expiry = self._data[key]
        if expiry is not None and time.time() > expiry:
            del self._data[key]
            return True
        return False

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        """Atomically set a key-value pair with optional TTL in seconds."""
        with self._lock:
            expiry = time.time() + ttl if ttl is not None else None
            self._data[key] = (value, expiry)

    def get(self, key: str) -> Optional[Any]:
        """Atomically retrieve a value. Returns None if missing or expired."""
        with self._lock:
            if self._is_expired(key):
                return None
            return self._data[key][0]

    def delete(self, key: str) -> bool:
        """Atomically delete a key. Returns True if deleted, False otherwise."""
        with self._lock:
            if key in self._data and not self._is_expired(key):
                del self._data[key]
                return True
            return False

    def set_many(self, items: Dict[str, Any], ttl: Optional[float] = None) -> None:
        """Atomically set multiple key-value pairs."""
        with self._lock:
            now = time.time()
            for key, value in items.items():
                expiry = now + ttl if ttl is not None else None
                self._data[key] = (value, expiry)

    def get_many(self, keys: List[str]) -> Dict[str, Optional[Any]]:
        """Atomically retrieve multiple values. Missing/expired keys map to None."""
        with self._lock:
            result = {}
            for key in keys:
                if self._is_expired(key):
                    result[key] = None
                else:
                    result[key] = self._data[key][0]
            return result

    def delete_many(self, keys: List[str]) -> int:
        """Atomically delete multiple keys. Returns count of successfully deleted keys."""
        with self._lock:
            count = 0
            for key in keys:
                if key in self._data and not self._is_expired(key):
                    del self._data[key]
                    count += 1
            return count

    def cleanup(self) -> int:
        """Explicitly remove all expired keys. Returns count of removed keys."""
        with self._lock:
            expired = [k for k, (_, exp) in self._data.items() if exp is not None and time.time() > exp]
            for k in expired:
                del self._data[k]
            return len(expired)

    def keys(self) -> List[str]:
        """Return list of non-expired keys."""
        with self._lock:
            return [k for k in self._data if not self._is_expired(k)]

    def __contains__(self, key: str) -> bool:
        return key in self._data and not self._is_expired(key)

    def __len__(self) -> int:
        return sum(1 for k in self._data if not self._is_expired(k))

    def __repr__(self) -> str:
        return f"KVStore(size={len(self)})"

