"""Simple interactive CLI for KVStore."""

import sys
import json
from kvstore.core import KVStore


def main() -> None:
    store = KVStore()
    print("KVStore CLI. Commands: set <k> <v> [ttl], get <k>, del <k>, "
          "set-bulk <json>, get-bulk <json>, cleanup, list, quit")
    while True:
        try:
            line = input("kv> ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\nBye!")
            break
        if not line:
            continue
        parts = line.split()
        cmd = parts[0].lower()
        if cmd == "quit":
            break
        elif cmd == "set" and len(parts) >= 3:
            ttl = float(parts[3]) if len(parts) > 3 else None
            store.set(parts[1], parts[2], ttl)
            print("OK")
        elif cmd == "get" and len(parts) == 2:
            print(f"Value: {store.get(parts[1])}")
        elif cmd == "del" and len(parts) == 2:
            print("Deleted:", store.delete(parts[1]))
        elif cmd == "set-bulk" and len(parts) == 2:
            try:
                store.set_many(json.loads(parts[1]))
                print("OK")
            except json.JSONDecodeError:
                print("Invalid JSON")
        elif cmd == "get-bulk" and len(parts) == 2:
            try:
                print(json.dumps(store.get_many(json.loads(parts[1]))))
            except json.JSONDecodeError:
                print("Invalid JSON")
        elif cmd == "cleanup":
            print(f"Cleaned up {store.cleanup()} expired keys")
        elif cmd == "list":
            print(store.keys())
        else:
            print("Unknown command or wrong arguments")


if __name__ == "__main__":
    main()

