"""Tests for KVStore."""

import unittest
import time
import threading
from kvstore.core import KVStore


class TestKVStore(unittest.TestCase):
    def setUp(self) -> None:
        self.store = KVStore()

    def test_basic_ops(self) -> None:
        self.store.set("a", 1)
        self.assertEqual(self.store.get("a"), 1)
        self.assertTrue(self.store.delete("a"))
        self.assertIsNone(self.store.get("a"))

    def test_ttl_expiration(self) -> None:
        self.store.set("ttl_key", "val", ttl=0.1)
        self.assertEqual(self.store.get("ttl_key"), "val")
        time.sleep(0.15)
        self.assertIsNone(self.store.get("ttl_key"))

    def test_atomic_updates(self) -> None:
        errors = []
        def writer() -> None:
            try:
                for i in range(1000):
                    self.store.set("counter", i)
            except Exception as e:
                errors.append(e)

        threads = [threading.Thread(target=writer) for _ in range(5)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        self.assertEqual(errors, [])
        self.assertIn(self.store.get("counter"), range(1000))

    def test_bulk_ops(self) -> None:
        items = {f"key_{i}": f"val_{i}" for i in range(10)}
        self.store.set_many(items)
        keys = list(items.keys())
        result = self.store.get_many(keys)
        self.assertEqual(result, items)

        deleted = self.store.delete_many(keys)
        self.assertEqual(deleted, 10)
        self.assertEqual(self.store.get_many(keys), {k: None for k in keys})

    def test_cleanup(self) -> None:
        self.store.set("a", 1, ttl=0.1)
        self.store.set("b", 2, ttl=0.1)
        self.store.set("c", 3)
        time.sleep(0.15)
        cleaned = self.store.cleanup()
        self.assertEqual(cleaned, 2)
        self.assertEqual(len(self.store), 1)

    def test_contains_and_len(self) -> None:
        self.store.set("x", 1)
        self.assertIn("x", self.store)
        self.assertNotIn("y", self.store)
        self.assertEqual(len(self.store), 1)


