JoinPredicate = Callable[[Row, Row], bool]
AggFunc = Callable[[List[Any]], Any]

T = TypeVar("T", bound="Table")

class Table:
    """Immutable in-memory SQL-like query engine with fluent API."""

    def __init__(self, rows: Optional[List[Row]] = None) -> None:
        self._rows: List[Row] = rows if rows is not None else []

    def _clone(self: T) -> T:
        """Create a shallow copy for fluent chaining."""
        return self.__class__(deepcopy(self._rows))

    def select(self: T, *columns: str) -> T:
        """Project specific columns. If empty, returns all columns."""
        if not columns:
            return self
        projected = [
            {col: row[col] for col in columns if col in row}
            for row in self._rows
        ]
        cloned = self._clone()
        cloned._rows = projected
        return cloned

    def where(self: T, predicate: Predicate) -> T:
        """Filter rows based on a boolean predicate."""
        cloned = self._clone()
        cloned._rows = [row for row in self._rows if predicate(row)]
        return cloned

    def join(self: T, other: Table, on: JoinPredicate) -> T:
        """Inner join with another table using a custom predicate."""
        joined = []
        for left in self._rows:
            for right in other._rows:
                if on(left, right):
                    # Merge keys, right-side takes precedence on collision
                    merged = {**left, **right}
                    joined.append(merged)
        cloned = self._clone()
        cloned._rows = joined
        return cloned

    def group_by(self: T, column: str) -> GroupedTable:
        """Group rows by a column. Returns a GroupedTable for aggregation."""
        groups: Dict[Any, List[Row]] = {}
        for row in self._rows:
            key = row.get(column)
            groups.setdefault(key, []).append(row)
        return GroupedTable(list(groups.items()), column)

    def order_by(self: T, column: str, descending: bool = False) -> T:
        """Sort rows by a column."""
        cloned = self._clone()
        cloned._rows = sorted(
            self._rows,
            key=lambda r: r.get(column, ""),
            reverse=descending
        )
        return cloned

    def limit(self: T, n: int) -> T:
        """Limit result set to n rows."""
        cloned = self._clone()
        cloned._rows = self._rows[:n]
        return cloned

    def to_list(self) -> List[Row]:
        """Materialize the query result."""
        return deepcopy(self._rows)

    def __repr__(self) -> str:
        return f"Table(rows={len(self._rows)})"


class GroupedTable:
    """Helper class returned by group_by() to support aggregation."""

    def __init__(self, groups: List[tuple[Any, List[Row]]], group_col: str) -> None:
        self._groups = groups
        self._group_col = group_col

    def agg(self, **aggregations: AggFunc) -> Table:
        """Apply aggregation functions to each group."""
        result_rows = []
        for key, rows in self._groups:
            row = {self._group_col: key}
            for col, func in aggregations.items():
                values = [r.get(col) for r in rows if r.get(col) is not None]
                row[col] = func(values) if values else None
            result_rows.append(row)
        return Table(result_rows)

    def __repr__(self) -> str:
        return f"GroupedTable(groups={len(self._groups)}, col={self._group_col})"


