from __future__ import annotations

import threading
import time
from typing import Any, Dict, List, Optional, Tuple


class InMemoryKVStore:
    """Thread-safe in-memory key-value store with TTL support.

    All public methods are atomic under a single lock. Expired entries are
    removed lazily on access to avoid background scheduling overhead.
    """

    def __init__(self) -> None:
        # monotonic clock prevents TTL drift from system clock adjustments
        self._data: Dict[str, Tuple[Any, Optional[float]]] = {}
        self._lock = threading.Lock()

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        if not isinstance(key, str):
            raise TypeError("Key must be a string")
        if ttl is not None and ttl < 0:
            raise ValueError("TTL must be non-negative")

        expiry = time.monotonic() + ttl if ttl is not None else None
        with self._lock:
            self._data[key] = (value, expiry)

    def get(self, key: str) -> Optional[Any]:
        if not isinstance(key, str):
            raise TypeError("Key must be a string")

        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return None
            value, expiry = entry
            # Lazy expiration: reclaim memory without background threads
            if expiry is not None and time.monotonic() >= expiry:
                del self._data[key]
                return None
            return value

    def delete(self, key: str) -> bool:
        if not isinstance(key, str):
            raise TypeError("Key must be a string")

        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return False
            value, expiry = entry
            if expiry is not None and time.monotonic() >= expiry:
                del self._data[key]
                return False
            del self._data[key]
            return True

    def set_many(self, items: Dict[str, Tuple[Any, Optional[float]]]) -> None:
        if not isinstance(items, dict):
            raise TypeError("Items must be a dictionary")
        for key, (value, ttl) in items.items():
            if not isinstance(key, str):
                raise TypeError("All keys must be strings")
            if ttl is not None and ttl < 0:
                raise ValueError("All TTLs must be non-negative")

        with self._lock:
            for key, (value, ttl) in items.items():
                expiry = time.monotonic() + ttl if ttl is not None else None
                self._data[key] = (value, expiry)

    def get_many(self, keys: List[str]) -> Dict[str, Optional[Any]]:
        if not isinstance(keys, list):
            raise TypeError("Keys must be a list")

        with self._lock:
            result = {}
            for key in keys:
                entry = self._data.get(key)
                if entry is None:
                    result[key] = None
                    continue
                value, expiry = entry
                if expiry is not None and time.monotonic() >= expiry:
                    del self._data[key]
                    result[key] = None
                else:
                    result[key] = value
            return result

    def delete_many(self, keys: List[str]) -> Dict[str, bool]:
        if not isinstance(keys, list):
            raise TypeError("Keys must be a list")

        with self._lock:
            result = {}
            for key in keys:
                entry = self._data.get(key)
                if entry is None:
                    result[key] = False
                    continue
                value, expiry = entry
                if expiry is not None and time.monotonic() >= expiry:
                    del self._data[key]
                    result[key] = False
                else:
                    del self._data[key]
                    result[key] = True
            return result

    def clear(self) -> None:
        with self._lock:
            self._data.clear()

