from __future__ import annotations

import argparse
import json
import sys
from typing import Optional

from .core import InMemoryKVStore


def _parse_kv_pairs(pairs: list[str]) -> dict[str, tuple[str, Optional[float]]]:
    """Parse CLI key=value arguments into store-compatible format."""
    result = {}
    for pair in pairs:
        if "=" not in pair:
            raise ValueError(f"Invalid format: {pair}. Expected key=value")
        key, val = pair.split("=", 1)
        result[key] = (val, None)
    return result


def main() -> None:
    parser = argparse.ArgumentParser(description="In-memory KV Store CLI")
    subparsers = parser.add_subparsers(dest="command", required=True)

    p_set = subparsers.add_parser("set", help="Set a key-value pair")
    p_set.add_argument("key", type=str)
    p_set.add_argument("value", type=str)
    p_set.add_argument("--ttl", type=float, default=None)

    p_get = subparsers.add_parser("get", help="Get a value by key")
    p_get.add_argument("key", type=str)

    p_del = subparsers.add_parser("delete", help="Delete a key")
    p_del.add_argument("key", type=str)

    p_bulk_set = subparsers.add_parser("bulk_set", help="Set multiple key-value pairs")
    p_bulk_set.add_argument("pairs", nargs="+", help="key=value pairs")

    p_bulk_get = subparsers.add_parser("bulk_get", help="Get multiple values")
    p_bulk_get.add_argument("keys", nargs="+", help="Keys to retrieve")

    p_bulk_del = subparsers.add_parser("bulk_delete", help="Delete multiple keys")
    p_bulk_del.add_argument("keys", nargs="+", help="Keys to delete")

    subparsers.add_parser("clear", help="Clear all entries")

    args = parser.parse_args()
    # CLI is stateless per invocation; each run initializes a fresh store
    store = InMemoryKVStore()

    try:
        if args.command == "set":
            store.set(args.key, args.value, args.ttl)
            print(f"Set {args.key}")
        elif args.command == "get":
            val = store.get(args.key)
            print(json.dumps(val))
        elif args.command == "delete":
            print(store.delete(args.key))
        elif args.command == "bulk_set":
            items = _parse_kv_pairs(args.pairs)
            store.set_many(items)
            print(f"Set {len(items)} items")
        elif args.command == "bulk_get":
            result = store.get_many(args.keys)
            print(json.dumps(result))
        elif args.command == "bulk_delete":
            result = store.delete_many(args.keys)
            print(json.dumps(result))
        elif args.command == "clear":
            store.clear()
            print("Cleared")
    except (TypeError, ValueError) as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

