import time
import threading
from typing import Callable, Dict, Generic, Iterable, Mapping, Optional, Sequence, TypeVar

K = TypeVar("K")
V = TypeVar("V")
R = TypeVar("R")


class InMemoryKVStore(Generic[K, V]):
    """Thread-safe in-memory key-value store with TTL support."""

    def __init__(self) -> None:
        # Stores (value, absolute_expiry_timestamp)
        self._data: Dict[K, tuple[V, Optional[float]]] = {}
        self._lock = threading.RLock()

    def set(self, key: K, value: V, ttl: Optional[float] = None) -> None:
        if ttl is not None and ttl < 0:
            raise ValueError("TTL must be non-negative")
        expiry = time.time() + ttl if ttl is not None else None
        with self._lock:
            self._data[key] = (value, expiry)

    def get(self, key: K) -> Optional[V]:
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return None
            value, expiry = entry
            # Lazy expiration: remove on access to prevent unbounded growth
            if expiry is not None and time.time() > expiry:
                del self._data[key]
                return None
            return value

    def delete(self, key: K) -> bool:
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return False
            value, expiry = entry
            if expiry is not None and time.time() > expiry:
                del self._data[key]
                return False
            del self._data[key]
            return True

    def exists(self, key: K) -> bool:
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return False
            value, expiry = entry
            if expiry is not None and time.time() > expiry:
                del self._data[key]
                return False
            return True

    def cleanup(self) -> int:
        """Remove all expired entries. Returns count of removed keys."""
        now = time.time()
        with self._lock:
            expired_keys = [k for k, (_, expiry) in self._data.items() if expiry is not None and now > expiry]
            for k in expired_keys:
                del self._data[k]
            return len(expired_keys)

    def bulk_set(self, items: Mapping[K, V], ttl: Optional[float] = None) -> None:
        if ttl is not None and ttl < 0:
            raise ValueError("TTL must be non-negative")
        expiry = time.time() + ttl if ttl is not None else None
        with self._lock:
            self._data.update((k, (v, expiry)) for k, v in items.items())

    def bulk_get(self, keys: Sequence[K]) -> Dict[K, Optional[V]]:
        now = time.time()
        with self._lock:
            result: Dict[K, Optional[V]] = {}
            for key in keys:
                entry = self._data.get(key)
                if entry is None:
                    result[key] = None
                    continue
                value, expiry = entry
                if expiry is not None and now > expiry:
                    del self._data[key]
                    result[key] = None
                else:
                    result[key] = value
            return result

    def bulk_delete(self, keys: Sequence[K]) -> int:
        now = time.time()
        with self._lock:
            deleted = 0
            for key in keys:
                entry = self._data.get(key)
                if entry is None:
                    continue
                value, expiry = entry
                if expiry is not None and now > expiry:
                    del self._data[key]
                    continue
                del self._data[key]
                deleted += 1
            return deleted

    def atomic_update(self, func: Callable[["InMemoryKVStore[K, V]"], R]) -> R:
        """Execute a callback atomically. All mutations within func are serialized."""
        with self._lock:
            return func(self)

    def clear(self) -> None:
        with self._lock:
            self._data.clear()

    def __len__(self) -> int:
        with self._lock:
            return len(self._data)

    def __contains__(self, key: K) -> bool:
        return self.exists(key)

    def keys(self) -> Iterable[K]:
        with self._lock:
            return list(self._data.keys())

    def values(self) -> Iterable[V]:
        with self._lock:
            return [v for v, _ in self._data.values()]

    def items(self) -> Iterable[tuple[K, V]]:
        with self._lock:
            return [(k, v) for k, (v, _) in self._data.items()]

    def __repr__(self) -> str:
        return f"InMemoryKVStore(entries={len(self)})"

