import sys
from .store import InMemoryKVStore


def _run_repl(store: InMemoryKVStore) -> None:
    print("KV Store REPL. Commands: set <k> <v> [ttl], get <k>, delete <k>, "
          "bulk_set <k1:v1,k2:v2>, cleanup, atomic, exit")
    while True:
        try:
            line = input("kv> ").strip()
            if not line:
                continue
            if line == "exit":
                break
            parts = line.split()
            cmd = parts[0]
            args = parts[1:]
            try:
                if cmd == "set":
                    if len(args) < 2:
                        print("Usage: set <key> <value> [ttl]")
                        continue
                    key, value = args[0], args[1]
                    ttl = float(args[2]) if len(args) > 2 else None
                    store.set(key, value, ttl)
                    print("OK")
                elif cmd == "get":
                    if len(args) != 1:
                        print("Usage: get <key>")
                        continue
                    val = store.get(args[0])
                    print(val if val is not None else "None")
                elif cmd == "delete":
                    if len(args) != 1:
                        print("Usage: delete <key>")
                        continue
                    print(store.delete(args[0]))
                elif cmd == "bulk_set":
                    if len(args) != 1:
                        print("Usage: bulk_set <k1:v1,k2:v2>")
                        continue
                    items = {}
                    for pair in args[0].split(","):
                        k, v = pair.split(":")
                        items[k] = v
                    store.bulk_set(items)
                    print("OK")
                elif cmd == "cleanup":
                    print(f"Removed {store.cleanup()} expired keys")
                elif cmd == "atomic":
                    # Demonstrates atomic read-modify-write
                    current = store.get("counter") or 0
                    store.set("counter", current + 1)
                    print(f"Atomic increment: counter={current + 1}")
                else:
                    print(f"Unknown command: {cmd}")
            except Exception as e:
                print(f"Error: {e}")
        except EOFError:
            break


def main() -> None:
    store = InMemoryKVStore()
    _run_repl(store)


if __name__ == "__main__":
    main()

