import time
from typing import Any, Dict, List, Optional, Tuple

class KVStore:
    def __init__(self):
        # Internal storage: key -> (value, expiry_timestamp or None)
        self._data: Dict[str, Tuple[Any, Optional[float]]] = {}

    def _check_expiry(self, key: str) -> bool:
        """Returns True if key is missing or expired."""
        if key not in self._data:
            return True
        _, expiry = self._data[key]
        if expiry is not None and time.time() > expiry:
            del self._data[key]
            return True
        return False

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        """Set a key-value pair with optional TTL in seconds."""
        expiry = time.time() + ttl if ttl is not None else None
        self._data[key] = (value, expiry)

    def get(self, key: str) -> Optional[Any]:
        """Get value by key. Returns None if missing or expired."""
        if self._check_expiry(key):
            return None
        return self._data[key][0]

    def delete(self, key: str) -> bool:
        """Delete a key. Returns True if deleted, False if missing/expired."""
        if self._check_expiry(key):
            return False
        if key in self._data:
            del self._data[key]
            return True
        return False

    def bulk_set(self, items: Dict[str, Any], ttl: Optional[float] = None) -> None:
        """Set multiple key-value pairs at once."""
        for k, v in items.items():
            self.set(k, v, ttl)

    def bulk_get(self, keys: List[str]) -> Dict[str, Optional[Any]]:
        """Get multiple values. Returns dict with same keys, None for missing/expired."""
        return {k: self.get(k) for k in keys}

    def bulk_delete(self, keys: List[str]) -> int:
        """Delete multiple keys. Returns count of successfully deleted keys."""
        count = 0
        for k in keys:
            if self.delete(k):
                count += 1
        return count

    def atomic_update(self, updates: Dict[str, Any]) -> None:
        """Apply multiple updates atomically. Rolls back on any failure."""
        # Take a snapshot so we can rollback if something goes wrong
        snapshot = {k: (v, exp) for k, (v, exp) in self._data.items()}
        try:
            for k, v in updates.items():
                # Simple validation: reject None values during atomic ops
                if v is None:
                    raise ValueError("None values not allowed in atomic_update")
                self.set(k, v)
        except Exception:
            # Rollback to snapshot state
            self._data = snapshot
            raise

