from .core import KVStore

def main():
    parser = argparse.ArgumentParser(description="Simple in-memory KV store CLI")
    subparsers = parser.add_subparsers(dest="command", help="Available commands")

    # set command
    p_set = subparsers.add_parser("set", help="Set a key-value pair")
    p_set.add_argument("key", help="Key")
    p_set.add_argument("value", help="Value")
    p_set.add_argument("--ttl", type=float, default=None, help="TTL in seconds")

    # get command
    p_get = subparsers.add_parser("get", help="Get a value by key")
    p_get.add_argument("key", help="Key")

    # bulk_set command
    p_bulk = subparsers.add_parser("bulk_set", help="Set multiple key-value pairs")
    p_bulk.add_argument("items", nargs="+", help="Alternating key value pairs")

    args = parser.parse_args()
    store = KVStore()

    if args.command == "set":
        store.set(args.key, args.value, args.ttl)
        print(f"[OK] Set '{args.key}'")
    elif args.command == "get":
        val = store.get(args.key)
        print(f"[RESULT] '{args.key}' = {val}")
    elif args.command == "bulk_set":
        # Convert flat list to dict: ['a', '1', 'b', '2'] -> {'a': '1', 'b': '2'}
        if len(args.items) % 2 != 0:
            print("[ERROR] bulk_set requires even number of arguments (key value key value...)")
            sys.exit(1)
        items = dict(zip(args.items[::2], args.items[1::2]))
        store.bulk_set(items)
        print(f"[OK] Bulk set {len(items)} items")
    else:
        parser.print_help()

if __name__ == "__main__":
