import os
import json

class MultiFileKVStore:
    def __init__(self, base_dir='kv_store', entries_per_file=10):
        self.base_dir = base_dir
        self.entries_per_file = entries_per_file
        self.current_file_index = 0
        self.data = {}

        if not os.path.exists(base_dir):
            os.makedirs(base_dir)
        self.load_existing_files()

    def load_existing_files(self):
        # Load existing key-value pairs from files
        for filename in os.listdir(self.base_dir):
            if filename.endswith('.json'):
                with open(os.path.join(self.base_dir, filename), 'r') as f:
                    self.data.update(json.load(f))

    def _get_current_file_path(self):
        return os.path.join(self.base_dir, f'kvstore_{self.current_file_index}.json')

    def _save_to_file(self, data, filepath):
        with open(filepath, 'w') as f:
            json.dump(data, f)

    def _load_from_file(self, filepath):
        with open(filepath, 'r') as f:
            return json.load(f)

    def add_file(self):
        self.current_file_index += 1
        self.data = {}

    def put(self, key, value):
        if key in self.data:
            self.data[key] = value  # Update value
        else:
            if len(self.data) >= self.entries_per_file:
                self._save_to_file(self.data, self._get_current_file_path())
                self.add_file()
            self.data[key] = value

    def get(self, key):
        return self.data.get(key)

    def delete(self, key):
        if key in self.data:
            del self.data[key]

    def commit(self):
        if self.data:  # Save current in-memory data to the file
            self._save_to_file(self.data, self._get_current_file_path())
            self.data = {}  # Clear in-memory data after saving

# Example Usage
if __name__ == "__main__":
    kv_store = MultiFileKVStore(entries_per_file=2)

    kv_store.put('name', 'Alice')
    kv_store.put('age', 30)
    kv_store.commit()  # Save current file

