import json
import logging
from pathlib import Path
from typing import Union, Optional


def load_and_merge_configs(
    primary_path: Union[str, Path],
    override_path: Optional[Union[str, Path]] = None
) -> dict:
    """
    Load a primary JSON configuration file and optionally merge an override file.

    Args:
        primary_path: Path to the primary configuration file.
        override_path: Optional path to an override configuration file.

    Returns:
        A merged dictionary containing configuration values.
        Returns an empty dict if the primary config is missing.
    """
    result = {}

    # Load primary configuration
    primary = None
    try:
        with open(primary_path, 'r') as f:
            primary = json.load(f)
    except FileNotFoundError:
        logging.warning("Primary config file not found: %s", primary_path)
    except json.JSONDecodeError as e:
        logging.error("Failed to parse primary config as JSON: %s", e, exc_info=True)
    except PermissionError as e:
        logging.error("Permission denied reading primary config: %s", e, exc_info=True)
    except OSError as e:
        logging.error("Error reading primary config: %s", e, exc_info=True)

    # Process primary configuration
    if primary is not None:
        if isinstance(primary, dict):
            result.update(primary)
        else:
            logging.warning("Primary config is not a dict, ignoring: %s", type(primary))

    # Load override configuration if provided
    if override_path:
        override = None
        try:
            with open(override_path, 'r') as f:
                override = json.load(f)
        except FileNotFoundError:
            logging.debug("Override config file not found: %s", override_path)
        except json.JSONDecodeError as e:
            logging.error("Failed to parse override config as JSON: %s", e, exc_info=True)
        except PermissionError as e:
            logging.error("Permission denied reading override config: %s", e, exc_info=True)
        except OSError as e:
            logging.error("Error reading override config: %s", e, exc_info=True)
        else:
            if isinstance(override, dict):
                result.update(override)
            else:
                logging.warning("Override config is not a dict, ignoring: %s", type(override))

    return result

