        """Set value for key."""
        file_path = self._key_to_path(key)
        try:
            file_path.parent.mkdir(parents=True, exist_ok=True)
            file_path.write_bytes(value)
        except IOError as e:
            raise StorageError(f"Failed to write file {file_path}: {e}")

    def delete(self, key: str) -> bool:
        """Delete key."""
        file_path = self._key_to_path(key)
        if file_path.exists():
            try:
                file_path.unlink()
                # Clean up empty directories
                self._cleanup_empty_dirs(file_path.parent)
                return True
            except IOError as e:
                raise StorageError(f"Failed to delete file {file_path}: {e}")
        return False

    def exists(self, key: str) -> bool:
        """Check if key exists."""
        return self._key_to_path(key).exists()

    def keys(self, pattern: str = "*") -> List[str]:
        """Get keys matching pattern."""
        all_keys = []

        for file_path in self.base_path.rglob("*"):
            if file_path.is_file():
                key = self._path_to_key(file_path)
                all_keys.append(key)

        if pattern == "*":
            return all_keys

        # Convert glob pattern to regex
        regex_pattern = pattern.replace('*', '.*').replace('?', '.')
        regex = re.compile(f'^{regex_pattern}$')

        return [key for key in all_keys if regex.match(key)]

    def clear(self) -> None:
        """Clear all data."""
        try:
            shutil.rmtree(self.base_path)
            self.base_path.mkdir(parents=True, exist_ok=True)
        except IOError as e:
            raise StorageError(f"Failed to clear storage: {e}")

    def __len__(self) -> int:
        """Get number of items."""
        count = 0
        for _ in self.base_path.rglob("*"):
            if _.is_file():
                count += 1
        return count

    def __iter__(self) -> Iterator[str]:
        """Iterate over keys."""
        for file_path in self.base_path.rglob("*"):
            if file_path.is_file():
                yield self._path_to_key(file_path)

    def _key_to_path(self, key: str) -> Path:
        """Convert key to filesystem path."""
        # Sanitize key for filesystem
        safe_key = key.replace('/', os.path.sep)
        return self.base_path / safe_key

    def _path_to_key(self, path: Path) -> str:
        """Convert filesystem path to key."""
        relative_path = path.relative_to(self.base_path)
        return str(relative_path).replace(os.path.sep, '/')

    def _cleanup_empty_dirs(self, directory: Path) -> None:
        """Remove empty directories recursively."""
        try:
            while directory != self.base_path and directory.exists():
                if not any(directory.iterdir()):
                    directory.rmdir()
                    directory = directory.parent
                else:
                    break
        except IOError:
            pass  # Ignore cleanup errors

