"""Utility functions."""

import hashlib
import time
from typing import Any, Callable
from functools import wraps
from .errors import ValidationError

def validate_key(key: str) -> None:
    """Validate key format."""
    if not isinstance(key, str):
        raise ValidationError("Key must be a string")
    if not key:
        raise ValidationError("Key cannot be empty")
    if len(key) > 256:
        raise ValidationError("Key too long (max 256 characters)")

    # Disallow problematic characters for file storage
    if '\x00' in key or '\n' in key or '\r' in key:
        raise ValidationError("Key contains invalid characters")

def hash_key(key: str) -> str:
    """Create hash of key for consistent naming."""
    return hashlib.sha256(key.encode()).hexdigest()

def retry(max_attempts: int = 3, delay: float = 0.1):
    """Decorator for retrying operations."""
    def decorator(func: Callable):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_exception = None
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    last_exception = e
                    if attempt < max_attempts - 1:
                        time.sleep(delay * (2 ** attempt))  # Exponential backoff
            raise last_exception
        return wrapper
    return decorator

def sizeof_fmt(num: int, suffix: str = 'B') -> str:
    """Format bytes to human readable string."""
    for unit in ['', 'Ki', 'Mi', 'Gi', 'Ti', 'Pi', 'Ei', 'Zi']:
        if abs(num) < 1024.0:
            return f"{num:3.1f} {unit}{suffix}"
        num /= 1024.0
    return f"{num:.1f} Yi{suffix}"

