"""Main KV store implementation."""

from typing import Any, Optional, List, Dict, Iterator, Union
from .storage.base import BaseStorage
from .storage.memory import MemoryStorage
from .storage.file import FileStorage
from .storage.sqlite import SQLiteStorage
from .serializers.base import BaseSerializer
from .serializers.json import JSONSerializer
from .serializers.pickle import PickleSerializer
from .errors import KeyNotFoundError, ValidationError
from .utils import validate_key, retry

class KVStore:
    """Key-Value store with multiple storage backends and serializers."""

    def __init__(
        self,
        storage: Optional[Union[str, BaseStorage]] = None,
        serializer: Optional[Union[str, BaseSerializer]] = None,
        **kwargs
    ):
        """
        Initialize KV store.

        Args:
            storage: Storage backend ('memory', 'file', 'sqlite', or BaseStorage instance)
            serializer: Serializer ('json', 'pickle', or BaseSerializer instance)
            **kwargs: Additional arguments for storage backend
        """
        # Initialize serializer
        if serializer is None or serializer == 'json':
            self.serializer = JSONSerializer()
        elif serializer == 'pickle':
            self.serializer = PickleSerializer()
        elif isinstance(serializer, BaseSerializer):
            self.serializer = serializer
        else:
            raise ValueError(f"Unknown serializer: {serializer}")

        # Initialize storage
        if storage is None or storage == 'memory':
            self.storage = MemoryStorage()
        elif storage == 'file':
            path = kwargs.get('path', './kvstore_data')
            self.storage = FileStorage(path)
        elif storage == 'sqlite':
            db_path = kwargs.get('db_path', ':memory:')
            table_name = kwargs.get('table_name', 'kvstore')
            self.storage = SQLiteStorage(db_path, table_name)
        elif isinstance(storage, BaseStorage):
            self.storage = storage
        else:
            raise ValueError(f"Unknown storage: {storage}")

    @retry(max_attempts=3)
    def get(self, key: str, default: Any = None) -> Any:
        """Get value for key."""
        validate_key(key)
        data = self.storage.get(key)
        if data is None:
            if default is not None:
                return default
            raise KeyNotFoundError(f"Key not found: {key}")

        try:
            return self.serializer.deserialize(data)
        except Exception as e:
            raise KeyNotFoundError(f"Failed to deserialize data for key {key}: {e}")

    @retry(max_attempts=3)
    def set(self, key: str, value: Any) -> None:
        """Set value for key."""
        validate_key(key)

        try:
            data = self.serializer.serialize(value)
        except Exception as e:
            raise ValidationError(f"Failed to serialize value for key {key}: {e}")

        self.storage.set(key, data)

    @retry(max_attempts=3)
    def delete(self, key: str) -> bool:
        """Delete key."""
        validate_key(key)
        return self.storage.delete(key)

    def exists(self, key: str) -> bool:
        """Check if key exists."""
        validate_key(key)
        return self.storage.exists(key)

    def keys(self, pattern: str = "*") -> List[str]:
        """Get keys matching pattern."""
        return self.storage.keys(pattern)

    def clear(self) -> None:
        """Clear all data."""
        self.storage.clear()

    def get_many(self, keys: List[str]) -> Dict[str, Any]:
        """Get multiple keys at once."""
        return {key: self.get(key) for key in keys}

    def set_many(self, items: Dict[str, Any]) -> None:
        """Set multiple keys at once."""
        for key, value in items.items():
            self.set(key, value)

    def update(self, key: str, updater: callable, default: Any = None) -> Any:
        """Update value using a function."""
        current = self.get(key, default)
        new_value = updater(current)
        self.set(key, new_value)
        return new_value

    def pop(self, key: str, default: Any = None) -> Any:
        """Pop key and return its value."""
        value = self.get(key, default)
        if value is not default:
            self.delete(key)
        return value

    def __getitem__(self, key: str) -> Any:
        """Get item using [] syntax."""
        return self.get(key)

    def __setitem__(self, key: str, value: Any) -> None:
        """Set item using [] syntax."""
        self.set(key, value)

    def __delitem__(self, key: str) -> None:
        """Delete item using del syntax."""
        if not self.delete(key):
            raise KeyNotFoundError(f"Key not found: {key}")

    def __contains__(self, key: str) -> bool:
        """Check if key exists using 'in' operator."""
        return self.exists(key)

    def __len__(self) -> int:
        """Get number of items."""
        return len(self.storage)

    def __iter__(self) -> Iterator[str]:
        """Iterate over keys."""
        return iter(self.storage)

    def items(self) -> Iterator[tuple[str, Any]]:
        """Iterate over key-value pairs."""
        for key in self:
            yield key, self.get(key)

    def values(self) -> Iterator[Any]:
        """Iterate over values."""
        for key in self:
            yield self.get(key)

